                (nf.step != null and self.expr_needs_native_scalar_stdlib_h(nf.step.?)) or
                self.block_needs_native_scalar_stdlib_h(nf.body),
            .func_decl => |fd| self.block_needs_native_scalar_stdlib_h(fd.func.body),
