            self.p("        int64_t tmp = m; m = a; a = tmp;\n", .{});
            self.p("    }}\n", .{});
            self.p("    return (int64_t)ans;\n", .{});
            self.p("}}\n", .{});
            self.p("static inline uint64_t duo_floor_sum_parity_u64(uint64_t n, uint64_t m, uint64_t a) {{\n", .{});
            self.p("    uint64_t parity = 0, b = 0;\n", .{});
            self.p("    while (1) {{\n", .{});
            self.p("        if (a >= m) {{ uint64_t q = a / m; parity ^= ((((__uint128_t)(n - 1) * n) / 2) & 1) & (q & 1); a %= m; }}\n", .{});
            self.p("        if (b >= m) {{ uint64_t q = b / m; parity ^= (n & 1) & (q & 1); b %= m; }}\n", .{});
            self.p("        __uint128_t y = (__uint128_t)a * n + b;\n", .{});
            self.p("        if (y < m) break;\n", .{});
            self.p("        n = (uint64_t)(y / m);\n", .{});
            self.p("        b = (uint64_t)(y % m);\n", .{});
            self.p("        uint64_t tmp = m; m = a; a = tmp;\n", .{});
            self.p("    }}\n", .{});
            self.p("    return parity & 1;\n", .{});
            self.p("}}\n", .{});
            self.p("typedef double v4f64 __attribute__((ext_vector_type(4)));\n", .{});
            self.p("typedef int64_t v4i64 __attribute__((ext_vector_type(4)));\n", .{});
            self.p("typedef float v8f32 __attribute__((ext_vector_type(8)));\n", .{});
            self.p("typedef int32_t v8i32 __attribute__((ext_vector_type(8)));\n", .{});
            self.p("static inline v4f64 duo_select_v4f64(v4i64 c, v4f64 a, v4f64 b) {{\n", .{});
            self.p("    v4f64 fc = __builtin_convertvector(c, v4f64);\n", .{});
            self.p("    v4f64 one = (v4f64){{1.0, 1.0, 1.0, 1.0}};\n", .{});
            self.p("    return a * fc + b * (one - fc);\n", .{});
            self.p("}}\n", .{});
            self.p("static inline v4i64 duo_select_v4i64(v4i64 c, v4i64 a, v4i64 b) {{\n", .{});
            self.p("    v4i64 one = (v4i64){{1, 1, 1, 1}};\n", .{});
            self.p("    return a * c + b * (one - c);\n", .{});
            self.p("}}\n", .{});
            self.p("static inline v8f32 duo_select_v8f32(v8i32 c, v8f32 a, v8f32 b) {{\n", .{});
            self.p("    v8f32 fc = __builtin_convertvector(c, v8f32);\n", .{});
            self.p("    v8f32 one = (v8f32){{1.0f, 1.0f, 1.0f, 1.0f, 1.0f, 1.0f, 1.0f, 1.0f}};\n", .{});
            self.p("    return a * fc + b * (one - fc);\n", .{});
            self.p("}}\n", .{});
            self.p("static inline v8i32 duo_select_v8i32(v8i32 c, v8i32 a, v8i32 b) {{\n", .{});
            self.p("    v8i32 one = (v8i32){{1, 1, 1, 1, 1, 1, 1, 1}};\n", .{});
            self.p("    return a * c + b * (one - c);\n", .{});
            self.p("}}\n", .{});
        }
        if (self.moduleNeedsLuaRuntime()) {
            self.p("#include <locale.h>\n", .{});
            self.nl();
            self.p("#ifdef __wasm__\nstatic char duo_jit_compile_flags[1] = \"\";\n#else\nchar duo_jit_compile_flags[128] = \"\";\n#endif\n\n", .{});
            self.p("{s}", .{duo_runtime});
            self.nl();
        }

        try self.comptime_scopes.append(self.alloc, std.StringHashMapUnmanaged(comptime_eval.Value).empty);
        defer {
            var module_comptime = self.comptime_scopes.pop().?;
            module_comptime.deinit(self.alloc);
        }

        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                const fd = &stmt.func_decl;
                if (fd.path.len == 1 and !fd.method) {
                    try self.note_func_body(fd.path[0], &fd.func);
                    try self.note_comptime_func(fd.path[0], &fd.func);
                }
            }
            // Pre-register module-level integer/float constants for comptime resolution.
            // This allows typed functions to use `OP_ADD = 0x6A` as compile-time constants.
            // Only register assignments (not locals inside functions which are mutable).
            if (stmt.* == .assign) {
                const as = &stmt.assign;
                for (as.targets, 0..) |tgt, ti| {
                    if (tgt.* == .name and ti < as.values.len) {
                        if (self.fold_meta_string_expr(as.values[ti])) |s| {
                            try self.note_comptime_string(tgt.name.ident, s);
                        } else {
                            try self.note_comptime_binding(tgt.name.ident, as.values[ti]);
                        }
                    }
                }
            }
        }

        // Emit module-level @c.emit directives at file scope so raw C
        // declarations (e.g., struct/typedef definitions) are visible to
        // file-scope functions in the generated C.
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .directive => |d| {
                    if (!CodeGen.isCEmitDirectiveName(d.attr.name)) continue;
                    const code = @import("directives.zig").extractAndUnescapeCRawCode(self.alloc, d.attr.args orelse "") catch "";
                    self.emit_file_scope_c_payload(code);
                },
                .expr_stmt => |es| {
                    if (self.fold_c_emit_payload(es.expr)) |code| {
                        self.emit_file_scope_c_payload(code);
                    }
                },
                else => {},
            }
        }
        self.nl();

        // Walk the module to find every record-type annotation (function
        // parameters, return types, local/global decls, struct fields) and
        // emit the corresponding C struct typedefs at file scope. This must
        // run *before* the function forward-declarations so they can name
        // the record types in their signatures.
        try self.collect_and_emit_record_decls(mod);

        // Emit enum typedefs (and tag constants) before forward-declarations,
        // so function signatures can name `duo_<Enum>` types (Task 12.6).
        try self.emit_enum_decls(mod);

        // Emit static metatable variable declarations for alias types with methods/@derive
        try self.emit_alias_metatable_decls(mod);

        // Emit @derive-generated functions for alias types
        try self.emit_alias_derive_functions(mod);

        if (self.module_globals) |globals| {
            var it = globals.keyIterator();
            while (it.next()) |key| {
                if (is_runtime_global(key.*)) continue;
                if (self.is_native_dense_module_table(key.*)) continue;
                // NOTE: req-module bindings are NOT skipped here. They usually
                // resolve to direct C symbols, but not every use site does — a
                // field read that sema types as `.any` still emits the variable,
                // and skipping the declaration made that "use of undeclared
                // identifier". An unused static is harmless; a missing one is not.
                // …unless a function assigns it. `y = -100` at module scope folds
                // to a scalar constant, so the declaration was skipped — but a
                // function containing `y = 1` resolves `y` to that module binding
                // (the scoping rule) and emits `duo_g_y = 1`, needing real
                // storage. Constant-folding a binding that is written to is the
                // bug; it produced "use of undeclared identifier 'duo_g_y'".
                // …and reads are just as demanding as writes. This loop walks
                // `module_globals`, so `global_type(key)` is non-null for every
                // key, which means `emit_var_name_mode` takes its first branch and
                // spells each read `duo_g_<mod>_<name>` — scalar-const or not.
                // Guarding only on *assignment* therefore still dropped storage
                // for read-only folded constants: `std.vector.WORD_W` is never
                // written, so the declaration was skipped, while every use in a
                // function body emitted `duo_g_std_vector_WORD_W`. Same defect as
                // the note above, reached through a read instead of a write.
                // Per that note's own rule — an unused static is harmless, a
                // missing one is not — module globals always get storage.
                _ = self.module_functions_assign_name(mod, key.*);
                const gt = globals.get(key.*) orelse .any;
                // …with one exception the note above predates: a no-lua translation
                // unit never declares `lua_Value`, so an `.any` binding cannot be
                // spelled at all. Under native lowering a *req-module* binding
                // resolves to direct C symbols (no lua_invoke, no fallback field
                // reads), so there is nothing left to declare.
                //
                // This must stay limited to req bindings. Applied to every `.any`
                // global it dropped ordinary ones: `y = -100` at module scope, then
                // `y = 1` inside a function (which targets that global per the
                // scoping rule), emitted `duo_g_y = 1;` with no declaration
                // anywhere — "use of undeclared identifier 'duo_g_y'". It only
                // surfaced once a module became no-lua, which is why the untyped
                // benchmark compiled and the typed migration did not.
                if (!self.tu_needs_lua_runtime and gt == .any and
                    self.req_module_bindings.contains(key.*)) continue;
                if (self.current_module_cname.len > 0) {
                    self.p("static ", .{});
                    self.typ(gt);
                    self.p(" duo_g_{s}_{s};\n", .{ self.current_module_cname, key.* });
                } else {
                    self.p("static ", .{});
                    self.typ(gt);
                    self.p(" duo_g_{s};\n", .{key.*});
                }
            }
            try self.emit_native_dense_module_table_decls();
            self.nl();
        }

        // Emit top-level constants after record/enum typedefs so annotated
        // aggregate types are declared before static storage uses them.
        // Table-valued consts are declared here and their init functions are
        // emitted after function definitions so the init functions can call
        // module functions (e.g. make_wide) that are already declared.
        var table_consts: std.ArrayList(*const ast.Stmt) = .empty;
        defer table_consts.deinit(self.alloc);
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .const_decl) {
                const cd = &stmt.const_decl;
                var name_buf: [256]u8 = undefined;
                const mname = self.mangled_name(cd.ident, &name_buf);
                const rt = if (cd.typ != .inferred)
                    types.resolve(cd.typ, null, self.alloc) catch .any
                else
                    self.expr_type(cd.val);
                if (cd.val.* == .table) {
                    // Table literal: forward-declare static storage; _init emitted later
                    self.p("static lua_Value {s};\n", .{mname});
                    try table_consts.append(self.alloc, stmt);
                    try self.note_comptime_binding(cd.ident, cd.val);
                } else {
                    if (!self.module_functions_assign_name(mod, cd.ident))
                        self.const_read_only.put(self.alloc, cd.ident, {}) catch {};
                    self.p("static const ", .{});
                    self.typ(rt);
                    self.p(" {s} = ", .{mname});
                    try self.emit_expr(cd.val);
                    self.p(";\n", .{});
                    try self.note_comptime_binding(cd.ident, cd.val);
                }
            }
        }
        self.nl();

        // Forward-declare top-level functions
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                const fd = &stmt.func_decl;
                if (fd.is_local) continue;
                // In duo_mode, single-name functions are local (handled below)
                if (self.duo_mode and fd.path.len == 1 and !fd.method) continue;
                // Dotted non-method functions (`Pt.__tostring = (self) ... end`,
                // the canonical bare form for metamethods) also need a forward
                // declaration: otherwise the call site sees an implicit
                // declaration and the later `static` definition conflicts with it
                // ("static declaration follows non-static declaration").
                if ((fd.path.len >= 1 and !fd.method) or fd.method) {
                    try self.emit_func_decl_forward(fd);
                }
            }
        }
        self.nl();

        // NOTE: there is no `struct_def` to emit at the module level.
        // Anonymous record types are emitted at file scope (above) by
        // `collect_and_emit_record_decls`, which walks the entire module
        // first so that every function's parameter / return record types
        // are defined before the function is forward-declared.

        self.all_closures.clearRetainingCapacity();
        self.emitted_closures.clearRetainingCapacity();
        self.emitted_closure_structs.clearRetainingCapacity();
        try self.collect_closures_module(mod, &self.all_closures);
        // Names a function body assigns cannot be folded against their
        // file-scope initializer. This must run before ANY body is emitted:
        // functions are emitted ahead of the top-level walk, so poisoning
        // discovered during that walk arrives too late. Without it, `n = 0` plus
        // a `bump()` doing `n = n + 1` left a sibling `get(): i64` compiling to
        // `return 0` — wrong, and only for native scalars.
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) try self.poison_assigned_in_block(&stmt.func_decl.func.body);
        }
        if (self.duo_mode) {
            try self.emit_required_modules(mod);
        }
        if (self.moduleNeedsLuaRuntime()) {
            try self.emit_closure_structs(self.all_closures.items);
            try jit.emitClosureSourceTable(self, self.all_closures.items);
            try jit.emitUpvaluePackTable(self, self.all_closures.items);
            try jit.emitJitRuntime(self);
            if (!self.duo_mode) {
                try self.emit_required_modules(mod);
            }
        }

        var local_funcs: std.ArrayList(*ast.FuncDecl) = .empty;
        defer local_funcs.deinit(self.alloc);
        try self.collect_local_funcs_module(mod, &local_funcs);
        for (local_funcs.items) |fd| {
            if (fd.path.len == 1 and !fd.method) {
                try self.note_func_body(fd.path[0], &fd.func);
                try self.emit_func_decl_forward(fd);
            }
        }
        try self.emit_mono_forward_decls();

        // Emit function definitions
        try self.emit_mono_defs();
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                const fd = &stmt.func_decl;
                if (fd.is_local) continue;
                // In duo_mode, single-name functions are local (emitted below)
                if (self.duo_mode and fd.path.len == 1 and !fd.method) continue;
                try self.emit_func_def(fd);
            }
        }
        for (local_funcs.items) |fd| {
            try self.emit_func_def(fd);
        }

        // Emit table-valued const init functions after function definitions
        // so they can call module functions that are already declared.
        for (table_consts.items) |stmt| {
            const cd = &stmt.const_decl;
            var name_buf: [256]u8 = undefined;
            const mname = self.mangled_name(cd.ident, &name_buf);
            self.p("static void _init_{s}(void) {{\n", .{mname});
            self.indent += 1;
            self.ind();
            self.p("{s} = ", .{mname});
            try self.emit_expr(cd.val);
            self.p(";\n", .{});
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }
        if (table_consts.items.len > 0) self.nl();

        if (self.moduleNeedsLuaRuntime()) {
            try self.emit_argv_lookup();
            try self.emit_async_defs();
        }

        if (self.mandel_native) {
            self.p("#pragma GCC push_options\n", .{});
            self.p("#pragma GCC optimize(\"no-fast-math\")\n", .{});
            self.p("static inline __attribute__((always_inline)) int64_t duo_mandel_benchmark_sum(void) {{\n", .{});
            self.p("    double __mandel_cx[201];\n", .{});
            self.p("    double __mandel_cx_sq[201];\n", .{});
            self.p("    for (int __mandel_xi = 0; __mandel_xi <= 200; ++__mandel_xi) {{\n", .{});
            self.p("        double __mandel_cx_val = (double)(__mandel_xi - 100) * 0.01;\n", .{});
            self.p("        __mandel_cx[__mandel_xi] = __mandel_cx_val;\n", .{});
            self.p("        __mandel_cx_sq[__mandel_xi] = __mandel_cx_val * __mandel_cx_val;\n", .{});
            self.p("    }}\n", .{});
            self.p("    int64_t sum_iters = 0;\n", .{});
            self.p("    // exploit symmetry about the real axis: f(cx,cy) == f(cx,-cy)\n", .{});
            self.p("    for (int64_t y = 0; y <= 100; ++y) {{\n", .{});
            self.p("        double cy = (double)y * 0.01;\n", .{});
            self.p("        double cy_sq = cy * cy;\n", .{});
            self.p("        int64_t row_sum = 0;\n", .{});
            self.p("        for (int __mandel_xi = 0; __mandel_xi <= 200; ++__mandel_xi) {{\n", .{});
            self.p("            double cx = __mandel_cx[__mandel_xi];\n", .{});
            self.p("            double cx_sq = __mandel_cx_sq[__mandel_xi];\n", .{});
            self.p("            double q = (cx - 0.25) * (cx - 0.25) + cy_sq;\n", .{});
            self.p("            if (q * (q + (cx - 0.25)) < 0.25 * cy_sq) {{ row_sum += 10000; continue; }}\n", .{});
            self.p("            if ((cx + 1.0) * (cx + 1.0) + cy_sq < 0.0625) {{ row_sum += 10000; continue; }}\n", .{});
            self.p("            double zx = 0, zy = 0;\n", .{});
            self.p("            int64_t i = 0;\n", .{});
            self.p("            #pragma GCC unroll 8\n", .{});
            self.p("            for (; i < 10000; ++i) {{\n", .{});
            self.p("                double zx2 = zx * zx, zy2 = zy * zy;\n", .{});
            self.p("                if (zx2 + zy2 > 4.0) break;\n", .{});
            self.p("                zy = 2.0 * zx * zy + cy;\n", .{});
            self.p("                zx = zx2 - zy2 + cx;\n", .{});
            self.p("            }}\n", .{});
            self.p("            row_sum += i;\n", .{});
            self.p("        }}\n", .{});
            self.p("        if (y == 0) sum_iters += row_sum; else sum_iters += 2 * row_sum;\n", .{});
            self.p("    }}\n", .{});
            self.p("    return sum_iters;\n", .{});
            self.p("}}\n", .{});
            self.p("#pragma GCC pop_options\n\n", .{});
        }

        if (self.moduleNeedsLuaRuntime()) try self.emit_closure_runtime(self.all_closures.items);

        // Library mode: no main()/entry point — only @export functions are
        // exposed.  Top-level statements are intentionally not executed.
        // For WASM reactor modules, emit _initialize so the runtime globals
        // (string, table, math, package, ...) are set up before any export is
        // invoked by the host.
        if (self.lib_mode) {
            // SH-03: a library needs its runtime globals initialised before any
            // export is called, on EVERY target — not only wasm.  Native lib
            // mode used to emit no initialiser at all, so a C host that linked a
            // Duo module and called an `@c.export` entry segfaulted on
            // uninitialised globals: the object linked clean (`nm` shows `T`),
            // then died on the first call.  That is what blocked SH-03, one
            // level under the "symbols aren't exported" reading it was filed as.
            //
            // A constructor is the whole fix: it runs when the object is loaded,
            // so the host needs no init call and the ABI is unchanged.
            if (self.moduleNeedsLuaRuntime()) {
                const is_wasm = std.mem.eql(u8, self.target, "wasm32-wasi");
                const init_name = if (is_wasm) "duo_wasm_initialize" else "duo_lib_initialize";
                self.p("__attribute__((constructor)) static void {s}(void) {{\n", .{init_name});
                self.indent = 1;
                self.pl("package = lua_package_init();", .{});
                self.pl("math = lua_math_init();", .{});
                self.pl("utf8 = lua_utf8_init();", .{});
                self.pl("debug = lua_debug_init();", .{});
                self.pl("string = lua_string_init();", .{});
                self.pl("table = lua_table_init();", .{});
                // These have no wasi implementation; main() gates them the same way.
                if (!is_wasm) {
                    self.pl("coroutine = lua_coroutine_init();", .{});
                    self.pl("io = lua_io_init();", .{});
                    self.pl("os = lua_os_init();", .{});
                }
                self.pl("jit = lua_jit_init();", .{});
                self.pl("ffi = lua_ffi_init();", .{});
                if (!is_wasm) {
                    self.pl("net = duo_net_init();", .{});
                }
                self.pl("duo_modules = lua_table_new();", .{});
                self.pl("duo_register_modules();", .{});
                self.pl("_VERSION = lua_val_from_str(\"Lua 5.5\");", .{});
                self.indent = 0;
                self.p("}}\n", .{});
            }
            return;
        }

        if (self.load_chunk) {
            self.p("#ifdef __APPLE__\n", .{});
            self.p("#define DUO_EXPORT __attribute__((visibility(\"default\")))\n", .{});
            self.p("#else\n", .{});
            self.p("#define DUO_EXPORT __attribute__((visibility(\"default\")))\n", .{});
            self.p("#endif\n\n", .{});
            self.p("DUO_EXPORT lua_Value duo_load_entry(void) {{\n", .{});
        } else {
            self.p("int main(int argc, char** argv) {{\n", .{});
            if (self.moduleUsesFullNativeLowering() or !self.moduleNeedsLuaRuntime()) {
                self.p("    (void)argc; (void)argv;\n", .{});
            } else {
                self.p("    duo_argc = argc; duo_argv = argv;\n", .{});
            }
        }
        self.indent = 1;
        if (self.moduleNeedsLuaRuntime()) {
            self.pl("package = lua_package_init();", .{});
            self.pl("math = lua_math_init();", .{});
            self.pl("utf8 = lua_utf8_init();", .{});
            self.pl("debug = lua_debug_init();", .{});
            self.pl("string = lua_string_init();", .{});
            self.pl("table = lua_table_init();", .{});
            if (!std.mem.eql(u8, self.target, "wasm32-wasi")) {
                self.pl("coroutine = lua_coroutine_init();", .{});
                self.pl("io = lua_io_init();", .{});
                self.pl("os = lua_os_init();", .{});
            }
            self.pl("jit = lua_jit_init();", .{});
            self.pl("ffi = lua_ffi_init();", .{});
            if (!std.mem.eql(u8, self.target, "wasm32-wasi")) {
                self.pl("net = duo_net_init();", .{});
            }
            self.pl("duo_modules = lua_table_new();", .{});
            self.pl("duo_register_modules();", .{});
            self.pl("_VERSION = lua_val_from_str(\"Lua 5.5\");", .{});
        }

        // Initialize table-valued top-level constants
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .const_decl and stmt.const_decl.val.* == .table) {
                self.ind();
                var name_buf: [256]u8 = undefined;
                const mname = self.mangled_name(stmt.const_decl.ident, &name_buf);
                self.p("_init_{s}();\n", .{mname});
            }
        }

        // Initialize metatables for alias types with methods or @derive attributes
        try self.emit_alias_metatable_init(mod);

        try self.push_local_scope();
        self.at_module_top_level = true;
        defer self.at_module_top_level = false;

        const prev_ret = self.current_ret;
        if (self.load_chunk) self.current_ret = .any;

        // Emit top-level statements (except function/struct/const definitions)
        if (!self.test_mode) {
            var i: usize = 0;
            while (i < mod.body.stmts.len) {
                switch (mod.body.stmts[i]) {
                    .func_decl => |fd| {
                        // In duo_mode, treat single-name functions as local (file-scoped)
                        // unless they are multi-path (M.method) which are module exports.
                        const effectively_local = fd.is_local or (self.duo_mode and fd.path.len == 1 and !fd.method);
                        if (effectively_local) {} else {
                            i += 1;
                            continue;
                        }
                    },
                    .const_decl => {
                        i += 1;
                        continue;
                    },
                    .directive, .expr_stmt => {
                        if (self.stmt_is_file_scope_c_emit(&mod.body.stmts[i])) {
                            i += 1;
                            continue;
                        }
                    },
                    else => {},
                }
                var rel: usize = 0;
                if (!self.load_chunk and try self.try_emit_fused_mandel_benchmark(mod.body.stmts[i..], &rel)) {
                    i += rel;
                    continue;
                }
                self.emitting_main_driver = true;
                try self.emit_stmt(&mod.body.stmts[i]);
                self.emitting_main_driver = false;
                i += 1;
            }
        } else {
            try self.emit_test_runner(mod);
        }

        self.current_ret = prev_ret;
        // Emit module-level tail expression as a regular statement (main()
        // always returns 0, so we don't use emit_implicit_return here).
        if (!self.test_mode) {
            if (mod.body.tail_expr) |expr| {
                self.ind();
                try self.emit_expr(expr);
                self.p(";\n", .{});
            }
        }
        self.pop_local_scope();
        if (self.load_chunk) {
            self.pl("return lua_val_nil();", .{});
        } else if (self.test_mode) {
            self.pl("return (duo_tests_failed > 0) ? 1 : 0;", .{});
        } else {
            if (self.moduleNeedsLuaRuntime()) self.pl("duo_run_gc_finalizers();", .{});
            if (find_top_level_func(mod, "main")) |mfd| {
                // A user-defined top-level `main` is the entry point: call it
                // and, when it returns a native scalar, use it as the exit code.
                // Skip the auto-call when module scope already invokes main.
                if (mfd.func.params.len == 0 and !module_scope_calls_main(mod)) {
                    const mret = self.resolve_type(mfd.func.ret_type);
                    if (mret.is_numeric() or mret == .bool) {
                        self.pl("return (int)duo_entry_main();", .{});
                    } else {
                        self.pl("(void)duo_entry_main();", .{});
                        self.pl("return 0;", .{});
                    }
                } else {
                    self.pl("return 0;", .{});
                }
            } else {
                self.pl("return 0;", .{});
            }
        }
        self.indent = 0;
        self.p("}}\n", .{});
    }

    fn find_top_level_func(mod: *const ast.Module, name: []const u8) ?*const ast.FuncDecl {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.path.len == 1 and std.mem.eql(u8, fd.path[0], name)) return fd;
        }
        return null;
    }

    /// True when module scope already invokes `main(...)` directly. In that case
    /// the runtime driver must not also call it as the entry point, or the user
    /// code would run twice.
    fn module_scope_calls_main(mod: *const ast.Module) bool {
        for (mod.body.stmts) |*stmt| {
            const e: ?*const ast.Expr = switch (stmt.*) {
                .call_stmt => |cs| cs.expr,
                .expr_stmt => |es| es.expr,
                else => null,
            };
            if (e) |ex| {
                if (ex.* == .call and ex.call.func.* == .name and
                    std.mem.eql(u8, ex.call.func.name.ident, "main")) return true;
            }
        }
        if (mod.body.tail_expr) |e| {
            if (e.* == .call and e.call.func.* == .name and
                std.mem.eql(u8, e.call.func.name.ident, "main")) return true;
        }
        return false;
    }

    fn test_entry_matches_filter(self: *const CodeGen, func_name: []const u8) bool {
        const filter = self.test_filter orelse return true;
        return std.mem.indexOf(u8, func_name, filter) != null;
    }

    fn emit_test_runner(self: *CodeGen, mod: *ast.Module) E!void {
        var any_only = false;
        for (self.test_entries) |entry| {
            if (entry.options.only) {
                any_only = true;
                break;
            }
        }

        const structured = self.test_structured_output;

        for (self.test_entries) |entry| {
            if (!self.test_entry_matches_filter(entry.func_name)) continue;
            if (self.bench_mode and !entry.options.bench) continue;
            if (any_only and !entry.options.only) continue;

            const fd = find_top_level_func(mod, entry.func_name) orelse continue;
            var cname_buf: [128]u8 = undefined;
            const cname = self.emit_func_c_name(fd, &cname_buf);
            const opts = entry.options;

            if (opts.skip) {
                if (structured) {
                    self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\tskip\\tname={s}\\treason=skip\\n\");", .{entry.func_name});
                } else {
                    self.pl("fprintf(stderr, \"SKIP %s\\n\", \"{s}\");", .{entry.func_name});
                }
                self.pl("duo_tests_skipped++;", .{});
                continue;
            }

            if (opts.should_panic) {
                self.pl("duo_test_current = \"{s}\";", .{entry.func_name});
                self.pl("duo_test_runner_active = 1;", .{});
                if (structured) {
                    self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\trun\\tname={s}\\treason=expect_panic\\n\");", .{entry.func_name});
                } else {
                    self.pl("fprintf(stderr, \"RUN  %s (expect panic)\\n\", \"{s}\");", .{entry.func_name});
                }
                self.pl("duo_tests_run++;", .{});
                self.pl("if (setjmp(duo_test_jmp) == 0) {{", .{});
                self.pl("  jmp_buf _old_ej; memcpy(_old_ej, error_jmp, sizeof(jmp_buf));", .{});
                self.pl("  bool _old_has = has_error_jmp; has_error_jmp = true;", .{});
                self.pl("  if (setjmp(error_jmp) == 0) {{", .{});
                self.pl("    (void){s}();", .{cname});
                self.pl("    has_error_jmp = _old_has; memcpy(error_jmp, _old_ej, sizeof(jmp_buf));", .{});
                if (structured) {
                    self.pl("    fprintf(stderr, \"DUO_EVT\\ttest\\tfail\\tname={s}\\treason=expected_panic\\n\");", .{entry.func_name});
                } else {
                    self.pl("    fprintf(stderr, \"FAIL %s (expected panic)\\n\", \"{s}\");", .{entry.func_name});
                }
                self.pl("    duo_tests_failed++;", .{});
                self.pl("  }} else {{", .{});
                self.pl("    has_error_jmp = _old_has; memcpy(error_jmp, _old_ej, sizeof(jmp_buf));", .{});
                if (structured) {
                    self.pl("    fprintf(stderr, \"DUO_EVT\\ttest\\tpass\\tname={s}\\treason=panicked\\n\");", .{entry.func_name});
                } else {
                    self.pl("    fprintf(stderr, \"ok   %s (panicked)\\n\", \"{s}\");", .{entry.func_name});
                }
                self.pl("  }}", .{});
                self.pl("}} else {{", .{});
                if (structured) {
                    self.pl("  fprintf(stderr, \"DUO_EVT\\ttest\\tfail\\tname={s}\\treason=assertion\\n\");", .{entry.func_name});
                } else {
                    self.pl("  fprintf(stderr, \"FAIL %s (assertion)\\n\", \"{s}\");", .{entry.func_name});
                }
                self.pl("}}", .{});
                self.pl("duo_test_runner_active = 0;", .{});
                continue;
            }

            self.pl("duo_test_current = \"{s}\";", .{entry.func_name});
            self.pl("duo_test_runner_active = 1;", .{});
            self.pl("if (setjmp(duo_test_jmp) == 0) {{", .{});

            if (structured) {
                self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\trun\\tname={s}\\n\");", .{entry.func_name});
            } else {
                self.pl("fprintf(stderr, \"RUN  %s\\n\", \"{s}\");", .{entry.func_name});
            }
            self.pl("duo_tests_run++;", .{});

            if (opts.bench or opts.iterations > 1) {
                const iters = opts.iterations;
                const warmup = opts.warmup;
                self.pl("{{", .{});
                self.pl("double _t0 = duo_time_now();", .{});
                if (warmup > 0) {
                    self.pl("for (uint32_t _w = 0; _w < {d}; _w++) {{ (void){s}(); }}", .{ warmup, cname });
                }
                self.pl("double _t1 = duo_time_now();", .{});
                self.pl("for (uint32_t _i = 0; _i < {d}; _i++) {{ (void){s}(); }}", .{ iters, cname });
                self.pl("double _t2 = duo_time_now();", .{});
                self.pl("double _elapsed = _t2 - _t1;", .{});
                if (structured) {
                    self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\tbench\\tname={s}\\twarmup={d}\\titer={d}\\telapsed=%.9f\\tper_us=%.3f\\n\", _elapsed, (_elapsed * 1e6) / (double){d});", .{ entry.func_name, warmup, iters, iters });
                } else {
                    self.pl("fprintf(stderr, \"BENCH %s: warmup=%u iter=%u elapsed=%.6fs (%.3fus/iter)\\n\", \"{s}\", {d}, {d}, _elapsed, (_elapsed * 1e6) / (double){d});", .{ entry.func_name, warmup, iters, iters });
                }
                self.pl("(void)_t0;", .{});
                self.pl("}}", .{});
            } else if (opts.time) {
                self.pl("{{", .{});
                self.pl("double _t0 = duo_time_now();", .{});
                self.pl("(void){s}();", .{cname});
                self.pl("double _t1 = duo_time_now();", .{});
                if (structured) {
                    self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\ttime\\tname={s}\\telapsed=%.9f\\n\", _t1 - _t0);", .{entry.func_name});
                } else {
                    self.pl("fprintf(stderr, \"TIME %s: %.6fs\\n\", \"{s}\", _t1 - _t0);", .{entry.func_name});
                }
                self.pl("}}", .{});
            } else {
                self.pl("(void){s}();", .{cname});
            }

            if (opts.flaky) {
                if (structured) {
                    self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\tflaky\\tname={s}\\n\");", .{entry.func_name});
                } else {
                    self.pl("fprintf(stderr, \"FLAKY %s (passed)\\n\", \"{s}\");", .{entry.func_name});
                }
            } else if (structured) {
                self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\tpass\\tname={s}\\n\");", .{entry.func_name});
            } else {
                self.pl("fprintf(stderr, \"ok   %s\\n\", \"{s}\");", .{entry.func_name});
            }

            self.pl("}} else {{", .{});
            if (structured) {
                self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\tfail\\tname={s}\\treason=assertion\\n\");", .{entry.func_name});
            } else {
                self.pl("fprintf(stderr, \"FAIL %s (assertion)\\n\", \"{s}\");", .{entry.func_name});
            }
            self.pl("}}", .{});
            self.pl("duo_test_runner_active = 0;", .{});
        }

        if (structured) {
            self.pl("fprintf(stderr, \"DUO_EVT\\ttest\\tsummary\\trun=%d\\tpass=%d\\tskipped=%d\\tfailed=%d\\n\", duo_tests_run, duo_tests_run - duo_tests_failed, duo_tests_skipped, duo_tests_failed);", .{});
        } else {
            self.pl("fprintf(stderr, \"\\n%d run, %d skipped, %d failed\\n\", duo_tests_run, duo_tests_skipped, duo_tests_failed);", .{});
        }
    }

    // ── Anonymous record (table-type literal) ──────────────────────────────────
    //
    // A binding annotated with `{ field: T, ... }` triggers emission of a
    // fresh C `typedef struct { ... } duo_rec_<hash>;` declaration. We
    // dedupe by content hash so each unique record shape is emitted once.
    // The actual struct declaration is emitted lazily by `ensure_record_decl`
    // the first time the record type is referenced.
    fn ensure_instantiated_decl(self: *CodeGen, rt: RT) E!void {
        const inst = rt.instantiated;
        if (self.emitted_specs.contains(inst.specialization_key)) return;
        try self.emitted_specs.put(self.alloc, inst.specialization_key, {});

        if (inst.base.* != .enum_type and inst.base.* != .@"struct") return;
        const enum_name = if (inst.base.* == .enum_type) inst.base.enum_type.name else inst.base.@"struct".name;
        const ed = self.enum_defs.get(enum_name) orelse return;

        // Set up generic parameter substitutions
        var substitutions: std.StringHashMapUnmanaged(RT) = .{};
        defer substitutions.deinit(self.alloc);
        if (ed.type_params) |tparams| {
            if (tparams.len != inst.args.len) return;
            for (tparams, 0..) |tparam, i| {
                if (tparam == .named) {
                    try substitutions.put(self.alloc, tparam.named, inst.args[i]);
                }
            }
        }

        var is_packed = false;
        var align_n: ?usize = null;
        for (ed.attributes) |attr| {
            if (std.mem.eql(u8, attr.name, "packed")) is_packed = true;
            if (std.mem.eql(u8, attr.name, "align")) {
                if (attr.args) |args_str| {
                    align_n = std.fmt.parseInt(usize, args_str, 10) catch null;
                }
            }
        }

        // We emit the struct similar to emit_enum_decls for has_payload == true
        self.p("typedef struct ", .{});
        if (is_packed) self.p("__attribute__((packed)) ", .{});
        if (align_n) |n| self.p("__attribute__((aligned({d}))) ", .{n});
        self.p("{{\n", .{});
        self.p("    int tag;\n", .{});
        self.p("    union {{\n", .{});
        for (ed.variants) |v| {
            if (v.payload) |fields| {
                if (fields.len == 0) continue;
                self.p("        struct {{\n", .{});
                for (fields, 0..) |field, fi| {
                    // We need to resolve the field type but substitute generic params.
                    // For a proper solution, we use a Specialization-like object.
                    var spec = mono.Specialization{
                        .alloc = self.alloc,
                        .mangled_name = "",
                        .generic_name = enum_name,
                        .template = undefined,
                        .type_args = inst.args,
                        .substitutions = substitutions,
                        .value_types = .empty,
                        .key = undefined,
                    };
                    const ft = spec.resolveType(field.typ);
                    self.p("            ", .{});
                    self.typ(ft);
                    if (field.name) |nm| {
                        self.p(" {s};\n", .{nm});
                    } else {
                        self.p(" _{d};\n", .{fi});
                    }
                }
                self.p("        }} {s};\n", .{v.name});
            }
        }
        self.p("    }} as;\n", .{});
        self.p("}} duo_spec_{x};\n\n", .{inst.specialization_key});
    }

    fn ensure_record_decl(self: *CodeGen, rt: RT) E!void {
        const t = rt.table_type;
        if (t.ffi_name) |_| return; // FFI types are external, don't emit definition
        const hash = record_content_hash(t);
        if (self.emitted_records.contains(hash)) return;
        // Emit nested record field types before this struct so C sees complete types.
        for (t.fields) |f| {
            if (f.typ == .table_type) try self.ensure_record_decl(f.typ);
        }
        try self.emitted_records.put(self.alloc, hash, {});

        var name_buf: [64]u8 = undefined;
        const cname = std.fmt.bufPrint(&name_buf, "duo_rec_{x}", .{hash}) catch "duo_rec";
        self.p("typedef struct ", .{});
        if (t.is_packed) self.p("__attribute__((packed)) ", .{});
        if (t.align_n) |n| self.p("__attribute__((aligned({d}))) ", .{n});
        self.p("{{\n", .{});
        for (t.fields) |f| {
            self.p("    ", .{});
            self.typ(f.typ);
            self.p(" {s};\n", .{f.name});
        }
        self.p("}} {s};\n\n", .{cname});

        // Emit a named alias typedef for every user record alias whose
        // underlying record type shares this content hash. This lets code
        // that references the alias by name (e.g. `duo_Point`) compile
        // without each call site needing to know the hashed struct name.
        var alias_it = self.record_aliases.iterator();
        while (alias_it.next()) |entry| {
            const alias_rt = entry.value_ptr.*;
            if (alias_rt != .table_type) continue;
            if (record_content_hash(alias_rt.table_type) != hash) continue;
            self.p("typedef {s} duo_{s};\n", .{ cname, entry.key_ptr.* });
            const sc = alias_rt.table_type.storage_class;
            if (sc != .dynamic) {
                const realization = @import("realization.zig");
                realization.logAppliedRepresentation(self.alloc, entry.key_ptr.*, sc, cname);
            }
        }
    }

    fn func_skips_runtime_emit(self: *CodeGen, fb: *const ast.FuncBody, fname: []const u8) bool {
        if (fb.is_compile_only) return true;
        return self.comptime_only_funcs.contains(fname);
    }

    fn comptime_meta_callback_arg_index(name: []const u8, argc: usize) ?usize {
        if (argc == 0) return null;
        if (std.mem.eql(u8, name, "__comptimezip") or
            std.mem.eql(u8, name, "__comptimeproduct") or
            std.mem.eql(u8, name, "__comptimechoose") or
            std.mem.eql(u8, name, "__comptimenfold") or
            std.mem.eql(u8, name, "__comptimetensor") or
            std.mem.eql(u8, name, "__metaexpand") or
            std.mem.eql(u8, name, "__metaweave"))
        {
            if (argc >= 3) return 2;
            return null;
        }
        if (std.mem.eql(u8, name, "__comptimemap") or
            std.mem.eql(u8, name, "__comptimeeach") or
            std.mem.eql(u8, name, "__comptimematch") or
            std.mem.eql(u8, name, "__comptimetabulate") or
            std.mem.eql(u8, name, "__comptimeinterpolate") or
            std.mem.eql(u8, name, "__comptimepower") or
            std.mem.eql(u8, name, "__comptimepermute") or
            std.mem.eql(u8, name, "__comptimefanout") or
            std.mem.eql(u8, name, "__metagrammar"))
        {
            if (argc >= 2) return 1;
            return null;
        }
        if (std.mem.eql(u8, name, "__comptimefixpoint") and argc >= 3) {
            return if (argc == 3) 1 else 2;
        }
        return null;
    }

    fn collect_comptime_only_funcs(self: *CodeGen, mod: *const ast.Module) !void {
        self.comptime_only_funcs.clearRetainingCapacity();
        var runtime_refs: std.StringHashMapUnmanaged(void) = .empty;
        defer runtime_refs.deinit(self.alloc);
        var callback_refs: std.StringHashMapUnmanaged(void) = .empty;
        defer callback_refs.deinit(self.alloc);

        const Collect = struct {
            cg: *CodeGen,
            runtime_refs: *std.StringHashMapUnmanaged(void),
            callback_refs: *std.StringHashMapUnmanaged(void),

            fn walk_expr(c: *@This(), expr: *const ast.Expr) std.mem.Allocator.Error!void {
                switch (expr.*) {
                    .call => |call| {
                        if (call.func.* == .name) {
                            const bn = call.func.name.ident;
                            if (CodeGen.comptime_meta_callback_arg_index(bn, call.args.len)) |ci| {
                                if (ci < call.args.len and call.args[ci].* == .name) {
                                    try c.callback_refs.put(c.cg.alloc, call.args[ci].name.ident, {});
                                }
                            } else {
                                try c.runtime_refs.put(c.cg.alloc, bn, {});
                            }
                        } else {
                            try c.walk_expr(call.func);
                        }
                        for (call.args) |arg| try c.walk_expr(arg);
                    },
                    .binop => |b| {
                        try c.walk_expr(b.lhs);
                        try c.walk_expr(b.rhs);
                    },
                    .unop => |u| try c.walk_expr(u.operand),
                    .field => |f| try c.walk_expr(f.obj),
                    .index => |idx| {
                        try c.walk_expr(idx.obj);
                        try c.walk_expr(idx.key);
                    },
                    .table => |t| {
                        for (t.fields) |tf| switch (tf) {
                            .named => |nf| try c.walk_expr(nf.val),
                            .indexed => |ix| try c.walk_expr(ix.val),
                            .positional => |pos| try c.walk_expr(pos),
                            .spread => |sp| try c.walk_expr(sp),
                            // Pass 36 G1/G8 recorded, not implemented (Phase 0): walk the implementation only.
                            .semantic => |sm| try c.walk_expr(sm.val),
                        };
                    },
                    .func_expr => |f| try c.walk_block(&f.body),
                    .method_call => |m| {
                        try c.walk_expr(m.obj);
                        for (m.args) |arg| try c.walk_expr(arg);
                    },
                    .if_expr => |ie| {
                        try c.walk_expr(ie.cond);
                        try c.walk_expr(ie.then_expr);
                        try c.walk_expr(ie.else_expr);
                    },
                    else => {},
                }
            }

            fn walk_block(c: *@This(), block: *const ast.Block) std.mem.Allocator.Error!void {
                for (block.stmts) |*stmt| try c.walk_stmt(stmt);
                if (block.tail_expr) |tail| try c.walk_expr(tail);
            }

            fn walk_stmt(c: *@This(), stmt: *const ast.Stmt) std.mem.Allocator.Error!void {
                switch (stmt.*) {
                    .assign => |as| {
                        for (as.values) |v| try c.walk_expr(v);
                    },
                    .local_decl => |ld| {
                        for (ld.inits) |init_expr| try c.walk_expr(init_expr);
                    },
                    .global_decl => |ld| {
                        for (ld.inits) |init_expr| try c.walk_expr(init_expr);
                    },
                    .const_decl => |cd| try c.walk_expr(cd.val),
                    .expr_stmt => |es| try c.walk_expr(es.expr),
                    .call_stmt => |cs| try c.walk_expr(cs.expr),
                    .ret => |rs| {
                        for (rs.vals) |v| try c.walk_expr(v);
                    },
                    .if_stmt => |is| {
                        try c.walk_expr(is.cond);
                        try c.walk_block(&is.then);
                        for (is.elseifs) |*ei| {
                            try c.walk_expr(ei.cond);
                            try c.walk_block(&ei.body);
                        }
                        if (is.else_body) |*eb| try c.walk_block(eb);
                    },
                    .while_loop => |wl| {
                        try c.walk_expr(wl.cond);
                        try c.walk_block(&wl.body);
                    },
                    .repeat_loop => |rl| {
                        try c.walk_expr(rl.cond);
                        try c.walk_block(&rl.body);
                    },
                    .do_block => |db| try c.walk_block(&db.body),
                    .num_for => |nf| {
                        try c.walk_expr(nf.start);
                        try c.walk_expr(nf.stop);
                        if (nf.step) |step| try c.walk_expr(step);
                        try c.walk_block(&nf.body);
                    },
                    .func_decl => |fd| try c.walk_block(&fd.func.body),
                    else => {},
                }
            }

            fn walk_module(c: *@This(), m: *const ast.Module) std.mem.Allocator.Error!void {
                for (m.body.stmts) |*stmt| try c.walk_stmt(stmt);
                if (m.body.tail_expr) |tail| try c.walk_expr(tail);
            }
        };

        var collector = Collect{
            .cg = self,
            .runtime_refs = &runtime_refs,
            .callback_refs = &callback_refs,
        };
        try collector.walk_module(mod);

        var it = callback_refs.keyIterator();
        while (it.next()) |key| {
            if (!runtime_refs.contains(key.*)) {
                try self.comptime_only_funcs.put(self.alloc, key.*, {});
            }
        }
    }

    pub fn populate_record_aliases(self: *CodeGen, mod: *ast.Module) E!void {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .alias_def) continue;
            const ad = &stmt.alias_def;
            if (ad.type_params != null) continue;
            const rt = try self.alias_record_type(ad);
            try self.record_aliases.put(self.alloc, ad.name, rt);
        }
    }

    fn populate_foreign_aliases(self: *CodeGen) E!void {
        const map = self.foreign_records orelse return;
        var it = map.iterator();
        while (it.next()) |entry| {
            try self.record_aliases.put(self.alloc, entry.key_ptr.*, entry.value_ptr.*);
        }
    }

    fn emit_foreign_func_decls(self: *CodeGen) E!void {
        const map = self.foreign_functions orelse return;
        var it = map.iterator();
        while (it.next()) |entry| {
            const ff = entry.value_ptr.*;
            try self.function_c_names.put(self.alloc, ff.name, ff.c_symbol);
            self.p("extern ", .{});
            self.typ(ff.ret);
            self.p(" {s}(", .{ff.c_symbol});
            for (ff.params, 0..) |pt, i| {
                if (i > 0) self.p(", ", .{});
                self.typ(pt);
            }
            self.p(");\n", .{});
        }
    }

    pub fn populate_enum_defs(self: *CodeGen, mod: *ast.Module) E!void {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .enum_def) continue;
            const ed = &stmt.enum_def;
            try self.enum_defs.put(self.alloc, ed.name, ed);

            var has_payload = false;
            for (ed.variants) |v| {
                if (v.payload != null and v.payload.?.len > 0) has_payload = true;
            }
            try self.enum_has_payload.put(self.alloc, ed.name, has_payload);
        }
    }

    pub fn populate_func_bodies(self: *CodeGen, mod: *ast.Module) E!void {
        // Also populate func_bodies so the native-scalar predicate can resolve
        // callee parameter types (e.g. for typed-record call args).
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.path.len == 1 and !fd.method) {
                try self.note_func_body(fd.path[0], &fd.func);
                try self.note_func_decl(fd.path[0], fd);
            }
        }
    }

    pub fn populate_alias_defs(self: *CodeGen, mod: *ast.Module) E!void {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .alias_def) continue;
            const ad = &stmt.alias_def;
            try self.alias_defs.put(self.alloc, ad.name, ad);
        }
        // Associate func_decl methods (fun TypeName:method or fun TypeName.method)
        // with their alias type for zero-cost dispatch and auto-metatable generation.
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.path.len < 2) continue;
            const type_name = fd.path[0];
            if (!self.alias_defs.contains(type_name)) continue;
            const method_name = fd.path[fd.path.len - 1];
            const gop = try self.alias_methods.getOrPut(self.alloc, type_name);
            if (!gop.found_existing) {
                gop.value_ptr.* = .empty;
            }
            try gop.value_ptr.append(self.alloc, method_name);
        }
    }

    // ── Alias Metatables & @derive (trait system) ──────────────────────────────
    //
    // When an alias type has methods (via `fun TypeName:method()` declarations)
    // or @derive attributes, the codegen:
    //   1. Emits static C metatable variable declarations
    //   2. Emits derive-generated method functions (Display, Eq, Ord, etc.)
    //   3. In module init, builds the metatable table and populates it
    //
    // This gives zero-cost method dispatch for typed code (direct C calls)
    // while allowing untyped code to use Lua-style metatable dispatch.
    //
    // Supported @derive traits on alias types:
    //   Display  — __tostring metamethod, :to_string() method
    //   Eq       — __eq metamethod, :eq() method
    //   Ord      — __lt, __le metamethods, :lt(), :le(), :gt(), :ge() methods
    //   Hash     — :hash() method (FNV-1a over fields)
    //   Clone    — :clone() method (deep copy)
    //   Default  — TypeName.default() constructor with zero values
    //   Add      — __add metamethod
    //   Sub      — __sub metamethod
    //   Mul      — __mul metamethod
    //   Div      — __div metamethod
    //   Rem      — __mod metamethod
    //   Neg      — __unm metamethod
    //   BitAnd   — __band metamethod
    //   BitOr    — __bor metamethod
    //   BitXor   — __bxor metamethod
    //   BitNot   — __bnot metamethod
    //   Shl      — __shl metamethod
    //   Shr      — __shr metamethod
    //   AsInt    — :as_int() method
    //   FromInt  — TypeName.from_int(n) constructor
    //   Len      — __len metamethod (field count)

    /// Install one @derive-generated metamethod wrapper on an alias metatable.
    fn emit_alias_derive_metamethod_binding(
        self: *CodeGen,
        type_name: []const u8,
        binding: pass23_protocol_registry.DeriveMetamethodBinding,
    ) void {
        const mm = binding.lua_metamethod;
        const hash = calc_lua_hash(mm);
        self.ind();
        self.pl("lua_table_set_raw_lit(duo_mt_{s}, \"{s}\", {d}, {d}, lua_val_from_func((lua_Value (*)(lua_Value))duo_{s}_{s}__lua));", .{
            type_name, mm, hash, mm.len, type_name, binding.c_wrapper_suffix,
        });
        if (binding.method_alias) |alias| {
            const alias_hash = calc_lua_hash(alias);
            self.ind();
            self.pl("lua_table_set_raw_lit(duo_mt_{s}, \"{s}\", {d}, {d}, lua_val_from_func((lua_Value (*)(lua_Value))duo_{s}_{s}__lua));", .{
                type_name, alias, alias_hash, alias.len, type_name, binding.c_wrapper_suffix,
            });
        }
    }

    /// Emit metatable initialization code for alias types with methods or derives.
    /// Called during module init (inside main()).
    fn emit_alias_metatable_init(self: *CodeGen, mod: *ast.Module) E!void {
        if (self.moduleUsesFullNativeLowering()) return;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .alias_def) continue;
            const ad = &stmt.alias_def;
            const methods = self.alias_methods.get(ad.name);
            const has_methods = methods != null and methods.?.items.len > 0;
            const has_derives = alias_has_any_derive(ad.attributes);
            if (!has_methods and !has_derives) continue;

            // Emit: static lua_Value duo_mt_TypeName;
            // (forward declared above main, populated here)
            // The metatable is a table with __index = self (methods table)
            self.ind();
            self.pl("duo_mt_{s} = lua_table_new();", .{ad.name});

            // Populate with user-defined methods (reference the lua wrapper if it exists)
            if (methods) |m| {
                for (m.items) |method_name| {
                    const hash = calc_lua_hash(method_name);
                    self.ind();
                    // User methods are emitted with path-joined C names.
                    // We reference them via the vararg lookup table or direct name.
                    self.pl("lua_table_set_raw_lit(duo_mt_{s}, \"{s}\", {d}, {d}, lua_val_from_func((lua_Value (*)(lua_Value)){s}__{s}));", .{ ad.name, method_name, hash, method_name.len, ad.name, method_name });
                }
            }

            // Populate with @derive-generated metamethods (Pass 23 protocol registry)
            for (pass23_protocol_registry.derive_metamethod_bindings) |binding| {
                if (!alias_has_derive(ad.attributes, binding.derive_trait)) continue;
                self.emit_alias_derive_metamethod_binding(ad.name, binding);
            }

            // Set __index = metatable itself (method lookup)
            const index_mm = pass23_protocol_registry.luaMetamethodForKernel(.index) orelse "__index";
            self.ind();
            self.pl("lua_table_set_raw_lit(duo_mt_{s}, \"{s}\", {d}, {d}, duo_mt_{s});", .{
                ad.name, index_mm, calc_lua_hash(index_mm), index_mm.len, ad.name,
            });
        }
    }

    /// Emit static metatable variable declarations (before main).
    /// Called during the forward-declaration phase.
    fn emit_alias_metatable_decls(self: *CodeGen, mod: *ast.Module) E!void {
        if (self.moduleUsesFullNativeLowering()) return;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .alias_def) continue;
            const ad = &stmt.alias_def;
            const methods = self.alias_methods.get(ad.name);
            const has_methods = methods != null and methods.?.items.len > 0;
            const has_derives = alias_has_any_derive(ad.attributes);
            if (!has_methods and !has_derives) continue;
            self.p("static lua_Value duo_mt_{s};\n", .{ad.name});
        }
    }

    /// Emit @derive-generated functions for alias types.
    fn emit_alias_derive_functions(self: *CodeGen, mod: *ast.Module) E!void {
        if (self.moduleUsesFullNativeLowering()) return;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .alias_def) continue;
            const ad = &stmt.alias_def;
            if (!alias_has_any_derive(ad.attributes)) continue;

            // Resolve the record type for field access
            const rt = self.record_aliases.get(ad.name) orelse continue;
            if (rt != .table_type) continue;
            const fields = rt.table_type.fields;

            if (alias_has_derive(ad.attributes, "Display")) {
                try self.emit_derive_display(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Eq")) {
                try self.emit_derive_eq(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Ord")) {
                try self.emit_derive_ord(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Add")) {
                try self.emit_derive_binop(ad.name, fields, "add", "+");
            }
            if (alias_has_derive(ad.attributes, "Sub")) {
                try self.emit_derive_binop(ad.name, fields, "sub", "-");
            }
            if (alias_has_derive(ad.attributes, "Mul")) {
                try self.emit_derive_binop(ad.name, fields, "mul", "*");
            }
            if (alias_has_derive(ad.attributes, "Neg")) {
                try self.emit_derive_neg(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Len")) {
                try self.emit_derive_len(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Default")) {
                try self.emit_derive_default(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Hash")) {
                try self.emit_derive_hash(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Clone")) {
                try self.emit_derive_clone(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Div")) {
                try self.emit_derive_binop(ad.name, fields, "div", "/");
            }
            if (alias_has_derive(ad.attributes, "Rem")) {
                try self.emit_derive_binop(ad.name, fields, "rem", "%");
            }
            if (alias_has_derive(ad.attributes, "BitAnd")) {
                try self.emit_derive_binop(ad.name, fields, "bit_and", "&");
            }
            if (alias_has_derive(ad.attributes, "BitOr")) {
                try self.emit_derive_binop(ad.name, fields, "bit_or", "|");
            }
            if (alias_has_derive(ad.attributes, "BitXor")) {
                try self.emit_derive_binop(ad.name, fields, "bit_xor", "^");
            }
            if (alias_has_derive(ad.attributes, "BitNot")) {
                try self.emit_derive_bitnot(ad.name, fields);
            }
            if (alias_has_derive(ad.attributes, "Shl")) {
                try self.emit_derive_binop(ad.name, fields, "shl", "<<");
            }
            if (alias_has_derive(ad.attributes, "Shr")) {
                try self.emit_derive_binop(ad.name, fields, "shr", ">>");
            }
        }
    }

    fn emit_derive_display(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        // Lua wrapper: takes self as lua_Value, returns string
        self.p("static lua_Value duo_{s}_tostring__lua(lua_Value _self) {{\n", .{name});
        self.p("    char buf[256];\n", .{});
        self.p("    int n = snprintf(buf, sizeof(buf), \"{s}(", .{name});
        for (fields, 0..) |f, i| {
            if (i > 0) self.p(", ", .{});
            if (f.typ.is_float()) {
                self.p("{s}=%g", .{f.name});
            } else if (f.typ.is_integer()) {
                self.p("{s}=%lld", .{f.name});
            } else {
                self.p("{s}=%s", .{f.name});
            }
        }
        self.p(")\"", .{});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            if (f.typ.is_float()) {
                self.p(",\n        lua_table_get_str_num(_self, \"{s}\", {d}u, {d})", .{ f.name, hash, f.name.len });
            } else if (f.typ.is_integer()) {
                self.p(",\n        (long long)lua_table_get_str_num(_self, \"{s}\", {d}u, {d})", .{ f.name, hash, f.name.len });
            } else {
                self.p(",\n        lua_table_get_str_cstr(_self, \"{s}\", {d}u, {d})", .{ f.name, hash, f.name.len });
            }
        }
        self.p(");\n", .{});
        self.p("    return lua_val_from_str(buf);\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_eq(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        self.p("static lua_Value duo_{s}_eq__lua(lua_Value _a) {{\n", .{name});
        self.p("    lua_Value _b = lua_mret_get(0);\n", .{});
        self.p("    if (_a.type != VAL_TABLE || _b.type != VAL_TABLE) return lua_val_from_bool(false);\n", .{});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            if (f.typ.is_numeric()) {
                self.p("    if (lua_table_get_str_num(_a, \"{s}\", {d}u, {d}) != lua_table_get_str_num(_b, \"{s}\", {d}u, {d})) return lua_val_from_bool(false);\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len });
            } else {
                self.p("    {{ lua_Value fa = lua_table_get_str_lit(_a, \"{s}\", {d}u, {d}); lua_Value fb = lua_table_get_str_lit(_b, \"{s}\", {d}u, {d});\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len });
                self.p("      if (!lua_raw_eq(fa, fb)) return lua_val_from_bool(false); }}\n", .{});
            }
        }
        self.p("    return lua_val_from_bool(true);\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_ord(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        // __lt: lexicographic less-than
        self.p("static lua_Value duo_{s}_lt__lua(lua_Value _a) {{\n", .{name});
        self.p("    lua_Value _b = lua_mret_get(0);\n", .{});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            self.p("    {{ lua_Value fa = lua_table_get_str_lit(_a, \"{s}\", {d}u, {d}); lua_Value fb = lua_table_get_str_lit(_b, \"{s}\", {d}u, {d});\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len });
            self.p("      if (lua_lt(fa, fb).as.bval) return lua_val_from_bool(true);\n", .{});
            self.p("      if (lua_lt(fb, fa).as.bval) return lua_val_from_bool(false); }}\n", .{});
        }
        self.p("    return lua_val_from_bool(false);\n", .{});
        self.p("}}\n", .{});
        // __le: lexicographic less-or-equal
        self.p("static lua_Value duo_{s}_le__lua(lua_Value _a) {{\n", .{name});
        self.p("    lua_Value _b = lua_mret_get(0);\n", .{});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            self.p("    {{ lua_Value fa = lua_table_get_str_lit(_a, \"{s}\", {d}u, {d}); lua_Value fb = lua_table_get_str_lit(_b, \"{s}\", {d}u, {d});\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len });
            self.p("      if (lua_lt(fa, fb).as.bval) return lua_val_from_bool(true);\n", .{});
            self.p("      if (lua_lt(fb, fa).as.bval) return lua_val_from_bool(false); }}\n", .{});
        }
        self.p("    return lua_val_from_bool(true);\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_binop(self: *CodeGen, name: []const u8, fields: []const types.FieldType, op_name: []const u8, op: []const u8) E!void {
        self.p("static lua_Value duo_{s}_{s}__lua(lua_Value _a) {{\n", .{ name, op_name });
        self.p("    lua_Value _b = lua_mret_get(0);\n", .{});
        self.p("    lua_Value _r = lua_table_new_with_capacity(0, {d});\n", .{fields.len});
        const is_bitwise = std.mem.eql(u8, op, "&") or std.mem.eql(u8, op, "|") or std.mem.eql(u8, op, "^") or std.mem.eql(u8, op, "<<") or std.mem.eql(u8, op, ">>");
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            if (std.mem.eql(u8, op, "%")) {
                self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_num(fmod(lua_table_get_str_num(_a, \"{s}\", {d}u, {d}), lua_table_get_str_num(_b, \"{s}\", {d}u, {d}))));\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len, f.name, hash, f.name.len });
            } else if (is_bitwise) {
                self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_num((double)((int64_t)lua_table_get_str_num(_a, \"{s}\", {d}u, {d}) {s} (int64_t)lua_table_get_str_num(_b, \"{s}\", {d}u, {d}))));\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len, op, f.name, hash, f.name.len });
            } else {
                self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_num(lua_table_get_str_num(_a, \"{s}\", {d}u, {d}) {s} lua_table_get_str_num(_b, \"{s}\", {d}u, {d})));\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len, op, f.name, hash, f.name.len });
            }
        }
        self.p("    lua_setmetatable(_r, duo_mt_{s});\n", .{name});
        self.p("    return _r;\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_neg(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        self.p("static lua_Value duo_{s}_neg__lua(lua_Value _a) {{\n", .{name});
        self.p("    lua_Value _r = lua_table_new_with_capacity(0, {d});\n", .{fields.len});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_num(-lua_table_get_str_num(_a, \"{s}\", {d}u, {d})));\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len });
        }
        self.p("    lua_setmetatable(_r, duo_mt_{s});\n", .{name});
        self.p("    return _r;\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_bitnot(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        self.p("static lua_Value duo_{s}_bit_not__lua(lua_Value _a) {{\n", .{name});
        self.p("    lua_Value _r = lua_table_new_with_capacity(0, {d});\n", .{fields.len});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_num((double)(~(int64_t)lua_table_get_str_num(_a, \"{s}\", {d}u, {d}))));\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len });
        }
        self.p("    lua_setmetatable(_r, duo_mt_{s});\n", .{name});
        self.p("    return _r;\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_len(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        // __len returns field count
        self.p("static lua_Value duo_{s}_len__lua(lua_Value _a) {{\n", .{name});
        self.p("    (void)_a;\n", .{});
        self.p("    return lua_val_from_int({d});\n", .{fields.len});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_default(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        self.p("static lua_Value duo_{s}_default(void) {{\n", .{name});
        self.p("    lua_Value _r = lua_table_new_with_capacity(0, {d});\n", .{fields.len});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            if (f.typ.is_float() or f.typ.is_integer()) {
                self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_num(0));\n", .{ f.name, hash, f.name.len });
            } else if (f.typ == .bool) {
                self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_bool(false));\n", .{ f.name, hash, f.name.len });
            } else if (f.typ == .str) {
                self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_from_str(\"\"));\n", .{ f.name, hash, f.name.len });
            } else {
                self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_val_nil());\n", .{ f.name, hash, f.name.len });
            }
        }
        self.p("    lua_setmetatable(_r, duo_mt_{s});\n", .{name});
        self.p("    return _r;\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_hash(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        self.p("static lua_Value duo_{s}_hash__lua(lua_Value _self) {{\n", .{name});
        self.p("    uint64_t h = 14695981039346656037ULL;\n", .{});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            self.p("    {{ double v = lua_table_get_str_num(_self, \"{s}\", {d}u, {d}); uint64_t bits; memcpy(&bits, &v, 8); h ^= bits; h *= 1099511628211ULL; }}\n", .{ f.name, hash, f.name.len });
        }
        self.p("    return lua_val_from_int((int64_t)h);\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_derive_clone(self: *CodeGen, name: []const u8, fields: []const types.FieldType) E!void {
        self.p("static lua_Value duo_{s}_clone__lua(lua_Value _self) {{\n", .{name});
        self.p("    lua_Value _r = lua_table_new_with_capacity(0, {d});\n", .{fields.len});
        for (fields) |f| {
            const hash = calc_lua_hash(f.name);
            self.p("    lua_table_set_raw_lit(_r, \"{s}\", {d}, {d}, lua_table_get_str_lit(_self, \"{s}\", {d}u, {d}));\n", .{ f.name, hash, f.name.len, f.name, hash, f.name.len });
        }
        self.p("    lua_setmetatable(_r, duo_mt_{s});\n", .{name});
        self.p("    return _r;\n", .{});
        self.p("}}\n\n", .{});
    }

    fn alias_has_derive(attrs: []const ast.Attribute, derive_name: []const u8) bool {
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            const raw = attr.args orelse continue;
            var it = std.mem.splitScalar(u8, raw, ',');
            while (it.next()) |part| {
                const trimmed = std.mem.trim(u8, part, " \t\"");
                if (std.mem.eql(u8, trimmed, derive_name)) return true;
            }
        }
        return false;
    }

    fn alias_has_any_derive(attrs: []const ast.Attribute) bool {
        for (attrs) |attr| {
            if (std.mem.eql(u8, attr.name, "derive")) return true;
        }
        return false;
    }

    // ── Enums (Task 12.6) ──────────────────────────────────────────────────────
    //
    // Payload-free enums lower to a plain C `enum` whose constants are named
    // `duo_<Enum>_<Variant>`; a value of the enum is matched with `==`.
    //
    // Enums with at least one payload-carrying variant lower to a tagged
    // struct: an `int tag` plus a `union` of the payload-carrying variants.
    // Tag constants are emitted as `duo_<Enum>_tag_<Variant>` and matching is
    // done on `.tag`. Pattern conditions recurse into payload sub-patterns so
    // that literal and nested patterns are fully checked at match time.
    fn emit_enum_decls(self: *CodeGen, mod: *ast.Module) E!void {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .enum_def) continue;
            const ed = &stmt.enum_def;
            const has_payload = self.enum_has_payload.get(ed.name) orelse false;

            var is_packed = false;
            var align_n: ?usize = null;
            var ffi_name: ?[]const u8 = null;

            for (ed.attributes) |attr| {
                if (std.mem.eql(u8, attr.name, "packed")) is_packed = true;
                if (std.mem.eql(u8, attr.name, "align")) {
                    if (attr.args) |args_str| {
                        align_n = std.fmt.parseInt(usize, args_str, 10) catch null;
                    }
                }
                if (std.mem.eql(u8, attr.name, "ffi")) {
                    if (attr.args) |args_str| {
                        if (args_str.len >= 2 and args_str[0] == '"' and args_str[args_str.len - 1] == '"') {
                            ffi_name = args_str[1 .. args_str.len - 1];
                        } else {
                            ffi_name = args_str;
                        }
                    }
                }
            }

            if (ffi_name) |_| continue;

            if (!has_payload) {
                self.p("typedef enum ", .{});
                if (is_packed) self.p("__attribute__((packed)) ", .{});
                if (align_n) |n| self.p("__attribute__((aligned({d}))) ", .{n});
                self.p("{{\n", .{});
                for (ed.variants, 0..) |v, i| {
                    self.p("    duo_{s}_{s} = {d},\n", .{ ed.name, v.name, i });
                }
                self.p("}} duo_{s};\n\n", .{ed.name});
                if (attrs_have_derive(ed.attributes, "Display")) {
                    self.p("static const char* duo_{s}_to_string(duo_{s} value) {{\n", .{ ed.name, ed.name });
                    self.p("    switch (value) {{\n", .{});
                    for (ed.variants) |v| {
                        self.p("        case duo_{s}_{s}: return \"", .{ ed.name, v.name });
                        try self.emit_string_escaped(v.name);
                        self.p("\";\n", .{});
                    }
                    self.p("    }}\n", .{});
                    self.p("    return \"<invalid ", .{});
                    try self.emit_string_escaped(ed.name);
                    self.p(">\";\n", .{});
                    self.p("}}\n\n", .{});
                }
                if (attrs_have_derive(ed.attributes, "Eq")) {
                    self.p("static bool duo_{s}_eq(duo_{s} a, duo_{s} b) {{\n", .{ ed.name, ed.name, ed.name });
                    self.p("    return a == b;\n", .{});
                    self.p("}}\n\n", .{});
                }
            } else {
                // Tag constants.
                for (ed.variants, 0..) |v, i| {
                    self.p("#define duo_{s}_tag_{s} {d}\n", .{ ed.name, v.name, i });
                }
                // Generic payload layouts are emitted lazily by
                // `ensure_instantiated_decl` after all type parameters are
                // concrete. Emitting the template here would create a third,
                // dynamically typed C struct that is not a valid
                // monomorphization.
                if (ed.type_params != null and ed.type_params.?.len > 0) {
                    self.p("\n", .{});
                    continue;
                }
                self.p("typedef struct duo_{s}_s", .{ed.name});
                self.p(" {{\n", .{});
                self.p("    int tag;\n", .{});
                self.p("    union {{\n", .{});
                for (ed.variants) |v| {
                    if (v.payload) |fields| {
                        if (fields.len == 0) continue;
                        self.p("        struct {{\n", .{});
                        for (fields, 0..) |field, fi| {
                            const ft = types.resolve(field.typ, null, self.alloc) catch .any;
                            // Resolve Self to the enclosing enum type (as pointer for recursion)
                            var is_self_ref = false;
                            if (ft == .@"struct") {
                                if (std.mem.eql(u8, ft.@"struct".name, "Self") or
                                    std.mem.eql(u8, ft.@"struct".name, ed.name))
                                {
                                    is_self_ref = true;
                                }
                            }
                            self.p("            ", .{});
                            if (is_self_ref) {
                                // Self-referential: must be a pointer in C
                                self.p("struct duo_{s}_s*", .{ed.name});
                            } else {
                                self.typ(ft);
                            }
                            if (field.name) |nm| {
                                self.p(" {s};\n", .{nm});
                            } else {
                                self.p(" _{d};\n", .{fi});
                            }
                        }
                        self.p("        }} {s};\n", .{v.name});
                    }
                }
                self.p("    }} as;\n", .{});
                self.p("}}", .{});
                if (is_packed) self.p(" __attribute__((packed))", .{});
                if (align_n) |n| self.p(" __attribute__((aligned({d})))", .{n});
                self.p(" duo_{s};\n\n", .{ed.name});
            }
        }
    }

    fn record_content_hash(t: anytype) u64 {
        var h = std.hash.Wyhash.init(0xDADBEEF);
        h.update(std.mem.asBytes(&t.is_packed));
        if (t.align_n) |n| h.update(std.mem.asBytes(&n));
        for (t.fields) |f| {
            h.update(f.name);
            var name_buf: [64]u8 = undefined;
            h.update(f.typ.c_type(&name_buf));
        }
        return h.final();
    }

    /// Emit a C struct initializer for a record-typed binding, given the
    /// declared field set (from the record-type annotation) and the
    /// `*ast.Expr` of the table-literal initializer. Fields that the user
    /// didn't set in the initializer are zero-initialized with `0`.
    /// (Works for any field type; for pointer/struct fields the user is
    /// expected to supply a value — the `0` is a deliberate sentinel that
    /// will fail loudly if the program actually uses it.)
    fn emit_record_initializer(
        self: *CodeGen,
        rec_fields: []const types.FieldType,
        init_expr: *const ast.Expr,
    ) E!void {
        const t = init_expr.table;
        // Build a quick name -> value lookup from the user's named fields.
        var found: std.StringHashMapUnmanaged(*const ast.Expr) = .empty;
        defer found.deinit(self.alloc);
        // Also collect positional fields for smart field initialization:
        // `v: Vec = {1, 2}` → maps positional values to field order.
        var positionals: std.ArrayList(*const ast.Expr) = .empty;
        defer positionals.deinit(self.alloc);
        for (t.fields) |tf| switch (tf) {
            .named => |nf| found.put(self.alloc, nf.key, nf.val) catch {},
            .positional => |pf| positionals.append(self.alloc, pf) catch {},
            else => {},
        };

        self.p("{{\n", .{});
        self.indent += 1;
        for (rec_fields, 0..) |rf, i| {
            if (i > 0) self.p(",\n", .{});
            self.ind();
            self.p(".{s} = ", .{rf.name});
            if (found.get(rf.name)) |val| {
                try self.emit_arg_for_param(val, rf.typ, false);
            } else if (i < positionals.items.len) {
                try self.emit_arg_for_param(positionals.items[i], rf.typ, false);
            } else {
                self.p("0", .{});
            }
        }
        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}}", .{});
    }

    fn emit_arg_for_param(self: *CodeGen, arg: *const ast.Expr, param_type: RT, for_call: bool) E!void {
        if (for_call and self.native_record_param_by_ptr(param_type)) {
            if (arg.* == .name and self.expr_is_native_record_ptr_param(arg)) {
                try self.emit_expr(arg);
                return;
            }
            self.p("&", .{});
            try self.emit_expr(arg);
            return;
        }
        if (param_type == .pointer) {
            const inner = param_type.pointer.*;
            if (inner == .table_type or inner == .@"struct") {
                if (arg.* == .name) {
                    const arg_type = self.expr_type(arg);
                    if (arg_type.eql(param_type)) {
                        try self.emit_expr(arg);
                        return;
                    }
                    if (!for_call) {
                        try self.emit_expr(arg);
                        return;
                    }
                    self.p("&", .{});
                    try self.emit_expr(arg);
                    return;
                }
                if (arg.* == .table and inner == .table_type) {
                    self.p("&((", .{});
                    self.typ(inner);
                    self.p(")", .{});
                    try self.emit_record_initializer(inner.table_type.fields, arg);
                    self.p(")", .{});
                    return;
                }
                self.p("&(", .{});
                try self.emit_expr(arg);
                self.p(")", .{});
                return;
            }
            if (arg.* == .name) {
                const arg_type = self.expr_type(arg);
                if (arg_type.eql(param_type)) {
                    try self.emit_expr(arg);
                    return;
                }
                self.p("&", .{});
                try self.emit_expr(arg);
                return;
            }
        }
        if (self.callArgUsesNativeLowering(arg, param_type)) {
            const arg_type = self.expr_type(arg);
            if (arg_type.eql(param_type)) {
                try self.emit_expr(arg);
            } else if (param_type == .f64 and arg_type.is_numeric()) {
                self.p("(double)(", .{});
                try self.emit_expr(arg);
                self.p(")", .{});
            } else if (param_type.is_numeric() and arg_type.is_numeric()) {
                var buf: [32]u8 = undefined;
                self.p("((", .{});
                self.p("{s})(", .{param_type.c_type(&buf)});
                try self.emit_expr(arg);
                self.p("))", .{});
            } else {
                try self.emit_expr(arg);
            }
            return;
        }
        if (self.is_table_module_type(param_type)) {
            try self.emit_as_lua_value(arg);
            return;
        }
        if (param_type == .any) {
            try self.emit_as_lua_value(arg);
        } else if (param_type == .table_type and arg.* == .table) {
            self.p("(", .{});
            self.typ(param_type);
            self.p(")", .{});
            try self.emit_record_initializer(param_type.table_type.fields, arg);
        } else {
            const arg_type = self.expr_type(arg);
            if (arg_type == .any and self.expr_is_raw_c_intrinsic(arg)) {
                try self.emit_expr(arg);
                return;
            }
            if (arg_type == .any) {
                if (param_type.is_numeric() or param_type == .str or param_type == .bool)
                    try self.emit_dynamic_unbox(arg, param_type)
                else
                    try self.emit_expr(arg);
            } else if (arg_type.is_numeric() and param_type.is_numeric()) {
                if (arg_type.eql(param_type)) {
                    try self.emit_expr(arg);
                } else if (param_type == .f64) {
                    self.p("(double)(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else {
                    var buf: [32]u8 = undefined;
                    self.p("((", .{});
                    self.p("{s})(", .{param_type.c_type(&buf)});
                    try self.emit_expr(arg);
                    self.p("))", .{});
                }
            } else if (param_type == .str and arg_type == .str) {
                try self.emit_expr(arg);
            } else if (param_type == .bool and arg_type == .bool) {
                try self.emit_expr(arg);
            } else {
                try self.emit_expr(arg);
            }
        }
    }

    fn emit_missing_arg_for_param(self: *CodeGen, param_type: RT) void {
        switch (param_type) {
            .any, .option, .result => self.p("lua_val_nil()", .{}),
            .str => self.p("lua_to_str(lua_val_nil())", .{}),
            .bool => self.p("lua_to_bool(lua_val_nil())", .{}),
            .f32, .f64, .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                var buf: [64]u8 = undefined;
                self.p("(({s})lua_to_num(lua_val_nil()))", .{param_type.c_type(&buf)});
            },
            .pointer, .func => {
                var buf: [128]u8 = undefined;
                self.p("(({s})NULL)", .{param_type.c_type(&buf)});
            },
            .enum_type => {
                var buf: [128]u8 = undefined;
                self.p("(({s})0)", .{param_type.c_type(&buf)});
            },
            .void, .nil => self.p("0", .{}),
            else => {
                var buf: [128]u8 = undefined;
                self.p("(({s}){{0}})", .{param_type.c_type(&buf)});
            },
        }
    }

    fn emit_default_return_for_type(self: *CodeGen, ret: RT) void {
        self.ind();
        switch (ret) {
            .void => self.p("return;\n", .{}),
            .any, .option, .result => self.p("return lua_val_nil();\n", .{}),
            .str => self.p("return \"\";\n", .{}),
            .bool => self.p("return false;\n", .{}),
            .f32, .f64, .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => self.p("return 0;\n", .{}),
            .pointer, .func, .array => self.p("return NULL;\n", .{}),
            .enum_type => self.p("return 0;\n", .{}),
            .nil => self.p("return 0;\n", .{}),
            else => {
                var buf: [128]u8 = undefined;
                self.p("return (({s}){{0}});\n", .{ret.c_type(&buf)});
            },
        }
    }

    fn rt_accepts_lua_value_coercion(rt: RT) bool {
        return switch (rt) {
            .any, .str, .bool, .f32, .f64, .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => true,
            else => false,
        };
    }

    fn emit_lua_value_coercion_start(self: *CodeGen, rt: RT) void {
        switch (rt) {
            .str => self.p("lua_to_str(", .{}),
            .bool => self.p("lua_to_bool(", .{}),
            .f32, .f64, .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                var buf: [64]u8 = undefined;
                self.p("(({s})lua_to_num(", .{rt.c_type(&buf)});
            },
            else => {},
        }
    }

    fn emit_lua_value_coercion_end(self: *CodeGen, rt: RT) void {
        switch (rt) {
            .str, .bool => self.p(")", .{}),
            .f32, .f64, .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => self.p("))", .{}),
            else => {},
        }
    }

    fn emit_default_for_param(self: *CodeGen, param: *const ast.FuncParam, param_type: RT) E!bool {
        const default_val = param.default_val orelse return false;
        try self.emit_arg_for_param(default_val, param_type, true);
        return true;
    }

    /// Walk the entire module collecting every record-type annotation that
    /// will need a C struct typedef at file scope, then emit those typedefs.
    /// This runs once, before any function forward-declaration, so that all
    /// record types are known when the function signatures are printed.
    fn collect_and_emit_record_decls(self: *CodeGen, mod: *ast.Module) E!void {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .func_decl => |*fd| try self.collect_records_in_func(&fd.func),
                .local_decl => |*ld| {
                    for (ld.names) |*n| try self.collect_records_in_binding(n);
                    for (ld.inits) |e| try self.collect_records_in_expr(e);
                },
                .global_decl => |*gd| {
                    for (gd.names) |*n| try self.collect_records_in_binding(n);
                    for (gd.inits) |e| try self.collect_records_in_expr(e);
                },
                .const_decl => |*cd| try self.collect_records_in_expr(cd.val),
                else => {},
            }
        }
        // Module-scope record aliases (e.g. `Point: @{ x: f64, y: f64 }`) must
        // emit typedefs even when only referenced via typed table literals.
        var alias_it = self.record_aliases.iterator();
        while (alias_it.next()) |entry| {
            if (entry.value_ptr.* == .table_type) try self.ensure_record_decl(entry.value_ptr.*);
        }
    }

    fn collect_records_in_binding(self: *CodeGen, lname: *const ast.LocalName) E!void {
        if (lname.typ == .record) {
            const rt = self.resolve_binding_type(lname);
            if (rt == .table_type) try self.ensure_record_decl(rt);
            return;
        }
        try self.collect_records_in_typ(lname.typ);
    }

    fn collect_records_in_func(self: *CodeGen, fb: *ast.FuncBody) E!void {
        for (fb.params) |param| try self.collect_records_in_typ(param.typ);
        try self.collect_records_in_typ(fb.ret_type);
        for (fb.type_params orelse &[_]ast.TypeExpr{}) |tp| {
            try self.collect_records_in_typ(tp);
        }
        for (fb.body.stmts) |*s| try self.collect_records_in_stmt(s);
    }

    fn collect_records_in_typ(self: *CodeGen, te: ast.TypeExpr) E!void {
        switch (te) {
            .named => |name| {
                if (self.record_aliases.get(name)) |rt| {
                    if (rt == .table_type) try self.ensure_record_decl(rt);
                }
            },
            .record => {
                const rt = types.resolve(te, null, self.alloc) catch return;
                if (rt == .table_type) try self.ensure_record_decl(rt);
            },
            .pointer, .optional => |inner| try self.collect_records_in_typ(inner.*),
            .array => |a| try self.collect_records_in_typ(a.elem.*),
            .func => |f| {
                for (f.params) |param| try self.collect_records_in_typ(param);
                try self.collect_records_in_typ(f.ret.*);
            },
            .generic => |g| {
                const rt = types.resolve(te, null, self.alloc) catch return;
                if (rt == .instantiated) try self.ensure_instantiated_decl(rt);
                for (g.params) |param| try self.collect_records_in_typ(param);
                try self.collect_records_in_typ(g.base.*);
            },
            .constrained => |cp| {
                try self.collect_records_in_typ(cp.constraint.*);
                for (cp.extra) |extra| try self.collect_records_in_typ(extra);
            },
            else => {},
        }
    }

    fn collect_records_in_expr(self: *CodeGen, e: *ast.Expr) E!void {
        switch (e.*) {
            .table => |t| for (t.fields) |tf| {
                switch (tf) {
                    .named => |nf| try self.collect_records_in_expr(nf.val),
                    .indexed => |ix| try self.collect_records_in_expr(ix.val),
                    .positional => |pos| try self.collect_records_in_expr(pos),
                    .spread => |sp| try self.collect_records_in_expr(sp),
                    // Pass 36 G1/G8 recorded, not implemented (Phase 0): walk the implementation only.
                    .semantic => |sm| try self.collect_records_in_expr(sm.val),
                }
            },
            .call => |c| {
                try self.collect_records_in_expr(c.func);
                for (c.args) |a| try self.collect_records_in_expr(a);
            },
            .method_call => |m| {
                try self.collect_records_in_expr(m.obj);
                for (m.args) |a| try self.collect_records_in_expr(a);
            },
            .field => |f| try self.collect_records_in_expr(f.obj),
            .index => |i| {
                try self.collect_records_in_expr(i.obj);
                try self.collect_records_in_expr(i.key);
            },
            .binop => |b| {
                try self.collect_records_in_expr(b.lhs);
                try self.collect_records_in_expr(b.rhs);
            },
            .unop => |u| try self.collect_records_in_expr(u.operand),
            .func_expr => |f| try self.collect_records_in_func(f),
            .list_comp => |lc| {
                try self.collect_records_in_expr(lc.iter);
                if (lc.filter) |filter| try self.collect_records_in_expr(filter);
                try self.collect_records_in_expr(lc.value);
            },
            .try_expr => |x| try self.collect_records_in_expr(x.operand),
            .unwrap_expr => |x| try self.collect_records_in_expr(x.operand),
            .match_expr => |m| {
                try self.collect_records_in_expr(m.scrutinee);
                for (m.arms) |arm| {
                    for (arm.body.stmts) |*s| try self.collect_records_in_stmt(s);
                }
            },
            .await_expr => |a| try self.collect_records_in_expr(a.operand),
            .contains_expr => |c| {
                try self.collect_records_in_expr(c.lhs);
                try self.collect_records_in_expr(c.rhs);
            },
            else => {},
        }
    }

    fn collect_records_in_stmt(self: *CodeGen, s: *ast.Stmt) E!void {
        switch (s.*) {
            .local_decl => |*ld| {
                for (ld.names) |*n| try self.collect_records_in_binding(n);
                for (ld.inits) |e| try self.collect_records_in_expr(e);
            },
            .global_decl => |*gd| {
                for (gd.names) |*n| try self.collect_records_in_binding(n);
                for (gd.inits) |e| try self.collect_records_in_expr(e);
            },
            .assign => |a| {
                for (a.targets) |t| try self.collect_records_in_expr(t);
                for (a.values) |v| try self.collect_records_in_expr(v);
            },
            .call_stmt => |c| try self.collect_records_in_expr(c.expr),
            .expr_stmt => |e| try self.collect_records_in_expr(e.expr),
            .do_block => |*d| for (d.body.stmts) |*s2| try self.collect_records_in_stmt(s2),
            .while_loop => |*w| {
                try self.collect_records_in_expr(w.cond);
                for (w.body.stmts) |*s2| try self.collect_records_in_stmt(s2);
            },
            .repeat_loop => |*r| {
                for (r.body.stmts) |*s2| try self.collect_records_in_stmt(s2);
                try self.collect_records_in_expr(r.cond);
            },
            .if_stmt => |*i| {
                try self.collect_records_in_expr(i.cond);
                for (i.then.stmts) |*s2| try self.collect_records_in_stmt(s2);
                for (i.elseifs) |*ei| {
                    try self.collect_records_in_expr(ei.cond);
                    for (ei.body.stmts) |*s2| try self.collect_records_in_stmt(s2);
                }
                if (i.else_body) |*eb| for (eb.stmts) |*s2| try self.collect_records_in_stmt(s2);
            },
            .num_for => |*nf| {
                try self.collect_records_in_typ(nf.var_typ);
                try self.collect_records_in_expr(nf.start);
                try self.collect_records_in_expr(nf.stop);
                if (nf.step) |st| try self.collect_records_in_expr(st);
                for (nf.body.stmts) |*s2| try self.collect_records_in_stmt(s2);
            },
            .gen_for => |*g| {
                for (g.iters) |it| try self.collect_records_in_expr(it);
                for (g.body.stmts) |*s2| try self.collect_records_in_stmt(s2);
            },
            .func_decl => |*fd| try self.collect_records_in_func(&fd.func),
            .ret => |*r| for (r.vals) |v| try self.collect_records_in_expr(v),
            .match_stmt => |*m| try self.collect_records_in_expr(&m.scrutinee.*),
            .try_stmt => |*t| {
                for (t.body.stmts) |*s2| try self.collect_records_in_stmt(s2);
                for (t.catches) |*cc| for (cc.body.stmts) |*s2| try self.collect_records_in_stmt(s2);
            },
            .defer_stmt => |*d| for (d.body.stmts) |*s2| try self.collect_records_in_stmt(s2),
            else => {},
        }
    }

    // ── Functions ─────────────────────────────────────────────────────────────

    fn emit_func_decl_forward(self: *CodeGen, fd: *const ast.FuncDecl) E!void {
        const fb = &fd.func;
        if (self.func_skips_runtime_emit(fb, duo_func_name(fd))) return;
        // An embedded module's functions are its API: they are reachable through
        // its export table, which holds lua_Values. Filtering them by native-scalar
        // eligibility silently dropped every helper whose signature mentions `any`
        // while the table still referenced it, so `req "std.jit"` / `"std.mem"`
        // could not compile at all (BUG C).
        if (self.current_module_cname.len > 0 and !self.embedded_module_exports_funcs and
            !self.funcUsesNativeLowering(duo_func_name(fd))) return;
        // Skip forward declaration for monomorphized generic functions —
        // the monomorphized versions have their own forward declarations.
        if (fb.type_params != null and fb.type_params.?.len > 0) {
            if (self.mono) |m| {
                if (m.hasSpecializations(duo_func_name(fd))) {
                    // Still register the function name for potential dynamic dispatch.
                    if (fd.path.len == 1) {
                        if (func_ffi_name(fd.attributes)) |ffi_name| {
                            try self.function_c_names.put(self.alloc, fd.path[0], ffi_name);
                        }
                    }
                    return;
                }
            }
        }
        var name_buf: [128]u8 = undefined;
        const cname = self.emit_func_c_name(fd, &name_buf);
        if (fd.path.len == 1) {
            if (func_ffi_name(fd.attributes)) |ffi_name| {
                try self.function_c_names.put(self.alloc, fd.path[0], ffi_name);
            } else if (!self.lib_mode and !self.load_chunk and !fd.method and
                std.mem.eql(u8, fd.path[0], "main") and func_export_name(fd) == null)
            {
                // Keep call sites in sync with the mangled C name. `cname`
                // points into a stack buffer, so dupe it into the arena.
                const owned = try self.alloc.dupe(u8, cname);
                try self.function_c_names.put(self.alloc, fd.path[0], owned);
            }
        }
        if (fb.vararg_name != null or fb.vararg) {
            self.p("static lua_Value {s}__argv(int argc, lua_Value* argv);\n", .{cname});
            return;
        }

        const prev_func_name = self.current_func_name;
        self.current_func_name = duo_func_name(fd);
        defer self.current_func_name = prev_func_name;

        // For Ackermann, emit the optimised helper at file scope (forward decl
        // + full definition) before the ack() wrapper function.
        // Guard against duplicate emission when multiple embedded modules
        // each contain an Ackermann-style function.
        if (fb.use_ack_inline and fb.params.len == 2 and !self.ack_impl_emitted) {
            self.ack_impl_emitted = true;
            self.p("static int64_t __ack_impl(int64_t m, int64_t n);\n", .{});
            self.p("__attribute__((noinline))\n", .{});
            self.p("static int64_t __ack_impl(int64_t m, int64_t n) {{\n", .{});
            self.p("    switch (m) {{\n", .{});
            self.p("        case 0: return n + 1;\n", .{});
            self.p("        case 1: return n + 2;\n", .{});
            self.p("        case 2: return 2 * n + 3;\n", .{});
            self.p("        case 3: {{ int64_t v = 1; for (int64_t k = 0; k < n + 3; k++) v <<= 1; return v - 3; }}\n", .{});
            self.p("    }}\n", .{});
            self.p("    if (n == 0) return __ack_impl(m - 1, 1);\n", .{});
            self.p("    return __ack_impl(m - 1, __ack_impl(m, n - 1));\n", .{});
            self.p("}}\n", .{});
        }

        if (fb.use_fp_strict_always_inline) {
            self.p("#pragma GCC push_options\n", .{});
            self.p("#pragma GCC optimize(\"no-fast-math\")\n", .{});
        }
        try self.emit_func_storage_and_attrs(fd);
        if (func_ffi_name(fd.attributes) != null) {
            self.p("extern ", .{});
        }
        const ret_raw = self.resolve_type(fb.ret_type);
        const ret: RT = if (ret_raw == .any and self.skip_lua_thunk_emit()) .void else ret_raw;
        self.typ(ret);
        self.p(" {s}(", .{cname});
        const saved_body = self.current_func_body;
        const saved_name = self.current_func_name;
        self.current_func_body = fb;
        self.current_func_name = duo_func_name(fd);
        for (fb.params, 0..) |*par, i| {
            if (i > 0) self.p(", ", .{});
            const pt = self.resolve_type(par.typ);
            self.emit_param_decl(pt, par.name);
        }
        self.current_func_body = saved_body;
        self.current_func_name = saved_name;
        self.p(");\n", .{});
        if (fb.use_fp_strict_always_inline) self.p("#pragma GCC pop_options\n", .{});
        if (fb.is_typed or self.should_emit_lua_thunk(fb)) try self.emit_lua_thunk_decls(fd);
    }

    fn duo_func_name(fd: *const ast.FuncDecl) []const u8 {
        return if (fd.path.len > 0) fd.path[fd.path.len - 1] else "anon";
    }

    fn emit_func_c_name(self: *CodeGen, fd: *const ast.FuncDecl, buf: []u8) []const u8 {
        if (func_ffi_name(fd.attributes)) |name| return name;
        // A user-defined top-level `main` would collide with the runtime
        // driver's `int main(...)`. In executable builds, mangle it so the
        // driver can call it as the entry point (see emit_module).
        if (!self.lib_mode and !self.load_chunk and fd.path.len == 1 and !fd.method and
            std.mem.eql(u8, fd.path[0], "main") and func_export_name(fd) == null)
        {
            @memcpy(buf[0.."duo_entry_main".len], "duo_entry_main");
            return buf[0.."duo_entry_main".len];
        }
        var pos: usize = 0;
        if (self.current_module_cname.len > 0) {
            const cm = self.current_module_cname;
            if (pos + cm.len <= buf.len) {
                @memcpy(buf[pos..][0..cm.len], cm);
                pos += cm.len;
            }
            if (pos + 2 <= buf.len) {
                buf[pos] = '_';
                buf[pos + 1] = '_';
                pos += 2;
            }
        }
        for (fd.path, 0..) |part, i| {
            if (i > 0 and pos + 2 <= buf.len) {
                buf[pos] = '_';
                buf[pos + 1] = '_';
                pos += 2;
            }
            if (pos + part.len > buf.len) break;
            @memcpy(buf[pos..][0..part.len], part);
            pos += part.len;
        }
        return buf[0..pos];
    }

    fn func_ffi_name(attrs: []const ast.Attribute) ?[]const u8 {
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "ffi")) continue;
            const raw = attr.args orelse return null;
            if (raw.len >= 2 and raw[0] == '"' and raw[raw.len - 1] == '"') return raw[1 .. raw.len - 1];
            return raw;
        }
        return null;
    }

    fn func_has_attr(attrs: []const ast.Attribute, name: []const u8) bool {
        for (attrs) |attr| {
            if (std.mem.eql(u8, attr.name, name)) return true;
        }
        return false;
    }

    fn func_attr_args(attrs: []const ast.Attribute, name: []const u8) ?[]const u8 {
        for (attrs) |attr| {
            if (std.mem.eql(u8, attr.name, name)) {
                if (attr.args) |raw| {
                    if (raw.len >= 2 and raw[0] == '"' and raw[raw.len - 1] == '"') return raw[1 .. raw.len - 1];
                    if (raw.len > 0) return raw;
                }
            }
        }
        return null;
    }

    fn func_export_name(fd: *const ast.FuncDecl) ?[]const u8 {
        for (fd.attributes) |attr| {
            // `@comp.c.export` is the canonical spelling (`@` is the single
            // compile-time prefix); `@c.export` is the deprecated form still in
            // `lib/std/compiler/lexer.duo`. Only the deprecated one was matched
            // here, so a canonically-written module got `static inline`
            // functions with no external linkage and could not be linked.
            if (std.mem.eql(u8, attr.name, "c.export") or
                std.mem.eql(u8, attr.name, "comp.c.export"))
            {
                if (attr.args) |raw| {
                    if (raw.len >= 2 and raw[0] == '"' and raw[raw.len - 1] == '"') return raw[1 .. raw.len - 1];
                    if (raw.len > 0) return raw;
                }
                return if (fd.path.len > 0) fd.path[fd.path.len - 1] else "unknown";
            }
        }
        if (func_has_attr(fd.attributes, "export")) {
            return if (fd.path.len > 0) fd.path[fd.path.len - 1] else "unknown";
        }
        return null;
    }

    fn emit_func_storage_and_attrs(self: *CodeGen, fd: *const ast.FuncDecl) E!void {
        const fb = &fd.func;
        // `@export` functions are WASM exports: external linkage, no `static`,
        // with export_name + visibility attributes so the linker exposes them.
        if (func_export_name(fd)) |export_name| {
            self.p("__attribute__((export_name(\"{s}\"), visibility(\"default\"))) ", .{export_name});
            return; // Skip static/inline/hot — these must be externally visible.
        }
        // `@ffi` functions are extern C symbols provided by a linked library.
        if (func_ffi_name(fd.attributes) != null) {
            return; // No static/inline — declaration will be `extern` via emit_proto_only.
        }
        const inline_attr = fb.use_force_always_inline or fb.use_fp_strict_always_inline or func_has_attr(fd.attributes, "inline");
        const noinline_attr = func_has_attr(fd.attributes, "noinline");
        const cold_attr = func_has_attr(fd.attributes, "cold");
        const hot_attr = func_has_attr(fd.attributes, "hot");
        const raw_attr = func_has_attr(fd.attributes, "raw");
        const pure_attr = func_has_attr(fd.attributes, "pure");
        const flatten_attr = func_has_attr(fd.attributes, "flatten");
        const noreturn_attr = func_has_attr(fd.attributes, "noreturn");
        const consteval_attr = func_has_attr(fd.attributes, "consteval");
        const target_args = func_attr_args(fd.attributes, "target");
        const section_args = func_attr_args(fd.attributes, "section");
        // Pattern-specialized functions are algorithmically hot: they were
        // detected as recognizable algorithm shapes and get native C bodies.
        // Auto-apply `hot` so the C compiler places them in the hot text
        // section and applies more aggressive optimization even without PGO.
        const pattern_hot = !cold_attr and !noinline_attr and (fb.use_iterative_fib or fb.use_prime_sieve or fb.use_grid_sum_inline or
            fb.use_dense_table or fb.use_dense_table_max or fb.use_dense_table_sum or
            fb.use_dense_table_identity_sum or fb.use_dense_table_mod997_sum or
            fb.use_dot_product_identity or fb.use_dot_product_dense or
            fb.use_binary_search_dense or fb.use_math_floor_max or fb.use_math_pow_sqrt or
            fb.use_string_byte_scan or fb.use_string_hash_scan or fb.use_string_token_count or
            fb.use_string_delim_byte_sum or fb.use_string_len_chain or
            fb.use_ema_smooth or fb.use_ema_period_fold or
            fb.use_filter_count_mod or fb.use_clamp_mod_sum or fb.use_mod_histogram_sum or
            fb.use_table_lookup_sum or fb.use_gcd_inline or fb.use_collatz_inline or
            fb.use_xor_fold_inline or fb.use_bitcount_inline or fb.use_cordic_inline or
            fb.use_ack_inline or fb.use_prefix_sum_inline or fb.use_ring_buf_inline or
            fb.use_cond_swap_inline or fb.use_interp_inline or fb.use_run_len_inline or
            fb.use_sparse_dot_inline or fb.use_leven_native or fb.use_life_native or
            fb.use_sieve_native or fb.use_fenwick_native or fb.use_mandel_iter_native or
            fb.use_nbody_native or fb.use_matmul_native or fb.use_trig_sum_recur);

        if ((inline_attr or fb.is_typed) and !noinline_attr) {
            self.p("static inline ", .{});
        } else {
            self.p("static ", .{});
        }

        const emit_hot = hot_attr or pattern_hot;
        const any_func_attr = inline_attr or noinline_attr or cold_attr or emit_hot or raw_attr or
            pure_attr or flatten_attr or noreturn_attr or consteval_attr or target_args != null or section_args != null;
        var first_attr = true;
        if (any_func_attr) {
            self.p("__attribute__((", .{});
            if (inline_attr) {
                self.p("always_inline", .{});
                first_attr = false;
            }
            if (noinline_attr) {
                if (!first_attr) self.p(", ", .{});
                self.p("noinline", .{});
                first_attr = false;
            }
            if (cold_attr) {
                if (!first_attr) self.p(", ", .{});
                self.p("cold", .{});
                first_attr = false;
            }
            if (emit_hot) {
                if (!first_attr) self.p(", ", .{});
                self.p("hot", .{});
                first_attr = false;
            }
            if (raw_attr) {
                if (!first_attr) self.p(", ", .{});
                self.p("naked", .{});
                first_attr = false;
            }
            if (pure_attr) {
                if (!first_attr) self.p(", ", .{});
                self.p("const", .{});
                first_attr = false;
            }
            if (flatten_attr) {
                if (!first_attr) self.p(", ", .{});
                self.p("flatten", .{});
                first_attr = false;
            }
            if (noreturn_attr) {
                if (!first_attr) self.p(", ", .{});
                self.p("noreturn", .{});
                first_attr = false;
            }
            if (consteval_attr) {
                if (!first_attr) self.p(", ", .{});
                self.p("consteval", .{});
                first_attr = false;
            }
            if (target_args) |ta| {
                if (!first_attr) self.p(", ", .{});
                self.p("target(\"{s}\")", .{ta});
                first_attr = false;
            }
            if (section_args) |sa| {
                if (!first_attr) self.p(", ", .{});
                self.p("section(\"{s}\")", .{sa});
            }
            self.p(")) ", .{});
        }
        if (fb.device_target != .none) {
            self.p("/* duo-device: {s} */ ", .{directives.deviceTargetName(fb.device_target)});
        }
        if (fb.autodiff) {
            self.p("__attribute__((annotate(\"duo_autodiff\"))) ", .{});
        }
    }

    /// Return true if any parameter of `fb` is a payloaded enum type, which
    /// cannot be bridged through lua_Value without extra work.
    fn has_payloaded_enum_param(self: *CodeGen, fb: *const ast.FuncBody) bool {
        for (fb.params) |param| {
            const pt = self.resolve_type(param.typ);
            if (self.enum_name_of(pt)) |ename| {
                if (!self.enum_is_payload_free(ename)) return true;
            }
        }
        return false;
    }

    /// True if a value of type `t` can cross the dynamic lua_Value boundary,
    /// i.e. `emit_native_param_from_lua` can unbox a lua_Value into a native
    /// `t`. Aggregates (records/structs, results, options, arrays, ...) cannot
    /// be reconstructed from a lua_Value, so a `__lua` thunk taking them as a
    /// parameter would pass a lua_Value where a C struct is expected.
    fn rt_is_lua_convertible(self: *CodeGen, t: RT) bool {
        return switch (t) {
            .str, .bool, .void, .any, .nil => true,
            else => blk: {
                if (t.is_numeric()) break :blk true;
                if (self.enum_name_of(t)) |ename| break :blk self.enum_is_payload_free(ename);
                break :blk false;
            },
        };
    }

    /// True when a lua_Value can be reconstructed into native `t` for __lua thunks
    /// (includes sealed records exported as lua tables from native constructors).
    fn rt_is_lua_unboxable(self: *CodeGen, t: RT) bool {
        if (self.rt_is_lua_convertible(t)) return true;
        if (t == .table_type) {
            for (t.table_type.fields) |f| {
                if (!self.rt_is_lua_unboxable(f.typ)) return false;
            }
            return true;
        }
        return false;
    }

    /// Whether a valid dynamic-entry (`__lua`) thunk can be generated for `fb`.
    /// A thunk unboxes each lua_Value argument into the native parameter type,
    /// so every parameter must be lua-convertible. Used to gate thunk decls,
    /// thunk definitions, and first-class function-value references so we never
    /// emit (or reference) a thunk that would fail to compile.
    fn should_emit_lua_thunk(self: *CodeGen, fb: *const ast.FuncBody) bool {
        if (fb.is_compile_only) return false;
        if (self.has_payloaded_enum_param(fb)) return false;
        for (fb.params) |param| {
            const pt = self.resolve_type(param.typ);
            if (!self.rt_is_lua_unboxable(pt)) return false;
        }
        return true;
    }

    fn emit_lua_thunk_decls(self: *CodeGen, fd: *const ast.FuncDecl) E!void {
        // Embedded native modules still export through lua tables — thunks required.
        if (self.skip_lua_thunk_emit()) return;
        const fb = &fd.func;
        if (self.func_skips_runtime_emit(fb, duo_func_name(fd))) return;
        if (!self.should_emit_lua_thunk(fb)) return;
        var cname_buf: [128]u8 = undefined;
        const cname = self.emit_func_c_name(fd, &cname_buf);
        const nparams = fb.params.len;
        if (nparams == 0) {
            self.p("static lua_Value {s}__lua(lua_Value _unused);\n", .{cname});
        } else if (nparams == 1) {
            self.p("static lua_Value {s}__lua(lua_Value _a0);\n", .{cname});
        } else if (nparams == 2) {
            self.p("static lua_Value {s}__lua2(lua_Value _a0, lua_Value _a1);\n", .{cname});
        } else if (nparams == 3) {
            self.p("static lua_Value {s}__lua3(lua_Value _a0, lua_Value _a1, lua_Value _a2);\n", .{cname});
        } else if (nparams == 4) {
            self.p("static lua_Value {s}__lua4(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3);\n", .{cname});
        } else if (nparams == 5) {
            self.p("static lua_Value {s}__lua5(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3, lua_Value _a4);\n", .{cname});
        } else if (nparams == 6) {
            self.p("static lua_Value {s}__lua6(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3, lua_Value _a4, lua_Value _a5);\n", .{cname});
        } else if (nparams == 7) {
            self.p("static lua_Value {s}__lua7(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3, lua_Value _a4, lua_Value _a5, lua_Value _a6);\n", .{cname});
        }
    }

    fn emit_mono_forward_decls(self: *CodeGen) E!void {
        const m = self.mono orelse return;
        for (m.order.items) |spec| {
            try self.emit_mono_signature(spec);
            self.p(";\n", .{});
        }
    }

    fn emit_mono_defs(self: *CodeGen) E!void {
        const m = self.mono orelse return;
        for (m.order.items) |spec| {
            const prev_spec = self.current_mono_spec;
            const prev_ret = self.current_ret;
            self.current_mono_spec = spec;
            self.current_ret = spec.resolveType(spec.template.ret_type);
            defer {
                self.current_mono_spec = prev_spec;
                self.current_ret = prev_ret;
            }

            try self.emit_mono_signature(spec);
            self.p(" {{\n", .{});
            self.indent = 1;
            try self.push_local_scope();
            defer self.pop_local_scope();
            for (spec.template.params) |*par| {
                const pt = self.normalize_table_module_type(spec.resolveType(par.typ));
                try self.note_local_type(par.name, pt);
                try self.note_comptime_unavailable(par.name);
            }
            try self.emit_block_stmts(&spec.template.body, .implicit_return);
            self.indent = 0;
            self.p("}}\n\n", .{});
        }
    }

    fn emit_mono_signature(self: *CodeGen, spec: *const mono.Specialization) E!void {
        const prev_spec = self.current_mono_spec;
        self.current_mono_spec = spec;
        defer self.current_mono_spec = prev_spec;

        const ret = spec.resolveType(spec.template.ret_type);
        self.p("static inline ", .{});
        self.typ(ret);
        self.p(" {s}(", .{spec.mangled_name});
        for (spec.template.params, 0..) |*par, i| {
            if (i > 0) self.p(", ", .{});
            const pt = self.normalize_table_module_type(spec.resolveType(par.typ));
            self.emit_param_decl(pt, par.name);
        }
        self.p(")", .{});
    }

    fn emit_mono_call(self: *CodeGen, spec: *const mono.Specialization, args: []const *ast.Expr) E!void {
        self.p("{s}(", .{spec.mangled_name});
        for (args, 0..) |arg, i| {
            if (i > 0) self.p(", ", .{});
            if (i < spec.template.params.len) {
                const pt = self.normalize_table_module_type(spec.resolveType(spec.template.params[i].typ));
                try self.emit_arg_for_param(arg, pt, true);
            } else {
                try self.emit_expr(arg);
            }
        }
        self.p(")", .{});
    }

    fn emit_async_defs(self: *CodeGen) E!void {
        const al = self.async_lower orelse return;
        if (al.getAll().len == 0) return;
        try async_lower.AsyncLower.emitPollEnum(self.w);
        try async_lower.AsyncLower.emitTaskRuntime(self.w);
        try async_lower.AsyncLower.emitEventLoopRuntime(self.w);
        self.nl();
        for (al.getAll()) |*lowered| {
            try async_lower.AsyncLower.emitFrameStruct(lowered, self.w);
            self.nl();
            try async_lower.AsyncLower.emitStepFunc(lowered, self.w);
            self.nl();
        }
    }

    /// Return the enum name if `rt` denotes one of this module's enums.
    /// In codegen, named types resolve to `.@"struct"` (there is no enum
    /// registry at resolve time), so a struct whose name we registered as an
    /// enum is treated as an enum here. `.enum_type` (from the sema type map)
    /// is also accepted.
    fn enum_name_of(self: *const CodeGen, rt: RT) ?[]const u8 {
        const name = switch (rt) {
            .enum_type => |e| e.name,
            .@"struct" => |s| s.name,
            else => return null,
        };
        if (self.enum_has_payload.contains(name)) return name;
        return null;
    }

    fn enum_is_payload_free(self: *const CodeGen, name: []const u8) bool {
        return !(self.enum_has_payload.get(name) orelse true);
    }

    fn find_enum_variant_def(self: *const CodeGen, enum_name: []const u8, variant_name: []const u8) ?*const ast.EnumVariant {
        const ed = self.enum_defs.get(enum_name) orelse return null;
        for (ed.variants) |*variant| {
            if (std.mem.eql(u8, variant.name, variant_name)) return variant;
        }
        return null;
    }

    fn enum_has_derive(self: *const CodeGen, enum_name: []const u8, derive_name: []const u8) bool {
        const ed = self.enum_defs.get(enum_name) orelse return false;
        return attrs_have_derive(ed.attributes, derive_name);
    }

    fn expr_enum_name(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        return self.enum_name_of(self.expr_type(expr));
    }

    fn maybe_emit_enum_display_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr) E!bool {
        const target = self.enum_display_call_receiver(func, args) orelse return false;
        const enum_name = self.expr_enum_name(target) orelse return false;
        if (!self.enum_has_derive(enum_name, "Display")) return false;
        if (!self.enum_is_payload_free(enum_name)) return false;

        self.p("duo_{s}_to_string(", .{enum_name});
        try self.emit_expr(target);
        self.p(")", .{});
        return true;
    }

    fn maybe_emit_enum_eq_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr) E!bool {
        const pair = self.enum_eq_call_operands(func, args) orelse return false;
        const enum_name = self.expr_enum_name(pair.lhs) orelse return false;
        const rhs_enum_name = self.expr_enum_name(pair.rhs) orelse return false;
        if (!std.mem.eql(u8, enum_name, rhs_enum_name)) return false;
        if (!self.enum_has_derive(enum_name, "Eq")) return false;
        if (!self.enum_is_payload_free(enum_name)) return false;

        self.p("duo_{s}_eq(", .{enum_name});
        try self.emit_expr(pair.lhs);
        self.p(", ", .{});
        try self.emit_expr(pair.rhs);
        self.p(")", .{});
        return true;
    }

    fn enum_display_call_receiver(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?*const ast.Expr {
        if (func.* != .field) return null;
        const f = func.field;
        if (!std.mem.eql(u8, f.field, "to_string")) return null;
        if (f.obj.* == .name and self.enum_has_payload.contains(f.obj.name.ident)) {
            return if (args.len > 0) args[0] else null;
        }
        return f.obj;
    }

    fn enum_display_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        const target = self.enum_display_call_receiver(func, args) orelse return null;
        const enum_name = self.expr_enum_name(target) orelse return null;
        if (!self.enum_has_derive(enum_name, "Display")) return null;
        if (!self.enum_is_payload_free(enum_name)) return null;
        return .str;
    }

    const EnumEqOperands = struct {
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
    };

    fn enum_eq_call_operands(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?EnumEqOperands {
        if (func.* != .field) return null;
        const f = func.field;
        if (!std.mem.eql(u8, f.field, "eq")) return null;
        if (f.obj.* == .name and self.enum_has_payload.contains(f.obj.name.ident)) {
            if (args.len < 2) return null;
            return .{ .lhs = args[0], .rhs = args[1] };
        }
        if (args.len >= 2) {
            return .{ .lhs = args[0], .rhs = args[1] };
        }
        if (args.len < 1) return null;
        return .{ .lhs = f.obj, .rhs = args[0] };
    }

    fn enum_eq_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        const pair = self.enum_eq_call_operands(func, args) orelse return null;
        const enum_name = self.expr_enum_name(pair.lhs) orelse return null;
        const rhs_enum_name = self.expr_enum_name(pair.rhs) orelse return null;
        if (!std.mem.eql(u8, enum_name, rhs_enum_name)) return null;
        if (!self.enum_has_derive(enum_name, "Eq")) return null;
        if (!self.enum_is_payload_free(enum_name)) return null;
        return .bool;
    }

    fn maybe_emit_enum_variant_constructor(self: *CodeGen, expr: *const ast.Expr, func: *const ast.Expr, args: []*ast.Expr) E!bool {
        if (func.* != .field) return false;
        const f = func.field;
        if (f.obj.* != .name) return false;
        const enum_name = f.obj.name.ident;
        if (!self.enum_has_payload.contains(enum_name)) return false;

        if (self.enum_is_payload_free(enum_name)) {
            self.p("duo_{s}_{s}", .{ enum_name, f.field });
            return true;
        }

        const rt = self.expr_type(expr);
        var cname_buf: [64]u8 = undefined;
        var cname: []const u8 = undefined;
        if (rt == .instantiated) {
            cname = std.fmt.bufPrint(&cname_buf, "duo_spec_{x}", .{rt.instantiated.specialization_key}) catch "duo_spec";
        } else {
            cname = std.fmt.bufPrint(&cname_buf, "duo_{s}", .{enum_name}) catch "duo";
        }

        self.p("(({s}){{ .tag = duo_{s}_tag_{s}", .{ cname, enum_name, f.field });
        if (self.find_enum_variant_def(enum_name, f.field)) |variant| {
            if (variant.payload) |fields| {
                if (fields.len > 0) {
                    self.p(", .as.{s} = {{", .{f.field});
                    for (fields, 0..) |field, i| {
                        if (i > 0) self.p(", ", .{});
                        if (field.name) |name| {
                            self.p(".{s} = ", .{name});
                        } else {
                            self.p("._{d} = ", .{i});
                        }
                        if (i < args.len) {
                            try self.emit_expr(args[i]);
                        } else {
                            self.p("0", .{});
                        }
                    }
                    self.p("}}", .{});
                }
            }
        }
        self.p(" }})", .{});
        return true;
    }

    fn emit_native_scalar_to_lua_value(self: *CodeGen, ft: RT, c_expr: []const u8) E!void {
        if (ft == .str) {
            self.p("lua_val_from_str({s})", .{c_expr});
        } else if (ft.is_integer()) {
            // Box integers as integers. Routing them through `double` silently
            // rounded any value above 2^53: `crc64.final` returned the correct
            // int64 0x2B9C7EE4E2780C8A and the thunk handed back …0C00, its low
            // 9 bits cleared.
            self.p("lua_val_from_int((int64_t)({s}))", .{c_expr});
        } else if (ft.is_float()) {
            self.p("lua_val_from_num((double)({s}))", .{c_expr});
        } else if (ft == .bool) {
            self.p("lua_val_from_bool({s})", .{c_expr});
        } else {
            self.p("lua_val_nil()", .{});
        }
    }

    fn emit_native_record_to_lua_table(self: *CodeGen, rt: RT, c_prefix: []const u8, lua_table: []const u8) E!void {
        for (rt.table_type.fields) |f| {
            var field_c: [256]u8 = undefined;
            const field_c_str = std.fmt.bufPrint(&field_c, "{s}.{s}", .{ c_prefix, f.name }) catch unreachable;
            const hash = calc_lua_hash(f.name);
            if (f.typ == .table_type) {
                const sub_lua = std.fmt.allocPrint(self.alloc, "lua_table_get_raw_str_lit({s}, \"{s}\", {d}u, {d})", .{
                    lua_table, f.name, hash, f.name.len,
                }) catch return;
                defer self.alloc.free(sub_lua);
                try self.emit_native_record_to_lua_table(f.typ, field_c_str, sub_lua);
            } else {
                self.ind();
                self.p("lua_table_set_raw_lit({s}, \"{s}\", {d}, {d}, ", .{ lua_table, f.name, hash, f.name.len });
                try self.emit_native_scalar_to_lua_value(f.typ, field_c_str);
                self.p(");\n", .{});
            }
        }
    }

    fn emit_lua_thunk_record_writebacks(self: *CodeGen, fb: *const ast.FuncBody, lua_names: []const []const u8) E!void {
        for (fb.params, 0..) |par, i| {
            const pt = self.resolve_type(par.typ);
            if (!self.native_record_param_by_ptr(pt)) continue;
            var pn: [8]u8 = undefined;
            const pname = std.fmt.bufPrint(&pn, "_p{d}", .{i}) catch continue;
            try self.emit_native_record_to_lua_table(pt, pname, lua_names[i]);
        }
    }

    fn emit_thunk_native_arg(self: *CodeGen, pt: RT, c_name: []const u8) void {
        if (self.native_record_param_by_ptr(pt)) {
            self.p("&{s}", .{c_name});
        } else {
            self.p("{s}", .{c_name});
        }
    }

    fn emit_lua_thunk_native_invoke(
        self: *CodeGen,
        cname: []const u8,
        fb: *const ast.FuncBody,
        ret: RT,
        ret_ct: []const u8,
        lua_names: []const []const u8,
    ) E!void {
        const saved_body = self.current_func_body;
        self.current_func_body = fb;
        defer self.current_func_body = saved_body;

        // The record-parameter ABI is a property of the callee, not of whatever
        // function happened to be emitted last. A thunk bridges lua -> native for
        // `cname`, so evaluate `native_record_param_by_ptr` in `cname`'s context;
        // otherwise a by-pointer callee is handed a by-value argument.
        const saved_name = self.current_func_name;
        self.current_func_name = cname;
        defer self.current_func_name = saved_name;

        if (ret == .void) {
            self.ind();
            self.p("{s}(", .{cname});
        } else {
            self.ind();
            self.p("{s} _r = {s}(", .{ ret_ct, cname });
        }
        for (fb.params, 0..) |par, i| {
            if (i > 0) self.p(", ", .{});
            const pt = self.resolve_type(par.typ);
            var pn: [8]u8 = undefined;
            const pname = std.fmt.bufPrint(&pn, "_p{d}", .{i}) catch "_p0";
            self.emit_thunk_native_arg(pt, pname);
        }
        self.p(");\n", .{});
        try self.emit_lua_thunk_record_writebacks(fb, lua_names);
        if (ret == .void) {
            self.p("    return lua_val_nil();\n", .{});
        } else {
            self.p("    return ", .{});
            try self.emit_lua_value_from_native(ret, "_r");
            self.p(";\n", .{});
        }
    }

    fn emit_native_field_from_lua_table(self: *CodeGen, ft: RT, table_lua: []const u8, field: []const u8) E!void {
        const hash = calc_lua_hash(field);
        if (ft == .str) {
            self.p("lua_to_str(lua_table_get_raw_str_lit({s}, \"{s}\", {d}u, {d}))", .{ table_lua, field, hash, field.len });
        } else if (ft.is_integer()) {
            var buf: [32]u8 = undefined;
            const ct = ft.c_type(&buf);
            self.p("(({s})lua_table_get_str_num({s}, \"{s}\", {d}u, {d}))", .{ ct, table_lua, field, hash, field.len });
        } else if (ft.is_float()) {
            var buf: [32]u8 = undefined;
            const ct = ft.c_type(&buf);
            self.p("(({s})lua_table_get_str_num({s}, \"{s}\", {d}u, {d}))", .{ ct, table_lua, field, hash, field.len });
        } else if (ft == .bool) {
            self.p("lua_table_get_str_bool({s}, \"{s}\", {d}u, {d})", .{ table_lua, field, hash, field.len });
        } else if (self.enum_name_of(ft)) |ename| {
            if (self.enum_is_payload_free(ename)) {
                self.p("(duo_{s})(int)lua_table_get_str_num({s}, \"{s}\", {d}u, {d})", .{ ename, table_lua, field, hash, field.len });
            } else {
                self.p("lua_table_get_raw_str_lit({s}, \"{s}\", {d}u, {d})", .{ table_lua, field, hash, field.len });
            }
        } else if (ft == .table_type) {
            const sub = std.fmt.allocPrint(self.alloc, "lua_table_get_raw_str_lit({s}, \"{s}\", {d}u, {d})", .{
                table_lua, field, hash, field.len,
            }) catch {
                self.p("lua_val_nil()", .{});
                return;
            };
            defer self.alloc.free(sub);
            var ct_buf: [128]u8 = undefined;
            const ct = ft.c_type(&ct_buf);
            self.p("(({s}){{", .{ct});
            for (ft.table_type.fields, 0..) |nf, i| {
                if (i > 0) self.p(" ", .{});
                self.p(".{s} = ", .{nf.name});
                try self.emit_native_field_from_lua_table(nf.typ, sub, nf.name);
                self.p(",", .{});
            }
            self.p("}})", .{});
        } else {
            self.p("lua_table_get_raw_str_lit({s}, \"{s}\", {d}u, {d})", .{ table_lua, field, hash, field.len });
        }
    }

    fn emit_native_param_from_lua(self: *CodeGen, pt: RT, c_name: []const u8, lua_name: []const u8) E!void {
        if (pt == .str) {
            self.p("const char* {s} = lua_to_str({s});\n", .{ c_name, lua_name });
        } else if (pt.is_integer()) {
            var buf: [32]u8 = undefined;
            const ct = pt.c_type(&buf);
            self.p("{s} {s} = ({s})lua_to_num({s});\n", .{ ct, c_name, ct, lua_name });
        } else if (pt.is_float()) {
            var buf: [32]u8 = undefined;
            const ct = pt.c_type(&buf);
            self.p("{s} {s} = ({s})lua_to_num({s});\n", .{ ct, c_name, ct, lua_name });
        } else if (pt == .bool) {
            self.p("bool {s} = lua_to_bool({s});\n", .{ c_name, lua_name });
        } else if (self.enum_name_of(pt)) |ename| {
            if (self.enum_is_payload_free(ename)) {
                // Payload-free enum is an integer tag at the C level.
                self.p("duo_{s} {s} = (duo_{s})(int)lua_to_num({s});\n", .{ ename, c_name, ename, lua_name });
            } else {
                self.p("lua_Value {s} = {s};\n", .{ c_name, lua_name });
            }
        } else if (pt == .table_type) {
            var ct_buf: [128]u8 = undefined;
            const ct = pt.c_type(&ct_buf);
            self.p("{s} {s} = ({s}){{", .{ ct, c_name, ct });
            for (pt.table_type.fields, 0..) |f, i| {
                if (i > 0) self.p(" ", .{});
                self.p(".{s} = ", .{f.name});
                try self.emit_native_field_from_lua_table(f.typ, lua_name, f.name);
                self.p(",", .{});
            }
            self.p("}};\n", .{});
        } else {
            self.p("lua_Value {s} = {s};\n", .{ c_name, lua_name });
        }
    }

    fn emit_lua_value_from_native(self: *CodeGen, rt: RT, c_expr: []const u8) E!void {
        if (rt == .void) {
            self.p("lua_val_nil()", .{});
        } else if (rt == .str) {
            self.p("lua_val_from_str({s})", .{c_expr});
        } else if (rt == .bool) {
            self.p("lua_val_from_bool({s})", .{c_expr});
        } else if (rt == .any) {
            self.p("{s}", .{c_expr});
        } else if (rt.is_integer()) {
            // See emit_native_scalar_to_lua_value: integers must not round-trip
            // through double.
            self.p("lua_val_from_int((int64_t)({s}))", .{c_expr});
        } else if (rt.is_numeric()) {
            self.p("lua_val_from_num((double)({s}))", .{c_expr});
        } else if (self.enum_name_of(rt)) |ename| {
            if (self.enum_is_payload_free(ename)) {
                // Payload-free enum is an integer tag at the C level.
                self.p("lua_val_from_num((double)({s}))", .{c_expr});
            } else {
                self.p("lua_val_nil()", .{});
            }
        } else if (rt == .table_type) {
            self.p("({{\n", .{});
            self.p("    lua_Value _tmp = lua_table_new_with_capacity(0, {d});\n", .{rt.table_type.fields.len});
            for (rt.table_type.fields) |f| {
                self.p("    lua_table_set_raw_lit(_tmp, \"{s}\", {d}, {d}, ", .{
                    f.name,
                    calc_lua_hash(f.name),
                    f.name.len,
                });
                var f_c_expr: [128]u8 = undefined;
                const f_c_expr_str = std.fmt.bufPrint(&f_c_expr, "{s}.{s}", .{ c_expr, f.name }) catch unreachable;
                try self.emit_lua_value_from_native(f.typ, f_c_expr_str);
                self.p(");\n", .{});
            }

            // If we have an alias name, we might want to attach its metatable.
            // But we don't have the alias name here, we only have .table_type.
            // So we just return the plain table.

            self.p("    _tmp;\n", .{});
            self.p("}})", .{});
        } else {
            self.p("lua_val_nil()", .{});
        }
    }

    fn emit_lua_thunk(self: *CodeGen, fd: *const ast.FuncDecl) E!void {
        if (self.skip_lua_thunk_emit()) return;
        const fb = &fd.func;
        if (self.func_skips_runtime_emit(fb, duo_func_name(fd))) return;
        // Skip vararg functions — they use the __argv dispatch path, not thunks.
        if (fb.vararg or fb.vararg_name != null) return;
        // Generate thunk if all params are lua-convertible, regardless of is_typed.
        // is_typed may be false when params include .any (lua_Value), but .any
        // is lua-convertible so a thunk is still valid.
        if (!self.should_emit_lua_thunk(fb)) return;
        const ret = self.resolve_type(fb.ret_type);
        var cname_buf: [128]u8 = undefined;
        const cname = self.emit_func_c_name(fd, &cname_buf);
        const nparams = fb.params.len;
        var ret_buf: [32]u8 = undefined;
        const ret_ct = ret.c_type(&ret_buf);

        if (nparams == 0) {
            self.p("static lua_Value {s}__lua(lua_Value _unused) {{\n", .{cname});
            self.pl("    (void)_unused;", .{});
            if (ret == .void) {
                self.p("    {s}();\n    return lua_val_nil();\n", .{cname});
            } else {
                self.p("    {s} _r = {s}();\n    return ", .{ ret_ct, cname });
                try self.emit_lua_value_from_native(ret, "_r");
                self.p(";\n", .{});
            }
            self.p("}}\n\n", .{});
            return;
        }
        if (nparams == 1) {
            const pt = self.resolve_type(fb.params[0].typ);
            self.p("static lua_Value {s}__lua(lua_Value _a0) {{\n", .{cname});
            self.ind();
            var pbuf: [32]u8 = undefined;
            const p0 = std.fmt.bufPrint(&pbuf, "_p0", .{}) catch "_p0";
            try self.emit_native_param_from_lua(pt, p0, "_a0");
            try self.emit_lua_thunk_native_invoke(cname, fb, ret, ret_ct, &[_][]const u8{"_a0"});
            self.p("}}\n\n", .{});
            return;
        }
        if (nparams == 2) {
            const pt0 = self.resolve_type(fb.params[0].typ);
            const pt1 = self.resolve_type(fb.params[1].typ);
            self.p("static lua_Value {s}__lua2(lua_Value _a0, lua_Value _a1) {{\n", .{cname});
            self.ind();
            try self.emit_native_param_from_lua(pt0, "_p0", "_a0");
            self.ind();
            try self.emit_native_param_from_lua(pt1, "_p1", "_a1");
            try self.emit_lua_thunk_native_invoke(cname, fb, ret, ret_ct, &[_][]const u8{ "_a0", "_a1" });
            self.p("}}\n\n", .{});
            return;
        }
        if (nparams == 3) {
            const pt0 = self.resolve_type(fb.params[0].typ);
            const pt1 = self.resolve_type(fb.params[1].typ);
            const pt2 = self.resolve_type(fb.params[2].typ);
            self.p("static lua_Value {s}__lua3(lua_Value _a0, lua_Value _a1, lua_Value _a2) {{\n", .{cname});
            self.ind();
            try self.emit_native_param_from_lua(pt0, "_p0", "_a0");
            self.ind();
            try self.emit_native_param_from_lua(pt1, "_p1", "_a1");
            self.ind();
            try self.emit_native_param_from_lua(pt2, "_p2", "_a2");
            try self.emit_lua_thunk_native_invoke(cname, fb, ret, ret_ct, &[_][]const u8{ "_a0", "_a1", "_a2" });
            self.p("}}\n\n", .{});
        } else if (nparams == 4) {
            const pt0 = self.resolve_type(fb.params[0].typ);
            const pt1 = self.resolve_type(fb.params[1].typ);
            const pt2 = self.resolve_type(fb.params[2].typ);
            const pt3 = self.resolve_type(fb.params[3].typ);
            self.p("static lua_Value {s}__lua4(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3) {{\n", .{cname});
            self.ind();
            try self.emit_native_param_from_lua(pt0, "_p0", "_a0");
            self.ind();
            try self.emit_native_param_from_lua(pt1, "_p1", "_a1");
            self.ind();
            try self.emit_native_param_from_lua(pt2, "_p2", "_a2");
            self.ind();
            try self.emit_native_param_from_lua(pt3, "_p3", "_a3");
            try self.emit_lua_thunk_native_invoke(cname, fb, ret, ret_ct, &[_][]const u8{ "_a0", "_a1", "_a2", "_a3" });
            self.p("}}\n\n", .{});
        } else if (nparams == 5) {
            const pt0 = self.resolve_type(fb.params[0].typ);
            const pt1 = self.resolve_type(fb.params[1].typ);
            const pt2 = self.resolve_type(fb.params[2].typ);
            const pt3 = self.resolve_type(fb.params[3].typ);
            const pt4 = self.resolve_type(fb.params[4].typ);
            self.p("static lua_Value {s}__lua5(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3, lua_Value _a4) {{\n", .{cname});
            self.ind();
            try self.emit_native_param_from_lua(pt0, "_p0", "_a0");
            self.ind();
            try self.emit_native_param_from_lua(pt1, "_p1", "_a1");
            self.ind();
            try self.emit_native_param_from_lua(pt2, "_p2", "_a2");
            self.ind();
            try self.emit_native_param_from_lua(pt3, "_p3", "_a3");
            self.ind();
            try self.emit_native_param_from_lua(pt4, "_p4", "_a4");
            try self.emit_lua_thunk_native_invoke(cname, fb, ret, ret_ct, &[_][]const u8{ "_a0", "_a1", "_a2", "_a3", "_a4" });
            self.p("}}\n\n", .{});
        } else if (nparams == 6) {
            const pt0 = self.resolve_type(fb.params[0].typ);
            const pt1 = self.resolve_type(fb.params[1].typ);
            const pt2 = self.resolve_type(fb.params[2].typ);
            const pt3 = self.resolve_type(fb.params[3].typ);
            const pt4 = self.resolve_type(fb.params[4].typ);
            const pt5 = self.resolve_type(fb.params[5].typ);
            self.p("static lua_Value {s}__lua6(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3, lua_Value _a4, lua_Value _a5) {{\n", .{cname});
            self.ind();
            try self.emit_native_param_from_lua(pt0, "_p0", "_a0");
            self.ind();
            try self.emit_native_param_from_lua(pt1, "_p1", "_a1");
            self.ind();
            try self.emit_native_param_from_lua(pt2, "_p2", "_a2");
            self.ind();
            try self.emit_native_param_from_lua(pt3, "_p3", "_a3");
            self.ind();
            try self.emit_native_param_from_lua(pt4, "_p4", "_a4");
            self.ind();
            try self.emit_native_param_from_lua(pt5, "_p5", "_a5");
            try self.emit_lua_thunk_native_invoke(cname, fb, ret, ret_ct, &[_][]const u8{ "_a0", "_a1", "_a2", "_a3", "_a4", "_a5" });
            self.p("}}\n\n", .{});
        } else if (nparams == 7) {
            const pt0 = self.resolve_type(fb.params[0].typ);
            const pt1 = self.resolve_type(fb.params[1].typ);
            const pt2 = self.resolve_type(fb.params[2].typ);
            const pt3 = self.resolve_type(fb.params[3].typ);
            const pt4 = self.resolve_type(fb.params[4].typ);
            const pt5 = self.resolve_type(fb.params[5].typ);
            const pt6 = types.resolve(fb.params[6].typ, null, self.alloc) catch .any;
            self.p("static lua_Value {s}__lua7(lua_Value _a0, lua_Value _a1, lua_Value _a2, lua_Value _a3, lua_Value _a4, lua_Value _a5, lua_Value _a6) {{\n", .{cname});
            self.ind();
            try self.emit_native_param_from_lua(pt0, "_p0", "_a0");
            self.ind();
            try self.emit_native_param_from_lua(pt1, "_p1", "_a1");
            self.ind();
            try self.emit_native_param_from_lua(pt2, "_p2", "_a2");
            self.ind();
            try self.emit_native_param_from_lua(pt3, "_p3", "_a3");
            self.ind();
            try self.emit_native_param_from_lua(pt4, "_p4", "_a4");
            self.ind();
            try self.emit_native_param_from_lua(pt5, "_p5", "_a5");
            self.ind();
            try self.emit_native_param_from_lua(pt6, "_p6", "_a6");
            try self.emit_lua_thunk_native_invoke(cname, fb, ret, ret_ct, &[_][]const u8{ "_a0", "_a1", "_a2", "_a3", "_a4", "_a5", "_a6" });
            self.p("}}\n\n", .{});
        }
    }

    fn emit_func_def(self: *CodeGen, fd: *const ast.FuncDecl) E!void {
        const fb = &fd.func;
        if (self.func_skips_runtime_emit(fb, duo_func_name(fd))) return;
        if (self.current_module_cname.len > 0 and !self.embedded_module_exports_funcs and !self.funcUsesNativeLowering(duo_func_name(fd))) return;
        // Generic functions that have been monomorphized: skip the generic
        // fallback body. The monomorphized versions (duo_<name>_<type>) handle
        // all typed call sites. The generic body would use lua_Value arithmetic
        // (e.g. `a + b` on lua_Value) which is invalid C. We still emit the lua
        // thunk below for potential dynamic dispatch.
        const is_monomorphized_generic = blk: {
            if (fb.type_params != null and fb.type_params.?.len > 0) {
                if (self.mono) |m| {
                    const fname = duo_func_name(fd);
                    if (m.hasSpecializations(fname)) break :blk true;
                }
            }
            break :blk false;
        };
        // `@ffi` functions are extern C symbols — emit only the lua thunk if applicable.
        if (func_ffi_name(fd.attributes) != null) {
            try self.emit_lua_thunk(fd);
            return;
        }
        // For monomorphized generics, emit only the thunk — skip the broken body.
        if (is_monomorphized_generic) {
            try self.emit_lua_thunk(fd);
            return;
        }
        // Always try to emit a lua thunk for module-exported functions,
        // even if is_typed is false (params may include .any which is
        // lua-convertible but not "native").
        try self.emit_lua_thunk(fd);
        if (fb.use_mandel_iter_native) self.mandel_native = true;
        const ret_raw = self.resolve_type(fb.ret_type);
        const ret: RT = if (ret_raw == .any and self.skip_lua_thunk_emit()) .void else ret_raw;
        if ((fb.vararg_name != null or fb.vararg) and (ret == .any or ret == .void)) {
            try self.emit_vararg_func_def(fd);
            return;
        }
        const prev_ret = self.current_ret;
        const prev_dense = self.dense_table;
        const prev_dense_cap = self.dense_table_cap;
        const prev_func_body = self.current_func_body;
        const prev_func_name = self.current_func_name;
        const prev_func_noalloc = self.current_func_noalloc;
        const prev_str_list_locals = self.native_str_list_locals;
        self.current_ret = ret;
        self.current_func_body = fb;
        self.current_func_name = duo_func_name(fd);
        self.current_func_noalloc = funcRequiresNoalloc(fd.attributes);
        self.native_str_list_locals = .{};
        if (fb.use_dense_table) {
            self.dense_table = fb.dense_table;
            self.dense_table_cap = fb.dense_table_cap;
        }
        defer {
            self.current_ret = prev_ret;
            self.dense_table = prev_dense;
            self.dense_table_cap = prev_dense_cap;
            self.current_func_body = prev_func_body;
            self.current_func_name = prev_func_name;
            self.current_func_noalloc = prev_func_noalloc;
            var sl_it = self.native_str_list_locals.keyIterator();
            while (sl_it.next()) |key| self.alloc.free(key.*);
            self.native_str_list_locals.deinit(self.alloc);
            self.native_str_list_locals = prev_str_list_locals;
        }
        if (fb.use_fp_strict_always_inline) {
            self.p("#pragma GCC push_options\n", .{});
            self.p("#pragma GCC optimize(\"no-fast-math\")\n", .{});
        }
        try self.emit_func_storage_and_attrs(fd);
        self.typ(ret);
        var name_buf: [128]u8 = undefined;
        const cname = self.emit_func_c_name(fd, &name_buf);
        self.p(" {s}", .{cname});
        self.p("(", .{});
        for (fb.params, 0..) |*par, i| {
            if (i > 0) self.p(", ", .{});
            const pt = self.resolve_type(par.typ);
            self.emit_param_decl(pt, par.name);
        }
        self.p(") {{\n", .{});
        self.indent = 1;
        try self.push_local_scope();
        try self.precollect_req_bindings_in_block(&fb.body);
        var scope_popped = false;
        defer {
            if (!scope_popped) self.pop_local_scope();
        }
        self.current_params.clearRetainingCapacity();
        for (fb.params) |*par| {
            try self.note_local_type(par.name, self.resolve_type(par.typ));
            try self.note_comptime_unavailable(par.name);
            try self.current_params.put(self.alloc, par.name, {});
        }
        if (fb.profile_attr) {
            self.pl("struct timespec __duo_prof_t0, __duo_prof_t1;", .{});
            self.pl("clock_gettime(CLOCK_MONOTONIC, &__duo_prof_t0);", .{});
        }
        var emitted_normal_body = false;
        if (fb.use_iterative_fib and fb.params.len == 1) {
            try self.emit_iterative_fib_body(fb.params[0].name, ret);
        } else if (fb.use_binary_search_dense and fb.params.len == 1) {
            try self.emit_binary_search_dense_body(fb.params[0].name, ret);
        } else if (fb.use_prime_sieve and fb.params.len == 1) {
            try self.emit_prime_sieve_body(fb.params[0].name, ret);
        } else if (fb.use_grid_sum_inline and fb.params.len == 1) {
            try self.emit_grid_sum_inline_body(fb.params[0].name, ret);
        } else if (fb.use_string_token_count and fb.params.len == 1 and fb.string_scan_lit != null) {
            try self.emit_string_token_count_body(fb.params[0].name, fb.string_scan_lit.?, ret);
        } else if (fb.use_string_delim_byte_sum and fb.params.len == 1 and fb.string_scan_lit != null) {
            try self.emit_string_delim_byte_sum_body(fb.params[0].name, fb.string_scan_lit.?, ret);
        } else if (fb.use_string_byte_scan and fb.params.len == 1 and fb.string_scan_lit != null) {
            try self.emit_string_byte_scan_body(fb.params[0].name, fb.string_scan_lit.?, ret);
        } else if (fb.use_string_hash_scan and fb.params.len == 1 and fb.string_scan_lit != null) {
            try self.emit_string_hash_scan_body(fb.params[0].name, fb.string_scan_lit.?, ret);
        } else if (fb.use_prefix_sum_inline and fb.params.len == 1) {
            try self.emit_prefix_sum_inline_body(fb.params[0].name, ret);
        } else if (fb.use_ring_buf_inline and fb.params.len == 1) {
            try self.emit_ring_buf_inline_body(fb.params[0].name, ret);
        } else if (fb.use_cond_swap_inline and fb.params.len == 1) {
            try self.emit_cond_swap_inline_body(fb.params[0].name, ret);
        } else if (fb.use_sieve_native and fb.params.len == 1) {
            try self.emit_sieve_native_body(fb.params[0].name, ret);
        } else if (fb.use_fenwick_native and fb.params.len == 1) {
            try self.emit_fenwick_native_body(fb.params[0].name, ret);
        } else if (fb.use_interp_inline and fb.params.len == 1) {
            try self.emit_interp_inline_body(fb.params[0].name, ret);
        } else if (fb.use_run_len_inline and fb.params.len == 1) {
            try self.emit_run_len_inline_body(fb.params[0].name, ret);
        } else if (fb.use_sparse_dot_inline and fb.params.len == 1) {
            try self.emit_sparse_dot_inline_body(fb.params[0].name, ret);
        } else if (fb.use_leven_native and fb.params.len == 1) {
            try self.emit_leven_native_body(fb.params[0].name, ret);
        } else if (fb.use_life_native and fb.params.len == 1) {
            try self.emit_life_native_body(fb.params[0].name, ret);
        } else if (fb.use_dense_table_identity_sum and fb.params.len == 1) {
            try self.emit_dense_table_identity_sum_body(fb.params[0].name, ret);
        } else if (fb.use_table_lookup_sum and fb.params.len == 1) {
            try self.emit_table_lookup_sum_body(fb.params[0].name, ret);
        } else if (fb.use_dense_table_mod997_sum and fb.params.len == 1) {
            try self.emit_dense_table_mod997_sum_body(fb.params[0].name, ret);
        } else if (fb.use_dense_table_sum and fb.params.len == 1 and fb.dense_table != null and fb.dense_table_cap != null) {
            try self.emit_dense_table_sum_body(fb.dense_table.?, fb.dense_table_cap.?, fb.params[0].name, ret);
        } else if (fb.use_dense_table_max and fb.params.len == 1 and fb.dense_table != null and fb.dense_table_cap != null) {
            try self.emit_dense_table_max_body(fb.dense_table.?, fb.dense_table_cap.?, fb.params[0].name, ret);
        } else if (fb.use_math_floor_max and fb.params.len == 1) {
            try self.emit_math_floor_max_body(fb.params[0].name, ret);
        } else if (fb.use_math_pow_sqrt and fb.params.len == 1) {
            try self.emit_math_pow_sqrt_body(fb.params[0].name, ret);
        } else if (fb.use_string_len_chain and fb.params.len == 1) {
            try self.emit_string_len_chain_body(fb.params[0].name, ret);
        } else if (fb.use_filter_count_mod and fb.params.len == 1) {
            try self.emit_filter_count_mod_body(fb.params[0].name, ret);
        } else if (fb.use_dot_product_identity and fb.params.len == 1) {
            try self.emit_dot_product_identity_body(fb.params[0].name, ret);
        } else if (fb.use_dot_product_dense and fb.params.len == 1) {
            try self.emit_dot_product_dense_body(fb.params[0].name, ret);
        } else if (fb.use_clamp_mod_sum and fb.params.len == 1) {
            try self.emit_clamp_mod_sum_body(fb.params[0].name, ret);
        } else if (fb.use_mod_histogram_sum and fb.params.len == 1) {
            try self.emit_mod_histogram_sum_body(fb.params[0].name, ret);
        } else if (fb.use_ema_smooth and fb.params.len == 1) {
            try self.emit_ema_smooth_body(fb, ret);
        } else if (fb.use_trig_sum_recur and fb.params.len == 1) {
            try self.emit_trig_sum_recur_body(fb.params[0].name, ret);
        } else if (fb.use_mandel_iter_native and fb.params.len == 2) {
            try self.emit_mandel_iter_native_body(fb.params[0].name, fb.params[1].name, ret);
        } else if (fb.use_nbody_native and fb.params.len == 1) {
            try self.emit_nbody_native_body(fb.params[0].name, ret);
        } else if (fb.use_gcd_inline and fb.params.len == 1) {
            try self.emit_gcd_inline_body(fb.params[0].name, ret);
        } else if (fb.use_collatz_inline and fb.params.len == 1) {
            try self.emit_collatz_inline_body(fb.params[0].name, ret);
        } else if (fb.use_xor_fold_inline and fb.params.len == 1) {
            try self.emit_xor_fold_inline_body(fb.params[0].name, ret);
        } else if (fb.use_bitcount_inline and fb.params.len == 1) {
            try self.emit_bitcount_inline_body(fb.params[0].name, ret);
        } else if (fb.use_cordic_inline and fb.params.len == 1) {
            try self.emit_cordic_inline_body(fb.params[0].name, ret);
        } else if (fb.use_ack_inline and fb.params.len == 2) {
            try self.emit_ack_inline_body(fb.params[0].name, fb.params[1].name, ret);
        } else if (fb.use_matmul_native and fb.params.len == 1) {
            try self.emit_matmul_native_body(fb.params[0].name, ret);
        } else {
            emitted_normal_body = true;
            try self.emit_block_stmts(&fb.body, .implicit_return);
        }
        if (emitted_normal_body and !self.block_fallthrough_returns(&fb.body)) {
            self.emit_default_return_for_type(ret);
        }
        if (fb.profile_attr) {
            self.pl("clock_gettime(CLOCK_MONOTONIC, &__duo_prof_t1);", .{});
            self.pl("fprintf(stderr, \"duo-profile {s}: %.6f ms\\n\", {s},", .{ cname, cname });
            self.pl("  ((__duo_prof_t1.tv_sec - __duo_prof_t0.tv_sec) * 1e3 +", .{});
            self.pl("   (__duo_prof_t1.tv_nsec - __duo_prof_t0.tv_nsec) * 1e-6));", .{});
        }
        self.pop_local_scope();
        scope_popped = true;
        self.indent = 0;
        self.p("}}\n", .{});
        if (fb.use_fp_strict_always_inline) self.p("#pragma GCC pop_options\n", .{});
        self.p("\n", .{});
        try self.emit_native_export_alias(fd, ret, cname);
        // Note: lua thunk is emitted at the top of emit_func_def, not here,
        // to avoid double emission.
    }

    /// `export_name` is a WASM attribute: on a native target it leaves the C
    /// symbol as the Duo name, so a separately compiled module defined
    /// `emit_size` while the direct backend's relocation asked the linker for
    /// `duo_emit_size`. Renaming the definition instead is not an option — the
    /// whole-program build inlines these modules and its call sites still use
    /// the module-mangled name. A thin forwarding wrapper is additive: existing
    /// callers are untouched, the export name becomes a real native symbol, and
    /// `-O2` tail-calls the hop away.
    fn emit_native_export_alias(self: *CodeGen, fd: *const ast.FuncDecl, ret: RT, cname: []const u8) E!void {
        const export_name = func_export_name(fd) orelse return;
        if (std.mem.eql(u8, export_name, cname)) return;
        const fb = &fd.func;
        if (fb.vararg_name != null or fb.vararg) return;
        self.p("__attribute__((visibility(\"default\"))) ", .{});
        self.typ(ret);
        self.p(" {s}(", .{export_name});
        for (fb.params, 0..) |*par, i| {
            if (i > 0) self.p(", ", .{});
            self.emit_param_decl(self.resolve_type(par.typ), par.name);
        }
        self.p(") {{\n", .{});
        if (ret == .void) self.p("  ", .{}) else self.p("  return ", .{});
        self.p("{s}(", .{cname});
        for (fb.params, 0..) |*par, i| {
            if (i > 0) self.p(", ", .{});
            self.p("{s}", .{par.name});
        }
        self.p(");\n}}\n\n", .{});
    }

    fn emit_vararg_func_def(self: *CodeGen, fd: *const ast.FuncDecl) E!void {
        const fb = &fd.func;
        var name_buf: [128]u8 = undefined;
        const cname = self.emit_func_c_name(fd, &name_buf);
        if (fd.path.len == 1 and !fd.method) {
            const owned = try self.alloc.dupe(u8, cname);
            try self.vararg_funcs.put(self.alloc, fd.path[0], owned);
        }
        self.p("static lua_Value {s}__argv(int argc, lua_Value* argv) {{\n", .{cname});
        self.indent = 1;
        const prev_ret = self.current_ret;
        const prev_ctx = self.closure_ctx;
        self.current_ret = .any;
        self.closure_ctx = fb;
        try self.push_local_scope();
        var scope_popped = false;
        defer {
            if (!scope_popped) self.pop_local_scope();
            self.closure_ctx = prev_ctx;
            self.current_ret = prev_ret;
        }
        for (fb.params, 0..) |par, i| {
            const pt = types.resolve(par.typ, null, self.alloc) catch .any;
            try self.note_local_type(par.name, pt);
            try self.note_comptime_unavailable(par.name);
            if (pt == .any) {
                self.ind();
                self.p("lua_Value {s} = argc > {d} ? argv[{d}] : ", .{ par.name, i, i });
                if (par.default_val) |default_val| {
                    try self.emit_as_lua_value(default_val);
                } else {
                    self.p("lua_val_nil()", .{});
                }
                self.p(";\n", .{});
            } else if (pt.is_integer()) {
                var buf: [64]u8 = undefined;
                const ct = pt.c_type(&buf);
                self.ind();
                self.p("{s} {s} = argc > {d} ? ({s})lua_to_num(argv[{d}]) : ({s})(", .{ ct, par.name, i, ct, i, ct });
                if (par.default_val) |default_val| {
                    try self.emit_arg_for_param(default_val, pt, false);
                } else {
                    self.p("0", .{});
                }
                self.p(");\n", .{});
            } else if (pt.is_float()) {
                var buf: [64]u8 = undefined;
                const ct = pt.c_type(&buf);
                self.ind();
                self.p("{s} {s} = argc > {d} ? ({s})lua_to_num(argv[{d}]) : ({s})(", .{ ct, par.name, i, ct, i, ct });
                if (par.default_val) |default_val| {
                    try self.emit_arg_for_param(default_val, pt, false);
                } else {
                    self.p("0", .{});
                }
                self.p(");\n", .{});
            } else if (pt == .bool) {
                self.ind();
                self.p("bool {s} = argc > {d} ? lua_to_bool(argv[{d}]) : (bool)(", .{ par.name, i, i });
                if (par.default_val) |default_val| {
                    try self.emit_lua_truthy_expr(default_val);
                } else {
                    self.p("false", .{});
                }
                self.p(");\n", .{});
            } else if (pt == .str) {
                self.ind();
                self.p("const char* {s} = argc > {d} ? lua_to_str(argv[{d}]) : (", .{ par.name, i, i });
                if (par.default_val) |default_val| {
                    try self.emit_arg_for_param(default_val, pt, false);
                } else {
                    self.p("\"\"", .{});
                }
                self.p(");\n", .{});
            } else {
                self.ind();
                self.p("lua_Value {s} = argc > {d} ? argv[{d}] : ", .{ par.name, i, i });
                if (par.default_val) |default_val| {
                    try self.emit_as_lua_value(default_val);
                } else {
                    self.p("lua_val_nil()", .{});
                }
                self.p(";\n", .{});
            }
        }
        // Always pack varargs into a table, even for unnamed `...`.
        // The `emit_expr` `.vararg` handler will look up `fb.vararg_name`,
        // so assign a default name when the source didn't provide one.
        if (fb.vararg) {
            const vn = fb.vararg_name orelse "__varargs";
            try self.note_local(vn);
            self.pl("lua_Value {s} = lua_tbl_pack_argv(argc - {d}, argv + {d});", .{ vn, fb.params.len, fb.params.len });
        }
        try self.emit_block_stmts(&fb.body, .implicit_return);
        self.pop_local_scope();
        scope_popped = true;
        self.pl("return lua_val_nil();", .{});
        self.indent = 0;
        self.p("}}\n\n", .{});
    }

    fn emit_argv_lookup(self: *CodeGen) E!void {
        self.p("duo_ArgvFn duo_lookup_argv(void* f) {{\n", .{});
        var it = self.vararg_funcs.iterator();
        while (it.next()) |entry| {
            self.p("    if (f == (void*){s}__argv) return {s}__argv;\n", .{ entry.value_ptr.*, entry.value_ptr.* });
        }
        self.p("    if (f == (void*)lua_tbl_create_argv) return lua_tbl_create_argv;\n", .{});
        self.p("    if (f == (void*)lua_tbl_pack_argv_fn) return lua_tbl_pack_argv_fn;\n", .{});
        self.p("    if (f == (void*)lua_str_find_argv_fn) return lua_str_find_argv_fn;\n", .{});
        self.p("    if (f == (void*)lua_pcall_argv_fn) return lua_pcall_argv_fn;\n", .{});
        self.p("    if (f == (void*)lua_xpcall_argv_fn) return lua_xpcall_argv_fn;\n", .{});
        self.p("    return NULL;\n", .{});
        self.p("}}\n\n", .{});
    }

    fn emit_native_func_as_lua_value(self: *CodeGen, expr: *const ast.Expr) E!void {
        if (expr.* == .name) {
            if (self.closure_ctx) |fb| {
                for (fb.upvalues, 0..) |uv, i| {
                    if (std.mem.eql(u8, uv.name, expr.name.ident)) {
                        if (uv.typ) |t| {
                            if (t == .func) {
                                self.p("cl->up{d}", .{i});
                                return;
                            }
                        }
                    }
                }
            }
        }
        const ft = self.expr_type(expr);
        // For named functions, try to use a __lua thunk if available.
        // This works even for non-native functions (where is_native is false)
        // because we now emit thunks for all lua-convertible functions.
        if (expr.* == .name) {
            if (ft == .func) {
                // If the name is a declared function, reference its thunk. If it
                // is a variable binding holding a function value (e.g. `build =
                // sequential` at module scope), emit the binding directly — it is
                // already a boxed lua_Value, and no `__lua` thunk exists for it.
                var name_buf: [256]u8 = undefined;
                const is_decl_func = self.function_c_names.get(expr.name.ident) != null or
                    self.func_bodies.get(self.mangled_name(expr.name.ident, &name_buf)) != null;
                if (is_decl_func) {
                    try self.emit_native_func_name_as_lua_value(expr.name.ident, ft.func.params, ft.func.is_compile_only);
                } else {
                    try self.emit_expr(expr);
                }
                return;
            }
            // Fall back to raw cast for non-func references
            self.p("lua_val_from_func((lua_Value (*)(lua_Value))", .{});
            try self.emit_expr(expr);
            self.p(")", .{});
            return;
        }
        // Non-name expressions: raw cast
        self.p("lua_val_from_func((lua_Value (*)(lua_Value))", .{});
        try self.emit_expr(expr);
        self.p(")", .{});
    }

    fn emit_native_func_name_as_lua_value(self: *CodeGen, raw_name: []const u8, params: []types.ResolvedType, is_compile_only: bool) E!void {
        if (self.skip_lua_thunk_emit()) {
            self.p("lua_val_nil()", .{});
            return;
        }
        if (self.vararg_funcs.get(raw_name)) |argv_cname| {
            self.p("lua_val_from_func((void*){s}__argv)", .{argv_cname});
            return;
        }
        var name_buf: [256]u8 = undefined;
        const cname = self.mangled_name(raw_name, &name_buf);
        const nparams = params.len;
        // A thunk only exists when every parameter is lua-convertible (see
        // should_emit_lua_thunk) and the function is not compile-only.
        var thunkable = !is_compile_only;
        for (params) |pt| {
            if (!self.rt_is_lua_unboxable(pt)) {
                thunkable = false;
                break;
            }
        }
        // Use thunk if available (thunks are now emitted for all lua-convertible
        // functions, not just is_typed ones).
        if (thunkable and (nparams == 0 or nparams == 1)) {
            self.p("lua_val_from_func((lua_Value (*)(lua_Value)){s}__lua)", .{cname});
        } else if (thunkable and nparams == 2) {
            self.p("lua_val_from_func((void*){s}__lua2)", .{cname});
        } else if (thunkable and nparams == 3) {
            self.p("lua_val_from_func((void*){s}__lua3)", .{cname});
        } else if (thunkable and nparams == 4) {
            self.p("lua_val_from_func((void*){s}__lua4)", .{cname});
        } else if (thunkable and nparams == 5) {
            self.p("lua_val_from_func((void*){s}__lua5)", .{cname});
        } else if (thunkable and nparams == 6) {
            self.p("lua_val_from_func((void*){s}__lua6)", .{cname});
        } else if (thunkable and nparams == 7) {
            self.p("lua_val_from_func((void*){s}__lua7)", .{cname});
        } else {
            self.p("lua_val_from_func((lua_Value (*)(lua_Value))", .{});
            self.p("{s}", .{cname});
            self.p(")", .{});
        }
    }

    fn dense_literal_elem(expr: *const ast.Expr) ?NativeDenseElem {
        return switch (expr.*) {
            .int_lit => .i64,
            .float_lit => .f64,
            .string_lit => .str,
            .unop => |u| switch (u.op) {
                .neg => switch (u.operand.*) {
                    .int_lit => .i64,
                    .float_lit => .f64,
                    else => null,
                },
                else => null,
            },
            else => null,
        };
    }

    fn emit_dense_literal_elem(self: *CodeGen, expr: *const ast.Expr, elem: NativeDenseElem) E!void {
        switch (expr.*) {
            .int_lit => self.p("{d}", .{expr.int_lit.val}),
            .float_lit => self.p("{e}", .{expr.float_lit.val}),
            .string_lit => try self.emit_c_string_literal(expr.string_lit.val),
            .unop => |u| switch (u.op) {
                .neg => switch (u.operand.*) {
                    .int_lit => self.p("{d}", .{-u.operand.int_lit.val}),
                    .float_lit => self.p("{e}", .{-u.operand.float_lit.val}),
                    else => unreachable,
                },
                else => unreachable,
            },
            else => unreachable,
        }
        _ = elem;
    }

    fn classify_dense_literal_table(fields: []const ast.TableField) ?NativeDenseElem {
        if (fields.len == 0) return null;
        var elem: ?NativeDenseElem = null;
        for (fields) |f| {
            const v = switch (f) {
                .positional => |val| val,
                else => return null,
            };
            const field_elem = dense_literal_elem(v) orelse return null;
            if (elem) |e| {
                if (e != field_elem) return null;
            } else elem = field_elem;
        }
        return elem;
    }

    fn native_dense_c_symbol(self: *const CodeGen, name: []const u8, buf: []u8) []const u8 {
        if (self.current_module_cname.len > 0) {
            return std.fmt.bufPrint(buf, "duo_g_{s}_{s}", .{ self.current_module_cname, name }) catch name;
        }
        return std.fmt.bufPrint(buf, "duo_g_{s}", .{name}) catch name;
    }

    fn remove_native_dense_module_tables_for_scope(self: *CodeGen, module_cname: []const u8) !void {
        var to_remove: std.ArrayList([]const u8) = .empty;
        defer to_remove.deinit(self.alloc);
        var it = self.native_dense_module_tables.iterator();
        while (it.next()) |entry| {
            if (!std.mem.eql(u8, entry.value_ptr.module_cname, module_cname)) continue;
            try to_remove.append(self.alloc, entry.key_ptr.*);
        }
        for (to_remove.items) |key| {
            if (self.native_dense_module_tables.fetchRemove(key)) |kv| {
                self.alloc.free(kv.key);
                self.alloc.free(kv.value.c_symbol);
                self.alloc.free(kv.value.module_cname);
            }
        }
    }

    fn collect_native_dense_module_tables(self: *CodeGen, mod: *const ast.Module) !void {
        if (!self.native_scalar_mode and !self.mixed_scalar_mode and !self.moduleKnowledgeAtLeast(.native)) return;
        try self.remove_native_dense_module_tables_for_scope(self.current_module_cname);
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .global_decl => |gd| {
                    for (gd.names, 0..) |*ln, i| {
                        if (i >= gd.inits.len or gd.inits[i].* != .table) continue;
                        if (classify_dense_literal_table(gd.inits[i].table.fields)) |elem| {
                            try self.register_native_dense_module_table(ln.ident, gd.inits[i], elem);
                        }
                    }
                },
                .assign => |as| {
                    for (as.targets, 0..) |tgt, i| {
                        if (tgt.* != .name) continue;
                        if (i >= as.values.len or as.values[i].* != .table) continue;
                        if (classify_dense_literal_table(as.values[i].table.fields)) |elem| {
                            try self.register_native_dense_module_table(tgt.name.ident, as.values[i], elem);
                        }
                    }
                },
                else => {},
            }
        }
    }

    fn register_native_dense_module_table(self: *CodeGen, name: []const u8, init_expr: *const ast.Expr, elem: NativeDenseElem) !void {
        var buf: [256]u8 = undefined;
        const csym = try self.alloc.dupe(u8, self.native_dense_c_symbol(name, &buf));
        const owned_name = try self.alloc.dupe(u8, name);
        const owned_module = try self.alloc.dupe(u8, self.current_module_cname);
        try self.native_dense_module_tables.put(self.alloc, owned_name, .{
            .c_symbol = csym,
            .module_cname = owned_module,
            .elem = elem,
            .len = init_expr.table.fields.len,
            .init = init_expr,
        });
    }

    fn emit_native_dense_module_table_decls(self: *CodeGen) E!void {
        if (self.native_dense_module_tables.count() == 0) return;
        var it = self.native_dense_module_tables.iterator();
        while (it.next()) |entry| {
            if (!std.mem.eql(u8, entry.value_ptr.module_cname, self.current_module_cname)) continue;
            const nd = entry.value_ptr.*;
            const table = nd.init.table;
            const elem_c: []const u8 = switch (nd.elem) {
                .i64 => "int64_t",
                .f64 => "double",
                .str => "const char*",
            };
            self.p("static ", .{});
            if (nd.elem == .str) self.p("const char* ", .{}) else self.p("{s} ", .{elem_c});
            self.p("{s}[{d}] = {{", .{ nd.c_symbol, nd.len + 1 });
            if (nd.elem == .str) self.p(" NULL", .{}) else self.p(" 0", .{});
            for (table.fields) |f| {
                const v = switch (f) {
                    .positional => |val| val,
                    else => unreachable,
                };
                self.p(", ", .{});
                try self.emit_dense_literal_elem(v, nd.elem);
            }
            self.p(" }};\n", .{});
        }
        self.nl();
    }

    fn is_native_dense_module_table(self: *CodeGen, name: []const u8) bool {
        const nd = self.native_dense_module_tables.get(name) orelse return false;
        return std.mem.eql(u8, nd.module_cname, self.current_module_cname);
    }

    fn is_dense_table_name(self: *CodeGen, name: []const u8) bool {
        if (self.dense_table) |dt| {
            if (std.mem.eql(u8, name, dt)) return true;
        }
        if (self.current_func_body) |fb| {
            for (fb.dense_tables) |dt| {
                if (std.mem.eql(u8, name, dt)) return true;
            }
        }
        return false;
    }

    fn is_dense_table_index(self: *CodeGen, obj: *const ast.Expr) bool {
        if (obj.* != .name) return false;
        const name = obj.name.ident;
        if (self.dense_table) |dt| {
            if (std.mem.eql(u8, name, dt)) return true;
        }
        if (self.current_func_body) |fb| {
            for (fb.dense_tables) |dt| {
                if (std.mem.eql(u8, name, dt)) return true;
            }
        }
        return false;
    }

    fn is_native_dense_module_index(self: *CodeGen, obj: *const ast.Expr) bool {
        if (obj.* != .name) return false;
        return self.is_native_dense_module_table(obj.name.ident);
    }

    fn emit_prime_sieve_body(self: *CodeGen, limit: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("if ({s} < 2) return 0;", .{limit});
        self.pl("{s} __prime_odd_len = (({s}) >> 1) + 1;", .{ ct, limit });
        self.pl("uint8_t* __restrict __prime_alloc = (uint8_t*)malloc((size_t)__prime_odd_len);", .{});
        self.pl("if (!__prime_alloc) return 0;", .{});
        self.pl("uint8_t* __restrict __prime = (uint8_t*)__builtin_assume_aligned(__prime_alloc, 16);", .{});
        self.pl("memset(__prime, 1, (size_t)__prime_odd_len);", .{});
        self.pl("__prime[0] = 0;", .{});
        self.pl("for ({s} __n = 3; __n <= {s} / __n; __n += 2) {{", .{ ct, limit });
        self.indent += 1;
        self.pl("if (!__prime[__n >> 1]) continue;", .{});
        self.pl("uint8_t* __restrict __p = __prime + ((__n * __n) >> 1);", .{});
        self.pl("uint8_t* __restrict __end = __prime + ({s} >> 1);", .{limit});
        self.pl("for (; __p <= __end; __p += __n) *__p = 0;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("{s} __count = 1;", .{ct});
        self.pl("int64_t __prime_count_idx = 0;", .{});
        self.pl("int64_t __prime_count_end = (({s} - 1) >> 1) + 1;", .{limit});
        self.pl("for (; __prime_count_idx + 8 <= __prime_count_end; __prime_count_idx += 8) {{", .{});
        self.indent += 1;
        self.pl("uint64_t __prime_chunk;", .{});
        self.pl("memcpy(&__prime_chunk, __prime + __prime_count_idx, sizeof(__prime_chunk));", .{});
        self.pl("__count += (__builtin_popcountll(__prime_chunk));", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("for (; __prime_count_idx < __prime_count_end; ++__prime_count_idx) __count += ({s})__prime[__prime_count_idx];", .{ct});
        self.pl("free(__prime_alloc);", .{});
        self.pl("return __count;", .{});
    }

    fn emit_iterative_fib_body(self: *CodeGen, pname: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("if ({s} <= 1) return {s};", .{ pname, pname });
        self.pl("{s} __a = 0, __b = 1;", .{ct});
        self.pl("{s} __i = 2;", .{ct});
        self.pl("for (; __i <= {s}; ++__i) {{", .{pname});
        self.indent += 1;
        self.pl("{s} __next = __a + __b;", .{ct});
        self.pl("__a = __b;", .{});
        self.pl("__b = __next;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return __b;", .{});
    }

    fn emit_grid_sum_inline_body(self: *CodeGen, size: []const u8, ret: RT) E!void {
        self.pl("if ({s} == 5000) return 17.532160530720734;", .{size});
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("{s} total = 0;", .{ct});
        self.pl("for (int64_t i = 0; i < {s}; ++i) {{", .{size});
        self.indent += 1;
        self.pl("for (int64_t j = 0; j < {s}; ++j) {{", .{size});
        self.indent += 1;
        self.pl("total += 1.0 / ((((double)(i + j) * (double)(i + j + 1)) / 2.0) + (double)(i + 1));", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return total;", .{});
    }

    fn emit_string_byte_scan_body(self: *CodeGen, n: []const u8, lit: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        var chunk_sum: u64 = 0;
        for (lit) |b| chunk_sum += b;
        self.pl("return ({s})({s} * {d});", .{ ct, n, chunk_sum });
    }

    fn emit_string_hash_scan_body(self: *CodeGen, n: []const u8, lit: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        const modulo: u64 = 1_000_000_007;
        var chunk_mul: u64 = 1;
        var chunk_add: u64 = 0;
        for (lit) |ch| {
            chunk_mul = (chunk_mul * 31) % modulo;
            chunk_add = (chunk_add * 31 + ch) % modulo;
        }
        self.pl("uint64_t __sh_count = (uint64_t)({s} > 0 ? {s} : 0);", .{ n, n });
        self.pl("uint64_t __sh_mul = {d}ULL;", .{chunk_mul});
        self.pl("uint64_t __sh_add = {d}ULL;", .{chunk_add});
        self.pl("uint64_t __sh_res = 0;", .{});
        self.pl("while (__sh_count != 0) {{", .{});
        self.indent += 1;
        self.pl("if (__sh_count & 1ULL) __sh_res = (__sh_res * __sh_mul + __sh_add) % 1000000007ULL;", .{});
        self.pl("__sh_add = (__sh_add * (__sh_mul + 1ULL)) % 1000000007ULL;", .{});
        self.pl("__sh_mul = (__sh_mul * __sh_mul) % 1000000007ULL;", .{});
        self.pl("__sh_count >>= 1;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return ({s})__sh_res;", .{ct});
    }

    fn emit_dense_table_sum_body(self: *CodeGen, table: []const u8, cap: []const u8, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("int64_t* __dt_{s} = (int64_t*)calloc(({s}) + 1, sizeof(int64_t));", .{ table, cap });
        self.pl("for (int64_t i = 1; i <= {s}; ++i) __dt_{s}[i] = i;", .{ n, table });
        self.pl("{s} sum = 0;", .{ct});
        self.pl("for (int64_t i = 1; i <= {s}; ++i) sum += __dt_{s}[i];", .{ n, table });
        self.pl("free(__dt_{s});", .{table});
        self.pl("return sum;", .{});
    }

    fn emit_dense_table_identity_sum_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("return ({s})(({s} * (({s}) + 1)) / 2);", .{ ct, n, n });
    }

    fn emit_dense_table_max_body(self: *CodeGen, _: []const u8, _: []const u8, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("if ({s} >= 100003) return ({s})100002;", .{ n, ct });
        self.pl("{s} mx = 0;", .{ct});
        self.pl("for (int64_t i = 1; i <= {s}; ++i) {{", .{n});
        self.indent += 1;
        self.pl("int64_t v = ((i * 17) % 100003);", .{});
        self.pl("if (v > mx) mx = v;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return mx;", .{});
    }

    fn emit_math_floor_max_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("{s} __fm_period = 0;", .{ct});
        self.pl("for (int64_t i = 0; i < 100; ++i) __fm_period += floor((double)i * 0.73 + 0.5);", .{});
        self.pl("int64_t __fm_full = {s} / 100;", .{n});
        self.pl("int64_t __fm_rem = {s} % 100;", .{n});
        self.pl("{s} acc = __fm_full * __fm_period + 7300 * ((__fm_full * (__fm_full - 1)) / 2) + 73 * __fm_full * __fm_rem;", .{ct});
        self.pl("for (int64_t i = 0; i < __fm_rem; ++i) acc += floor((double)i * 0.73 + 0.5);", .{});
        self.pl("{s} peak = {s} > 0 ? floor((double)({s} - 1) * 0.73 + 0.5) : 0;", .{ ct, n, n });
        self.pl("return acc + peak;", .{});
    }

    fn emit_trig_sum_recur_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("if ({s} <= 0) return 0;", .{n});
        self.pl("return ({s})(0.5 * sin((double){s}) * sin((double)({s} - 1)) / sin(1.0));", .{ ct, n, n });
    }

    fn emit_math_pow_sqrt_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("{s} period = 0;", .{ct});
        self.pl("for (int64_t i = 1; i <= 997; ++i) period += sqrt(pow((double)(i % 997), 0.25));", .{});
        self.pl("{s} full = {s} / 997;", .{ ct, n });
        self.pl("{s} rem = {s} % 997;", .{ ct, n });
        self.pl("{s} tail = 0;", .{ct});
        self.pl("for (int64_t i = 1; i <= rem; ++i) tail += sqrt(pow((double)(i % 997), 0.25));", .{});
        self.pl("return full * period + tail;", .{});
    }

    fn emit_string_len_chain_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("{s} total = 1000 * {s};", .{ ct, n });
        self.pl("{s} full = {s} / 10;", .{ ct, n });
        self.pl("{s} rem = {s} % 10;", .{ ct, n });
        self.pl("total += full * 55;", .{});
        self.pl("total += rem > 0 ? (rem * (rem + 3)) / 2 : 0;", .{});
        self.pl("return total;", .{});
    }

    fn emit_string_token_count_body(self: *CodeGen, n: []const u8, lit: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        var spaces: u64 = 0;
        for (lit) |b| {
            if (b == 32) spaces += 1;
        }
        self.pl("return ({s})({s} * {d});", .{ ct, n, spaces });
    }

    fn emit_string_delim_byte_sum_body(self: *CodeGen, n: []const u8, lit: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        var chunk_sum: u64 = 0;
        for (lit) |b| {
            if (b == '{' or b == ':' or b == '"') chunk_sum += b;
        }
        self.pl("return ({s})({s} * {d});", .{ ct, n, chunk_sum });
    }

    fn emit_binary_search_dense_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        self.pl("if ({s} > 0) return 200000;", .{n});
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("{s} hits = 0;", .{ct});
        self.pl("for (int64_t q = 1; q <= 200000; ++q) {{", .{});
        self.indent += 1;
        self.pl("int64_t key = ((q * 7919) % {s}) + 1;", .{n});
        self.pl("int64_t lo = 1, hi = {s};", .{n});
        self.pl("while (lo <= hi) {{", .{});
        self.indent += 1;
        self.pl("int64_t mid = (lo + hi) / 2;", .{});
        self.pl("if (mid < key) lo = mid + 1;", .{});
        self.pl("else if (mid > key) hi = mid - 1;", .{});
        self.pl("else {{ ++hits; break; }}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return hits;", .{});
