        self.pl("{s} full = {s} / 997;", .{ ct, n });
        self.pl("{s} rem = {s} % 997;", .{ ct, n });
        self.pl("{s} tail = 0;", .{ct});
        self.pl("for (int64_t i = 1; i <= rem; ++i) tail += (i * 13) % 997;", .{});
        self.pl("return full * period + tail;", .{});
