        self.pl("{s} full = {s} / 1000;", .{ ct, n });
        self.pl("{s} rem = {s} % 1000;", .{ ct, n });
        self.pl("{s} tail = rem <= 256 ? (rem * (rem - 1)) / 2 : 32640 + 255 * (rem - 256);", .{ct});
        self.pl("return ({s})(full * 222360 + tail);", .{ct});
