            .if_stmt => |*is| {
                if (is.binding) |b| {
                    try self.note_local(b.name);
                    const bind_rt = self.expr_type(b.expr);
                    if (self.funcUsesNativeLowering(self.current_func_name orelse "") and
                        bind_rt != .any and semantic_algebra.lowersToNativeC(bind_rt))
                    {
                        self.ind();
                        var buf: [64]u8 = undefined;
                        self.p("{s} {s} = ", .{ bind_rt.c_type(&buf), b.name });
                        try self.emit_expr(b.expr);
                        self.p(";\n", .{});
                    } else {
                        self.ind();
                        self.p("lua_Value {s} = ", .{b.name});
                        try self.emit_as_lua_value(b.expr);
                        self.p(";\n", .{});
                    }
                }
                // Dead-branch elimination: if condition is compile-time known,
                // emit only the taken branch (no if/else wrapper).
                if (self.try_eval_const_condition(is.cond)) |known| {
                    if (known) {
                        // Condition always true — emit then-block directly
                        try self.emit_control_block(&is.then);
                    } else {
                        // Condition always false — check elseifs then else
                        var found_taken = false;
                        for (is.elseifs) |*ei| {
                            if (self.try_eval_const_condition(ei.cond)) |ei_known| {
                                if (ei_known) {
                                    try self.emit_control_block(&ei.body);
                                    found_taken = true;
                                    break;
                                }
                                // This elseif is also false, skip it
                            } else {
                                // Unknown elseif — must emit rest dynamically
                                self.ind();
                                self.p("if (", .{});
                                if (self.expr_type(ei.cond) == .any) {
                                    self.p("lua_to_bool(", .{});
                                    try self.emit_expr(ei.cond);
                                    self.p(")", .{});
                                } else {
                                    try self.emit_expr(ei.cond);
                                }
                                self.p(") {{\n", .{});
                                self.indent += 1;
                                try self.emit_control_block(&ei.body);
                                self.indent -= 1;
                                if (is.else_body) |*eb| {
                                    self.ind();
                                    self.p("}} else {{\n", .{});
                                    self.indent += 1;
                                    try self.emit_control_block(eb);
                                    self.indent -= 1;
                                }
                                self.pl("}}", .{});
                                found_taken = true;
                                break;
                            }
                        }
                        if (!found_taken) {
                            if (is.else_body) |*eb| {
                                try self.emit_control_block(eb);
                            }
                        }
                    }
                } else {
                    // Normal runtime if/else emission
                    self.ind();
                    self.p("if (", .{});
                    if (self.expr_type(is.cond) == .any) {
                        self.p("lua_to_bool(", .{});
                        try self.emit_expr(is.cond);
                        self.p(")", .{});
                    } else {
                        try self.emit_expr(is.cond);
                    }
                    self.p(") {{\n", .{});
                    self.indent += 1;
                    try self.emit_control_block(&is.then);
                    self.indent -= 1;
                    for (is.elseifs) |*ei| {
                        self.ind();
                        self.p("}} else if (", .{});
                        if (self.expr_type(ei.cond) == .any) {
                            self.p("lua_to_bool(", .{});
                            try self.emit_expr(ei.cond);
                            self.p(")", .{});
                        } else {
                            try self.emit_expr(ei.cond);
                        }
                        self.p(") {{\n", .{});
                        self.indent += 1;
                        try self.emit_control_block(&ei.body);
                        self.indent -= 1;
                    }
                    if (is.else_body) |*eb| {
                        self.ind();
                        self.p("}} else {{\n", .{});
                        self.indent += 1;
                        try self.emit_control_block(eb);
                        self.indent -= 1;
                    }
                    self.pl("}}", .{});
                }
            },
            .while_loop => |*wl| {
                // Dead-loop elimination: skip entirely if condition is always false
                if (self.try_eval_const_condition(wl.cond)) |known| {
                    if (!known) {
                        // while false ... end → emit nothing (dead code)
                    } else {
                        // while true → emit infinite loop (let C handle it)
                        self.pl("while (1) {{", .{});
                        self.indent += 1;
                        try self.push_break_scope();
                        defer self.pop_break_scope();
                        try self.emit_block(&wl.body);
                        self.indent -= 1;
                        self.pl("}}", .{});
                    }
                } else {
                    self.ind();
                    self.p("while (", .{});
                    if (self.expr_type(wl.cond) == .any) {
                        self.p("lua_to_bool(", .{});
                        try self.emit_expr(wl.cond);
                        self.p(")", .{});
                    } else {
                        try self.emit_expr(wl.cond);
                    }
                    self.p(") {{\n", .{});
                    self.indent += 1;
                    try self.push_break_scope();
                    defer self.pop_break_scope();
                    try self.emit_block(&wl.body);
                    self.indent -= 1;
                    self.pl("}}", .{});
                }
