            .repeat_loop => |*rl| {
                self.pl("do {{", .{});
                self.indent += 1;
                try self.push_break_scope();
                defer self.pop_break_scope();
                try self.emit_block(&rl.body);
                self.indent -= 1;
                self.ind();
                self.p("}} while (!(", .{});
                if (self.expr_type(rl.cond) == .any) {
                    self.p("lua_to_bool(", .{});
                    try self.emit_expr(rl.cond);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(rl.cond);
