    }

    fn derive_arg_count(args: ?[]const u8) usize {
        const raw = args orelse return 0;
        var count: usize = 0;
        var it = std.mem.splitScalar(u8, raw, ',');
        while (it.next()) |part| {
            if (std.mem.trim(u8, part, " \t\r\n").len != 0) count += 1;
        }
        return count;
    }

    fn enum_derive_count(attrs: []const ast.Attribute) usize {
        var count: usize = 0;
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            count += derive_arg_count(attr.args);
        }
        return count;
    }

    fn strip_attribute_string(raw: []const u8) []const u8 {
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        if (trimmed.len >= 2 and trimmed[0] == '"' and trimmed[trimmed.len - 1] == '"') {
            return trimmed[1 .. trimmed.len - 1];
        }
        return trimmed;
    }

    fn attrs_have_derive(attrs: []const ast.Attribute, derive_name: []const u8) bool {
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            const raw = attr.args orelse continue;
            var it = std.mem.splitScalar(u8, raw, ',');
            while (it.next()) |part| {
                if (std.mem.eql(u8, strip_attribute_string(part), derive_name)) return true;
            }
        }
        return false;
    }

    fn enum_has_derive_descriptor(self: *const CodeGen, enum_name: []const u8) bool {
        const ed = self.enum_defs.get(enum_name) orelse return false;
        return enum_derive_count(ed.attributes) > 0;
    }

    fn emit_enum_descriptor(self: *CodeGen, ed: *const ast.EnumDef) E!void {
        const derive_count = enum_derive_count(ed.attributes);
        if (derive_count == 0) return;

        try self.note_local(ed.name);
        self.ind();
        self.pl("lua_Value {s} = lua_table_new_with_capacity(0, 4);", .{ed.name});
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"__duo_kind\", {d}, 10, lua_val_lit(\"enum\"));", .{ ed.name, calc_lua_hash("__duo_kind") });
        self.ind();
        self.p("lua_table_set_raw_lit({s}, \"name\", {d}, 4, lua_val_lit(\"", .{ ed.name, calc_lua_hash("name") });
        try self.emit_string_escaped(ed.name);
        self.p("\"));\n", .{});

        self.ind();
        self.pl("lua_Value {s}_variants = lua_table_new_with_capacity({d}, 0);", .{ ed.name, ed.variants.len });
        for (ed.variants, 0..) |variant, i| {
            const has_payload = variant.payload != null and variant.payload.?.len > 0;
            self.ind();
            self.pl("lua_Value {s}_variant_{d} = lua_table_new_with_capacity(0, 3);", .{ ed.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_variant_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ ed.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(variant.name);
            self.p("\"));\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_variant_{d}, \"tag\", {d}, 3, lua_val_from_int({d}));", .{ ed.name, i, calc_lua_hash("tag"), i });
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_variant_{d}, \"has_payload\", {d}, 11, lua_val_from_bool({s}));", .{ ed.name, i, calc_lua_hash("has_payload"), if (has_payload) "true" else "false" });
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_variants, {d}, {s}_variant_{d});", .{ ed.name, i + 1, ed.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"variants\", {d}, 8, {s}_variants);", .{ ed.name, calc_lua_hash("variants"), ed.name });

        self.ind();
        self.pl("lua_Value {s}_derives = lua_table_new_with_capacity({d}, 0);", .{ ed.name, derive_count });
        var derive_index: usize = 1;
        for (ed.attributes) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            const raw = attr.args orelse continue;
            var it = std.mem.splitScalar(u8, raw, ',');
            while (it.next()) |part| {
                const derive_name = strip_attribute_string(part);
                if (derive_name.len == 0) continue;
                self.ind();
                self.p("lua_table_set_raw_i64({s}_derives, {d}, lua_val_lit(\"", .{ ed.name, derive_index });
                try self.emit_string_escaped(derive_name);
                self.p("\"));\n", .{});
                derive_index += 1;
            }
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"derives\", {d}, 7, {s}_derives);", .{ ed.name, calc_lua_hash("derives"), ed.name });
    }

    fn emit_concept_descriptor(self: *CodeGen, cd: *const ast.ConceptDef) E!void {
        try self.note_local(cd.name);
        self.ind();
        self.pl("lua_Value {s} = lua_table_new_with_capacity(0, 4);", .{cd.name});
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"__duo_kind\", {d}, 10, lua_val_lit(\"concept\"));", .{ cd.name, calc_lua_hash("__duo_kind") });
        self.ind();
        self.p("lua_table_set_raw_lit({s}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, calc_lua_hash("name") });
        try self.emit_string_escaped(cd.name);
        self.p("\"));\n", .{});

        self.ind();
        self.pl("lua_Value {s}_fields = lua_table_new_with_capacity({d}, 0);", .{ cd.name, cd.required_fields.len });
        for (cd.required_fields, 0..) |field, i| {
            self.ind();
            self.pl("lua_Value {s}_field_{d} = lua_table_new_with_capacity(0, 2);", .{ cd.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_field_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(field.name);
            self.p("\"));\n", .{});
            self.ind();
            self.p("lua_table_set_raw_lit({s}_field_{d}, \"type\", {d}, 4, ", .{ cd.name, i, calc_lua_hash("type") });
            try self.emit_type_expr_metadata(field.typ);
            self.p(");\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_fields, {d}, {s}_field_{d});", .{ cd.name, i + 1, cd.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"required_fields\", {d}, 15, {s}_fields);", .{ cd.name, calc_lua_hash("required_fields"), cd.name });

        self.ind();
        self.pl("lua_Value {s}_methods = lua_table_new_with_capacity({d}, 0);", .{ cd.name, cd.required_methods.len });
        for (cd.required_methods, 0..) |method, i| {
            self.ind();
            self.pl("lua_Value {s}_method_{d} = lua_table_new_with_capacity(0, 3);", .{ cd.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_method_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(method.name);
            self.p("\"));\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_method_{d}, \"param_count\", {d}, 11, lua_val_from_num({d}));", .{ cd.name, i, calc_lua_hash("param_count"), method.params.len });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_method_{d}, \"return\", {d}, 6, ", .{ cd.name, i, calc_lua_hash("return") });
            try self.emit_type_expr_metadata(method.ret_type);
            self.p(");\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_methods, {d}, {s}_method_{d});", .{ cd.name, i + 1, cd.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"required_methods\", {d}, 16, {s}_methods);", .{ cd.name, calc_lua_hash("required_methods"), cd.name });
    }

    fn emit_type_expr_metadata(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        self.p("lua_val_from_str(\"", .{});
        try self.emit_type_expr_metadata_inner(type_expr);
        self.p("\")", .{});
    }

    fn emit_type_expr_metadata_inner(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        switch (type_expr) {
            .inferred => try self.emit_string_escaped("any"),
            .named => |name| try self.emit_string_escaped(name),
            .pointer => |child| {
                try self.emit_string_escaped("*");
                try self.emit_type_expr_metadata_inner(child.*);
            },
            .optional => |child| {
                try self.emit_string_escaped("?");
                try self.emit_type_expr_metadata_inner(child.*);
            },
            .array => |arr| {
                if (arr.size) |size| {
                    self.p("[{d}]", .{size});
                } else {
                    try self.emit_string_escaped("[]");
                }
                try self.emit_type_expr_metadata_inner(arr.elem.*);
            },
            .func => try self.emit_string_escaped("function"),
            .record => try self.emit_string_escaped("table"),
            .tuple => try self.emit_string_escaped("tuple"),
            .generic => |g| {
                try self.emit_type_expr_metadata_inner(g.base.*);
                try self.emit_string_escaped("[");
                for (g.params, 0..) |param, i| {
                    if (i > 0) try self.emit_string_escaped(",");
                    try self.emit_type_expr_metadata_inner(param);
                }
                try self.emit_string_escaped("]");
            },
            .constrained => |cp| {
                try self.emit_string_escaped(cp.name);
                try self.emit_string_escaped(":");
                try self.emit_type_expr_metadata_inner(cp.constraint.*);
                for (cp.extra) |extra| {
                    try self.emit_string_escaped("+");
                    try self.emit_type_expr_metadata_inner(extra);
                }
            },
        }
    }

    // ── print() special case ──────────────────────────────────────────────────

    fn emit_print_call(self: *CodeGen, args: []*ast.Expr) E!void {
        if (args.len == 0) {
            self.p("puts(\"\");\n", .{});
            return;
        }
        // Build format string based on arg types
        var fmt_buf: std.ArrayList(u8) = .empty;
        defer fmt_buf.deinit(self.alloc);
        var has_sep = false;
        for (args) |arg| {
            if (has_sep) try fmt_buf.appendSlice(self.alloc, "\\t");
            has_sep = true;
            const t = self.expr_type(arg);
            const spec: []const u8 = blk: {
                if (self.enum_name_of(t)) |ename| {
                    if (self.enum_is_payload_free(ename) and self.enum_has_derive(ename, "Display"))
                        break :blk "%s";
                    if (self.enum_is_payload_free(ename)) break :blk "%d";
                }
                break :blk switch (t) {
                    .i8, .i16, .i32 => "%d",
                    .i64 => "%lld",
                    .u8, .u16, .u32 => "%u",
                    .u64 => "%llu",
                    .f32, .f64 => "%.17g",
                    .bool => "%s",
                    .str => "%s",
                    else => "%s",
                };
            };
            try fmt_buf.appendSlice(self.alloc, spec);
        }
        try fmt_buf.appendSlice(self.alloc, "\\n");
        self.p("printf(\"{s}\"", .{fmt_buf.items});
        for (args) |arg| {
            self.p(", ", .{});
            const t = self.expr_type(arg);
            if (t == .bool) {
                self.p("(", .{});
                try self.emit_expr(arg);
                self.p(") ? \"true\" : \"false\"", .{});
            } else if (t == .any) {
                // Display context: honour __tostring so `print(v)` matches
                // `print(tostring(v))` without the caller writing it out.
                self.p("lua_to_display_str(", .{});
                try self.emit_expr(arg);
                self.p(")", .{});
            } else if (t == .str or arg.* == .string_lit) {
                if (self.expr_emits_lua_value(arg)) {
                    self.p("lua_to_str(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(arg);
                }
            } else if (self.enum_name_of(t)) |ename| {
                if (self.enum_is_payload_free(ename) and self.enum_has_derive(ename, "Display")) {
                    self.p("duo_{s}_to_string(", .{ename});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else if (self.enum_is_payload_free(ename)) {
                    self.p("(int)(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else {
                    self.p("lua_to_str(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                }
            } else {
                try self.emit_expr(arg);
            }
        }
        self.p(");\n", .{});
    }

    fn emit_dynamic_unbox(self: *CodeGen, e: *const ast.Expr, want: RT) E!void {
        const et = self.expr_type(e);
        if (!self.moduleNeedsLuaRuntime()) {
            if (e.* == .name) {
                if (self.local_type(e.name.ident)) |lt| {
                    if (lt.is_numeric() and want.is_numeric()) {
                        if (lt.eql(want)) {
                            try self.emit_expr(e);
                        } else {
                            var buf: [64]u8 = undefined;
                            self.p("(({s})(", .{want.c_type(&buf)});
                            try self.emit_expr(e);
                            self.p("))", .{});
                        }
                        return;
                    }
                    if (lt.eql(want)) {
                        try self.emit_expr(e);
                        return;
                    }
                }
            }
            if (et != .any) {
                if (want.is_numeric() and et.is_numeric()) {
                    if (want.eql(et)) {
                        try self.emit_expr(e);
                    } else {
                        var buf: [64]u8 = undefined;
                        self.p("(({s})(", .{want.c_type(&buf)});
                        try self.emit_expr(e);
                        self.p("))", .{});
                    }
                    return;
                }
                if (want.eql(et)) {
                    try self.emit_expr(e);
                    return;
                }
            }
        }
        if (e.* == .index) {
            if (self.req_module_dense_index_info(e.index.obj)) |nd| {
                const matches = switch (nd.elem) {
                    .str => want == .str,
                    .i64, .f64 => want.is_numeric(),
                };
                if (matches) {
                    try self.emit_expr(e);
                    return;
                }
            }
        }
        if (e.* == .index and self.is_native_dense_module_index(e.index.obj)) {
            // Sema types this as `.any` (it doesn't know about the codegen-only
            // dense-table classification), but the value codegens to a raw C
            // array element, not a lua_Value. Emit it directly when the
            // requested type matches the element's natural representation.
            const nd = self.native_dense_module_tables.get(e.index.obj.name.ident).?;
            const matches = switch (nd.elem) {
                .str => want == .str,
                .i64, .f64 => want.is_numeric(),
            };
            if (matches) {
                try self.emit_expr(e);
                return;
            }
        }
        if (try self.try_emit_table_projection_unbox(e, want)) return;
        // A call into a req-module lowers to a direct C call returning a native
        // value. If sema typed the call `.any` we would wrap it in lua_to_num(),
        // which does not accept an int64_t — so consult the callee's real return
        // type here rather than trusting expr_type alone.
        if (want.is_numeric() and !et.is_numeric()) {
            if (self.infer_req_module_call_return_type(e)) |crt| {
                if (crt.is_numeric()) {
                    var cbuf: [64]u8 = undefined;
                    self.p("(({s})(", .{want.c_type(&cbuf)});
                    try self.emit_expr(e);
                    self.p("))", .{});
                    return;
                }
            }
        }
        if (want.is_numeric() and et.is_numeric()) {
            if (want.eql(et)) {
                // A bare C integer literal has type `int` (32-bit) even where a
                // 64-bit value is wanted. That silently breaks shifts by >= 32
                // (the count wraps mod 32) and any literal that does not fit in
                // 32 bits, so give integer literals explicit 64-bit width.
                if (want == .i64 and e.* == .int_lit) {
                    self.p("INT64_C({d})", .{e.int_lit.val});
                    return;
                }
                try self.emit_expr(e);
            } else {
                var buf: [64]u8 = undefined;
                self.p("(({s})(", .{want.c_type(&buf)});
                try self.emit_expr(e);
                self.p("))", .{});
            }
            return;
        }
        // `tonumber(s) or fallback` already lowers to a native double under full
        // native lowering, so coercing it must be a plain cast — `lua_to_num` does
        // not exist in that profile.
        if (want.is_numeric() and self.expr_is_native_tonumber_or(e)) {
            var cbuf: [64]u8 = undefined;
            self.p("(({s})(", .{want.c_type(&cbuf)});
            try self.emit_expr(e);
            self.p("))", .{});
            return;
        }
        switch (want) {
            .str => {
                if (et == .str) {
                    try self.emit_expr(e);
                } else {
                    self.p("lua_to_str(", .{});
                    try self.emit_expr(e);
                    self.p(")", .{});
                }
            },
            .bool => {
                if (et == .bool) {
                    try self.emit_expr(e);
                } else {
                    self.p("lua_to_bool(", .{});
                    try self.emit_expr(e);
                    self.p(")", .{});
                }
            },
            .f64 => {
                self.p("(double)lua_to_num(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            },
            else => {
                var buf: [64]u8 = undefined;
                self.p("(({s})lua_to_num(", .{want.c_type(&buf)});
                try self.emit_expr(e);
                self.p("))", .{});
            },
        }
    }

    fn emit_mret_get_as(self: *CodeGen, idx: usize, want: RT) void {
        if (want.is_numeric()) {
            var buf: [64]u8 = undefined;
            self.p("(({s})lua_mret_get_num({d}))", .{ want.c_type(&buf), idx });
        } else if (want == .bool) {
            self.p("lua_mret_get_bool({d})", .{idx});
        } else if (want == .str) {
            self.p("lua_mret_get_cstr({d})", .{idx});
        } else {
            self.p("lua_mret_get({d})", .{idx});
        }
    }

    fn try_emit_table_projection_unbox(self: *CodeGen, e: *const ast.Expr, want: RT) E!bool {
        if (!want.is_numeric() and want != .bool and want != .str) return false;
        switch (e.*) {
            .field => |f| {
                if (f.obj.* == .name) {
                    if (self.req_module_bindings.get(f.obj.name.ident)) |mod_cname| {
                        if (try self.try_emit_req_module_const_field(mod_cname, f.field, want)) return true;
                    }
                }
                // §2.7 ambient namespace: `std.a.b.C` is a static path and folds.
                if (f.obj.* == .field) {
                    if (try self.try_emit_ambient_module_const_field(f.obj, f.field, want)) return true;
                }
                const obj_rt = self.expr_type(f.obj);
                if (self.type_lowers_native(obj_rt)) {
                    try self.emit_native_field_access(f.obj, f.field);
                    return true;
                }
                if (obj_rt != .any and self.expr_type(e) != .any) return false;
                const hash = calc_lua_hash(f.field);
                // Pass 34 L2 — interned field IDs: every fallback `.field` access on the
                // dynamic path is emitted through a duo_fallback_get_* marker carrying a
                // stable per-compilation field ID. The marker expands to the standard
                // string-keyed lookup (zero runtime cost), and the generated C records
                // fallback field access + interned field-ID counts for the L6 manifest.
                const fid = self.interned_fallback_field_id(f.field);
                if (want.is_numeric()) {
                    var buf: [64]u8 = undefined;
                    self.p("(({s})duo_fallback_get_num({d}, ", .{ want.c_type(&buf), fid });
                    try self.emit_expr(f.obj);
                    self.p(", \"{s}\", {d}u, {d}))", .{ f.field, hash, f.field.len });
                } else if (want == .bool) {
                    self.p("duo_fallback_get_bool({d}, ", .{fid});
                    try self.emit_expr(f.obj);
                    self.p(", \"{s}\", {d}u, {d})", .{ f.field, hash, f.field.len });
                } else {
                    self.p("duo_fallback_get_cstr({d}, ", .{fid});
                    try self.emit_expr(f.obj);
                    self.p(", \"{s}\", {d}u, {d})", .{ f.field, hash, f.field.len });
                }
                return true;
            },
            .index => |idx| {
                if (self.req_module_dense_index_info(idx.obj)) |nd| {
                    self.p("{s}[", .{nd.c_symbol});
                    try self.emit_expr(idx.key);
                    self.p("]", .{});
                    return true;
                }
                if (self.is_native_dense_module_index(idx.obj)) return false;
                if (self.is_integer_key(idx.key) or positive_int_key(idx.key) != null) {
                    if (want.is_numeric()) {
                        var buf: [64]u8 = undefined;
                        self.p("(({s})lua_table_get_i64_num(", .{want.c_type(&buf)});
                    } else if (want == .bool) {
                        self.p("lua_table_get_i64_bool(", .{});
                    } else {
                        self.p("lua_table_get_i64_cstr(", .{});
                    }
                    try self.emit_expr(idx.obj);
                    self.p(", ", .{});
                    if (positive_int_key(idx.key)) |key| {
                        self.p("{d}", .{key});
                    } else {
                        try self.emit_i64_index_key(idx.key);
                    }
                } else {
                    if (want.is_numeric()) {
                        var buf: [64]u8 = undefined;
                        self.p("(({s})lua_table_get_key_num(", .{want.c_type(&buf)});
                    } else if (want == .bool) {
                        self.p("lua_table_get_key_bool(", .{});
                    } else {
                        self.p("lua_table_get_key_cstr(", .{});
                    }
                    try self.emit_expr(idx.obj);
                    self.p(", ", .{});
                    try self.emit_as_lua_value(idx.key);
                }
                if (want.is_numeric())
                    self.p("))", .{})
                else
                    self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// True when a `.any` binop operand is a table field/index (or numeric call)
    /// whose value is known to be numeric — safe to unbox without skipping metamethods
    /// on arbitrary userdata/table objects.
    fn dynamic_binop_operand_is_numeric_access(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            // Table field reads on dynamic objects; emit unboxes when the value is numeric.
            .field => true,
            .index => |idx| self.expr_type(e).is_numeric() or
                (self.expr_is_dynamic_table(idx.obj) and self.is_integer_key(idx.key)),
            .call => self.expr_type(e).is_numeric(),
            .unop => |u| u.op == .neg and self.dynamic_binop_operand_is_numeric_access(u.operand),
            else => false,
        };
    }

    /// Dynamic table field/index read on a `.any` object — still runs full `lua_table_get`
    /// (including `__index`), but pairs with a numeric-marked local in one-sided binops.
    fn dynamic_binop_operand_is_dynamic_table_read(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .field => |f| blk: {
                if (self.expr_is_req_module_const_field(e)) break :blk false;
                const obj_rt = self.expr_type(f.obj);
                if (obj_rt == .table_type and obj_rt.table_type.storage_class == .native) break :blk false;
                break :blk self.expr_is_dynamic_table(f.obj);
            },
            .index => self.expr_is_dynamic_table(e.index.obj),
            else => false,
        };
    }

    /// Operand safe to treat as a number in a native binop when the other side
    /// is also safe. Bare `.name` locals only qualify after numeric assignment.
    fn dynamic_binop_operand_is_safe_native_unbox(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .int_lit, .float_lit => true,
            .name => |n| self.is_numeric_lua_local(n.ident),
            else => blk: {
                if (self.expr_is_req_module_const_field(e)) break :blk true;
                if (self.expr_is_native_record_field(e)) break :blk true;
                break :blk self.dynamic_binop_operand_is_numeric_access(e);
            },
        };
    }

    /// Both operands are `.any` but each can be unboxed without metamethod dispatch.
    fn try_emit_both_any_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        if (!self.dynamic_binop_operand_is_safe_native_unbox(lhs)) return false;
        if (!self.dynamic_binop_operand_is_safe_native_unbox(rhs)) return false;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(lhs) or self.expr_tree_has_float(rhs);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// One operand is a numeric-marked `lua_Value` local (or literal); the other is a
    /// dynamic table read with a non-numeric key/param. Unbox the local side only.
    fn try_emit_one_sided_any_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        const lhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(lhs);
        const rhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(rhs);
        if (lhs_safe and rhs_safe) return false;

        const pair: struct { safe: *const ast.Expr, read: *const ast.Expr } = if (lhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(rhs) and !rhs_safe)
            .{ .safe = lhs, .read = rhs }
        else if (rhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(lhs) and !lhs_safe)
            .{ .safe = rhs, .read = lhs }
        else
            return false;
        const safe_expr = pair.safe;
        const read_expr = pair.read;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(safe_expr) or self.expr_tree_has_float(read_expr);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(safe_expr, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(read_expr, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// Both operands are dynamic table reads with non-safe keys (e.g. untyped index
    /// params). Still runs full `lua_table_get` per operand; skips `lua_add` etc. on
    /// numeric table values. Not used when either side is a bare `.name` or already
    /// handled by both-any / one-sided paths.
    fn try_emit_both_dynamic_table_read_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        if (!self.dynamic_binop_operand_is_dynamic_table_read(lhs)) return false;
        if (!self.dynamic_binop_operand_is_dynamic_table_read(rhs)) return false;
        if (self.dynamic_binop_operand_is_safe_native_unbox(lhs)) return false;
        if (self.dynamic_binop_operand_is_safe_native_unbox(rhs)) return false;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(lhs) or self.expr_tree_has_float(rhs);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// When exactly one binop operand is a native scalar and the other is `.any`,
    /// emit a direct C operator with a single unbox on the dynamic side.
    fn try_emit_mixed_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        const native_t: RT = if (lt.is_native() and lt != .any and rt == .any)
            lt
        else if (rt.is_native() and rt != .any and lt == .any)
            rt
        else
            return false;
        const native_is_lhs = lt.eql(native_t);
        const any_expr = if (native_is_lhs) rhs else lhs;
        const native_expr = if (native_is_lhs) lhs else rhs;
        const via_any_unbox = self.dynamic_binop_operand_is_safe_native_unbox(any_expr);
        const via_dynamic_read = self.dynamic_binop_operand_is_dynamic_table_read(any_expr);
        const via_native_access = self.dynamic_binop_operand_is_numeric_access(native_expr);
        if (!via_any_unbox and !via_native_access and !via_dynamic_read) return false;
        // Unbox the `.any` side; the native side is either a typed local or a
        // numeric table access that already lowers to a native scalar.
        const dynamic = any_expr;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        if (op == .@"and" or op == .@"or") {
            if (native_t != .bool) return false;
            if (op == .@"or") {
                self.p("((", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") ? (", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") : (", .{});
                try self.emit_dynamic_unbox(dynamic, .bool);
                self.p("))", .{});
            } else {
                self.p("((", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") ? (", .{});
                try self.emit_dynamic_unbox(dynamic, .bool);
                self.p(") : (", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p("))", .{});
            }
            return true;
        }

        if ((op == .eq or op == .neq) and native_t == .str) {
            if (!self.expr_is_native_cstr(if (native_is_lhs) lhs else rhs)) return false;
            self.p("(strcmp(", .{});
            if (native_is_lhs) {
                try self.emit_expr(lhs);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .str);
            } else {
                try self.emit_dynamic_unbox(lhs, .str);
                self.p(", ", .{});
                try self.emit_expr(rhs);
            }
            self.p(") {s} 0)", .{if (op == .eq) "==" else "!="});
            return true;
        }

        if (native_t == .bool) return false;

        const use_float = native_t == .f64 or op == .div or self.expr_tree_has_float(dynamic);
        const unbox_t: RT = if (use_float) .f64 else if (native_t.is_integer()) .i64 else native_t;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                if (native_is_lhs) {
                    try self.emit_expr(lhs);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_dynamic_unbox(rhs, unbox_t);
                } else {
                    try self.emit_dynamic_unbox(lhs, unbox_t);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_expr(rhs);
                }
                self.p(")", .{});
                return true;
            },
            .idiv => {
                if (native_is_lhs) {
                    self.p("lua_idiv_i64((int64_t)(", .{});
                    try self.emit_expr(lhs);
                    self.p("), ", .{});
                    try self.emit_dynamic_unbox(rhs, .i64);
                    self.p(")", .{});
                } else {
                    self.p("lua_idiv_i64(", .{});
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(", (int64_t)(", .{});
                    try self.emit_expr(rhs);
                    self.p("))", .{});
                }
                return true;
            },
            .mod => {
                if (native_is_lhs) {
                    self.p("lua_imod_i64((int64_t)(", .{});
                    try self.emit_expr(lhs);
                    self.p("), ", .{});
                    try self.emit_dynamic_unbox(rhs, .i64);
                    self.p(")", .{});
                } else {
                    self.p("lua_imod_i64(", .{});
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(", (int64_t)(", .{});
                    try self.emit_expr(rhs);
                    self.p("))", .{});
                }
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                if (!native_t.is_integer()) return false;
                self.p("(", .{});
                if (native_is_lhs) {
                    try self.emit_expr(lhs);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_dynamic_unbox(rhs, .i64);
                } else {
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_expr(rhs);
                }
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    fn collect_concat_operands(self: *CodeGen, expr: *const ast.Expr, parts: *std.ArrayList(*const ast.Expr)) E!void {
        if (expr.* == .binop and expr.binop.op == .concat) {
            try self.collect_concat_operands(expr.binop.lhs, parts);
            try self.collect_concat_operands(expr.binop.rhs, parts);
            return;
        }
        try parts.append(self.alloc, expr);
    }

    fn concat_operand_is_native_cstr(self: *CodeGen, expr: *const ast.Expr) bool {
        return self.expr_type(expr) == .str and !self.expr_emits_lua_value(expr);
    }

    fn emit_native_str_concat_left_fold(self: *CodeGen, parts: []const *const ast.Expr, count: usize) E!void {
        if (count == 1) {
            try self.emit_expr(parts[0]);
            return;
        }
        self.p("duo_str_concat(", .{});
        try self.emit_native_str_concat_left_fold(parts, count - 1);
        self.p(", ", .{});
        try self.emit_expr(parts[count - 1]);
        self.p(")", .{});
    }

    fn try_emit_native_str_concat(self: *CodeGen, expr: *const ast.Expr) E!bool {
        var parts: std.ArrayList(*const ast.Expr) = .empty;
        defer parts.deinit(self.alloc);
        try self.collect_concat_operands(expr, &parts);
        if (parts.items.len == 0) return false;
        for (parts.items) |part| {
            if (!self.concat_operand_is_native_cstr(part)) return false;
        }
        try self.emit_native_str_concat_left_fold(parts.items, parts.items.len);
        return true;
    }

    fn expr_is_string_char_call(_: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .call or e.call.func.* != .field) return false;
        const f = e.call.func.field;
        return f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "string") and
            std.mem.eql(u8, f.field, "char");
    }

    fn emit_string_char_lua_value(self: *CodeGen, expr: *const ast.Expr) E!void {
        const c = expr.call;
        self.p("lua_str_char(", .{});
        for (0..4) |i| {
            if (i > 0) self.p(", ", .{});
            if (i < c.args.len) {
                try self.emit_as_lua_value(c.args[i]);
            } else {
                self.p("lua_val_nil()", .{});
            }
        }
        self.p(")", .{});
    }

    fn emit_as_lua_value(self: *CodeGen, expr: *const ast.Expr) E!void {
        // Full-native programs never box — emit direct C values only.
        if (!self.moduleNeedsLuaRuntime()) {
            try self.emit_expr(expr);
            return;
        }
        if (expr.* == .name) {
            if (self.is_native_dense_module_table(expr.name.ident)) {
                try self.emit_native_dense_module_table_as_lua_value(expr.name.ident);
                return;
            }
            if (self.vararg_funcs.get(expr.name.ident)) |argv_cname| {
                self.p("lua_val_from_func((void*){s}__argv)", .{argv_cname});
                return;
            }
            // A module file-scope constant is emitted as a *native* C const
            // (`static const int64_t std_hash_crc64__poly_lo`), but `expr_type`
            // reports it as a plain comptime binding, so no boxing wrapper was
            // added and it reached `lua_bxor` raw: "passing 'const int64_t' to
            // parameter of incompatible type 'lua_Value'". Box it here, where we
            // know a lua_Value is required.
            if (self.current_module_cname.len > 0 and
                self.global_type(expr.name.ident) == null and
                !self.is_local_name(expr.name.ident) and
                self.function_c_names.get(expr.name.ident) == null)
            {
                if (self.comptime_bindings().get(expr.name.ident)) |cv| {
                    const wrap: ?[]const u8 = switch (cv) {
                        .int => "lua_val_from_int",
                        .float => "lua_val_from_num",
                        .bool => "lua_val_from_bool",
                        else => null,
                    };
                    if (wrap) |w| {
                        self.p("{s}(", .{w});
                        self.emit_var_name(expr.name.ident);
                        self.p(")", .{});
                        return;
                    }
                }
            }
        }
        if (expr.* == .string_lit) {
            const hash = calc_lua_hash(expr.string_lit.val);
            self.p("lua_val_from_literal(\"", .{});
            try self.emit_string_escaped(expr.string_lit.val);
            self.p("\", {d}, {d})", .{ hash, expr.string_lit.val.len });
            return;
        }
        const t = self.expr_type(expr);
        const skip_numeric_unbox = blk: {
            const fn_name = self.current_func_name orelse break :blk false;
            if (!self.funcUsesNativeLowering(fn_name)) break :blk false;
            if (!self.exprKnowledge(expr).dominates(.stable)) break :blk false;
            break :blk self.exprLowersToNativeC(t);
        };
        switch (t) {
            .str => {
                if (self.expr_is_string_char_call(expr)) {
                    try self.emit_string_char_lua_value(expr);
                } else if (self.expr_emits_lua_value(expr)) {
                    try self.emit_expr(expr);
                } else {
                    self.p("lua_val_from_str(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                }
            },
            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                self.p("lua_val_from_int((int64_t)(", .{});
                if (self.expr_emits_lua_value(expr) and !skip_numeric_unbox) {
                    self.p("lua_to_num(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(expr);
                }
                self.p("))", .{});
            },
            .f32, .f64 => {
                self.p("lua_val_from_num((double)(", .{});
                if (self.expr_emits_lua_value(expr) and !skip_numeric_unbox) {
                    self.p("lua_to_num(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(expr);
                }
                self.p("))", .{});
            },
            .bool => {
                self.p("lua_val_from_bool(", .{});
                try self.emit_expr(expr);
                self.p(")", .{});
            },
            .func => {
                if (expr.* == .func_expr) {
                    try self.emit_expr(expr);
                } else {
                    try self.emit_native_func_as_lua_value(expr);
                }
            },
            .any => {
                try self.emit_expr(expr);
            },
            else => {
                self.p("lua_val_nil()", .{});
            },
        }
    }

    /// Emit `Alias.fn(args)` as a direct call to the `req`'d module's symbol.
    /// Returns false when the callee is not a resolvable module export, so the
    /// caller can fall through to its existing handling.
    fn emitReqQualifiedCall(self: *CodeGen, c: anytype) E!bool {
        if (c.func.* != .field) return false;
        const f = c.func.field;
        if (f.obj.* != .name) return false;
        const rc = self.req_ctx orelse return false;
        // `@comp.c.export("name")` fixes the emitted C symbol, so it is used
        // verbatim rather than mangled with the module prefix.
        const sym = rc.exportSymbol(f.obj.name.ident, f.field) orelse return false;

        self.p("{s}(", .{sym});
        for (c.args, 0..) |arg, i| {
            if (i > 0) self.p(", ", .{});
            // A field access must go through the native path, which knows a
            // record parameter passed by pointer needs `->`. Plain `emit_expr`
            // always writes `.`, so `Str.sub(self.src, ...)` emitted
            // `self.src` on a `self` that the same function was otherwise
            // dereferencing as `self->pos` — clang rejected the whole module.
            // The native helper falls back to `.` for non-pointer bases, so
            // this is identical everywhere else.
            if (arg.* == .field) {
                try self.emit_native_field_access(arg.field.obj, arg.field.field);
            } else {
                try self.emit_expr(arg);
            }
        }
        self.p(")", .{});
        return true;
    }

    fn emit_bound_field_call(self: *CodeGen, c: anytype) E!void {
        const f = c.func.field;
        const hash = calc_lua_hash(f.field);
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __self = ", .{});
        try self.emit_as_lua_value(f.obj);
        self.p(";\n", .{});
        self.ind();
        self.p("lua_Value __fn = lua_table_get_str_lit(__self, \"{s}\", {d}u, {d});\n", .{ f.field, hash, f.field.len });
        self.ind();
        self.p("lua_Value __argv[{d}] = {{__self", .{c.args.len + 1});
        for (c.args) |arg| {
            self.p(", ", .{});
            try self.emit_as_lua_value(arg);
        }
        self.p("}};\n", .{});
        self.ind();
        self.p("lua_invoke(__fn, {d}, __argv);\n", .{c.args.len + 1});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    // ── Expressions ───────────────────────────────────────────────────────────

    fn emit_num_for_bound(self: *CodeGen, expr: *const ast.Expr, vt: RT) E!void {
        if (self.expr_type(expr) == .any and !self.expr_is_raw_c_intrinsic(expr)) {
            self.p("(", .{});
            self.typ(vt);
            self.p(")lua_to_num(", .{});
            try self.emit_as_lua_value(expr);
            self.p(")", .{});
        } else {
            try self.emit_expr(expr);
        }
    }

    /// True when the expression is the nil literal.
    fn expr_is_nil_lit(self: *CodeGen, e: *const ast.Expr) bool {
        _ = self;
        return e.* == .nil;
    }

    /// True when a native (non-any, non-pointer) typed value can never hold nil.
    fn expr_is_typed_non_nil(self: *CodeGen, e: *const ast.Expr) bool {
        const t = self.expr_type(e);
        return t != .any and t != .nil and t != .str and t != .func and t != .pointer;
    }

    fn emit_list_comprehension(self: *CodeGen, lc: ast.ListComprehension) E!void {
        self.p("({{\n", .{});
        self.indent += 1;
        try self.push_local_scope();
        defer self.pop_local_scope();

        self.ind();
        self.p("lua_Value tmp = lua_table_new();\n", .{});
        self.ind();
        self.p("lua_Value tbl = ", .{});
        try self.emit_as_lua_value(lc.iter);
        self.p(";\n", .{});
        self.ind();
        self.p("int out_idx = 1;\n", .{});
        self.ind();
        self.p("if (tbl.type == VAL_TABLE) {{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Table* t_ptr = (lua_Table*)tbl.as.tval;\n", .{});

        if (lc.key_name) |key_name| {
            try self.note_local(key_name);
            try self.note_local(lc.value_name);

            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("if (t_ptr->array[_gf_idx].type == VAL_NIL) continue;\n", .{});
            self.ind();
            self.p("lua_Value {s} = lua_val_from_num((double)(_gf_idx + 1));\n", .{key_name});
            self.ind();
            self.p("lua_Value {s} = t_ptr->array[_gf_idx];\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});

            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->capacity; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("if (t_ptr->hash_keys[_gf_idx].type == VAL_NIL) continue;\n", .{});
            self.ind();
            self.p("lua_Value {s} = t_ptr->hash_keys[_gf_idx];\n", .{key_name});
            self.ind();
            self.p("lua_Value {s} = t_ptr->hash_vals[_gf_idx];\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        } else {
            try self.note_local(lc.value_name);
            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("lua_Value {s} = t_ptr->array[_gf_idx];\n", .{lc.value_name});
            self.ind();
            self.p("if ({s}.type == VAL_NIL) break;\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }

        self.indent -= 1;
        self.ind();
        self.p("}}\n", .{});
        self.ind();
        self.p("tmp;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn emit_list_comprehension_append(self: *CodeGen, lc: ast.ListComprehension) E!void {
        if (lc.filter) |filter| {
            self.ind();
            self.p("if (", .{});
            try self.emit_lua_truthy_expr(filter);
            self.p(") {{\n", .{});
            self.indent += 1;
        }
        self.ind();
        self.p("lua_table_set_raw_i64(tmp, out_idx++, ", .{});
        try self.emit_as_lua_value(lc.value);
        self.p(");\n", .{});
        if (lc.filter != null) {
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }
    }

    /// `#x` where the operand's type is `.any` (untyped / boxed).
    ///
    /// With the Lua runtime present this is `lua_len_num`, which dispatches on
    /// the boxed tag: table length, string length, 0 for nil. Both `.any` arms
    /// of the `.len` unop used to emit that call unconditionally, but the
    /// runtime preamble that DEFINES `lua_len_num` is emitted only when
    /// `moduleNeedsLuaRuntime()` holds. A full-native module therefore got the
    /// call with no declaration, and clang rejected the whole file with "call
    /// to undeclared function 'lua_len_num'" — examples/nil_init_smoke.duo,
    /// hence `zig build agent-smoke`, died there. Same declaration/use
    /// asymmetry as the `duo_test_jmp` one fixed above.
    ///
    /// There the fix was to declare the symbol on every target. Here it cannot
    /// be: `lua_len_num` takes a `lua_Value`, and a full-native module has no
    /// `lua_Value` type, so declaring it would drag the entire boxed runtime
    /// back in to serve one length. The call goes instead.
    ///
    /// The `.any` bindings full-native mode actually emits are the `void*` a
    /// nil-initialised local starts as — `x = nil` then `x = "hi"`, which is
    /// exactly the smoke test — and what later lands in one is a C string.
    /// Native-list and dense-module shapes are recognised by their own arms
    /// before reaching here. `strlen` is the native reading of the same edge,
    /// and the NULL guard reproduces `lua_len_num`'s own answer for an operand
    /// that is still nil: 0.
    fn emit_any_len(self: *CodeGen, operand: *const ast.Expr) E!void {
        if (self.moduleNeedsLuaRuntime()) {
            self.p("lua_len_num(", .{});
            try self.emit_expr(operand);
            self.p(")", .{});
            return;
        }
        self.p("({{ const char* _duo_lenv = (const char*)(", .{});
        try self.emit_expr(operand);
        self.p("); _duo_lenv ? (int64_t)strlen(_duo_lenv) : (int64_t)0; }})", .{});
    }

    fn emit_expr(self: *CodeGen, expr: *const ast.Expr) E!void {
        switch (expr.*) {
            .quote, .unquote, .macro_call => self.p("/* unexpanded macro expression */ lua_val_nil()", .{}),
            // Pass 36 G1/G2 (`@name`, `@`) are canon but Phase 0 ships no parser
            // production for them, so nothing reaches here. Refuse rather than
            // invent a lowering before the resolution ladder exists.
            .semantic, .semantic_scope => self.p("/* Pass 36 semantic access: not yet lowered */ lua_val_nil()", .{}),
            .sequence => |seq| {
                // In single-value context, emit first expression; rest are side effects.
                if (seq.exprs.len > 0) {
                    try self.emit_expr(seq.exprs[0]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
            },
            .nil => self.p("NULL", .{}),
            .true_lit => self.p("true", .{}),
            .false_lit => self.p("false", .{}),
            .int_lit => |v| self.p("{d}", .{v.val}),
            .float_lit => |v| self.p("{e}", .{v.val}),
            .string_lit => |v| {
                self.p("\"", .{});
                try self.emit_string_escaped(v.val);
                self.p("\"", .{});
            },
            .vararg => {
                if (self.closure_ctx) |fb| {
                    if (fb.vararg_name) |vn| {
                        self.p("lua_tbl_unpack(", .{});
                        self.p("{s}, lua_val_nil(), lua_val_nil())", .{vn});
                        return;
                    }
                    // Unnamed varargs: use default name from __argv path
                    if (fb.vararg) {
                        self.p("lua_tbl_unpack(__varargs, lua_val_nil(), lua_val_nil())", .{});
                        return;
                    }
                }
                self.p("/* ... */", .{});
            },
            .name => |n| {
                if (self.closure_ctx) |fb| {
                    for (fb.params, 0..) |par, i| {
                        if (std.mem.eql(u8, par.name, n.ident)) {
                            const pt = types.resolve(par.typ, null, self.alloc) catch .any;
                            if (pt != .any) {
                                self.p("{s}", .{par.name});
                            } else {
                                self.p("(argc > {d} ? argv[{d}] : lua_val_nil())", .{ i, i });
                            }
                            return;
                        }
                    }
                    for (fb.upvalues, 0..) |uv, i| {
                        if (std.mem.eql(u8, uv.name, n.ident) and uv.is_local) {
                            // Only use closure struct for local upvalues.
                            // Skip if this name is a known global (accessed directly).
                            const is_glob = (!self.is_local_name(n.ident) and self.global_type(n.ident) != null);
                            if (!is_glob) {
                                if (upvalue_uses_pointer(uv)) {
                                    self.p("(*cl->up{d})", .{i});
                                } else {
                                    self.p("cl->up{d}", .{i});
                                }
                                return;
                            }
                        }
                    }
                }
                // Comptime constant folding: if the name has a known compile-time
                // value (e.g., module-level OP_ADD = 0x6A), emit the literal directly.
                // Only applies inside typed functions for non-local names (true constants).
                if (self.current_ret != .any and self.current_ret != .void) {
                    if (!self.is_local_name(n.ident)) {
                        const bindings = self.comptime_bindings();
                        if (bindings.get(n.ident)) |val| {
                            switch (val) {
                                .int => |v| {
                                    self.p("{d}", .{v});
                                    return;
                                },
                                .float => |v| {
                                    self.p("{d}", .{v});
                                    return;
                                },
                                .bool => |v| {
                                    self.p("{s}", .{if (v) "1" else "0"});
                                    return;
                                },
                                else => {},
                            }
                        }
                    }
                }
                if (self.is_native_str_list_local(n.ident)) {
                    self.p("(void*)0", .{});
                    return;
                }
                // 2.10 G3: a primitive type name in VALUE position is a
                // descriptor value. Last resort — every compile-time use of a
                // type name (`to(T)(v)`, `mem.store(T)`, a type annotation)
                // resolves the name earlier and never reaches here, so this only
                // fires where the program genuinely wants the type as data.
                if (primitive_descriptor_name(n.ident)) |canon| {
                    self.emit_primitive_descriptor(canon);
                    return;
                }
                self.emit_var_name(n.ident);
            },
            .field => |f| {
                // Pass 38 G6: `value.@name` — SEMANTIC access. The parser keeps
                // the `@` sigil in the field name so only this arm treats it
                // specially and every other field path is untouched.
                //
                // §1.3 defines it as the effective metatable entry, and §8.5
                // maps `@x` onto Lua's `__x`, which is exactly what
                // `lua_get_metafield_lit` already reads — so this is one lookup
                // against machinery that exists, not a new dispatch mechanism.
                // Retrieval, never binding: `p.@eq` is the VALUE of the
                // relation. It yields nil when the relation is absent rather
                // than erroring, matching §9's rule that an unconsumed
                // projection is a graph fact and not an emitted symbol.
                if (f.field.len > 1 and f.field[0] == '@') {
                    const sem = f.field[1..];
                    var lua_name_buf: [128]u8 = undefined;
                    const lua_name = std.fmt.bufPrint(&lua_name_buf, "__{s}", .{sem}) catch sem;
                    self.p("lua_get_metafield_lit(", .{});
                    try self.emit_as_lua_value(f.obj);
                    self.p(", \"{s}\", {d}u, {d})", .{ lua_name, calc_lua_hash(lua_name), lua_name.len });
                    return;
                }
                // Enum variant access: `Color.Green` -> the C enum constant
                if (f.obj.* == .name and self.enum_has_payload.contains(f.obj.name.ident)) {
                    const ename = f.obj.name.ident;
                    if (self.find_enum_variant_def(ename, f.field) != null) {
                        if (self.enum_has_payload.get(ename).? == false) {
                            self.p("duo_{s}_{s}", .{ ename, f.field });
                        } else {
                            // Payloaded enum referenced by bare variant: emit a
                            // struct literal with just the tag set.
                            self.p("((duo_{s}){{ .tag = duo_{s}_tag_{s} }})", .{ ename, ename, f.field });
                        }
                        return;
                    }
                    if (self.enum_has_derive_descriptor(ename)) {
                        self.p("lua_table_get_str_lit({s}, \"{s}\", {d}u, {d})", .{ ename, f.field, calc_lua_hash(f.field), f.field.len });
                    } else {
                        self.p("lua_val_nil()", .{});
                    }
                    return;
                }
                if (f.obj.* == .name) {
                    if (self.req_module_bindings.get(f.obj.name.ident)) |mod_cname| {
                        if (try self.try_emit_req_module_const_field(mod_cname, f.field, self.expr_type(expr))) return;
                    }
                }
                // §2.7 ambient namespace: `std.a.b.C` is a static path and folds.
                if (f.obj.* == .field) {
                    if (try self.try_emit_ambient_module_const_field(f.obj, f.field, self.expr_type(expr))) return;
                }
                // §2.7: when the path itself NAMES A MODULE (`std.json`) there is
                // no `std` variable to walk from — emitting one produced
                // "use of undeclared identifier 'std'". Resolve it exactly as a
                // `req` binding does, so the caller's own field access
                // (`.encode`) then reads the module table as usual. Runs after
                // the const fold so a folded symbol still wins, and only when the
                // path resolves to a real module file, leaving `a.b` untouched.
                if (self.duo_mode) {
                    var mbuf: [512]u8 = undefined;
                    if (ambient_dotted_path(expr, &mbuf)) |mod_path| {
                        if (std.mem.startsWith(u8, mod_path, "std.") and
                            self.find_module_file_for_req(mod_path) != null)
                        {
                            self.p("lua_require(lua_val_from_literal(\"{s}\", {d}, {d}))", .{
                                mod_path,
                                calc_lua_hash(mod_path),
                                mod_path.len,
                            });
                            return;
                        }
                    }
                }
                const obj_rt = self.expr_type(f.obj);
                if (obj_rt == .any) {
                    const hash = calc_lua_hash(f.field);
                    const ft = self.expr_type(expr);
                    // When field type is known, extract native value for downstream native ops
                    if (ft.is_numeric()) {
                        self.p("((", .{});
                        self.typ(ft);
                        self.p(")lua_table_get_str_num(", .{});
                        try self.emit_expr(f.obj);
                        self.p(", \"{s}\", {d}u, {d}))", .{ f.field, hash, f.field.len });
                    } else if (ft == .bool) {
                        self.p("lua_table_get_str_bool(", .{});
                        try self.emit_expr(f.obj);
                        self.p(", \"{s}\", {d}u, {d})", .{ f.field, hash, f.field.len });
                    } else if (ft == .str) {
                        self.p("lua_table_get_str_cstr(", .{});
                        try self.emit_expr(f.obj);
                        self.p(", \"{s}\", {d}u, {d})", .{ f.field, hash, f.field.len });
                    } else {
                        self.p("lua_table_get_str_lit(", .{});
                        try self.emit_expr(f.obj);
                        self.p(", \"{s}\", {d}u, {d})", .{ f.field, hash, f.field.len });
                    }
                } else {
                    try self.emit_native_field_access(f.obj, f.field);
                }
            },
            .index => |idx| {
                if (self.req_module_dense_index_info(idx.obj)) |nd| {
                    self.p("{s}[", .{nd.c_symbol});
                    try self.emit_expr(idx.key);
                    self.p("]", .{});
                    return;
                }
                if (self.is_native_dense_module_index(idx.obj)) {
                    const nd = self.native_dense_module_tables.get(idx.obj.name.ident).?;
                    self.p("{s}[", .{nd.c_symbol});
                    try self.emit_expr(idx.key);
                    self.p("]", .{});
                    return;
                }
                if (self.is_dense_table_index(idx.obj)) {
                    if (idx.obj.* == .name) {
                        const dt = idx.obj.name.ident;
                        self.p("__dt_{s}[", .{dt});
                        try self.emit_expr(idx.key);
                        self.p("]", .{});
                        return;
                    }
                }
                const ft = self.expr_type(expr);
                if (self.expr_is_dynamic_table(idx.obj)) {
                    if (positive_int_key(idx.key)) |key| {
                        if (ft.is_numeric()) {
                            self.p("((", .{});
                            self.typ(ft);
                            self.p(")lua_table_get_i64_num(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", {d}))", .{key});
                        } else {
                            self.p("lua_table_get_i64(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", {d})", .{key});
                        }
                    } else if (self.is_integer_key(idx.key)) {
                        if (ft.is_numeric()) {
                            self.p("((", .{});
                            self.typ(ft);
                            self.p(")lua_table_get_i64_num(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", ", .{});
                            try self.emit_i64_index_key(idx.key);
                            self.p("))", .{});
                        } else {
                            self.p("lua_table_get_i64(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", ", .{});
                            try self.emit_i64_index_key(idx.key);
                            self.p(")", .{});
                        }
                    } else {
                        if (ft.is_numeric()) {
                            self.p("((", .{});
                            self.typ(ft);
                            self.p(")lua_table_get_key_num(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", ", .{});
                            try self.emit_as_lua_value(idx.key);
                            self.p("))", .{});
                        } else if (ft == .bool) {
                            self.p("lua_table_get_key_bool(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", ", .{});
                            try self.emit_as_lua_value(idx.key);
                            self.p(")", .{});
                        } else if (ft == .str) {
                            self.p("lua_table_get_key_cstr(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", ", .{});
                            try self.emit_as_lua_value(idx.key);
                            self.p(")", .{});
                        } else {
                            self.p("lua_table_get(", .{});
                            try self.emit_expr(idx.obj);
                            self.p(", ", .{});
                            try self.emit_as_lua_value(idx.key);
                            self.p(")", .{});
                        }
                    }
                } else {
                    try self.emit_expr(idx.obj);
                    self.p("[", .{});
                    try self.emit_expr(idx.key);
                    self.p("]", .{});
                }
            },
            .call => |c| {
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__constexpr") and c.args.len == 1) {
                    try self.emit_comptime_expr(c.args[0], self.expr_type(expr) == .any);
                    return;
                }
                // __asm("template") or __asm("template", "constraints") — emit inline asm
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__asm")) {
                    try self.emit_inline_asm(c.args);
                    return;
                }
                // __bitcast(expr, "type") — emit reinterpret cast
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__bitcast") and c.args.len == 2) {
                    if (c.args[1].* == .string_lit) {
                        self.p("(*({s}*)&(", .{c.args[1].string_lit.val});
                        try self.emit_expr(c.args[0]);
                        self.p("))", .{});
                        return;
                    }
                }
                // __volatile(ptr) — volatile pointer dereference
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__volatile") and c.args.len == 1) {
                    self.p("(*(volatile typeof(*(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p("))*)&(*(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(")))", .{});
                    return;
                }
                // __sizeof("type") or __sizeof(expr) — emit sizeof
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__sizeof") and c.args.len == 1) {
                    if (c.args[0].* == .string_lit) {
                        self.p("((int64_t)sizeof({s}))", .{c.args[0].string_lit.val});
                    } else {
                        self.p("((int64_t)sizeof(", .{});
                        try self.emit_expr(c.args[0]);
                        self.p("))", .{});
                    }
                    return;
                }
                // __alignof("type") — emit _Alignof
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__alignof") and c.args.len == 1) {
                    if (c.args[0].* == .string_lit) {
                        self.p("((int64_t)_Alignof({s}))", .{c.args[0].string_lit.val});
                    } else {
                        self.p("((int64_t)_Alignof(typeof(", .{});
                        try self.emit_expr(c.args[0]);
                        self.p(")))", .{});
                    }
                    return;
                }
                // __offsetof("struct_type", "field") — emit offsetof
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__offsetof") and c.args.len == 2) {
                    if (c.args[0].* == .string_lit and c.args[1].* == .string_lit) {
                        self.p("((int64_t)__builtin_offsetof({s}, {s}))", .{ c.args[0].string_lit.val, c.args[1].string_lit.val });
                        return;
                    }
                }
                // __emit("raw C code") — inject raw C expression at compile time.
                // Ultimate metaprogramming escape hatch — more powerful than any
                // macro system because you can emit arbitrary C.
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__emit") and c.args.len >= 1) {
                    if (self.fold_meta_string_expr(c.args[0])) |folded| {
                        self.p("{s}", .{folded});
                        return;
                    }
                    if (c.args[0].* == .string_lit) {
                        self.p("{s}", .{c.args[0].string_lit.val});
                    } else {
                        // Try comptime eval to get the string
                        const val = comptime_eval.evalWithBindings(c.args[0], self.comptime_bindings(), self.comptime_eval_options()) catch {
                            self.p("/* __emit: arg must be comptime string */0", .{});
                            return;
                        };
                        if (val == .string) {
                            self.p("{s}", .{val.string});
                        } else {
                            self.p("/* __emit: arg must evaluate to string */0", .{});
                        }
                    }
                    return;
                }
                // __c_call("name", args...) — direct raw C function call.
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__c_call") and c.args.len >= 1) {
                    if (c.args[0].* != .string_lit) {
                        self.p("/* __c_call: first arg must be function name */0", .{});
                        return;
                    }
                    self.p("{s}(", .{c.args[0].string_lit.val});
                    for (c.args[1..], 0..) |arg, i| {
                        if (i > 0) self.p(", ", .{});
                        try self.emit_expr(arg);
                    }
                    self.p(")", .{});
                    return;
                }
                // __as("ctype", expr) — explicit typed coercion from @as(T, expr).
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__as") and c.args.len == 2) {
                    if (c.args[0].* != .string_lit) {
                        self.p("/* __as: first arg must be type name */0", .{});
                        return;
                    }
                    const target_name = c.args[0].string_lit.val;
                    if (self.type_from_c_name(target_name)) |target| {
                        try self.emit_arg_for_param(c.args[1], target, true);
                    } else {
                        self.p("(({s})(", .{target_name});
                        try self.emit_expr(c.args[1]);
                        self.p("))", .{});
                    }
                    return;
                }
                // __as_type(expr, "ctype") — explicit typed coercion (reversed arg order from __as)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__as_type") and c.args.len == 2) {
                    if (c.args[1].* != .string_lit) {
                        self.p("/* __as_type: second arg must be type name */0", .{});
                        return;
                    }
                    const target_name = c.args[1].string_lit.val;
                    if (self.type_from_c_name(target_name)) |target| {
                        try self.emit_arg_for_param(c.args[0], target, true);
                    } else {
                        self.p("(({s})(", .{target_name});
                        try self.emit_expr(c.args[0]);
                        self.p("))", .{});
                    }
                    return;
                }
                // __typeinfo(expr) — returns string type name at compile time
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__typeinfo") and c.args.len == 1) {
                    const rt = self.expr_type(c.args[0]);
                    var buf: [128]u8 = undefined;
                    const name = rt.c_type(&buf);
                    self.p("\"{s}\"", .{name});
                    return;
                }
                // __comptimeif(cond_expr, then_expr, else_expr) — compile-time conditional expression
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__comptimeif") and c.args.len == 3) {
                    if (self.try_eval_const_condition(c.args[0])) |known| {
                        if (known) {
                            try self.emit_expr(c.args[1]);
                        } else {
                            try self.emit_expr(c.args[2]);
                        }
                        return;
                    }
                    // Fall through to runtime if condition is unknown
                }
                // __static_assert(cond_string, msg_string) — compile-time assertion
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__static_assert")) {
                    if (c.args.len >= 1 and c.args[0].* == .string_lit) {
                        const msg = if (c.args.len >= 2 and c.args[1].* == .string_lit) c.args[1].string_lit.val else "static assertion failed";
                        self.p("_Static_assert({s}, \"{s}\")", .{ c.args[0].string_lit.val, msg });
                    } else if (c.args.len >= 1) {
                        // Try comptime eval for the condition
                        if (self.try_eval_const_condition(c.args[0])) |known| {
                            if (!known) {
                                self.p("_Static_assert(0, \"compile-time assertion failed\")", .{});
                            } else {
                                self.p("((void)0)", .{});
                            }
                        } else {
                            self.p("_Static_assert(", .{});
                            try self.emit_expr(c.args[0]);
                            const msg2 = if (c.args.len >= 2 and c.args[1].* == .string_lit) c.args[1].string_lit.val else "assertion failed";
                            self.p(", \"{s}\")", .{msg2});
                        }
                    }
                    return;
                }
                // __typeof(expr) — emit typeof(expr) for type-generic C programming
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__typeof") and c.args.len == 1) {
                    if (c.args[0].* == .string_lit) {
                        // String literal → use as raw type name
                        self.p("{s}", .{c.args[0].string_lit.val});
                    } else {
                        self.p("typeof(", .{});
                        try self.emit_expr(c.args[0]);
                        self.p(")", .{});
                    }
                    return;
                }
                // __likely(expr) — branch prediction hint (likely true)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__likely") and c.args.len == 1) {
                    self.p("(__builtin_expect(!!(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p("), 1))", .{});
                    return;
                }
                // __unlikely(expr) — branch prediction hint (likely false)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__unlikely") and c.args.len == 1) {
                    self.p("(__builtin_expect(!!(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p("), 0))", .{});
                    return;
                }
                // __prefetch(ptr) or __prefetch(ptr, rw, locality) — cache prefetch
                // rw: 0=read, 1=write. locality: 0-3 (3=keep in all caches)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__prefetch")) {
                    if (c.args.len == 1) {
                        self.p("(__builtin_prefetch((const void*)(", .{});
                        try self.emit_expr(c.args[0]);
                        self.p("), 0, 3), 0)", .{});
                    } else if (c.args.len == 3) {
                        self.p("(__builtin_prefetch((const void*)(", .{});
                        try self.emit_expr(c.args[0]);
                        self.p("), ", .{});
                        try self.emit_expr(c.args[1]);
                        self.p(", ", .{});
                        try self.emit_expr(c.args[2]);
                        self.p("), 0)", .{});
                    }
                    return;
                }
                // __assume(expr) — optimizer hint that expr is always true
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__assume") and c.args.len == 1) {
                    self.p("(__builtin_assume(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p("), 0)", .{});
                    return;
                }
                // __unreachable() — mark code path as unreachable for optimizer
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__unreachable") and c.args.len == 0) {
                    self.p("(__builtin_unreachable(), 0)", .{});
                    return;
                }
                // __trap() — cause immediate abort (for invariant violations)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__trap") and c.args.len == 0) {
                    self.p("(__builtin_trap(), 0)", .{});
                    return;
                }
                // __comptimefold(start, stop, step, "acc_init", "body_template")
                // Unrolls a loop at compile time. Body template uses %i for index, %a for accumulator.
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__comptimefold")) {
                    try self.emit_comptimefold(c.args);
                    return;
                }
                // __comptimefor(start, stop, "body_template")
                // Generates code for each iteration. Body template uses %i for the index.
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__comptimefor")) {
                    try self.emit_comptimefor(c.args);
                    return;
                }
                // __select(index, args...) — compile-time argument selection (like Zig's @field)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__select") and c.args.len >= 2) {
                    if (c.args[0].* == .int_lit) {
                        const idx: usize = @intCast(c.args[0].int_lit.val);
                        if (idx < c.args.len - 1) {
                            try self.emit_expr(c.args[idx + 1]);
                            return;
                        }
                    }
                }
                // __ctz(expr) — count trailing zeros
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__ctz") and c.args.len == 1) {
                    self.p("((int64_t)__builtin_ctzll((unsigned long long)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(")))", .{});
                    return;
                }
                // __clz(expr) — count leading zeros
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__clz") and c.args.len == 1) {
                    self.p("((int64_t)__builtin_clzll((unsigned long long)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(")))", .{});
                    return;
                }
                // __popcount(expr) — population count (number of set bits)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__popcount") and c.args.len == 1) {
                    self.p("((int64_t)__builtin_popcountll((unsigned long long)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(")))", .{});
                    return;
                }
                // __bswap(expr) — byte swap (endian conversion)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__bswap") and c.args.len == 1) {
                    self.p("((int64_t)__builtin_bswap64((uint64_t)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(")))", .{});
                    return;
                }
                // __rotl(value, shift) — rotate left
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__rotl") and c.args.len == 2) {
                    self.p("((int64_t)(((uint64_t)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(") << (", .{});
                    try self.emit_expr(c.args[1]);
                    self.p(")) | ((uint64_t)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(") >> (64 - (", .{});
                    try self.emit_expr(c.args[1]);
                    self.p(")))))", .{});
                    return;
                }
                // __rotr(value, shift) — rotate right
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__rotr") and c.args.len == 2) {
                    self.p("((int64_t)(((uint64_t)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(") >> (", .{});
                    try self.emit_expr(c.args[1]);
                    self.p(")) | ((uint64_t)(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(") << (64 - (", .{});
                    try self.emit_expr(c.args[1]);
                    self.p(")))))", .{});
                    return;
                }
                // __fence() — memory fence / compiler barrier
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__fence") and c.args.len == 0) {
                    self.p("(__atomic_thread_fence(__ATOMIC_SEQ_CST), 0)", .{});
                    return;
                }
                // ═══════════════════════════════════════════════════════════════
                // METAPROGRAMMING: Type introspection & reflection
                // ═══════════════════════════════════════════════════════════════

                // __fields(TypeOrExpr) — returns compile-time table of field descriptors
                // Each entry: { name = "field_name", type = "c_type", offset = N, size = N }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__fields")) {
                    try self.emit_fields_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and try self.maybe_emit_meta_int_call(c.func.name.ident, c.args)) {
                    return;
                }
                if (c.func.* == .name and try self.maybe_emit_meta_bool_call(c.func.name.ident, c.args)) {
                    return;
                }
                if (c.func.* == .name and try self.maybe_emit_meta_string_call(c.func.name.ident, c.args)) {
                    return;
                }
                // __methods(TypeOrExpr) — returns compile-time table of method names
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__methods")) {
                    try self.emit_methods_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__concept_methods")) {
                    try self.emit_concept_methods_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__concept_fields")) {
                    try self.emit_concept_fields_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__concept_members")) {
                    try self.emit_concept_members_intrinsic(c.args);
                    return;
                }
                // __variants(EnumType) — returns compile-time table of variant descriptors
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__variants")) {
                    try self.emit_variants_intrinsic(c.args);
                    return;
                }
                // __has_field(TypeOrExpr, "field_name") — compile-time boolean check
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__has_field") and c.args.len == 2) {
                    try self.emit_has_field_intrinsic(c.args);
                    return;
                }
                // __has_method(TypeOrExpr, "method_name") — compile-time boolean check
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__has_method") and c.args.len == 2) {
                    try self.emit_has_method_intrinsic(c.args);
                    return;
                }
                // __has_metamethod(TypeOrExpr, "metamethod_name") — compile-time metamethod check
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__has_metamethod") and c.args.len == 2) {
                    try self.emit_has_metamethod_intrinsic(c.args);
                    return;
                }
                // __satisfies(TypeOrExpr, "concept_name") — compile-time concept check
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__satisfies") and c.args.len == 2) {
                    try self.emit_satisfies_intrinsic(c.args);
                    return;
                }
                // __field_type(TypeOrExpr, "field_name") — returns C type name string
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__field_type") and c.args.len == 2) {
                    try self.emit_field_type_intrinsic(c.args);
                    return;
                }
                // __type_name(expr) — returns the Duo type name as a string literal
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__type_name") and c.args.len == 1) {
                    try self.emit_type_name_intrinsic(c.args);
                    return;
                }
                // __type_shape(expr) — returns table storage class: dynamic|guarded|sealed|native
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__type_shape") and c.args.len == 1) {
                    try self.emit_type_shape_intrinsic(c.args);
                    return;
                }
                // __why_shape(expr) — factual explanation for table storage-class choice
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__why_shape") and c.args.len == 1) {
                    try self.emit_why_shape_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__why_boxed") and c.args.len == 1) {
                    try self.emit_why_boxed_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__why_not_native") and c.args.len == 1) {
                    try self.emit_why_not_native_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__representation") and c.args.len == 1) {
                    try self.emit_representation_intrinsic(c.args);
                    return;
                }
                // __why(expr) — specialization explanation (table shapes today; honest fallback otherwise)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__why") and c.args.len == 1) {
                    try self.emit_why_intrinsic(c.args);
                    return;
                }
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__why_module") and c.args.len == 1) {
                    try self.emit_why_module_intrinsic(c.args);
                    return;
                }
                // __origin(expr) — provenance summary: storage_class + shape_id when known
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__origin") and c.args.len == 1) {
                    try self.emit_origin_intrinsic(c.args);
                    return;
                }
                // __type_id(expr) — returns a stable compile-time integer type identifier
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__type_id") and c.args.len == 1) {
                    try self.emit_type_id_intrinsic(c.args);
                    return;
                }
                // __is_type(expr, "type_name") — compile-time type check
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__is_type") and c.args.len == 2) {
                    try self.emit_is_type_intrinsic(c.args);
                    return;
                }

                // ═══════════════════════════════════════════════════════════════
                // METAPROGRAMMING: Compile-time messages & errors
                // ═══════════════════════════════════════════════════════════════

                // __comptimeprint("msg") — print at compile time (debug aid)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__comptimeprint") and c.args.len >= 1) {
                    try self.emit_comptime_message(c.args, .info);
                    return;
                }
                // __comptimewarn("msg") — emit compile-time warning
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__comptimewarn") and c.args.len >= 1) {
                    try self.emit_comptime_message(c.args, .warning);
                    return;
                }
                // __comptimeerror("msg") — abort compilation with error
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__comptimeerror") and c.args.len >= 1) {
                    try self.emit_comptime_message(c.args, .err);
                    return;
                }

                // ═══════════════════════════════════════════════════════════════
                // METAPROGRAMMING: File embedding
                // ═══════════════════════════════════════════════════════════════

                // __embed_str("path") — embed file contents as string literal
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__embed_str") and c.args.len == 1) {
                    try self.emit_embed_str(c.args[0]);
                    return;
                }
                // __embed_file("path") — embed file as byte array (returns pointer + len)
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__embed_file") and c.args.len == 1) {
                    try self.emit_embed_file(c.args[0]);
                    return;
                }
                // __make_type("name", "field1", "type1", "field2", "type2", ...) — define struct
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__make_type")) {
                    try self.emit_make_type_intrinsic(c.args);
                    return;
                }

                // ═══════════════════════════════════════════════════════════════
                // METAPROGRAMMING: Layout control
                // ═══════════════════════════════════════════════════════════════

                // __field_offset(TypeOrExpr, "field_name") — byte offset of field
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__field_offset") and c.args.len == 2) {
                    try self.emit_field_offset_intrinsic(c.args);
                    return;
                }
                // __field_size(TypeOrExpr, "field_name") — byte size of field
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__field_size") and c.args.len == 2) {
                    try self.emit_field_size_intrinsic(c.args);
                    return;
                }
                // __bitfield("struct_type", {field_name, bits}, ...) — define packed bitfield
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__bitfield")) {
                    try self.emit_bitfield_intrinsic(c.args);
                    return;
                }
                // __union("union_type", ...) — define C union type
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__union")) {
                    try self.emit_union_intrinsic(c.args);
                    return;
                }

                // ═══════════════════════════════════════════════════════════════
                // METAPROGRAMMING: Metatable type tracking
                // ═══════════════════════════════════════════════════════════════

                // __metatable_type(expr) — returns metatable type info as table
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__metatable_type") and c.args.len == 1) {
                    try self.emit_metatable_type_intrinsic(c.args);
                    return;
                }

                // ═══════════════════════════════════════════════════════════════
                // METAPROGRAMMING: Dispatch hints (zero-overhead wrappers)
                // ═══════════════════════════════════════════════════════════════

                // __inline_always(expr) — hint: inline the expression's function call
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__inline_always") and c.args.len == 1) {
                    self.p("(__attribute__((always_inline)) ", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(")", .{});
                    return;
                }
                // __no_inline(expr) — hint: never inline this call
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__no_inline") and c.args.len == 1) {
                    self.p("(__attribute__((noinline)) ", .{});
                    try self.emit_expr(c.args[0]);
                    self.p(")", .{});
                    return;
