                    try self.emit_expr(c.args[0]);
                    self.p("), 0))", .{});
                    return;
                }
                // __hot_path(expr) — mark as hot (likely) code path
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__hot_path") and c.args.len == 1) {
                    self.p("(__builtin_expect(!!(", .{});
                    try self.emit_expr(c.args[0]);
                    self.p("), 1))", .{});
                    return;
                }
                if (try self.maybe_emit_enum_eq_call(c.func, c.args)) return;
                if (try self.maybe_emit_enum_display_call(c.func, c.args)) return;
                if (try self.maybe_emit_enum_variant_constructor(expr, c.func, c.args)) return;
                if (try self.maybe_emit_ml_call(c.func, c.args)) return;
                if (try self.maybe_emit_mem_call(c.func, c.args, self.expr_type(expr))) return;
                if (try self.maybe_emit_atomic_call(c.func, c.args, self.expr_type(expr))) return;
                if (try self.maybe_emit_math_call(c.func, c.args, self.expr_type(expr))) return;
                if (try self.maybe_emit_simd_call(c.func, c.args)) return;
                if (try self.maybe_emit_stdlib_call(c.func, c.args, self.expr_type(expr))) return;
                if (try self.try_emit_req_module_field_call(c.func, c.args, self.expr_type(expr))) return;
                if (try self.maybe_emit_stdlib_module_call(c.func, c.args, self.expr_type(expr))) return;
                if (c.func.* == .name) {
                    if (try self.tryEmitCallTransformDispatch(expr)) return;
                    if (types.inferCallShape(expr)) |shape| {
                        const site = self.callSiteForShape(shape);
                        self.noteCallTransformProvenance(shape, site, null);
                    }
                } else if (types.inferCallShape(expr)) |shape| {
                    const site = self.callSiteForShape(shape);
                    self.noteCallTransformProvenance(shape, site, null);
                }
                var ft = self.expr_type(c.func);
                // Sema may only know a function name as `.any` for forward calls.
                // Recover the typed signature so we can emit a direct C call.
                if (c.func.* == .name) {
                    var name_buf: [256]u8 = undefined;
                    if (self.func_bodies.get(self.mangled_name(c.func.name.ident, &name_buf))) |body| {
                        const fb_type = self.func_expr_type(body);
                        if (fb_type == .func) ft = fb_type;
                    }
                    // Mixed native/dynamic: non-allowlisted callees route through lua_invoke
                    // UNLESS the callee's resolved type proves all params+return are native.
                    // This is the per-call knowledge lattice (Pass 2) driving emission.
                    if (!self.moduleUsesFullNativeLowering() and
                        ft == .func and c.func.* == .name and !self.funcUsesNativeLowering(c.func.name.ident))
                    {
                        if (!self.funcTypeIsFullyNative(ft)) {
                            // Embedded modules: keep native ft for same-module calls with
                            // native returns (params may be any → lua_Value in C ABI).
                            if (self.current_module_cname.len == 0 or !self.exprLowersToNativeC(ft.func.ret.*)) {
                                ft = .any;
                            }
                        }
                    }
                    // Same-module embedded calls (e.g. decode.read_byte in read_i32_imm) and
                    // main-module mixed-native allowlist (e.g. cur_loc/adv in lexer.duo).
                    if (ft == .func and self.exprLowersToNativeC(ft.func.ret.*) and
                        (self.current_module_cname.len > 0 or
                            (c.func.* == .name and self.funcUsesNativeLowering(c.func.name.ident))))
                    {
                        try self.emitDirectNamedFuncCall(expr);
                        return;
                    }
                }
                if (c.func.* == .name) {
                    if (self.vararg_funcs.get(c.func.name.ident)) |argv_cname| {
                        self.p("({{\n", .{});
                        self.indent += 1;
                        self.ind();
                        if (c.args.len == 0) {
                            self.pl("lua_Value __r = {s}__argv(0, NULL);", .{argv_cname});
                        } else {
                            self.p("lua_Value __argv[{d}] = {{", .{c.args.len});
                            for (c.args, 0..) |arg, i| {
                                if (i > 0) self.p(", ", .{});
                                try self.emit_as_lua_value(arg);
                            }
