                                try self.emit_expr(b.lhs);
                                self.p(" {s} ", .{binop_str(b.op)});
                                try self.emit_expr(b.rhs);
                                self.p(")", .{});
                            }
                        },
                        else => {
                            if (b.op == .mul and try self.try_emit_sin_cos_product(b.lhs, b.rhs)) return;
                            self.p("(", .{});
                            try self.emit_expr(b.lhs);
                            self.p(" {s} ", .{binop_str(b.op)});
                            try self.emit_expr(b.rhs);
                            self.p(")", .{});
                        },
                    }
                }
            },
            .unop => |u| {
                const ot = self.expr_type(u.operand);
                const unbox_unary = self.dynamic_binop_operand_is_safe_native_unbox(u.operand) or
                    self.dynamic_binop_operand_is_dynamic_table_read(u.operand);
                if (ot == .any) {
                    if (unbox_unary) {
                        const unbox_t: RT = if (self.expr_tree_has_float(u.operand)) .f64 else .i64;
                        switch (u.op) {
                            .neg => {
                                self.p("(-", .{});
                                try self.emit_dynamic_unbox(u.operand, unbox_t);
                                self.p(")", .{});
                            },
                            .bnot => {
                                self.p("(~", .{});
                                try self.emit_dynamic_unbox(u.operand, .i64);
                                self.p(")", .{});
                            },
                            else => {
                                switch (u.op) {
                                    .neg => {
                                        self.p("lua_unm(", .{});
                                        try self.emit_expr(u.operand);
                                        self.p(")", .{});
                                    },
                                    .not => {
                                        self.p("(!lua_to_bool(", .{});
                                        try self.emit_expr(u.operand);
                                        self.p("))", .{});
                                    },
                                    .len => {
                                        if (u.operand.* == .name and self.is_native_str_list_local(u.operand.name.ident)) {
                                            self.p("{s}_len", .{u.operand.name.ident});
                                        } else {
                                            try self.emit_any_len(u.operand);
                                        }
                                    },
                                    .bnot => {
                                        self.p("lua_bnot(", .{});
                                        try self.emit_expr(u.operand);
                                        self.p(")", .{});
                                    },
                                    .compile => try self.emit_comptime_expr(u.operand, true),
                                }
                            },
                        }
                    } else switch (u.op) {
                        .neg => {
                            self.p("lua_unm(", .{});
                            try self.emit_expr(u.operand);
                            self.p(")", .{});
                        },
                        .not => {
                            self.p("(!lua_to_bool(", .{});
                            try self.emit_expr(u.operand);
                            self.p("))", .{});
                        },
                        .len => {
                            if (u.operand.* == .name and self.is_native_str_list_local(u.operand.name.ident)) {
                                self.p("{s}_len", .{u.operand.name.ident});
                                return;
                            }
                            // Native dense module tables codegen to a raw C
                            // array (not a lua_Value); their length is a
                            // compile-time constant, not something
                            // lua_len_num can read off the array.
                            if (u.operand.* == .name and self.is_native_dense_module_table(u.operand.name.ident)) {
                                const nd = self.native_dense_module_tables.get(u.operand.name.ident).?;
                                self.p("{d}", .{nd.len});
                                return;
                            }
                            // Untyped operands recover the numeric length
                            // directly while preserving __len dispatch.
                            try self.emit_any_len(u.operand);
                        },
                        .bnot => {
                            self.p("lua_bnot(", .{});
                            try self.emit_expr(u.operand);
                            self.p(")", .{});
                        },
                        .compile => {
                            try self.emit_comptime_expr(u.operand, true);
                        },
                    }
                } else {
                    switch (u.op) {
                        .neg => {
                            self.p("(-", .{});
                            try self.emit_expr(u.operand);
                            self.p(")", .{});
                        },
                        .not => {
                            self.p("(!", .{});
                            try self.emit_expr(u.operand);
                            self.p(")", .{});
                        },
                        .len => {
                            if (ot == .str) {
                                self.p("((int64_t)strlen(", .{});
                                try self.emit_expr(u.operand);
                                self.p("))", .{});
                            } else {
                                self.p("strlen(", .{});
                                try self.emit_expr(u.operand);
                                self.p(")", .{});
                            }
                        },
                        .bnot => {
                            self.p("(~", .{});
                            try self.emit_expr(u.operand);
                            self.p(")", .{});
                        },
                        .compile => {
                            try self.emit_comptime_expr(u.operand, false);
                        },
                    }
                }
            },
            .func_expr => |fb| {
                const id = fb.closure_id orelse 0;
                self.p("lua_val_from_closure((lua_Closure*)duo_make_closure_{d}(", .{id});
                for (fb.upvalues, 0..) |uv, i| {
                    if (i > 0) self.p(", ", .{});
                    // When inside a closure body, the upvalue name might be an
                    // upvalue of the *current* closure. In that case, emit
                    // cl->upN instead of the bare variable name (which isn't
                    // visible at file scope). This handles upvalue chaining.
                    if (self.find_upvalue_in_closure(uv.name)) |outer_idx| {
                        const outer_uv = self.closure_ctx.?.upvalues[outer_idx];
                        if (upvalue_uses_pointer(uv)) {
                            if (upvalue_uses_pointer(outer_uv)) {
                                self.p("cl->up{d}", .{outer_idx});
                            } else {
                                self.p("&cl->up{d}", .{outer_idx});
                            }
                        } else if (uv.typ) |t| {
                            if (t == .func) {
                                try self.emit_native_func_name_as_lua_value(uv.name, t.func.params, t.func.is_compile_only);
                            } else if (upvalue_uses_pointer(outer_uv)) {
                                self.p("(*cl->up{d})", .{outer_idx});
                            } else {
                                self.p("cl->up{d}", .{outer_idx});
                            }
                        } else {
                            if (upvalue_uses_pointer(outer_uv)) {
                                self.p("(*cl->up{d})", .{outer_idx});
                            } else {
                                self.p("cl->up{d}", .{outer_idx});
                            }
                        }
                        continue;
                    }
                    // Not an upvalue of the current closure: emit normally
                    if (upvalue_uses_pointer(uv)) {
                        // Mutable upvalue: pass address of the variable
                        self.p("&", .{});
                        self.emit_var_name(uv.name);
                    } else if (self.upvalue_scalar_coercion(uv)) |scalar_rt| {
                        // The closure slot is a `lua_Value`, but sema typed this
                        // capture `.any` while codegen emitted the local as a
                        // native scalar (`base = 100` -> `int64_t base`). Passing
                        // it raw is a type error, so box it at the capture point.
                        switch (scalar_rt) {
                            .bool => {
                                self.p("lua_val_from_bool(", .{});
                                self.emit_var_name(uv.name);
                                self.p(")", .{});
                            },
                            .str => {
                                self.p("lua_val_from_str(", .{});
                                self.emit_var_name(uv.name);
                                self.p(")", .{});
                            },
                            .f32, .f64 => {
                                self.p("lua_val_from_num((double)(", .{});
                                self.emit_var_name(uv.name);
                                self.p("))", .{});
                            },
                            else => {
                                self.p("lua_val_from_int((int64_t)(", .{});
                                self.emit_var_name(uv.name);
                                self.p("))", .{});
                            },
                        }
                    } else if (uv.typ) |t| {
                        if (t == .func) {
                            try self.emit_native_func_name_as_lua_value(uv.name, t.func.params, t.func.is_compile_only);
                        } else {
                            self.emit_var_name(uv.name);
                        }
                    } else {
                        self.emit_var_name(uv.name);
                    }
                }
                self.p("))", .{});
            },
            .table => |t| {
                var array_count: usize = 0;
                var hash_count: usize = 0;
                for (t.fields) |fld| {
                    switch (fld) {
                        .positional => array_count += 1,
                        .named, .indexed => hash_count += 1,
                        .spread => {},
                        // Pass 36 G1/G8 recorded, not implemented (Phase 0): semantic entries live in the
                        // semantic namespace, so they reserve no ordinary table slot.
                        .semantic => {},
                    }
                }
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value tmp = lua_table_new_with_capacity({d}, {d});\n", .{ array_count, hash_count });
                var pos_idx: f64 = 1.0;
                for (t.fields) |fld| {
                    self.ind();
                    switch (fld) {
                        .indexed => |idx| {
                            if (positive_int_key(idx.key)) |key| {
                                self.p("lua_table_set_raw_i64(tmp, {d}, ", .{key});
                                try self.emit_as_lua_value(idx.val);
                                self.p(");\n", .{});
                            } else {
                                self.p("lua_table_set_raw(tmp, ", .{});
                                try self.emit_as_lua_value(idx.key);
                                self.p(", ", .{});
                                try self.emit_as_lua_value(idx.val);
                                self.p(");\n", .{});
                            }
                        },
                        .named => |nmd| {
                            const hash = calc_lua_hash(nmd.key);
                            self.p("lua_table_set_raw_lit(tmp, \"{s}\", ", .{nmd.key});
                            self.p("{d}, {d}, ", .{ hash, nmd.key.len });
                            try self.emit_as_lua_value(nmd.val);
                            self.p(");\n", .{});
                        },
                        .positional => |pos_expr| {
                            // Special case: `{...}` — copy all varargs into the table.
                            if (pos_expr.* == .vararg) {
                                if (self.closure_ctx) |fb| {
                                    const vn = fb.vararg_name orelse "__varargs";
                                    self.pl("for (int _vi = 0; _vi < (int)lua_len_num({s}); _vi++) {{", .{vn});
                                    self.ind();
                                    self.pl("lua_table_set_raw_i64(tmp, {d} + _vi, lua_table_get_raw({s}, lua_val_from_int(_vi + 1)));", .{ @as(i64, @intFromFloat(pos_idx)), vn });
                                    self.pl("}}", .{});
                                    continue;
                                }
                            }
                            self.p("lua_table_set_raw_i64(tmp, {d}, ", .{@as(i64, @intFromFloat(pos_idx))});
                            try self.emit_as_lua_value(pos_expr);
                            self.p(");\n", .{});
                            pos_idx += 1.0;
                        },
                        .spread => |src| {
                            self.ind();
                            self.p("{{ lua_Value _spr = ", .{});
                            try self.emit_as_lua_value(src);
                            self.p(";\n", .{});
                            self.ind();
                            self.pl("if (_spr.type == VAL_TABLE) {{", .{});
                            self.indent += 1;
                            self.ind();
                            self.pl("lua_Table* _st = (lua_Table*)_spr.as.tval;", .{});
                            self.ind();
                            self.pl("for (int _si = 0; _si < _st->array_size; _si++) {{", .{});
                            self.indent += 1;
                            self.ind();
                            self.pl("if (_st->array[_si].type != VAL_NIL) lua_table_set_raw_i64(tmp, _si + 1, _st->array[_si]);", .{});
                            self.indent -= 1;
                            self.ind();
                            self.pl("}}", .{});
                            self.ind();
                            self.pl("for (int _si = 0; _si < _st->capacity; _si++) {{", .{});
                            self.indent += 1;
                            self.ind();
                            self.pl("if (_st->hash_keys[_si].type != VAL_NIL) lua_table_set_raw(tmp, _st->hash_keys[_si], _st->hash_vals[_si]);", .{});
                            self.indent -= 1;
                            self.ind();
                            self.pl("}}", .{});
                            self.indent -= 1;
                            self.ind();
                            self.pl("}}", .{});
                            self.ind();
                            self.pl("}}", .{});
                        },
                        // Pass 36 G8 (`{ @eq = impl }`): a semantic entry installs into
                        // the semantic namespace, not the ordinary table, so it emits
                        // no raw set here. Refuse rather than invent an installation
                        // path before the resolution ladder exists.
                        .semantic => self.p("/* Pass 36 semantic table entry: not yet lowered */\n", .{}),
                    }
                }
                self.ind();
                self.p("tmp;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            .list_comp => |lc| try self.emit_list_comprehension(lc),
            .try_expr => |te| {
                // expr? — propagate error; in this runtime errors are already thrown
                // via lua_error/longjmp, so the operand either returns normally or jumps.
                try self.emit_expr(te.operand);
            },
            .unwrap_expr => |ue| {
                // expr! — unwrap result, panicking on nil (unreachable in @nopanic fns).
                self.p("({{lua_Value _uw = (", .{});
                try self.emit_expr(ue.operand);
                self.p("); if (LUA_UNLIKELY(_uw.type == VAL_NIL)) lua_error(lua_val_from_str(\"unwrap of nil\")); _uw; }})", .{});
            },
            .if_expr => |ie| {
                self.p("((", .{});
                try self.emit_expr(ie.cond);
                self.p(") ? (", .{});
                try self.emit_expr(ie.then_expr);
                self.p(") : (", .{});
                try self.emit_expr(ie.else_expr);
                self.p("))", .{});
            },
            .match_expr => |match_expr| {
                try self.emit_match_expr(match_expr);
            },
            .await_expr => |ae| {
                // await expr — synchronous evaluation; the async state-machine lowering
                // handles the full cooperative scheduling model for async functions.
                try self.emit_expr(ae.operand);
            },
            .contains_expr => |ce| {
                // x in y — membership test via duo_contains(container, item).
                const as_lua = self.expr_type(expr) == .any;
                if (as_lua) self.p("lua_val_from_bool(", .{});
                self.p("duo_contains(", .{});
                try self.emit_expr(ce.rhs);
                self.p(", ", .{});
                try self.emit_expr(ce.lhs);
                self.p(")", .{});
                if (as_lua) self.p(")", .{});
            },
            .range => |r| {
                // TODO: proper range codegen — for now emit as runtime trio
                self.p("duo_range(", .{});
                try self.emit_expr(r.start);
                self.p(", ", .{});
                try self.emit_expr(r.end);
                if (r.step) |s| {
                    self.p(", ", .{});
                    try self.emit_expr(s);
                }
                self.p(")", .{});
            },
        }
    }

    fn isHexDigitByte(c: u8) bool {
        return (c >= '0' and c <= '9') or (c >= 'a' and c <= 'f') or (c >= 'A' and c <= 'F');
    }

    fn emit_string_escaped(self: *CodeGen, s: []const u8) E!void {
        for (s, 0..) |c, i| {
            switch (c) {
                '"' => self.p("\\\"", .{}),
                '\\' => self.p("\\\\", .{}),
                '\n' => self.p("\\n", .{}),
                '\r' => self.p("\\r", .{}),
                '\t' => self.p("\\t", .{}),
                else => {
                    if (c < 32 or c == 127) {
                        self.p("\\x{x:0>2}", .{c});
                        // See jit.zig emitCStringLiteral: \x escapes greedily
                        // consume following hex digits in C, so split the
                        // literal if the next raw byte is one.
                        if (i + 1 < s.len and isHexDigitByte(s[i + 1])) self.p("\"\"", .{});
                    } else self.p("{c}", .{c});
                },
            }
        }
    }

    fn emit_c_string_literal(self: *CodeGen, s: []const u8) E!void {
        self.p("\"", .{});
        try self.emit_string_escaped(s);
        self.p("\"", .{});
    }

    fn emit_rewrite_description_expr(self: *CodeGen, arg: *const ast.Expr) E!void {
        self.p("({{ const char* __duo_rewrite_bundle = ", .{});
        try self.emit_expr(arg);
        self.p("; ", .{});
        const bundles = [_][]const u8{ "algebraic", "fast", "all" };
        for (bundles, 0..) |bundle, i| {
            if (i > 0) self.p(" : ", .{});
            self.p("(strcmp(__duo_rewrite_bundle, \"{s}\") == 0) ? ", .{bundle});
            try self.emit_c_string_literal(rewrite_rules.bundleDescription(bundle).?);
        }
        self.p(" : \"\"; }})", .{});
    }

    fn fold_meta_string_expr(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        return switch (expr.*) {
            .string_lit => |s| s.val,
            .name => |n| blk: {
                const value = self.comptime_bindings().get(n.ident) orelse break :blk null;
                break :blk if (value == .string) value.string else null;
            },
            .call => |c| blk: {
                if (c.func.* != .name) break :blk null;
                const name = c.func.name.ident;
                if (transform_engine.publicNameForInternal(name) != null and
                    !transform_engine.requireMetaDispatchBeforeHook(name))
                    break :blk null;
                if (self.meta_combinator_fold_depth == 0 and meta_dispatch.canDispatch(name)) {
                    self.meta_combinator_fold_depth += 1;
                    defer self.meta_combinator_fold_depth -= 1;
                    var storage: [8]comptime_eval.Value = undefined;
                    const n = self.buildMetaCombinatorValues(name, c.args, &storage) orelse break :blk null;
                    break :blk self.runMetaCombinatorString(name, storage[0..n], .top_level_assign);
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn isCEmitDirectiveName(name: []const u8) bool {
        return @import("meta_module.zig").isCEmitDirective(name);
    }

    /// Fold `@c.emit(@comp.*(...))` / `__emit(combinator(...))` payload to a C string.
    fn fold_c_emit_payload(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        if (expr.* != .call) return null;
        const c = expr.call;
        if (c.func.* != .name or c.args.len == 0) return null;
        if (!std.mem.eql(u8, c.func.name.ident, "__emit")) return null;
        if (c.args[0].* == .string_lit) return c.args[0].string_lit.val;
        return self.fold_meta_string_expr(c.args[0]);
    }

    fn emit_file_scope_c_payload(self: *CodeGen, code: []const u8) void {
        const trimmed = std.mem.trim(u8, code, " \t\r\n");
        if (trimmed.len == 0) return;
        if (trimmed[trimmed.len - 1] != ';' and trimmed[trimmed.len - 1] != '}')
            self.p("{s};\n", .{code})
        else
            self.p("{s}\n", .{code});
    }

    fn stmt_is_file_scope_c_emit(self: *CodeGen, stmt: *const ast.Stmt) bool {
        return switch (stmt.*) {
            .directive => |d| blk: {
                if (!CodeGen.isCEmitDirectiveName(d.attr.name)) break :blk false;
                if (d.attr.args) |raw| {
                    break :blk @import("directives.zig").isRawCEmitLiteral(raw);
                }
                break :blk true;
            },
            .expr_stmt => |es| self.fold_c_emit_payload(es.expr) != null,
            else => false,
        };
    }

    fn count_lines(s: []const u8) i64 {
        if (s.len == 0) return 0;
        var count: i64 = 0;
        var saw_non_ws = false;
        for (s) |c| {
            if (c == '\n') count += 1;
            if (c != '\n' and c != '\r' and c != '\t' and c != ' ') saw_non_ws = true;
        }
        if (s[s.len - 1] != '\n' and saw_non_ws) count += 1;
        return count;
    }

    fn split_count(source: []const u8, sep: []const u8) i64 {
        if (source.len == 0) return 0;
        if (sep.len == 0) return @intCast(source.len);
        var count: i64 = 1;
        var rest = source;
        while (std.mem.indexOf(u8, rest, sep)) |idx| {
            count += 1;
            rest = rest[idx + sep.len ..];
        }
        return count;
    }

    fn maybe_emit_meta_int_call(self: *CodeGen, name: []const u8, args: []const *ast.Expr) E!bool {
        if (std.mem.eql(u8, name, "__strcountlines") and args.len == 1) {
            const source = self.fold_meta_string_expr(args[0]) orelse return false;
            self.p("{d}", .{count_lines(source)});
            return true;
        }
        if (std.mem.eql(u8, name, "__strsplitcount") and args.len == 2) {
            const source = self.fold_meta_string_expr(args[0]) orelse return false;
            const sep = self.fold_meta_string_expr(args[1]) orelse return false;
            self.p("{d}", .{split_count(source, sep)});
            return true;
        }
        if (std.mem.eql(u8, name, "__strcomptelen") and args.len == 1) {
            if (self.fold_meta_string_expr(args[0])) |source| {
                self.p("{d}", .{@as(i64, @intCast(source.len))});
                return true;
            }
            if (self.expr_type(args[0]) == .str) {
                self.p("({{ const unsigned char* _duo_s = (const unsigned char*)(", .{});
                try self.emit_expr(args[0]);
                self.p("); int64_t _duo_len = 0; while (*_duo_s) {{ if ((*_duo_s & 0xC0) != 0x80) _duo_len++; _duo_s++; }} _duo_len; }})", .{});
                return true;
            }
        }
        if (std.mem.eql(u8, name, "__concept_count") and args.len == 1 and args[0].* == .string_lit) {
            const concepts = self.concepts orelse return false;
            const concept = concepts.get(args[0].string_lit.val) orelse return false;
            self.p("{d}", .{@as(i64, @intCast(concept.required_methods.len + concept.required_fields.len))});
            return true;
        }
        if (std.mem.eql(u8, name, "__rewrite_rulecount") and args.len == 0) {
            self.p("{d}", .{@as(i64, @intCast(rewrite_rules.ruleCount()))});
            return true;
        }
        return false;
    }

    fn maybe_emit_meta_bool_call(self: *CodeGen, name: []const u8, args: []const *ast.Expr) E!bool {
        if (std.mem.eql(u8, name, "__strcontains") and args.len == 2 and args[1].* == .string_lit) {
            if (self.fold_meta_string_expr(args[0])) |source| {
                self.p("{s}", .{if (std.mem.indexOf(u8, source, args[1].string_lit.val) != null) "true" else "false"});
                return true;
            }
            if (self.expr_is_native_cstr(args[0])) {
                self.p("({{ const char* _duo_s = ", .{});
                try self.emit_expr(args[0]);
                self.p("; strstr(_duo_s, \"", .{});
                try self.emit_string_escaped(args[1].string_lit.val);
                self.p("\") != NULL; }})", .{});
                return true;
            }
        }
        if (std.mem.eql(u8, name, "__strstartswith") and args.len == 2) {
            if (self.fold_meta_string_expr(args[0])) |source| {
                const prefix = self.fold_meta_string_expr(args[1]) orelse return false;
                self.p("{s}", .{if (std.mem.startsWith(u8, source, prefix)) "true" else "false"});
                return true;
            }
            if (try self.try_emit_native_string_affix("starts_with", args[0], args[1])) return true;
        }
        if (std.mem.eql(u8, name, "__strendswith") and args.len == 2) {
            if (self.fold_meta_string_expr(args[0])) |source| {
                const suffix = self.fold_meta_string_expr(args[1]) orelse return false;
                self.p("{s}", .{if (std.mem.endsWith(u8, source, suffix)) "true" else "false"});
                return true;
            }
            if (try self.try_emit_native_string_affix("ends_with", args[0], args[1])) return true;
        }
        if (std.mem.eql(u8, name, "__streq") and args.len == 2) {
            if (self.fold_meta_string_expr(args[0])) |lhs| {
                const rhs = self.fold_meta_string_expr(args[1]) orelse return false;
                self.p("{s}", .{if (std.mem.eql(u8, lhs, rhs)) "true" else "false"});
                return true;
            }
            if (self.expr_is_native_cstr(args[0]) and self.expr_is_native_cstr(args[1])) {
                self.p("({{ const char* _duo_a = ", .{});
                try self.emit_expr(args[0]);
                self.p("; const char* _duo_b = ", .{});
                try self.emit_expr(args[1]);
                self.p("; strcmp(_duo_a, _duo_b) == 0; }})", .{});
                return true;
            }
        }
        return false;
    }

    fn comptimeJoinTableStrings(self: *CodeGen, parts: comptime_eval.Value, sep: []const u8) E!?[]const u8 {
        if (parts != .table) return null;
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(self.alloc);
        for (parts.table, 0..) |entry, i| {
            if (i > 0 and sep.len > 0) try out.appendSlice(self.alloc, sep);
            switch (entry.val) {
                .string => |v| try out.appendSlice(self.alloc, v),
                .int => |v| {
                    var buf: [32]u8 = undefined;
                    const written = std.fmt.bufPrint(&buf, "{d}", .{v}) catch return null;
                    try out.appendSlice(self.alloc, written);
                },
                .float => |v| {
                    var buf: [32]u8 = undefined;
                    const written = std.fmt.bufPrint(&buf, "{d}", .{v}) catch return null;
                    try out.appendSlice(self.alloc, written);
                },
                .bool => |v| try out.appendSlice(self.alloc, if (v) "true" else "false"),
                .nil => try out.appendSlice(self.alloc, "nil"),
                else => return null,
            }
        }
        return try out.toOwnedSlice(self.alloc);
    }

    fn maybe_emit_meta_string_call(self: *CodeGen, name: []const u8, args: []const *ast.Expr) E!bool {
        if (transform_engine.publicNameForInternal(name) != null and
            !transform_engine.requireMetaDispatchBeforeHook(name))
            return false;
        if (meta_dispatch.canDispatch(name)) {
            return try self.tryEmitMetaCombinatorString(name, args);
        }
        if (std.mem.eql(u8, name, "__metaladder") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.scalingLadderText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagenthooks") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentHooksText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentdedupe") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentDedupeText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentgaps") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentGapsText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentgrammar") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentGrammarText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metacatalog") or std.mem.eql(u8, name, "__metaagentcatalog")) {
            if (args.len > 1) return false;
            const filter = if (args.len == 1 and args[0].* == .string_lit) args[0].string_lit.val else null;
            const catalog = if (std.mem.eql(u8, name, "__metaagentcatalog") and filter == null)
                try meta_module.formatAgentCatalog(self.alloc)
            else
                try meta_module.formatCatalogFiltered(self.alloc, filter);
            defer self.alloc.free(catalog);
            try self.emit_c_string_literal(catalog);
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentladder") and args.len == 0) {
            const ladder = try meta_module.formatAgentLadder(self.alloc);
            defer self.alloc.free(ladder);
            try self.emit_c_string_literal(ladder);
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentmultiplier")) {
            if (args.len == 0) {
                try self.emit_c_string_literal(meta_module.agentMultiplierText());
                return true;
            }
            if (args.len == 1 and args[0].* == .string_lit) {
                const hint = meta_module.agentMultiplierFor(args[0].string_lit.val);
                try self.emit_c_string_literal(hint);
                return true;
            }
            return false;
        }
        if (std.mem.eql(u8, name, "__rewrite_describe") and args.len == 1 and args[0].* == .string_lit) {
            const description = rewrite_rules.bundleDescription(args[0].string_lit.val) orelse return false;
            try self.emit_c_string_literal(description);
            return true;
        }
        if (std.mem.eql(u8, name, "__rewrite_describe") and args.len == 1) {
            try self.emit_rewrite_description_expr(args[0]);
            return true;
        }
        if (std.mem.eql(u8, name, "__strjoin") and args.len == 2) {
            const parts = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch return false;
            const sep_val = comptime_eval.evalWithBindings(args[1], self.comptime_bindings(), self.comptime_eval_options()) catch return false;
            const sep: []const u8 = switch (sep_val) {
                .string => sep_val.string,
                else => return false,
            };
            const joined = try self.comptimeJoinTableStrings(parts, sep) orelse return false;
            defer self.alloc.free(joined);
            try self.emit_c_string_literal(joined);
            return true;
        }
        if (std.mem.eql(u8, name, "__moduletypenames") and args.len == 0) {
            const value = meta_codegen.moduleTypeNamesHook(self.meta_host(), self.alloc) orelse return false;
            if (value != .string) return false;
            try self.emit_c_string_literal(value.string);
            return true;
        }
        if (std.mem.eql(u8, name, "__concepttypenames") and args.len == 1 and args[0].* == .string_lit) {
            const value = meta_codegen.conceptTypeNamesHook(self.meta_host(), args[0].string_lit.val, self.alloc) orelse return false;
            if (value != .string) return false;
            try self.emit_c_string_literal(value.string);
            return true;
        }
        return false;
    }

    fn emit_comptime_value(self: *CodeGen, value: comptime_eval.Value, as_lua_value: bool) E!void {
        switch (value) {
            .unavailable => unreachable,
            .nil => if (as_lua_value) self.p("lua_val_nil()", .{}) else self.p("0", .{}),
            .bool => |v| if (as_lua_value) self.p("lua_val_from_bool({s})", .{if (v) "true" else "false"}) else self.p("{s}", .{if (v) "true" else "false"}),
            .int => |v| if (as_lua_value) self.p("lua_val_from_int({d})", .{v}) else self.p("{d}", .{v}),
            .float => |v| if (as_lua_value) self.p("lua_val_from_num({d})", .{v}) else self.p("{d}", .{v}),
            .string => |v| {
                if (as_lua_value) {
                    const hash = calc_lua_hash(v);
                    self.p("lua_val_from_literal(\"", .{});
                    try self.emit_string_escaped(v);
                    self.p("\", {d}, {d})", .{ hash, v.len });
                } else {
                    self.p("\"", .{});
                    try self.emit_string_escaped(v);
                    self.p("\"", .{});
                }
            },
            .table => |entries| {
                // TODO: emit native C struct when as_lua_value == false for typed tables
                // Currently always uses Lua API for table construction
                var array_count: usize = 0;
                var hash_count: usize = 0;
                for (entries) |entry| {
                    if (entry.name != null) {
                        hash_count += 1;
                    } else if (entry.key) |key| {
                        if (key == .int and key.int >= 1) {
                            array_count += 1;
                        } else {
                            hash_count += 1;
                        }
                    }
                }
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value tmp = lua_table_new_with_capacity({d}, {d});\n", .{ array_count, hash_count });
                for (entries) |entry| {
                    self.ind();
                    if (entry.name) |name| {
                        const hash = calc_lua_hash(name);
                        self.p("lua_table_set_raw_lit(tmp, \"{s}\", {d}, {d}, ", .{ name, hash, name.len });
                        try self.emit_comptime_value(entry.val, true);
                        self.p(");\n", .{});
                    } else if (entry.key) |key| {
                        if (key == .int and key.int >= 1) {
                            self.p("lua_table_set_raw_i64(tmp, {d}, ", .{key.int});
                            try self.emit_comptime_value(entry.val, true);
                            self.p(");\n", .{});
                        } else {
                            self.p("lua_table_set_raw(tmp, ", .{});
                            try self.emit_comptime_value(key, true);
                            self.p(", ", .{});
                            try self.emit_comptime_value(entry.val, true);
                            self.p(");\n", .{});
                        }
                    } else {
                        self.p("lua_table_set_raw(tmp, ", .{});
                        self.p("lua_val_nil()", .{});
                        self.p(", ", .{});
                        try self.emit_comptime_value(entry.val, true);
                        self.p(");\n", .{});
                    }
                }
                self.ind();
                self.p("tmp;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            .func => unreachable,
        }
    }

    /// Emit GCC-style inline assembly from __asm("template") or
    /// __asm("template", "output_constraints", "input_constraints", "clobbers").
    /// Uses existing Duo call syntax — no new keywords required.
    /// Example: __asm("nop")
    /// Example: __asm("mov %0, %1", "=r(result)", "r(input)", "memory")
    fn emit_inline_asm(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len == 0) return;
        if (args[0].* != .string_lit) {
            self.p("/* __asm: first arg must be string literal */", .{});
            return;
        }
        const template = args[0].string_lit.val;
        self.p("__asm__ volatile(\"{s}\"", .{template});
        // Output constraints
        if (args.len >= 2 and args[1].* == .string_lit) {
            self.p(" : \"{s}\"", .{args[1].string_lit.val});
        } else {
            self.p(" :", .{});
        }
        // Input constraints
        if (args.len >= 3 and args[2].* == .string_lit) {
            self.p(" : \"{s}\"", .{args[2].string_lit.val});
        } else {
            self.p(" :", .{});
        }
        // Clobbers
        if (args.len >= 4 and args[3].* == .string_lit) {
            self.p(" : \"{s}\"", .{args[3].string_lit.val});
        }
        self.p(")", .{});
    }

    /// __comptimefold(start, stop, step, "init", "body")
    /// Unrolls a loop at compile time. In body: %i → index, %a → accumulator.
    /// Example: __comptimefold(0, 4, 1, "0", "%a + arr[%i]")
    /// → ((((0) + arr[0]) + arr[1]) + arr[2]) + arr[3])
    fn emit_comptimefold(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 5) {
            self.p("/* __comptimefold: needs 5 args (start, stop, step, init, body) */0", .{});
            return;
        }
        // Evaluate start, stop, step at compile time
        const start_val = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefold: start must be comptime */0", .{});
            return;
        };
        const stop_val = comptime_eval.evalWithBindings(args[1], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefold: stop must be comptime */0", .{});
            return;
        };
        const step_val = comptime_eval.evalWithBindings(args[2], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefold: step must be comptime */0", .{});
            return;
        };
        if (start_val != .int or stop_val != .int or step_val != .int) {
            self.p("/* __comptimefold: bounds must be integers */0", .{});
            return;
        }
        if (args[3].* != .string_lit or args[4].* != .string_lit) {
            self.p("/* __comptimefold: init and body must be string literals */0", .{});
            return;
        }
        const init_str = args[3].string_lit.val;
        const body_tmpl = args[4].string_lit.val;
        const start = start_val.int;
        const stop = stop_val.int;
        const step = step_val.int;
        if (step == 0 or (step > 0 and start > stop) or (step < 0 and start < stop)) {
            self.p("{s}", .{init_str});
            return;
        }
        // Generate the unrolled fold
        var acc_str: []const u8 = init_str;
        var i = start;
        var iterations: usize = 0;
        while ((step > 0 and i < stop) or (step < 0 and i > stop)) : ({
            i += step;
            iterations += 1;
        }) {
            if (iterations > 1024) break; // Safety limit
            // Substitute %i and %a in body template
            var idx_buf: [24]u8 = undefined;
            const idx_str = std.fmt.bufPrint(&idx_buf, "{d}", .{i}) catch break;
            const with_i = std.mem.replaceOwned(u8, self.alloc, body_tmpl, "%i", idx_str) catch break;
            acc_str = std.mem.replaceOwned(u8, self.alloc, with_i, "%a", acc_str) catch break;
        }
        self.p("({s})", .{acc_str});
    }

    /// __comptimefor(start, stop, "body_template")
    /// Generates a sequence of statements at compile time. %i → index.
    /// When used as an expression, generates a comma-expression.
    /// Example: __comptimefor(0, 3, "arr[%i] = %i;")
    /// → arr[0] = 0; arr[1] = 1; arr[2] = 2;
    fn emit_comptimefor(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 3) {
            self.p("/* __comptimefor: needs 3 args (start, stop, body) */0", .{});
            return;
        }
        const start_val = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefor: start must be comptime */0", .{});
            return;
        };
        const stop_val = comptime_eval.evalWithBindings(args[1], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefor: stop must be comptime */0", .{});
            return;
        };
        if (start_val != .int or stop_val != .int) {
            self.p("/* __comptimefor: bounds must be integers */0", .{});
            return;
        }
        if (args[2].* != .string_lit) {
            self.p("/* __comptimefor: body must be string literal */0", .{});
            return;
        }
        const body_tmpl = args[2].string_lit.val;
        const start = start_val.int;
        const stop = stop_val.int;
        if (start >= stop) {
            self.p("0", .{});
            return;
        }
        // Generate unrolled iterations as a compound expression
        self.p("(", .{});
        var first = true;
        var i = start;
        var iterations: usize = 0;
        while (i < stop) : ({
            i += 1;
            iterations += 1;
        }) {
            if (iterations > 1024) break; // Safety limit
            if (!first) self.p(", ", .{});
            first = false;
            var idx_buf: [24]u8 = undefined;
            const idx_str = std.fmt.bufPrint(&idx_buf, "{d}", .{i}) catch break;
            const expanded = std.mem.replaceOwned(u8, self.alloc, body_tmpl, "%i", idx_str) catch break;
            self.p("{s}", .{expanded});
        }
        self.p(")", .{});
    }

    fn emit_comptime_expr(self: *CodeGen, expr: *const ast.Expr, as_lua_value: bool) E!void {
        const value = comptime_eval.evalWithBindings(expr, self.comptime_bindings(), self.comptime_eval_options()) catch {
            if (as_lua_value) {
                try self.emit_as_lua_value(expr);
            } else {
                try self.emit_expr(expr);
            }
            return;
        };
        try self.emit_comptime_value(value, as_lua_value);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // METAPROGRAMMING HELPER FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    const MessageLevel = enum { info, warning, err };

    /// __fields(T) — emit a comptime table of {name, type, offset, size} for each field
    fn emit_fields_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1) {
            self.p("lua_val_nil()", .{});
            return;
        }
        const rt = self.expr_type(args[0]);
        switch (rt) {
            .table_type => |t| {
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __ft = lua_table_new_with_capacity({d}, 0);\n", .{t.fields.len});
                for (t.fields, 0..) |field, i| {
                    self.ind();
                    self.p("lua_table_set_raw_i64(__ft, {d}, ({{\n", .{i + 1});
                    self.indent += 1;
                    self.ind();
                    self.p("lua_Value __e = lua_table_new_with_capacity(0, 4);\n", .{});
                    self.ind();
                    const name_hash = calc_lua_hash(field.name);
                    self.p("lua_table_set_raw_lit(__e, \"name\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("name"), field.name });
                    self.ind();
                    var buf: [128]u8 = undefined;
                    const type_name = field.typ.c_type(&buf);
                    self.p("lua_table_set_raw_lit(__e, \"type\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("type"), type_name });
                    self.ind();
                    self.p("lua_table_set_raw_lit(__e, \"index\", {d}, 5, lua_val_from_int({d}));\n", .{ calc_lua_hash("index"), i });
                    self.ind();
                    _ = name_hash;
                    self.p("__e;\n", .{});
                    self.indent -= 1;
                    self.ind();
                    self.p("}}));\n", .{});
                }
                self.ind();
                self.p("__ft;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            .enum_type => |et| {
                // For enums, return variant info as "fields"
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __ft = lua_table_new_with_capacity({d}, 0);\n", .{et.variants.len});
                for (et.variants, 0..) |v, i| {
                    self.ind();
                    self.p("lua_table_set_raw_i64(__ft, {d}, ({{\n", .{i + 1});
                    self.indent += 1;
                    self.ind();
                    self.p("lua_Value __e = lua_table_new_with_capacity(0, 3);\n", .{});
                    self.ind();
                    self.p("lua_table_set_raw_lit(__e, \"name\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("name"), v.name });
                    self.ind();
                    const has_payload: i64 = if (v.payload != null) 1 else 0;
                    self.p("lua_table_set_raw_lit(__e, \"has_payload\", {d}, 11, lua_val_from_bool({s}));\n", .{ calc_lua_hash("has_payload"), if (has_payload == 1) "true" else "false" });
                    self.ind();
                    self.p("lua_table_set_raw_lit(__e, \"tag\", {d}, 3, lua_val_from_int({d}));\n", .{ calc_lua_hash("tag"), i });
                    self.ind();
                    self.p("__e;\n", .{});
                    self.indent -= 1;
                    self.ind();
                    self.p("}}));\n", .{});
                }
                self.ind();
                self.p("__ft;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            else => self.p("lua_val_nil()", .{}),
        }
    }

    /// __concept_methods("Concept") — compile-time table of required method signatures
    fn emit_concept_methods_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        try self.emit_concept_members_table(args, .methods);
    }

    fn emit_concept_fields_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        try self.emit_concept_members_table(args, .fields);
    }

    fn emit_concept_members_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        try self.emit_concept_members_table(args, .all);
    }

    const ConceptMemberSet = enum { methods, fields, all };

    fn find_current_concept_def(self: *CodeGen, name: []const u8) ?*const ast.ConceptDef {
        const mod = self.current_module orelse return null;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .concept_def) continue;
            if (std.mem.eql(u8, stmt.concept_def.name, name)) return &stmt.concept_def;
        }
        return null;
    }

    fn emit_type_expr_string(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        const text: []const u8 = switch (type_expr) {
            .inferred => "any",
            .named => |name| name,
            .optional => |child| switch (child.*) {
                .named => |name| name,
                .inferred => "any",
                else => "any",
            },
            else => "any",
        };
        try self.emit_c_string_literal(text);
    }

    fn emit_resolved_type_name_string(self: *CodeGen, rt: RT) E!void {
        const text: []const u8 = switch (rt) {
            .i8 => "i8",
            .i16 => "i16",
            .i32 => "i32",
            .i64 => "i64",
            .u8 => "u8",
            .u16 => "u16",
            .u32 => "u32",
            .u64 => "u64",
            .f32 => "f32",
            .f64 => "f64",
            .bool => "bool",
            .str => "str",
            .void => "void",
            .any => "any",
            .nil => "nil",
            .@"struct" => |s| s.name,
            else => "any",
        };
        try self.emit_c_string_literal(text);
    }

    fn emit_concept_field_row(
        self: *CodeGen,
        field: sema.ConceptInfo.FieldRequirement,
        ast_field: ?ast.ConceptDef.RequiredField,
    ) E!void {
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __m = lua_table_new_with_capacity(0, 3);\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"name\", {d}, 4, lua_val_from_str(\"", .{calc_lua_hash("name")});
        try self.emit_string_escaped(field.name);
        self.p("\"));\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"kind\", {d}, 4, lua_val_from_str(\"field\"));\n", .{calc_lua_hash("kind")});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"type\", {d}, 4, lua_val_from_str(", .{calc_lua_hash("type")});
        if (ast_field) |source_field| {
            try self.emit_type_expr_string(source_field.typ);
        } else {
            try self.emit_resolved_type_name_string(field.typ);
        }
        self.p("));\n", .{});
        self.ind();
        self.p("__m;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn emit_concept_method_row(
        self: *CodeGen,
        method: sema.ConceptInfo.MethodRequirement,
        ast_method: ?ast.FuncSignature,
    ) E!void {
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __m = lua_table_new_with_capacity(0, 5);\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"name\", {d}, 4, lua_val_from_str(\"", .{calc_lua_hash("name")});
        try self.emit_string_escaped(method.name);
        self.p("\"));\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"kind\", {d}, 4, lua_val_from_str(\"method\"));\n", .{calc_lua_hash("kind")});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"param_count\", {d}, 11, lua_val_from_int({d}));\n", .{ calc_lua_hash("param_count"), method.param_count });
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"ret\", {d}, 3, lua_val_from_str(", .{calc_lua_hash("ret")});
        if (ast_method) |sig| {
            try self.emit_type_expr_string(sig.ret_type);
        } else {
            try self.emit_resolved_type_name_string(method.ret_type);
        }
        self.p("));\n", .{});
        self.ind();
        self.p("lua_Value __params = lua_table_new_with_capacity({d}, 0);\n", .{method.param_count});
        if (ast_method) |sig| {
            for (sig.params, 0..) |param, i| {
                self.ind();
                self.p("lua_table_set_raw_i64(__params, {d}, lua_val_from_str(", .{i + 1});
                try self.emit_type_expr_string(param.typ);
                self.p("));\n", .{});
            }
        } else if (method.param_types.len > 0) {
            for (method.param_types, 0..) |pt, i| {
                self.ind();
                self.p("lua_table_set_raw_i64(__params, {d}, lua_val_from_str(", .{i + 1});
                try self.emit_resolved_type_name_string(pt);
                self.p("));\n", .{});
            }
        } else {
            var i: usize = 0;
            while (i < method.param_count) : (i += 1) {
                self.ind();
                self.p("lua_table_set_raw_i64(__params, {d}, lua_val_from_str(\"any\"));\n", .{i + 1});
            }
        }
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"params\", {d}, 6, __params);\n", .{calc_lua_hash("params")});
        self.ind();
        self.p("__m;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn ast_concept_method(def: ?*const ast.ConceptDef, name: []const u8) ?ast.FuncSignature {
        const concept = def orelse return null;
        for (concept.required_methods) |method| {
            if (std.mem.eql(u8, method.name, name)) return method;
        }
        return null;
    }

    fn ast_concept_field(def: ?*const ast.ConceptDef, name: []const u8) ?ast.ConceptDef.RequiredField {
        const concept = def orelse return null;
        for (concept.required_fields) |field| {
            if (std.mem.eql(u8, field.name, name)) return field;
        }
        return null;
    }

    fn emit_concept_members_table(self: *CodeGen, args: []const *ast.Expr, set: ConceptMemberSet) E!void {
        if (args.len < 1 or args[0].* != .string_lit) {
            self.p("lua_val_nil()", .{});
            return;
        }
        const concept_name = args[0].string_lit.val;
        const concepts = self.concepts orelse {
            self.p("lua_val_nil()", .{});
            return;
        };
        const concept = concepts.get(concept_name) orelse {
            self.p("lua_val_nil()", .{});
            return;
        };
        const total = switch (set) {
            .methods => concept.required_methods.len,
            .fields => concept.required_fields.len,
            .all => concept.required_methods.len + concept.required_fields.len,
        };
        const ast_def = self.find_current_concept_def(concept_name);
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __cm = lua_table_new_with_capacity({d}, 0);\n", .{total});
        var idx: usize = 1;
        if (set == .methods or set == .all) {
            for (concept.required_methods) |method| {
                self.ind();
                self.p("lua_table_set_raw_i64(__cm, {d}, ", .{idx});
                try self.emit_concept_method_row(method, ast_concept_method(ast_def, method.name));
                self.p(");\n", .{});
                idx += 1;
            }
        }
        if (set == .fields or set == .all) {
            for (concept.required_fields) |field| {
                self.ind();
                self.p("lua_table_set_raw_i64(__cm, {d}, ", .{idx});
                try self.emit_concept_field_row(field, ast_concept_field(ast_def, field.name));
                self.p(");\n", .{});
                idx += 1;
            }
        }
        self.ind();
        self.p("__cm;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __methods(T) — emit comptime table of method names for a type
    fn emit_methods_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1) {
            self.p("lua_val_nil()", .{});
            return;
        }
        // Look up the type name in alias_defs which tracks methods
        const rt = self.expr_type(args[0]);
        const type_name: ?[]const u8 = switch (rt) {
            .@"struct" => |s| s.name,
            .enum_type => |et| et.name,
            else => if (args[0].* == .string_lit) args[0].string_lit.val else if (args[0].* == .name) args[0].name.ident else null,
        };
        if (type_name) |tname| {
            if (self.table_methods) |tm| {
                if (tm.get(tname)) |tmethods| {
                    self.p("({{\n", .{});
                    self.indent += 1;
                    self.ind();
                    self.p("lua_Value __mt = lua_table_new_with_capacity({d}, 0);\n", .{tmethods.items.len});
                    for (tmethods.items, 0..) |method, i| {
                        self.ind();
                        self.p("lua_table_set_raw_i64(__mt, {d}, lua_val_from_str(\"{s}\"));\n", .{ i + 1, method });
                    }
                    self.ind();
                    self.p("__mt;\n", .{});
                    self.indent -= 1;
                    self.ind();
                    self.p("}})", .{});
                    return;
                }
            }
            if (self.alias_defs.get(tname)) |alias_def| {
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __mt = lua_table_new_with_capacity({d}, 0);\n", .{alias_def.methods.len});
                for (alias_def.methods, 0..) |method, i| {
                    self.ind();
                    const mname = if (method.path.len > 0) method.path[method.path.len - 1] else "?";
                    self.p("lua_table_set_raw_i64(__mt, {d}, lua_val_from_str(\"{s}\"));\n", .{ i + 1, mname });
                }
                self.ind();
                self.p("__mt;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
                return;
            }
        }
        self.p("lua_val_nil()", .{});
    }

    /// __variants(EnumT) — emit comptime table of variant descriptors
    fn emit_variants_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1) {
            self.p("lua_val_nil()", .{});
            return;
        }
        const rt = self.expr_type(args[0]);
        if (rt == .enum_type) {
            const et = rt.enum_type;
            self.p("({{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("lua_Value __vt = lua_table_new_with_capacity({d}, 0);\n", .{et.variants.len});
            for (et.variants, 0..) |v, i| {
                self.ind();
                self.p("lua_table_set_raw_i64(__vt, {d}, ({{\n", .{i + 1});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __v = lua_table_new_with_capacity(0, 3);\n", .{});
                self.ind();
                self.p("lua_table_set_raw_lit(__v, \"name\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("name"), v.name });
                self.ind();
                self.p("lua_table_set_raw_lit(__v, \"tag\", {d}, 3, lua_val_from_int({d}));\n", .{ calc_lua_hash("tag"), i });
                self.ind();
                if (v.payload) |payload| {
                    self.p("lua_table_set_raw_lit(__v, \"arity\", {d}, 5, lua_val_from_int({d}));\n", .{ calc_lua_hash("arity"), payload.len });
                } else {
                    self.p("lua_table_set_raw_lit(__v, \"arity\", {d}, 5, lua_val_from_int(0));\n", .{calc_lua_hash("arity")});
                }
                self.ind();
                self.p("__v;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}}));\n", .{});
            }
            self.ind();
            self.p("__vt;\n", .{});
            self.indent -= 1;
            self.ind();
            self.p("}})", .{});
        } else {
            self.p("lua_val_nil()", .{});
        }
    }

    /// __has_field(T, "name") — compile-time check if type has a named field
    fn emit_has_field_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .string_lit) args[1].string_lit.val else {
            self.p("false", .{});
            return;
        };
        const found = switch (rt) {
            .table_type => |t| blk: {
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
        self.p("{s}", .{if (found) "true" else "false"});
    }

    /// __has_method(T, "name") — compile-time check if type has a named method
    fn emit_has_method_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const method_name = if (args[1].* == .string_lit) args[1].string_lit.val else {
            self.p("false", .{});
            return;
        };
        const type_name: ?[]const u8 = switch (rt) {
            .@"struct" => |s| s.name,
            .enum_type => |et| et.name,
            else => null,
        };
        if (type_name) |tname| {
            if (self.alias_defs.get(tname)) |alias_def| {
                for (alias_def.methods) |m| {
                    const mname = if (m.path.len > 0) m.path[m.path.len - 1] else "";
                    if (std.mem.eql(u8, mname, method_name)) {
                        self.p("true", .{});
                        return;
                    }
                }
            }
        }
        self.p("false", .{});
    }

    /// __has_metamethod(T, "__index") — compile-time check for metamethod presence
    fn emit_has_metamethod_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        // At compile time we can check if the type is known to have a metatable
        // For now, this is a runtime check emitted as C
        if (args[1].* == .string_lit) {
            const raw = args[1].string_lit.val;
            const mm_name = pass23_protocol_registry.resolveToLuaMetamethod(raw);
            const mm_hash = calc_lua_hash(mm_name);
            self.p("(lua_get_metafield_lit(", .{});
            try self.emit_as_lua_value(args[0]);
            self.p(", \"{s}\", {d}u, {d}).type != VAL_NIL)", .{ mm_name, mm_hash, mm_name.len });
        } else {
            self.p("false", .{});
        }
    }

    /// __satisfies(T, "concept") — compile-time concept membership check.
    fn emit_satisfies_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (self.eval_satisfies(args)) |known| {
            self.p("{s}", .{if (known) "true" else "false"});
            return;
        }
        self.p("false", .{});
    }

    fn eval_satisfies(self: *CodeGen, args: []const *ast.Expr) ?bool {
        if (args.len != 2) return null;
        const concept_name = if (args[1].* == .string_lit) args[1].string_lit.val else return null;
        const concepts = self.concepts orelse return null;
        const concept = concepts.get(concept_name) orelse return null;

        const aliasHasField = struct {
            fn check(ad: *const ast.AliasDef, field_name: []const u8) bool {
                for (ad.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) return true;
                }
                if (ad.target) |target| {
                    switch (target) {
                        .record => |rec| {
                            for (rec.fields) |f| {
                                if (std.mem.eql(u8, f.name, field_name)) return true;
                            }
                        },
                        else => {},
                    }
                }
                return false;
            }
        }.check;

        if (args[0].* == .name) {
            const type_name = args[0].name.ident;
            if (self.alias_defs.get(type_name)) |ad| {
                for (concept.required_fields) |req_field| {
                    if (!aliasHasField(ad, req_field.name)) return false;
                }
                for (concept.required_methods) |req_method| {
                    var found = aliasHasField(ad, req_method.name);
                    if (!found) {
                        for (ad.methods) |m| {
                            const mname = if (m.path.len > 0) m.path[m.path.len - 1] else "";
                            if (std.mem.eql(u8, mname, req_method.name)) {
                                found = true;
                                break;
                            }
                        }
                    }
                    if (!found) return false;
                }
                return true;
            }
            const table_name = type_name;
            const methods = if (self.table_methods) |tm| tm.get(table_name) else null;
            if (methods != null) {
                for (concept.required_fields) |req_field| {
                    var found = false;
                    if (methods) |ms| {
                        for (ms.items) |m| {
                            if (std.mem.eql(u8, m, req_field.name)) {
                                found = true;
                                break;
                            }
                        }
                    }
                    if (!found) return false;
                }
                for (concept.required_methods) |req_method| {
                    var found = false;
                    if (methods) |ms| {
                        for (ms.items) |m| {
                            if (std.mem.eql(u8, m, req_method.name)) {
                                found = true;
                                break;
                            }
                        }
                    }
                    if (!found) return false;
                }
                return true;
            }
            return null;
        }

        const rt = self.expr_type(args[0]);
        const type_name: ?[]const u8 = switch (rt) {
            .@"struct" => |s| s.name,
            .enum_type => |et| et.name,
            else => null,
        };
        const alias_def = if (type_name) |tname| self.alias_defs.get(tname) else null;

        for (concept.required_fields) |req_field| {
            var found = false;
            if (alias_def) |ad| {
                if (aliasHasField(ad, req_field.name)) found = true;
            }
            if (!found and rt == .table_type) {
                for (rt.table_type.fields) |rec_field| {
                    if (std.mem.eql(u8, rec_field.name, req_field.name)) {
                        found = true;
                        break;
                    }
                }
            }
            if (!found) return false;
        }
        for (concept.required_methods) |req_method| {
            var found = false;
            if (alias_def) |ad| {
                if (aliasHasField(ad, req_method.name)) found = true;
                if (!found) {
                    for (ad.methods) |m| {
                        const mname = if (m.path.len > 0) m.path[m.path.len - 1] else "";
                        if (std.mem.eql(u8, mname, req_method.name)) {
                            found = true;
                            break;
                        }
                    }
                }
            }
            if (!found and rt == .table_type) {
                for (rt.table_type.fields) |rec_field| {
                    if (std.mem.eql(u8, rec_field.name, req_method.name)) {
                        found = true;
                        break;
                    }
                }
            }
            if (!found) return false;
        }
        return true;
    }

    /// __field_type(T, "name") — returns C type name of a field as string literal
    fn emit_field_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .string_lit) args[1].string_lit.val else {
            self.p("\"unknown\"", .{});
            return;
        };
        switch (rt) {
            .table_type => |t| {
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) {
                        var buf: [128]u8 = undefined;
                        const ctype = f.typ.c_type(&buf);
                        self.p("\"{s}\"", .{ctype});
                        return;
                    }
                }
            },
            else => {},
        }
        self.p("\"unknown\"", .{});
    }

    /// __type_name(expr) — returns the Duo type name as a compile-time string
    fn emit_type_name_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        var buf: [128]u8 = undefined;
        const name = rt.c_type(&buf);
        self.p("\"{s}\"", .{name});
    }

    fn resolveStorageClass(self: *CodeGen, rt: RT) types.StorageClass {
        if (types.tableStorageClass(rt)) |sc| return sc;
        if (rt == .@"struct") {
            if (self.record_aliases.get(rt.@"struct".name)) |alias_rt| {
                if (types.tableStorageClass(alias_rt)) |sc| return sc;
            }
        }
        return .dynamic;
    }

    fn resolveTableRecordType(self: *CodeGen, rt: RT) ?RT {
        if (types.tableStorageClass(rt)) |_| return rt;
        if (rt == .@"struct") {
            if (self.record_aliases.get(rt.@"struct".name)) |alias_rt| {
                if (types.tableStorageClass(alias_rt)) |_| return alias_rt;
            }
        }
        return null;
    }

    /// __type_shape(expr) — returns table storage class as compile-time string
    fn emit_type_shape_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const sc = self.resolveStorageClass(self.expr_type(args[0]));
        const label = types.storageClassName(sc);
        self.logTransformProvenance("comp.type.shape", .emit_call, "expr", label);
        self.p("\"{s}\"", .{label});
    }

    /// __why_shape(expr) — factual storage-class explanation
    fn emit_why_shape_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const table_rt = self.resolveTableRecordType(rt) orelse rt;
        const explanation = types.explainStorageClass(table_rt);
        self.logTransformProvenance("comp.why.shape", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    fn exprBoundaryFacts(self: *CodeGen, expr: *const ast.Expr) dynamic_boundary.ExprFacts {
        const rt = self.expr_type(expr);
        const fn_name = self.current_func_name;
        const func_native = if (fn_name) |n| self.funcUsesNativeLowering(n) else false;
        return .{
            .rt = rt,
            .knowledge = self.exprKnowledge(expr),
            .storage_class = self.resolveStorageClass(rt),
            .module_native = self.moduleUsesFullNativeLowering(),
            .func_native = func_native,
            .lowers_native = self.exprLowersToNativeC(rt),
            .module_needs_runtime = self.moduleNeedsLuaRuntime(),
        };
    }

    fn emit_why_boxed_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = dynamic_boundary.explainBoxed(self.exprBoundaryFacts(args[0]));
        self.logTransformProvenance("comp.why.boxed", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    fn emit_why_not_native_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = dynamic_boundary.explainNotNative(self.exprBoundaryFacts(args[0]));
        self.logTransformProvenance("comp.why.not.native", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    fn emit_representation_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = dynamic_boundary.explainRepresentation(self.exprBoundaryFacts(args[0]));
        self.logTransformProvenance("comp.representation", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    /// __why(expr) — general specialization explanation (table shapes; honest fallback)
    fn emit_why_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        if (self.resolveTableRecordType(rt)) |table_rt| {
            const explanation = types.explainStorageClass(table_rt);
            self.logTransformProvenance("comp.why", .emit_call, "expr", explanation);
            self.p("\"{s}\"", .{explanation});
            return;
        }
        const fallback = "no compiler explanation available for this expression kind yet";
        self.logTransformProvenance("comp.why", .emit_call, "expr", fallback);
        self.p("\"{s}\"", .{fallback});
    }

    /// __why_module(binding) — Pass 34 L1 module sealing witness string.
    fn emit_why_module_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = blk: {
            if (args[0].* != .name) break :blk "module_sealed=n/a; operand is not a module binding name";
            const name = args[0].name.ident;
            const has_req = self.req_module_bindings.contains(name);
            const sealed = self.module_sealed_bindings.contains(name);
            if (has_req and sealed) {
                break :blk "module_sealed=true; req binding frozen after load; cross-module calls may devirtualize";
            }
            if (has_req) {
                break :blk "module_sealed=false; req binding mutated after load; guarded dynamic fallback";
            }
            break :blk "module_sealed=n/a; not a req module binding";
        };
        self.logTransformProvenance("comp.why.module", .emit_call, "binding", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    /// __origin(expr) — compact provenance: storage_class + shape_id for typed records
    fn emit_origin_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        if (self.resolveTableRecordType(rt)) |table_rt| {
            const sc = types.storageClassName(self.resolveStorageClass(table_rt));
            const sid = types.tableShapeIdentityHash(table_rt) orelse 0;
            var buf: [128]u8 = undefined;
            const origin = std.fmt.bufPrint(&buf, "storage_class={s};shape_id={d}", .{ sc, sid }) catch "storage_class=unknown";
            self.logTransformProvenance("comp.origin", .emit_call, "expr", origin);
            self.p("\"{s}\"", .{origin});
            return;
        }
        if (self.enum_name_of(rt)) |ename| {
            var buf: [64]u8 = undefined;
            const origin = std.fmt.bufPrint(&buf, "kind=enum;name={s}", .{ename}) catch "kind=enum";
            self.logTransformProvenance("comp.origin", .emit_call, "expr", origin);
            self.p("\"{s}\"", .{origin});
            return;
        }
        const fallback = "kind=dynamic";
        self.logTransformProvenance("comp.origin", .emit_call, "expr", fallback);
        self.p("\"{s}\"", .{fallback});
    }

    fn metaStringFromExpr(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        if (self.meta_combinator_fold_depth > 0) {
            return switch (expr.*) {
                .string_lit => |s| s.val,
                .name => |n| blk: {
                    const value = self.comptime_bindings().get(n.ident) orelse break :blk null;
                    break :blk if (value == .string) value.string else null;
                },
                else => null,
            };
        }
        return switch (expr.*) {
            .string_lit => |s| s.val,
            else => self.fold_meta_string_expr(expr),
        };
    }

    fn metaStringFromExprOrFold(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        if (self.metaStringFromExpr(expr)) |s| return s;
        const saved = self.meta_combinator_fold_depth;
        self.meta_combinator_fold_depth = 0;
        defer self.meta_combinator_fold_depth = saved;
        return self.fold_meta_string_expr(expr);
    }

    fn deriveNameValueFromExpr(expr: *const ast.Expr) ?comptime_eval.Value {
        return switch (expr.*) {
            .name => |n| .{ .string = n.ident },
            .string_lit => |s| .{ .string = s.val },
            else => null,
        };
    }

    fn buildMetaCombinatorValues(
        self: *CodeGen,
        internal: []const u8,
        args: []const *ast.Expr,
        storage: *[8]comptime_eval.Value,
    ) ?usize {
        const opts = self.comptime_eval_options();
        const bindings = self.comptime_bindings();

        const simple_two_arg = struct {
            name: []const u8,
            wants_callback: bool,
        };
        const two_arg_specs = [_]simple_two_arg{
            .{ .name = "__comptimemap", .wants_callback = true },
            .{ .name = "__comptimeeach", .wants_callback = true },
            .{ .name = "__comptimematch", .wants_callback = true },
            .{ .name = "__comptimepower", .wants_callback = true },
            .{ .name = "__comptimepermute", .wants_callback = true },
            .{ .name = "__comptimenfold", .wants_callback = true },
            .{ .name = "__metagrammar", .wants_callback = true },
            .{ .name = "__derivemap", .wants_callback = false },
            .{ .name = "__derivepower", .wants_callback = false },
            .{ .name = "__derivenfold", .wants_callback = false },
            .{ .name = "__derivepermute", .wants_callback = false },
            .{ .name = "__derivetower", .wants_callback = false },
        };
        if (args.len == 2) {
            for (two_arg_specs) |spec| {
                if (!std.mem.eql(u8, internal, spec.name)) continue;
                storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
                if (spec.wants_callback) {
                    storage[1] = comptime_eval.evalWithBindings(args[1], bindings, opts) catch return null;
                    if (storage[1] != .func) return null;
                } else {
                    storage[1] = deriveNameValueFromExpr(args[1]) orelse return null;
                }
                return 2;
            }
        }
        if (std.mem.eql(u8, internal, "__metaweave") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }

        if (std.mem.eql(u8, internal, "__comptimechoose") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = switch (args[1].*) {
                .int_lit => .{ .int = args[1].int_lit.val },
                else => return null,
            };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__derivechoose") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = switch (args[1].*) {
                .int_lit => .{ .int = args[1].int_lit.val },
                else => return null,
            };
            storage[2] = deriveNameValueFromExpr(args[2]) orelse return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__comptimefanout") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = switch (args[1].*) {
                .int_lit => .{ .int = args[1].int_lit.val },
                else => return null,
            };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__comptimetabulate") and args.len == 2) {
            storage[0] = switch (args[0].*) {
                .int_lit => .{ .int = args[0].int_lit.val },
                else => return null,
            };
            storage[1] = comptime_eval.evalWithBindings(args[1], bindings, opts) catch return null;
            if (storage[1] != .func) return null;
            return 2;
        }
        if (std.mem.eql(u8, internal, "__comptimeinterpolate") and args.len == 2) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = comptime_eval.evalWithBindings(args[1], bindings, opts) catch return null;
            return 2;
        }
        if (std.mem.eql(u8, internal, "__comptimezip") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__comptimeproduct") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__comptimetensor") and args.len == 4) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            storage[3] = comptime_eval.evalWithBindings(args[3], bindings, opts) catch return null;
            if (storage[3] != .func) return null;
            return 4;
        }
        if (std.mem.eql(u8, internal, "__derivetensor") and args.len == 4) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            storage[3] = deriveNameValueFromExpr(args[3]) orelse return null;
            return 4;
        }
        if (std.mem.eql(u8, internal, "__deriveproduct") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = deriveNameValueFromExpr(args[2]) orelse return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__metaexpand") and args.len >= 2) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            if (args.len >= 3) {
                storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
                if (storage[2] != .func) return null;
                return 3;
            }
            return 2;
        }
        if (std.mem.eql(u8, internal, "__metaceiling") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            return 3;
        }
        if (std.mem.eql(u8, internal, "__metaomni") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            return 3;
        }
        if (std.mem.eql(u8, internal, "__metaomni") and args.len == 4) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            storage[3] = comptime_eval.evalWithBindings(args[3], bindings, opts) catch return null;
            if (storage[3] != .func) return null;
            return 4;
        }
        if (std.mem.eql(u8, internal, "__metaburst") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            return 3;
        }
        if (std.mem.eql(u8, internal, "__metatranscend") and args.len == 4) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            storage[3] = .{ .string = self.metaStringFromExprOrFold(args[3]) orelse return null };
            return 4;
        }
        if (std.mem.eql(u8, internal, "__metatranscend") and args.len == 5) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = .{ .string = self.metaStringFromExprOrFold(args[2]) orelse return null };
            storage[3] = .{ .string = self.metaStringFromExprOrFold(args[3]) orelse return null };
            storage[4] = comptime_eval.evalWithBindings(args[4], bindings, opts) catch return null;
            if (storage[4] != .func) return null;
            return 5;
        }
        if (std.mem.eql(u8, internal, "__metainfinity") and args.len == 5) {
            for (0..5) |i| {
                storage[i] = .{ .string = self.metaStringFromExprOrFold(args[i]) orelse return null };
            }
            return 5;
        }
        if (std.mem.eql(u8, internal, "__metahyper") and args.len == 6) {
            for (0..6) |i| {
                storage[i] = .{ .string = self.metaStringFromExprOrFold(args[i]) orelse return null };
            }
            return 6;
        }
        if (std.mem.eql(u8, internal, "__metatemplate") and args.len >= 2) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            if (args.len >= 3) {
                storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
                if (storage[2] != .func) return null;
                return 3;
            }
            return 2;
        }
        if (std.mem.eql(u8, internal, "__metagenerate") and args.len >= 1) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            if (args.len >= 2) {
                storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
                if (args.len >= 3) {
                    storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
                    if (storage[2] != .func) return null;
                    return 3;
                }
                return 2;
            }
            return 1;
        }
        if (std.mem.eql(u8, internal, "__metascheme") and args.len >= 1) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            if (args.len >= 2) {
                storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
                if (args.len >= 3) {
                    storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
                    if (storage[2] != .func) return null;
                    return 3;
                }
                return 2;
            }
            return 1;
        }
        if (std.mem.eql(u8, internal, "__metaschemeclauses") and args.len >= 1) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            if (args.len >= 2) {
                storage[1] = comptime_eval.evalWithBindings(args[1], bindings, opts) catch return null;
                if (storage[1] != .func) return null;
                return 2;
            }
            return 1;
        }
        if (std.mem.eql(u8, internal, "__comptimefixpoint") and args.len == 3) {
            storage[0] = switch (args[0].*) {
                .string_lit => |s| .{ .string = s.val },
                else => .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null },
            };
            const fp = fixpointCallFromArgs(args) orelse return null;
            storage[1] = .{ .int = @intCast(fp.max_iter) };
            storage[2] = comptime_eval.evalWithBindings(fp.callback, bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        return null;
    }

    fn runMetaCombinatorString(
        self: *CodeGen,
        internal: []const u8,
        values: []const comptime_eval.Value,
        site: transform_engine.SiteKind,
    ) ?[]const u8 {
        if (transform_engine.publicNameForInternal(internal) != null and
            !transform_engine.requireMetaDispatchBeforeHook(internal))
            return null;
        const result = meta_dispatch.dispatchAtSite(self.meta_host(), internal, values, self.alloc, site);
        return switch (result) {
            .string => |s| s,
            else => null,
        };
    }

    fn tryEmitMetaCombinatorString(self: *CodeGen, internal: []const u8, args: []const *ast.Expr) E!bool {
        self.meta_combinator_fold_depth += 1;
        defer self.meta_combinator_fold_depth -= 1;
        var storage: [8]comptime_eval.Value = undefined;
        const n = self.buildMetaCombinatorValues(internal, args, &storage) orelse return false;
        const folded = self.runMetaCombinatorString(internal, storage[0..n], self.metaCombinatorEmitSite()) orelse return false;
        try self.emit_c_string_literal(folded);
        return true;
    }

    fn fixpointCallFromArgs(args: []const *ast.Expr) ?struct {
        callback: *ast.Expr,
        max_iter: usize,
    } {
        if (args.len != 3 or args[0].* != .string_lit) return null;
        if (args[1].* == .int_lit and args[2].* == .func_expr) {
            return .{ .callback = args[2], .max_iter = @intCast(args[1].int_lit.val) };
        }
        if (args[2].* == .int_lit and args[1].* == .func_expr) {
            return .{ .callback = args[1], .max_iter = @intCast(args[2].int_lit.val) };
        }
        return null;
    }

    fn metaCombinatorEmitSite(self: *const CodeGen) transform_engine.SiteKind {
        if (self.current_func_body != null) return .block_body;
        return .emit_call;
    }

    fn logTransformProvenance(
        self: *CodeGen,
        public_name: []const u8,
        site: transform_engine.SiteKind,
        input: []const u8,
        output: []const u8,
    ) void {
        if (!transform_engine.isRegisteredTransform(public_name)) return;
        transform_engine.logProvenance(
            self.alloc,
            public_name,
            site,
            std.hash.Wyhash.hash(0, input),
            std.hash.Wyhash.hash(0, output),
        );
    }

    /// __type_id(expr) — stable compile-time type identifier (FNV hash of type name)
    fn emit_type_id_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        var buf: [128]u8 = undefined;
        const name = rt.c_type(&buf);
        // FNV-1a hash for stable type IDs
        var hash: u64 = 14695981039346656037;
        for (name) |byte| {
            hash ^= @as(u64, byte);
            hash *%= 1099511628211;
        }
        self.p("((int64_t){d}LL)", .{@as(i64, @bitCast(hash))});
    }

    /// __is_type(expr, "type_name") — compile-time type identity check
    fn emit_is_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const expected = if (args[1].* == .string_lit) args[1].string_lit.val else {
            self.p("false", .{});
            return;
        };
        var buf: [128]u8 = undefined;
        const actual = rt.c_type(&buf);
        // Check both C type name and Duo type name
        const matches = std.mem.eql(u8, actual, expected) or
            (std.mem.eql(u8, expected, "i64") and std.mem.eql(u8, actual, "int64_t")) or
            (std.mem.eql(u8, expected, "i32") and std.mem.eql(u8, actual, "int32_t")) or
            (std.mem.eql(u8, expected, "f64") and std.mem.eql(u8, actual, "double")) or
            (std.mem.eql(u8, expected, "f32") and std.mem.eql(u8, actual, "float")) or
            (std.mem.eql(u8, expected, "str") and std.mem.eql(u8, actual, "const char*")) or
            (std.mem.eql(u8, expected, "bool") and std.mem.eql(u8, actual, "bool")) or
            (std.mem.eql(u8, expected, "any") and std.mem.eql(u8, actual, "lua_Value"));
        self.p("{s}", .{if (matches) "true" else "false"});
    }

    /// __comptimeprint / __comptimewarn / __comptimeerror — compile-time messages
    fn emit_comptime_message(self: *CodeGen, args: []const *ast.Expr, level: MessageLevel) E!void {
        // Evaluate message at compile time
        const val = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch {
            if (args[0].* == .string_lit) {
                const msg = args[0].string_lit.val;
                switch (level) {
                    .info => std.debug.print("[comptime] {s}\n", .{msg}),
                    .warning => std.debug.print("[comptime warning] {s}\n", .{msg}),
                    .err => {
                        std.debug.print("[comptime error] {s}\n", .{msg});
                        self.p("_Static_assert(0, \"{s}\")", .{msg});
                        return;
                    },
                }
                self.p("((void)0)", .{});
                return;
            }
            self.p("((void)0)", .{});
            return;
        };
        if (val == .string) {
            switch (level) {
                .info => std.debug.print("[comptime] {s}\n", .{val.string}),
                .warning => std.debug.print("[comptime warning] {s}\n", .{val.string}),
                .err => {
                    std.debug.print("[comptime error] {s}\n", .{val.string});
                    self.p("_Static_assert(0, \"{s}\")", .{val.string});
                    return;
                },
            }
        }
        self.p("((void)0)", .{});
    }

    /// __embed_str("path") — embed file contents as a C string literal
    fn emit_embed_str(self: *CodeGen, arg: *const ast.Expr) E!void {
        if (arg.* == .string_lit) {
            // Use C23 #embed or fall back to xxd-style inclusion
            // For maximum portability, emit as a char literal via _Pragma or include
            self.p("((const char[]){{", .{});
            self.p("#embed \"{s}\"", .{arg.string_lit.val});
            self.p(", 0}})", .{});
        } else {
            self.p("\"\"", .{});
        }
    }

    /// __embed_file("path") — embed file as static byte array
    fn emit_embed_file(self: *CodeGen, arg: *const ast.Expr) E!void {
        if (arg.* == .string_lit) {
            // Emit as a compound literal with the embedded data
            self.p("({{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("static const unsigned char __embed_data[] = {{\n", .{});
            self.ind();
            self.p("    #embed \"{s}\"\n", .{arg.string_lit.val});
            self.ind();
            self.p("}};\n", .{});
            self.ind();
            self.p("lua_Value __et = lua_table_new_with_capacity(0, 2);\n", .{});
            self.ind();
            self.p("lua_table_set_raw_lit(__et, \"ptr\", {d}, 3, lua_val_from_int((int64_t)(uintptr_t)__embed_data));\n", .{calc_lua_hash("ptr")});
            self.ind();
            self.p("lua_table_set_raw_lit(__et, \"len\", {d}, 3, lua_val_from_int((int64_t)sizeof(__embed_data)));\n", .{calc_lua_hash("len")});
            self.ind();
            self.p("__et;\n", .{});
            self.indent -= 1;
            self.ind();
            self.p("}})", .{});
        } else {
            self.p("lua_val_nil()", .{});
        }
    }

    /// __field_offset(T, "field") — emit offsetof for a record field
    fn emit_field_offset_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .string_lit) args[1].string_lit.val else {
            self.p("0", .{});
            return;
        };
        switch (rt) {
            .table_type => |t| {
                // Calculate offset based on field position and type sizes
                var offset: usize = 0;
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) {
                        self.p("{d}", .{offset});
                        return;
                    }
                    // Approximate field sizes for native types
                    offset += field_byte_size(f.typ);
                }
            },
            else => {},
        }
        // Fall back to __builtin_offsetof if struct name is known
        if (args[0].* == .string_lit) {
            self.p("((int64_t)__builtin_offsetof({s}, {s}))", .{ args[0].string_lit.val, field_name });
        } else {
            self.p("0", .{});
        }
    }

    /// __field_size(T, "field") — emit sizeof for a specific field's type
    fn emit_field_size_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .string_lit) args[1].string_lit.val else {
            self.p("0", .{});
            return;
        };
        switch (rt) {
            .table_type => |t| {
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) {
                        self.p("{d}", .{field_byte_size(f.typ)});
                        return;
                    }
                }
            },
            else => {},
        }
        self.p("0", .{});
    }

    /// Helper: approximate byte size of a resolved type
    fn field_byte_size(rt: types.ResolvedType) usize {
        return switch (rt) {
            .i8, .u8, .bool => 1,
            .i16, .u16 => 2,
            .i32, .u32, .f32 => 4,
            .i64, .u64, .f64 => 8,
            .str, .pointer, .any => 8, // pointer-sized
            .v4f64, .v4i64 => 32,
            .v8f32, .v8i32 => 32,
            else => 8, // default pointer-sized
        };
    }

    /// __bitfield("name", ...) — define a packed bitfield struct
    fn emit_bitfield_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1 or args[0].* != .string_lit) {
            self.p("lua_val_from_int(0)", .{});
            return;
        }
        const struct_name = args[0].string_lit.val;
        // Emit a packed struct typedef with bitfield members
        // Args after first: alternating "field_name" and bit_width (int literal)
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("typedef struct __attribute__((packed)) {{\n", .{});
        var i: usize = 1;
        while (i + 1 < args.len) : (i += 2) {
            if (args[i].* == .string_lit and args[i + 1].* == .int_lit) {
                self.ind();
                self.p("    uint64_t {s} : {d};\n", .{ args[i].string_lit.val, args[i + 1].int_lit.val });
            }
        }
        self.ind();
        self.p("}} {s};\n", .{struct_name});
        self.ind();
        self.p("lua_val_from_int((int64_t)sizeof({s}));\n", .{struct_name});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __union("name", ...) — define a C union type
    fn emit_union_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1 or args[0].* != .string_lit) {
            self.p("lua_val_from_int(0)", .{});
            return;
        }
        const union_name = args[0].string_lit.val;
        // Args after first: alternating "field_name" and "c_type"
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("typedef union {{\n", .{});
        var i: usize = 1;
        while (i + 1 < args.len) : (i += 2) {
            if (args[i].* == .string_lit and args[i + 1].* == .string_lit) {
                self.ind();
                self.p("    {s} {s};\n", .{ args[i + 1].string_lit.val, args[i].string_lit.val });
            }
        }
        self.ind();
        self.p("}} {s};\n", .{union_name});
        self.ind();
        self.p("lua_val_from_int((int64_t)sizeof({s}));\n", .{union_name});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __make_type("name", "field1", "type1", "field2", "type2", ...) — define a struct type
    /// Returns sizeof(type) as an integer. The typedef is emitted inline.
    fn emit_make_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1 or args[0].* != .string_lit) {
            self.p("lua_val_from_int(0)", .{});
            return;
        }
        const type_name = args[0].string_lit.val;
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("typedef struct {{\n", .{});
        var i: usize = 1;
        while (i + 1 < args.len) : (i += 2) {
            if (args[i].* == .string_lit and args[i + 1].* == .string_lit) {
                self.ind();
                self.p("    {s} {s};\n", .{ args[i + 1].string_lit.val, args[i].string_lit.val });
            }
        }
        self.ind();
        self.p("}} {s};\n", .{type_name});
        self.ind();
        self.p("lua_val_from_int((int64_t)sizeof({s}));\n", .{type_name});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __metatable_type(expr) — returns type info about an expression's metatable
    fn emit_metatable_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        // Emit a runtime query that returns metatable info as a table
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __obj = ", .{});
        try self.emit_as_lua_value(args[0]);
        self.p(";\n", .{});
        self.ind();
        self.p("lua_Value __mt_info = lua_table_new_with_capacity(0, 2);\n", .{});
        self.ind();
        self.p("lua_Value __mt = lua_getmetatable(__obj);\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__mt_info, \"has_metatable\", {d}, 13, lua_val_from_bool(__mt.type != VAL_NIL));\n", .{calc_lua_hash("has_metatable")});
        self.ind();
        self.p("lua_table_set_raw_lit(__mt_info, \"metatable\", {d}, 9, __mt);\n", .{calc_lua_hash("metatable")});
        self.ind();
        self.p("__mt_info;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn exprs_same(_: *CodeGen, a: *const ast.Expr, b: *const ast.Expr) bool {
        if (@intFromPtr(a) == @intFromPtr(b)) return true;
        if (@as(std.meta.Tag(ast.Expr), a.*) != @as(std.meta.Tag(ast.Expr), b.*)) return false;
        return switch (a.*) {
            .name => std.mem.eql(u8, a.name.ident, b.name.ident),
            else => false,
        };
    }

    fn math_unary_arg(expr: *const ast.Expr, fname: []const u8) ?*const ast.Expr {
        if (expr.* != .call) return null;
        const c = &expr.call;
        if (c.func.* != .field) return null;
        const f = &c.func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "math")) return null;
        if (!std.mem.eql(u8, f.field, fname)) return null;
        if (c.args.len != 1) return null;
        return c.args[0];
    }

    fn try_emit_sin_cos_product(self: *CodeGen, lhs: *const ast.Expr, rhs: *const ast.Expr) E!bool {
        const sin_arg = math_unary_arg(lhs, "sin") orelse math_unary_arg(rhs, "sin");
        const cos_arg = math_unary_arg(lhs, "cos") orelse math_unary_arg(rhs, "cos");
        if (sin_arg == null or cos_arg == null) return false;
        if (!self.exprs_same(sin_arg.?, cos_arg.?)) return false;
        const arg = sin_arg.?;
        self.p("(0.5 * sin(2.0 * (double)(", .{});
        try self.emit_expr(arg);
        self.p(")))", .{});
        return true;
    }

    fn maybe_emit_math_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_numeric()) return false;
        if (func.* != .field) return false;
        const f = &func.field;
        if (f.obj.* != .name) return false;
        if (!std.mem.eql(u8, f.obj.name.ident, "math")) return false;

        const fname = f.field;
        // Integer-typed max/min/abs: emit native integer ops instead of the
        // double-returning libm path, avoiding the int->double->int round-trip.
        if (std.mem.eql(u8, fname, "max") or std.mem.eql(u8, fname, "min")) {
            if (args.len != 2) return false;
            if (self.expr_type(args[0]).is_integer() and self.expr_type(args[1]).is_integer()) {
                self.p("{s}(", .{if (std.mem.eql(u8, fname, "max")) "lua_imax_i64" else "lua_imin_i64"});
                try self.emit_expr(args[0]);
                self.p(", ", .{});
                try self.emit_expr(args[1]);
                self.p(")", .{});
                return true;
            }
        }
        if (std.mem.eql(u8, fname, "abs") and args.len == 1 and self.expr_type(args[0]).is_integer()) {
            self.p("llabs(", .{});
            try self.emit_expr(args[0]);
            self.p(")", .{});
            return true;
        }
        if ((std.mem.eql(u8, fname, "deg") or std.mem.eql(u8, fname, "rad")) and args.len == 1) {
            const scale = if (std.mem.eql(u8, fname, "deg")) "180.0 / 3.14159265358979323846" else "3.14159265358979323846 / 180.0";
            self.p("(", .{});
            const at = self.expr_type(args[0]);
            if (at.is_integer()) {
                self.p("(double)(", .{});
                try self.emit_expr(args[0]);
                self.p(")", .{});
            } else if (at == .any or self.expr_emits_lua_value(args[0])) {
                self.p("lua_to_num(", .{});
                try self.emit_as_lua_value(args[0]);
                self.p(")", .{});
            } else {
                try self.emit_expr(args[0]);
            }
            self.p(" * ({s}))", .{scale});
            return true;
        }
        const lua_names = [_][]const u8{
            "sqrt", "abs",  "floor", "ceil", "sin",  "cos",  "tan",
            "asin", "acos", "atan",  "exp",  "log",  "fmod", "max",
            "min",  "pow",  "log10", "sinh", "cosh", "tanh",
        };
        if ((std.mem.eql(u8, fname, "max") or std.mem.eql(u8, fname, "min")) and args.len != 2) return false;
        const c_names = [_][]const u8{
            "sqrt", "fabs", "floor", "ceil", "sin",  "cos",  "tan",
            "asin", "acos", "atan",  "exp",  "log",  "fmod", "fmax",
            "fmin", "pow",  "log10", "sinh", "cosh", "tanh",
        };
        for (lua_names, c_names) |ln, cn| {
            if (std.mem.eql(u8, fname, ln)) {
                self.p("{s}(", .{cn});
                for (args, 0..) |arg, i| {
                    if (i > 0) self.p(", ", .{});
                    const at = self.expr_type(arg);
                    if (at.is_integer()) {
                        self.p("(double)(", .{});
                        try self.emit_expr(arg);
                        self.p(")", .{});
                    } else if (at == .any or self.expr_emits_lua_value(arg)) {
                        self.p("lua_to_num(", .{});
                        try self.emit_as_lua_value(arg);
                        self.p(")", .{});
                    } else {
                        try self.emit_expr(arg);
                    }
                }
                self.p(")", .{});
                return true;
            }
        }
        return false;
    }

    /// One lowering for both orientations of the conversion edge (A3 ONE EDGE,
    /// 3.2: "orientations to/from share one edge"). `target` names the
    /// destination descriptor; `value` is the single runtime operand.
    fn emit_convert_edge(self: *CodeGen, target: []const u8, loc: ast.Loc, value: *ast.Expr, result_rt: RT) E!bool {
        var one = [_]*ast.Expr{value};
        if (std.mem.eql(u8, target, "str")) {
            var synth = ast.Expr{ .name = .{ .loc = loc, .ident = "tostring" } };
            return try self.maybe_emit_stdlib_call(&synth, one[0..], result_rt);
        }
        if (std.mem.eql(u8, target, "f64") or std.mem.eql(u8, target, "f32")) {
            var synth = ast.Expr{ .name = .{ .loc = loc, .ident = "tonumber" } };
            return try self.maybe_emit_stdlib_call(&synth, one[0..], result_rt);
        }
        // Integer targets lower to the native C conversion, which truncates
        // toward zero — no boxed call in between.
        if (std.mem.eql(u8, target, "i64") or std.mem.eql(u8, target, "i32") or
            std.mem.eql(u8, target, "i16") or std.mem.eql(u8, target, "i8"))
        {
            // A native C cast is only valid when the SOURCE is already numeric.
            // Applied to a `str` it cast the `const char*` and produced a
            // POINTER VALUE silently (`to(i64)("42")` -> 4338831547), and
            // applied to an `any` it did not compile at all ("operand of type
            // 'lua_Value' where arithmetic or pointer type is required"). Both
            // route through the boxed numeric conversion instead, which parses
            // strings — the same conversion `tonumber` is a projection of, so
            // the edge has one meaning regardless of what flows into it.
            const src = self.expr_type(value);
            if (result_rt == .any) self.p("lua_val_from_int(", .{});
            if (src == .str or src == .any) {
                self.p("((int64_t)lua_to_num(", .{});
                try self.emit_as_lua_value(value);
                self.p("))", .{});
            } else {
                self.p("((int64_t)(", .{});
                try self.emit_expr(value);
                self.p("))", .{});
            }
            if (result_rt == .any) self.p(")", .{});
            return true;
        }
        return false;
    }

    /// LAW-CALL's "data always wins the name", enforced by SCOPE LOOKUP rather
    /// than by guessing from operand types. A relation family may only be
    /// projected onto a bare name when the program has not bound that name
    /// itself — `lib/std/reflect.duo` and `lib/std/utf8.duo` both define their
    /// own `len`, and an unguarded projection silently hijacked them.
    fn user_owns_name(self: *CodeGen, name: []const u8) bool {
        if (self.func_decls.contains(name)) return true;
        if (self.func_bodies.contains(name)) return true;
        var i = self.local_scopes.items.len;
        while (i > 0) {
            i -= 1;
            if (self.local_scopes.items[i].contains(name)) return true;
        }
        return false;
    }

    /// Spec 2.10 G3 (de-magicking): a primitive type name is an ORDINARY VALUE,
    /// not a third category. `to(str)(x)` used to work only because the call
    /// emitter pattern-matched the AST shape and never evaluated `str` — the
    /// moment the same name reached value position (`t = str`, `print(str)`,
    /// `str.from(i64)(v)`) codegen emitted a bare C identifier and clang said
    /// "use of undeclared identifier 'str'". That is exactly the "third
    /// category" the de-magicking test forbids.
    ///
    /// The set here is deliberately the LEXER KEYWORD set (`typeKeywordName` in
    /// parser.zig), not `mem_type_from_name`'s wider alias list. `str`/`i64` are
    /// reserved words, so no program can bind them and no projection can hijack
    /// a user name; `string`, `ptr`, `isize`, `usize` are ordinary identifiers a
    /// program MAY bind, so they stay out.
    /// Whether a numeric `for` step is a statically-known NEGATIVE value.
    /// null means the sign is only knowable at run time, which the caller
    /// handles with a hoisted runtime test rather than guessing.
    fn num_for_step_negative(e: *const ast.Expr) ?bool {
        return switch (e.*) {
            .int_lit => |x| x.val < 0,
            .float_lit => |x| x.val < 0,
            .unop => |u| if (u.op == .neg) blk: {
                const inner = num_for_step_negative(u.operand) orelse break :blk null;
                break :blk !inner;
            } else null,
            else => null,
        };
    }

    fn primitive_descriptor_name(name: []const u8) ?[]const u8 {
        for ([_][]const u8{
            "i8",  "i16", "i32",  "i64",
            "u8",  "u16", "u32",  "u64",
            "f32", "f64", "bool", "void",
            "str",
        }) |t| {
            if (std.mem.eql(u8, name, t)) return t;
        }
        return null;
    }

    /// The runtime form of a descriptor. Its identity IS its canonical name, so
    /// two spellings of the same type are one value and `to(str) == to(str)`
    /// holds without a registry. Compile-time uses (`to(T)(v)`, `mem.store(T)`)
    /// intercept the name before this ever runs, so a descriptor only
    /// materializes when the program actually treats it as data.
    fn emit_primitive_descriptor(self: *CodeGen, canon: []const u8) void {
        self.p("lua_val_from_literal(\"{s}\", {d}, {d})", .{
            canon, calc_lua_hash(canon), canon.len,
        });
    }

    fn maybe_emit_stdlib_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        // `has(.lens)(subject)` — the presence FAMILY (2.8): subject is the
        // container, parameter is the lens. A lens parses to a lambda over
        // `__proj_v`, so presence is just "apply the lens, test for nil".
        // Demand is real: 110 sites in lib/ spell this `x.field != nil`.
        if (func.* == .call) {
            const hf = func.call;
            if (hf.func.* == .name and std.mem.eql(u8, hf.func.name.ident, "has") and
                hf.args.len == 1 and args.len == 1 and !self.user_owns_name("has"))
            {
                // The lens is a lambda over `__proj_v`; take its field directly
                // rather than materializing and invoking the closure (A4 DEMAND
                // — nothing physical unless consumed).
                if (hf.args[0].* == .func_expr) {
                    if (pipeline_projection_field_name(hf.args[0].func_expr)) |fname| {
                        var fexpr = ast.Expr{ .field = .{ .loc = hf.loc, .obj = args[0], .field = fname } };
                        // Presence is a bool; box it when the consuming site
                        // expects a lua_Value.
                        if (result_rt == .any) self.p("lua_val_from_bool(", .{});
                        self.p("((", .{});
                        try self.emit_as_lua_value(&fexpr);
                        self.p(").type != VAL_NIL)", .{});
                        if (result_rt == .any) self.p(")", .{});
                        return true;
                    }
                }
            }
        }

        // `T:from(S)(v)` — the REVERSE ORIENTATION of the conversion edge
        // (2.6 spells it `str:from(point)(raw)`): the TARGET is the receiver,
        // the SOURCE is the descriptor group. Same edge as `to(T)(v)`.
        if (func.* == .method_call) {
            const recv = func.method_call;
            if (std.mem.eql(u8, recv.method, "from") and recv.obj.* == .name and args.len == 1) {
                if (try self.emit_convert_edge(recv.obj.name.ident, recv.loc, args[0], result_rt)) return true;
            }
        }
        // Same edge, DOT spelling. Gate 6 requires `to(str)` and `str.from(T)`
        // to be one edge with one id, and canonical Duo writes `.` not `:` —
        // without this arm `str.from(...)` fell through to a table lookup on the
        // descriptor and died. Two groups (`str.from(i64)(42)`, the source
        // descriptor named explicitly per gate 6) and one group
        // (`str.from(42)`, the source inferred from the value) both lower
        // through emit_convert_edge, so all four spellings are one lowering.
        if (func.* == .call and func.call.func.* == .field and args.len == 1) {
            const fld = func.call.func.field;
            if (std.mem.eql(u8, fld.field, "from") and fld.obj.* == .name and func.call.args.len == 1) {
                if (try self.emit_convert_edge(fld.obj.name.ident, fld.loc, args[0], result_rt)) return true;
            }
        }
        if (func.* == .field and args.len == 1) {
            const fld = func.field;
            if (std.mem.eql(u8, fld.field, "from") and fld.obj.* == .name) {
                if (try self.emit_convert_edge(fld.obj.name.ident, fld.loc, args[0], result_rt)) return true;
            }
        }
        // Canonical relation family `to` (spec 2.6): `to(T)(v)` is the curried
        // conversion — `to(str)(x)`, `to(i64)(x)`. Spec 2.10's de-magicking test
        // (G3) requires every std name to be an ordinary value or a relation
        // family with inspectable edges, "no third category", so the
        // Lua-inherited tostring/tonumber are PROJECTIONS of `to` rather than
        // builtins of their own. The canonical spelling is the one to write;
        // the vestiges remain only as aliases.
        if (func.* == .call) {
            const inner = func.call;
            const fam_to = inner.func.* == .name and std.mem.eql(u8, inner.func.name.ident, "to");
            // `from` is NOT resolvable standalone: 2.6 spells it
            // `str:from(point)(raw)` — the TARGET is the receiver, the source
            // is the descriptor group. It therefore arrives through method
            // projection below, never as a bare call, so there is nothing to
            // guess from demand here.
            if (fam_to and inner.args.len == 1 and inner.args[0].* == .name and args.len == 1) {
                // Same edge as `T:from(S)(v)` — one lowering, two spellings.
                if (try self.emit_convert_edge(inner.args[0].name.ident, inner.func.name.loc, args[0], result_rt)) return true;
            }
        }
        if (func.* != .name) return false;
        const name = func.name.ident;
        // `len` relation family (2.6). `#x` is its OPERATOR projection (2.1)
        // and `s:len()` already has a specialized typed-string lowering that
        // owns the receiver form — so only the operation-first spelling is
        // added here, and only when the program has not bound `len` itself.
        if (std.mem.eql(u8, name, "len") and args.len == 1 and !self.user_owns_name("len")) {
            var u = ast.Expr{ .unop = .{ .loc = func.name.loc, .op = .len, .operand = args[0] } };
            try self.emit_expr(&u);
            return true;
        }
        if (std.mem.eql(u8, name, "assert")) {
            self.p("lua_assert(", .{});
            if (args.len > 0) {
                try self.emit_as_lua_value(args[0]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(", ", .{});
            if (args.len > 1) {
                self.p("lua_to_str(", .{});
                try self.emit_as_lua_value(args[1]);
                self.p(")", .{});
            } else {
                self.p("NULL", .{});
            }
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "require") or std.mem.eql(u8, name, "req")) {
            // Don't intercept req/require if the user defined their own function.
            var name_buf: [256]u8 = undefined;
            const mangled = self.mangled_name(name, &name_buf);
            if (self.func_bodies.contains(mangled)) {
                return false; // Let the normal call path handle it
            }
            self.p("lua_require(", .{});
            if (args.len > 0) {
                try self.emit_as_lua_value(args[0]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "select")) {
            const n = if (args.len > 1) args.len - 1 else 0;
            if (result_rt.is_integer() and args.len > 0 and args[0].* == .string_lit and
                std.mem.eql(u8, args[0].string_lit.val, "#") and !self.args_contain_vararg(args[1..]))
            {
                self.p("{d}", .{n});
                return true;
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("lua_select_v(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", {d}", .{n});
            var i: usize = 1;
            while (i < args.len) : (i += 1) {
                self.p(", ", .{});
                try self.emit_as_lua_value(args[i]);
            }
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "error")) {
            try self.emit_fatal_error(if (args.len > 0) args[0] else null);
            return true;
        } else if (std.mem.eql(u8, name, "pcall")) {
            const want_bool = result_rt == .bool;
            var coerced = false;
            if (!want_bool) {
                coerced = self.emit_lua_result_coerce_prefix(result_rt);
            }
            if (args.len > 2) {
                self.p("{s}({d}, (lua_Value[]){{", .{ if (want_bool) "lua_pcall_argv_bool" else "lua_pcall_argv_fn", args.len });
                for (args, 0..) |arg, i| {
                    if (i > 0) self.p(", ", .{});
                    try self.emit_as_lua_value(arg);
                }
                self.p("}})", .{});
            } else {
                self.p("{s}(", .{if (want_bool) "lua_pcall_bool" else "lua_pcall"});
                if (args.len > 0) {
                    try self.emit_as_lua_value(args[0]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
                self.p(", ", .{});
                if (args.len > 1) {
                    try self.emit_as_lua_value(args[1]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
                self.p(")", .{});
            }
            if (coerced) {
                self.emit_lua_result_coerce_suffix(result_rt);
            }
            return true;
        } else if (std.mem.eql(u8, name, "next")) {
            self.p("lua_next(", .{});
            if (args.len > 0) {
                try self.emit_as_lua_value(args[0]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(", ", .{});
            if (args.len > 1) {
                try self.emit_as_lua_value(args[1]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "unpack")) {
            self.p("lua_tbl_unpack(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "setmetatable")) {
            self.p("lua_setmetatable(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "getmetatable")) {
            self.p("lua_getmetatable(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawget")) {
            self.p("lua_rawget(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawset")) {
            self.p("lua_rawset(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawlen")) {
            if (result_rt.is_integer()) {
                if (args.len > 0 and args[0].* == .string_lit) {
                    self.p("{d}", .{args[0].string_lit.val.len});
                    return true;
                }
                if (args.len > 0 and self.expr_type(args[0]) == .str) {
                    self.p("((int64_t)strlen(", .{});
                    try self.emit_expr(args[0]);
                    self.p("))", .{});
                    return true;
                }
                self.p("lua_rawlen_i64(", .{});
            } else {
                const coerced = self.emit_lua_result_coerce_prefix(result_rt);
                self.p("lua_rawlen(", .{});
                if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
                self.p(")", .{});
                if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
                return true;
            }
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawequal")) {
            if (result_rt == .bool) {
                self.p("({{ lua_Value _duo_a = ", .{});
                if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
                self.p("; lua_Value _duo_b = ", .{});
                if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
                self.p("; lua_raweq_value(_duo_a, _duo_b); }})", .{});
                return true;
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("lua_rawequal(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "collectgarbage")) {
            if (args.len == 0 and (result_rt == .f64 or result_rt == .f32)) {
                self.p("({{ duo_run_gc_finalizers(); 0.0; }})", .{});
                return true;
            }
            if (args.len > 0 and args[0].* == .string_lit) {
                const opt = args[0].string_lit.val;
                if ((result_rt == .f64 or result_rt == .f32) and std.mem.eql(u8, opt, "count")) {
                    self.p("((double)duo_gc_kbytes)", .{});
                    return true;
                }
                if ((result_rt == .f64 or result_rt == .f32) and std.mem.eql(u8, opt, "collect")) {
                    self.p("({{ duo_run_gc_finalizers(); 0.0; }})", .{});
                    return true;
                }
                if (result_rt == .bool and (std.mem.eql(u8, opt, "stop") or std.mem.eql(u8, opt, "restart"))) {
                    self.p("true", .{});
                    return true;
                }
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("lua_collectgarbage(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "warn")) {
            self.p("lua_warn(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "xpcall")) {
            const want_bool = result_rt == .bool;
            var coerced = false;
            if (!want_bool) {
                coerced = self.emit_lua_result_coerce_prefix(result_rt);
            }
            if (args.len > 3) {
                self.p("{s}({d}, (lua_Value[]){{", .{ if (want_bool) "lua_xpcall_argv_bool" else "lua_xpcall_argv_fn", args.len });
                for (args, 0..) |arg, i| {
                    if (i > 0) self.p(", ", .{});
                    try self.emit_as_lua_value(arg);
                }
                self.p("}})", .{});
            } else {
                self.p("{s}(", .{if (want_bool) "lua_xpcall_bool" else "lua_xpcall"});
                if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
                self.p(", ", .{});
                if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
                self.p(", ", .{});
                if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
                self.p(")", .{});
            }
            if (coerced) {
                self.emit_lua_result_coerce_suffix(result_rt);
            }
            return true;
        } else if (std.mem.eql(u8, name, "load")) {
            self.p("lua_load(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 3) try self.emit_as_lua_value(args[3]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "loadfile")) {
            self.p("lua_loadfile(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "dofile")) {
            self.p("lua_dofile(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "tostring")) {
            if (args.len > 0) {
                if (self.expr_enum_name(args[0])) |enum_name| {
                    if (self.enum_has_derive(enum_name, "Display") and self.enum_is_payload_free(enum_name)) {
                        if (result_rt == .any) self.p("lua_val_lit(", .{});
                        self.p("duo_{s}_to_string(", .{enum_name});
                        try self.emit_expr(args[0]);
                        self.p(")", .{});
                        if (result_rt == .any) self.p(")", .{});
                        return true;
                    }
                }
            }
            const want_cstr = result_rt == .str;
            if (want_cstr) self.p("lua_to_str(", .{});
            self.p("tostring(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (want_cstr) self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "tonumber")) {
            if (!self.moduleNeedsLuaRuntime() and args.len == 1 and self.expr_type(args[0]) == .str) {
                if (result_rt.is_integer()) self.p("((int64_t)(", .{});
                self.p("strtod(", .{});
                try self.emit_expr(args[0]);
                self.p(", NULL)", .{});
                if (result_rt.is_integer()) self.p(")", .{});
                return true;
            }
            if ((result_rt == .f64 or result_rt == .f32) and args.len == 1) {
                const at = self.expr_type(args[0]);
                if (at.is_numeric()) {
                    if (at.is_integer()) self.p("(double)(", .{});
                    try self.emit_expr(args[0]);
                    if (at.is_integer()) self.p(")", .{});
                    return true;
                }
                self.p("lua_to_num(", .{});
                try self.emit_as_lua_value(args[0]);
                self.p(")", .{});
                return true;
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("tonumber(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "pairs")) {
            self.p("lua_pairs(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "ipairs")) {
            self.p("lua_ipairs(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "type")) {
            if (result_rt == .str and args.len == 1) {
                if (self.known_lua_type_name_without_eval(args[0])) |type_name| {
                    self.p("\"{s}\"", .{type_name});
                    return true;
                }
            }
            const want_cstr = result_rt == .str;
            if (want_cstr) self.p("lua_to_str(", .{});
            self.p("type(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (want_cstr) self.p(")", .{});
            return true;
        }
        return false;
    }

    fn known_lua_type_name_without_eval(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        return switch (expr.*) {
            .nil => "nil",
            .true_lit, .false_lit => "boolean",
            .int_lit, .float_lit => "number",
            .string_lit => "string",
            .name => |name| blk: {
                if (is_runtime_global(name.ident)) break :blk null;
                const rt = self.expr_type(expr);
                if (rt.is_numeric()) break :blk "number";
                if (rt == .bool) break :blk "boolean";
                if (rt == .str) break :blk "string";
                break :blk null;
            },
            else => null,
        };
    }

    fn args_contain_vararg(_: *CodeGen, args: []*ast.Expr) bool {
        for (args) |arg| {
            if (arg.* == .vararg) return true;
        }
        return false;
    }

    fn expr_is_native_cstr(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .string_lit => true,
            .name => self.expr_type(e) == .str,
            .index => self.expr_type(e) == .str and (self.is_native_dense_module_index(e.index.obj) or
                self.req_module_dense_index_info(e.index.obj) != null),
            // A typed call returning str lowers to a native `const char*` when
            // the module uses native lowering (native_scalar_mode or module
            // knowledge >= native). In that mode emit directly; otherwise the
            // call may still return a boxed value.
            .call => blk: {
                if (self.infer_req_module_call_return_type(e)) |rt| {
                    if (rt == .str) break :blk true;
                }
                if (self.expr_type(e) != .str) break :blk false;
                if (self.moduleUsesFullNativeLowering()) break :blk true;
                if (self.current_func_name) |name| break :blk self.funcUsesNativeLowering(name);
                break :blk false;
            },
            else => false,
        };
    }

    /// Emit `strcmp(lhs, rhs)` where a native operand emits directly as
    /// `const char*` and a dynamic operand is unwrapped via `lua_to_str`.
    /// Shared by ==/!=/< etc. string comparison paths (no boxed dispatch).
    fn emitStrCompareOperands(
        self: *CodeGen,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lhs_c: bool,
        rhs_c: bool,
    ) !void {
        self.p("strcmp(", .{});
        if (lhs_c) {
            try self.emit_expr(lhs);
        } else {
            self.p("lua_to_str(", .{});
            try self.emit_as_lua_value(lhs);
            self.p(")", .{});
        }
        self.p(", ", .{});
        if (rhs_c) {
            try self.emit_expr(rhs);
        } else {
            self.p("lua_to_str(", .{});
            try self.emit_as_lua_value(rhs);
            self.p(")", .{});
        }
        self.p(")", .{});
    }

    fn expr_is_raw_c_intrinsic(_: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .call or e.call.func.* != .name) return false;
        const name = e.call.func.name.ident;
        return std.mem.eql(u8, name, "__emit") or
            std.mem.eql(u8, name, "__c_call") or
            std.mem.eql(u8, name, "__as") or
            std.mem.eql(u8, name, "__as_type") or
            std.mem.eql(u8, name, "__sizeof") or
            std.mem.eql(u8, name, "__alignof") or
            std.mem.eql(u8, name, "__offsetof") or
            std.mem.eql(u8, name, "__bitcast") or
            std.mem.eql(u8, name, "__volatile");
    }

    fn expr_is_recognized_stdlib_module(self: *CodeGen, name: []const u8) bool {
        _ = self;
        const modules = [_][]const u8{
            "math",      "string", "table", "io",  "os",  "utf8",   "debug",
            "coroutine", "jit",    "ffi",   "net", "mem", "atomic", "fmt",
            "package",
        };
        for (modules) |m| {
            if (std.mem.eql(u8, name, m)) return true;
        }
        return false;
    }

    /// True when `emit_expr(e)` produces a pointer into a boxed lua_String
    /// (whose length header duo_str_len_hdr can read): generic lua_Value-emitting
    /// exprs coerced via lua_to_str, or recognized stdlib string-module calls
    /// (string.char/sub/rep/...) that lower through lua_str_* and are unwrapped
    /// with lua_to_str. Plain native strings (concat, params, native calls,
    /// literals) are NOT lua_String-backed.
    fn expr_is_boxed_string_ptr(self: *CodeGen, e: *const ast.Expr) bool {
        if (self.expr_emits_lua_value(e)) return true;
        if (e.* != .call or e.call.func.* != .field) return false;
        const f = e.call.func.field;
        if (f.obj.* != .name or !self.expr_is_recognized_stdlib_module(f.obj.name.ident)) return false;
        return self.expr_type(e) == .str;
    }

    fn expr_emits_lua_value(self: *CodeGen, e: *const ast.Expr) bool {
        if (self.expr_is_raw_c_intrinsic(e)) return false;
        // Field-call on any-typed object goes through lua_invoke -> returns lua_Value
        // regardless of what expr_type resolved the return type to (from function signatures).
        // Exception: recognized stdlib module calls (string.*, table.*, io.*, math.*, etc.)
        // go through emit_boxed_runtime_call which applies coercion -> native C.
        if (e.* == .call and e.call.func.* == .field and
            self.expr_type(e.call.func.field.obj) == .any and
            !(e.call.func.field.obj.* == .name and
                self.expr_is_recognized_stdlib_module(e.call.func.field.obj.name.ident)))
        {
            // A call through a req-module binding lowers to a direct C call
            // returning a native value, not a lua_Value — same exception as the
            // recognized stdlib modules above. Claiming otherwise makes callers
            // wrap it in lua_to_num(), which does not accept an int64_t.
            if (e.call.func.field.obj.* == .name and
                self.req_module_bindings.contains(e.call.func.field.obj.name.ident))
            {
                if (self.infer_req_module_call_return_type(e)) |crt| {
                    if (crt != .any and self.type_lowers_native(crt)) return false;
                }
            }
            return true;
        }
        if (self.expr_type(e) == .any) {
            // Binops on dynamic table field reads produce native C values
            // (e.g. lua_table_get_str_num returns double), not lua_Value.
            if (e.* == .binop) {
                if (self.expr_is_dynamic_table_field(e.binop.lhs) or
                    self.expr_is_dynamic_table_field(e.binop.rhs))
                    return false;
                if (self.dynamic_binop_operand_is_safe_native_unbox(e.binop.lhs) and
                    self.dynamic_binop_operand_is_safe_native_unbox(e.binop.rhs))
                    return false;
                if (e.binop.lhs.* == .binop and !self.expr_emits_lua_value(e.binop.lhs)) return false;
                if (e.binop.rhs.* == .binop and !self.expr_emits_lua_value(e.binop.rhs)) return false;
            }
            // Dynamic table field reads (lua_table_get_str_num/cstr/bool) return native C types.
            if (self.expr_is_dynamic_table_field(e)) return false;
            // Native math calls (math.sqrt etc.) emit native C (sqrt), not lua_Value.
            if (e.* == .call and e.call.func.* == .field and
                e.call.func.field.obj.* == .name and
                std.mem.eql(u8, e.call.func.field.obj.name.ident, "math"))
                return false;
            return true;
        }
        return false;
    }

    fn emit_mem_size_arg(self: *CodeGen, args: []*ast.Expr, index: usize, fallback: []const u8) E!void {
        if (index >= args.len) {
            self.p("{s}", .{fallback});
            return;
        }
        self.p("(size_t)(", .{});
        if (self.expr_type(args[index]) == .any and !self.expr_is_raw_c_intrinsic(args[index])) {
            self.p("lua_to_num(", .{});
            try self.emit_as_lua_value(args[index]);
            self.p(")", .{});
        } else {
            try self.emit_expr(args[index]);
        }
        self.p(")", .{});
    }

    fn emit_mem_integer_arg(self: *CodeGen, args: []*ast.Expr, index: usize, fallback: []const u8) E!void {
        if (index >= args.len) {
            self.p("{s}", .{fallback});
            return;
        }
        if (self.expr_type(args[index]) == .any and !self.expr_is_raw_c_intrinsic(args[index])) {
            self.p("(int64_t)lua_to_num(", .{});
