            if (args.len > 1) try self.emit_mem_integer_arg(args, 1, "0") else self.p("1", .{});
            self.p(" - 1), sizeof(double)); _v; }})", .{});
            return true;
        }
        return false;
    }

    fn emit_atomic_ptr_arg(self: *CodeGen, args: []*ast.Expr, index: usize, rt: RT) E!void {
        self.p("((", .{});
        self.typ(rt);
        self.p("*)(void*)(", .{});
        if (index < args.len) try self.emit_expr(args[index]) else self.p("NULL", .{});
        self.p("))", .{});
    }

    fn emit_atomic_value_as(self: *CodeGen, args: []*ast.Expr, index: usize, rt: RT) E!void {
        self.p("(", .{});
        self.typ(rt);
        self.p(")(", .{});
        if (index < args.len) try self.emit_mem_value_as(args[index], rt) else self.p("0", .{});
        self.p(")", .{});
    }

    fn atomic_fetch_builtin(fname: []const u8) ?[]const u8 {
        if (std.mem.eql(u8, fname, "fetch_add")) return "__atomic_fetch_add";
        if (std.mem.eql(u8, fname, "fetch_sub")) return "__atomic_fetch_sub";
        if (std.mem.eql(u8, fname, "fetch_and")) return "__atomic_fetch_and";
        if (std.mem.eql(u8, fname, "fetch_or")) return "__atomic_fetch_or";
        if (std.mem.eql(u8, fname, "fetch_xor")) return "__atomic_fetch_xor";
        return null;
    }

    fn maybe_emit_atomic_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        const fname = self.atomic_intrinsic_name(func) orelse return false;
        const rt = self.mem_type_arg(args, 0) orelse result_rt;

        if (std.mem.eql(u8, fname, "load")) {
            self.p("__atomic_load_n(", .{});
            try self.emit_atomic_ptr_arg(args, 1, rt);
            self.p(", {s})", .{atomic_order_literal(args, 2, "__ATOMIC_SEQ_CST")});
            return true;
        }
        if (std.mem.eql(u8, fname, "store")) {
            self.p("__atomic_store_n(", .{});
            try self.emit_atomic_ptr_arg(args, 1, rt);
            self.p(", ", .{});
            try self.emit_atomic_value_as(args, 2, rt);
            self.p(", {s})", .{atomic_order_literal(args, 3, "__ATOMIC_SEQ_CST")});
            return true;
        }
        if (std.mem.eql(u8, fname, "exchange")) {
            self.p("__atomic_exchange_n(", .{});
            try self.emit_atomic_ptr_arg(args, 1, rt);
            self.p(", ", .{});
            try self.emit_atomic_value_as(args, 2, rt);
            self.p(", {s})", .{atomic_order_literal(args, 3, "__ATOMIC_SEQ_CST")});
            return true;
        }
        if (std.mem.eql(u8, fname, "compare_exchange")) {
            self.p("__atomic_compare_exchange_n(", .{});
            try self.emit_atomic_ptr_arg(args, 1, rt);
            self.p(", ", .{});
            try self.emit_atomic_ptr_arg(args, 2, rt);
            self.p(", ", .{});
            try self.emit_atomic_value_as(args, 3, rt);
            self.p(", false, {s}, {s})", .{
                atomic_order_literal(args, 4, "__ATOMIC_SEQ_CST"),
                atomic_compare_failure_order(args),
            });
            return true;
        }
        if (atomic_fetch_builtin(fname)) |builtin| {
            self.p("{s}(", .{builtin});
            try self.emit_atomic_ptr_arg(args, 1, rt);
            self.p(", ", .{});
            try self.emit_atomic_value_as(args, 2, rt);
            self.p(", {s})", .{atomic_order_literal(args, 3, "__ATOMIC_SEQ_CST")});
            return true;
        }
        if (std.mem.eql(u8, fname, "fence")) {
            self.p("__atomic_thread_fence({s})", .{atomic_order_literal(args, 0, "__ATOMIC_SEQ_CST")});
            return true;
        }
        if (std.mem.eql(u8, fname, "compiler_fence")) {
            self.p("__atomic_signal_fence({s})", .{atomic_order_literal(args, 0, "__ATOMIC_SEQ_CST")});
            return true;
        }
        return false;
    }

    fn emit_lua_global_fn(self: *CodeGen, name: []const u8) bool {
        const mapped: ?[]const u8 = if (std.mem.eql(u8, name, "tostring")) "tostring" else if (std.mem.eql(u8, name, "tonumber")) "tonumber" else if (std.mem.eql(u8, name, "type")) "type" else null;
        if (mapped) |fn_name| {
            self.p("lua_val_from_func((lua_Value (*)(lua_Value)){s})", .{fn_name});
            return true;
        }
        return false;
    }

    fn maybe_emit_simd_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr) E!bool {
        if (func.* != .field) return false;
        const f = &func.field;
        if (f.obj.* != .name) return false;
        if (!std.mem.eql(u8, f.obj.name.ident, "simd")) return false;

        const fname = f.field;
        if (std.mem.eql(u8, fname, "v4f64")) {
            self.p("(v4f64){{", .{});
            for (args, 0..) |arg, i| {
                if (i > 0) self.p(", ", .{});
                try self.emit_expr(arg);
            }
            self.p("}}", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "v4i64")) {
            self.p("(v4i64){{", .{});
            for (args, 0..) |arg, i| {
                if (i > 0) self.p(", ", .{});
                try self.emit_expr(arg);
            }
            self.p("}}", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "v8f32")) {
            self.p("(v8f32){{", .{});
            for (args, 0..) |arg, i| {
                if (i > 0) self.p(", ", .{});
                try self.emit_expr(arg);
            }
            self.p("}}", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "v8i32")) {
            self.p("(v8i32){{", .{});
            for (args, 0..) |arg, i| {
                if (i > 0) self.p(", ", .{});
                try self.emit_expr(arg);
            }
            self.p("}}", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "sqrt")) {
            self.p("__builtin_elementwise_sqrt(", .{});
            if (args.len > 0) try self.emit_expr(args[0]);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "le") or std.mem.eql(u8, fname, "lt") or
            std.mem.eql(u8, fname, "ge") or std.mem.eql(u8, fname, "gt") or
            std.mem.eql(u8, fname, "eq") or std.mem.eql(u8, fname, "ne"))
        {
            const op_str: []const u8 = if (std.mem.eql(u8, fname, "le")) " <= " else if (std.mem.eql(u8, fname, "lt")) " < " else if (std.mem.eql(u8, fname, "ge")) " >= " else if (std.mem.eql(u8, fname, "gt")) " > " else if (std.mem.eql(u8, fname, "eq")) " == " else " != ";
            const lhs_rt: RT = if (args.len > 0) self.expr_type(args[0]) else .v4f64;
            const mask_rt = lhs_rt.vector_mask() orelse .v4i64;
            const mask_ct = switch (mask_rt) {
                .v8i32 => "v8i32",
                else => "v4i64",
            };
            const mask_lanes = switch (mask_rt) {
                .v8i32 => "1, 1, 1, 1, 1, 1, 1, 1",
                else => "1, 1, 1, 1",
            };
            self.p("(({s})((", .{mask_ct});
            if (args.len > 0) try self.emit_expr(args[0]);
            self.p("{s}", .{op_str});
            if (args.len > 1) try self.emit_expr(args[1]) else self.p("0", .{});
            self.p(") & ({s}){{{s}}}))", .{ mask_ct, mask_lanes });
            return true;
        }
        if (std.mem.eql(u8, fname, "select")) {
            const at: RT = if (args.len > 1) self.expr_type(args[1]) else .any;
            if (at == .v8f32) {
                self.p("duo_select_v8f32(", .{});
            } else if (at == .v4f64) {
                self.p("duo_select_v4f64(", .{});
            } else if (at == .v8i32) {
                self.p("duo_select_v8i32(", .{});
            } else {
                self.p("duo_select_v4i64(", .{});
            }
            if (args.len > 0) try self.emit_expr(args[0]);
            self.p(", ", .{});
            if (args.len > 1) try self.emit_expr(args[1]) else self.p("0", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_expr(args[2]) else self.p("0", .{});
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "sum")) {
            self.p("__builtin_reduce_add(", .{});
            if (args.len > 0) try self.emit_expr(args[0]);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "any")) {
            self.p("(__builtin_reduce_add(", .{});
            if (args.len > 0) try self.emit_expr(args[0]);
            self.p(") != 0)", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "all")) {
            const mask_rt: RT = if (args.len > 0) self.expr_type(args[0]) else .v4i64;
            const lane_count: i64 = switch (mask_rt) {
                .v8i32 => 8,
                else => 4,
            };
            self.p("(__builtin_reduce_add(", .{});
            if (args.len > 0) try self.emit_expr(args[0]);
            self.p(") == {d})", .{lane_count});
            return true;
        }
        if (std.mem.eql(u8, fname, "fma")) {
            self.p("(", .{});
            if (args.len > 0) try self.emit_expr(args[0]);
            self.p(" * ", .{});
            if (args.len > 1) try self.emit_expr(args[1]) else self.p("0", .{});
            self.p(" + ", .{});
            if (args.len > 2) try self.emit_expr(args[2]) else self.p("0", .{});
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "dot_f32") and args.len >= 3) {
            self.p("duo_simd_dot_f32((const float*)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (const float*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[2]);
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "dot_f64") and args.len >= 3) {
            self.p("duo_simd_dot_f64((const double*)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (const double*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[2]);
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "matmul_f32") and args.len >= 6) {
            self.p("duo_simd_matmul_f32((const float*)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (const float*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (float*)(", .{});
            try self.emit_expr(args[2]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[3]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[4]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[5]);
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "matmul_f64") and args.len >= 6) {
            self.p("duo_simd_matmul_f64((const double*)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (const double*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (double*)(", .{});
            try self.emit_expr(args[2]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[3]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[4]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[5]);
            self.p("))", .{});
            return true;
        }
        return false;
    }

    /// True when `e` is the `tonumber(s) or fallback` form that
    /// `try_emit_native_tonumber_or` lowers to a native strtod statement
    /// expression. Callers must not wrap such an expression in `lua_to_num()`:
    /// it already yields a `double`, and the full-native profile that selects
    /// this lowering never declares `lua_to_num`.
    fn expr_is_native_tonumber_or(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .binop) return false;
        const b = e.binop;
        if (b.op != .@"or" or self.moduleNeedsLuaRuntime()) return false;
        if (b.lhs.* != .call or b.lhs.call.func.* != .name) return false;
        if (!std.mem.eql(u8, b.lhs.call.func.name.ident, "tonumber")) return false;
        if (b.lhs.call.args.len != 1 or self.expr_type(b.lhs.call.args[0]) != .str) return false;
        return true;
    }

    fn try_emit_native_tonumber_or(self: *CodeGen, b: anytype) E!bool {
        if (b.op != .@"or" or self.moduleNeedsLuaRuntime()) return false;
        if (b.lhs.* != .call or b.lhs.call.func.* != .name) return false;
        if (!std.mem.eql(u8, b.lhs.call.func.name.ident, "tonumber")) return false;
        if (b.lhs.call.args.len != 1 or self.expr_type(b.lhs.call.args[0]) != .str) return false;
        self.p("({{ const char* _duo_s = ", .{});
        try self.emit_expr(b.lhs.call.args[0]);
        self.p("; char* _duo_ep; double _duo_v = strtod(_duo_s, &_duo_ep); (_duo_ep == _duo_s) ? (", .{});
        try self.emit_expr(b.rhs);
        self.p(") : _duo_v; }})", .{});
        return true;
    }

    fn try_emit_native_string_transform(self: *CodeGen, fname: []const u8, obj: *ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        if (result_rt != .str) return false;
        if (std.mem.eql(u8, fname, "lower") or std.mem.eql(u8, fname, "upper") or std.mem.eql(u8, fname, "reverse")) {
            if (args.len != 0) return false;
            self.p("duo_str_{s}_cstr(", .{fname});
            try self.emit_mem_value_as(obj, .str);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "sub")) {
            if (args.len == 0 or args.len > 2) return false;
            self.p("duo_str_sub_cstr(", .{});
            try self.emit_mem_value_as(obj, .str);
            self.p(", ", .{});
            self.p("(int64_t)(", .{});
            try self.emit_mem_value_as(args[0], .i64);
            self.p(")", .{});
            if (args.len > 1) {
                self.p(", ", .{});
                self.p("(int64_t)(", .{});
                try self.emit_mem_value_as(args[1], .i64);
                self.p(")", .{});
            } else {
                self.p(", INT64_MAX", .{});
            }
            self.p(")", .{});
            return true;
        }
        return false;
    }

    fn try_emit_native_string_call(self: *CodeGen, fname: []const u8, args: []*ast.Expr, result_rt: RT) E!bool {
        if (std.mem.eql(u8, fname, "len")) {
            if (args.len == 0) return false;
            if (args[0].* == .string_lit) {
                self.p("{d}", .{args[0].string_lit.val.len});
                return true;
            }
            if (self.expr_type(args[0]) == .str) {
                // Boxed strings (lua_to_str(...) of a boxed value or a recognized
                // stdlib string call) carry a lua_String header whose len
                // duo_str_len_hdr reads directly. Plain native strings (concat
                // results, params, native calls, literals) are NOT lua_String-
                // backed — reading the header reads garbage, so use strlen.
                const is_boxed = self.expr_is_boxed_string_ptr(args[0]);
                if (result_rt.is_numeric()) {
                    var buf: [64]u8 = undefined;
                    self.p("(({s}){s}(", .{ result_rt.c_type(&buf), if (is_boxed) "duo_str_len_hdr" else "strlen" });
                } else {
                    self.p("((int64_t){s}(", .{if (is_boxed) "duo_str_len_hdr" else "strlen"});
                }
                try self.emit_expr(args[0]);
                self.p("))", .{});
                return true;
            }
            if (result_rt.is_integer()) {
                var buf: [64]u8 = undefined;
                self.p("(({s})lua_str_byte_len(", .{result_rt.c_type(&buf)});
                try self.emit_as_lua_value(args[0]);
                self.p("))", .{});
                return true;
            }
            return false;
        }
        if (std.mem.eql(u8, fname, "byte")) {
            if (args.len < 2) return false;
            if (args[0].* == .string_lit and args[1].* == .int_lit) {
                const s = args[0].string_lit.val;
                const idx = args[1].int_lit.val;
                if (idx >= 1 and idx <= @as(i64, @intCast(s.len)))
                    self.p("{d}", .{@as(i64, s[@intCast(idx - 1)])})
                else
                    self.p("0", .{});
                return true;
            }
            if (self.expr_type(args[0]) == .str and self.expr_type(args[1]).is_integer()) {
                var buf: [64]u8 = undefined;
                const cast_rt = if (result_rt.is_numeric()) result_rt else RT.i64;
                self.p("(({s})(unsigned char)(", .{cast_rt.c_type(&buf)});
                try self.emit_expr(args[0]);
                self.p("[", .{});
                try self.emit_expr(args[1]);
                self.p(" - 1]))", .{});
                return true;
            }
            if (result_rt.is_integer()) {
                var buf: [64]u8 = undefined;
                self.p("(({s})", .{result_rt.c_type(&buf)});
                self.p("lua_str_byte_i64(", .{});
                try self.emit_as_lua_value(args[0]);
                self.p(", ", .{});
                try self.emit_as_lua_value(args[1]);
                self.p(", ", .{});
                if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
                self.p("))", .{});
                return true;
            }
            return false;
        }
        if ((std.mem.eql(u8, fname, "starts_with") or std.mem.eql(u8, fname, "ends_with")) and
            result_rt == .bool and args.len == 2)
        {
            return try self.try_emit_native_string_affix(fname, args[0], args[1]);
        }
        if (std.mem.eql(u8, fname, "rep") and result_rt == .str) {
            if (args.len < 2 or args.len > 3) return false;
            const pat_t = self.expr_type(args[0]);
            const cnt_t = self.expr_type(args[1]);
            if ((pat_t == .str or args[0].* == .string_lit) and cnt_t.is_integer()) {
                self.p("duo_str_rep(", .{});
                try self.emit_expr(args[0]);
                self.p(", ", .{});
                try self.emit_expr(args[1]);
                self.p(")", .{});
                return true;
            }
            return false;
        }
        if (args.len > 0) {
            if (try self.try_emit_native_string_transform(fname, args[0], args[1..], result_rt)) return true;
        }
        return false;
    }

    fn utf8_literal_len(s: []const u8) i64 {
        var len: i64 = 0;
        for (s) |c| {
            if ((c & 0xC0) != 0x80) len += 1;
        }
        return len;
    }

    fn try_emit_native_utf8_len(self: *CodeGen, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_integer() or args.len != 1) return false;
        if (args[0].* == .string_lit) {
            self.p("{d}", .{utf8_literal_len(args[0].string_lit.val)});
            return true;
        }
        if (self.expr_type(args[0]) == .str) {
            self.p("({{ const unsigned char* _duo_s = (const unsigned char*)(", .{});
            try self.emit_expr(args[0]);
            self.p("); int64_t _duo_len = 0; while (*_duo_s) {{ if ((*_duo_s & 0xC0) != 0x80) _duo_len++; _duo_s++; }} _duo_len; }})", .{});
            return true;
        }
        return false;
    }

    fn try_emit_native_string_affix(self: *CodeGen, fname: []const u8, s_expr: *const ast.Expr, part_expr: *const ast.Expr) E!bool {
        if (!self.expr_is_native_cstr(s_expr) or !self.expr_is_native_cstr(part_expr)) return false;
        const is_suffix = std.mem.eql(u8, fname, "ends_with");
        if (!is_suffix and !std.mem.eql(u8, fname, "starts_with")) return false;

        self.p("({{ const char* _duo_s = ", .{});
        try self.emit_expr(s_expr);
        self.p("; const char* _duo_part = ", .{});
        try self.emit_expr(part_expr);
        self.p("; size_t _duo_slen = strlen(_duo_s); size_t _duo_plen = strlen(_duo_part); _duo_plen <= _duo_slen && memcmp(", .{});
        if (is_suffix) {
            self.p("_duo_s + _duo_slen - _duo_plen", .{});
        } else {
            self.p("_duo_s", .{});
        }
        self.p(", _duo_part, _duo_plen) == 0; }})", .{});
        return true;
    }

    fn emit_lua_result_coerce_prefix(self: *CodeGen, result_rt: RT) bool {
        switch (result_rt) {
            .str => {
                self.p("lua_to_str(", .{});
                return true;
            },
            .bool => {
                self.p("lua_to_bool(", .{});
                return true;
            },
            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64, .f32, .f64 => {
                var buf: [64]u8 = undefined;
                self.p("(({s})lua_to_num(", .{result_rt.c_type(&buf)});
                return true;
            },
            else => return false,
        }
    }

    fn emit_lua_result_coerce_suffix(self: *CodeGen, result_rt: RT) void {
        switch (result_rt) {
            .str, .bool => self.p(")", .{}),
            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64, .f32, .f64 => self.p("))", .{}),
            else => {},
