    }

    fn emit_boxed_runtime_call(self: *CodeGen, mapped: []const u8, args: []*ast.Expr, expected: usize, result_rt: RT) E!void {
        const coerced = self.emit_lua_result_coerce_prefix(result_rt);
        self.p("{s}(", .{mapped});
        var i: usize = 0;
        while (i < expected) : (i += 1) {
            if (i > 0) self.p(", ", .{});
            if (i < args.len) {
                try self.emit_as_lua_value(args[i]);
            } else {
                self.p("lua_val_nil()", .{});
            }
        }
        self.p(")", .{});
        if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
    }

    fn expr_is_dynamic_table_field(self: *CodeGen, e: *const ast.Expr) bool {
        return e.* == .field and self.expr_is_dynamic_table(e.field.obj);
    }

    fn try_emit_native_net_send(self: *CodeGen, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_integer() or args.len != 2) return false;
        if (!self.expr_type(args[0]).is_integer()) return false;
        if (self.expr_is_dynamic_table_field(args[0])) return false;
        if (!self.expr_is_native_cstr(args[1])) return false;

        self.p("((int64_t)send((int)(", .{});
        try self.emit_expr(args[0]);
        self.p("), ", .{});
        try self.emit_expr(args[1]);
        self.p(", ", .{});
        if (args[1].* == .string_lit) {
            self.p("{d}", .{args[1].string_lit.val.len});
        } else {
            self.p("strlen(", .{});
            try self.emit_expr(args[1]);
            self.p(")", .{});
        }
        self.p(", 0))", .{});
        return true;
    }

    fn try_emit_native_net_close(self: *CodeGen, args: []*ast.Expr) E!bool {
        if (args.len != 1 or !self.expr_type(args[0]).is_integer()) return false;
        if (self.expr_is_dynamic_table_field(args[0])) return false;
        self.p("close((int)(", .{});
        try self.emit_expr(args[0]);
        self.p("))", .{});
        return true;
    }

    fn try_emit_native_net_udp_sendto(self: *CodeGen, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_integer() or args.len != 4) return false;
        if (!self.expr_type(args[0]).is_integer()) return false;
        if (self.expr_is_dynamic_table_field(args[0])) return false;
        if (!self.expr_is_native_cstr(args[1])) return false;
        if (!self.expr_is_native_cstr(args[2])) return false;
        if (!self.expr_type(args[3]).is_integer()) return false;

        self.p("duo_net_udp_sendto_native((int64_t)(", .{});
        try self.emit_expr(args[0]);
        self.p("), ", .{});
        try self.emit_expr(args[1]);
        self.p(", ", .{});
        if (args[1].* == .string_lit) {
            self.p("{d}", .{args[1].string_lit.val.len});
        } else {
            self.p("strlen(", .{});
            try self.emit_expr(args[1]);
            self.p(")", .{});
        }
        self.p(", ", .{});
        try self.emit_expr(args[2]);
        self.p(", (int64_t)(", .{});
        try self.emit_expr(args[3]);
        self.p("))", .{});
        return true;
    }

    fn try_emit_math_fast_call(self: *CodeGen, fname: []const u8, args: []*ast.Expr, result_rt: RT) E!bool {
        var buf: [64]u8 = undefined;
        const ct = result_rt.c_type(&buf);

        if (std.mem.eql(u8, fname, "fast_popcount") and args.len == 1) {
            self.p("((int64_t)__builtin_popcountll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_clz") and args.len == 1) {
            self.p("((", .{});
            self.p("{s}", .{ct});
            self.p(")(", .{});
            try self.emit_expr(args[0]);
            self.p(") == 0 ? 64 : (int64_t)__builtin_clzll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_ctz") and args.len == 1) {
            self.p("((", .{});
            self.p("{s}", .{ct});
            self.p(")(", .{});
            try self.emit_expr(args[0]);
            self.p(") == 0 ? 64 : (int64_t)__builtin_ctzll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_bit_length") and args.len == 1) {
            self.p("((", .{});
            self.p("{s}", .{ct});
            self.p(")(", .{});
            try self.emit_expr(args[0]);
            self.p(") == 0 ? 0 : 64 - (int64_t)__builtin_clzll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_rotl") and args.len == 2) {
            self.p("((int64_t)__builtin_rotateleft64((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (unsigned)(", .{});
            try self.emit_expr(args[1]);
            self.p(") & 63))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_rotr") and args.len == 2) {
            self.p("((int64_t)__builtin_rotateright64((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (unsigned)(", .{});
            try self.emit_expr(args[1]);
            self.p(") & 63))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_min") and args.len == 2) {
            self.p("lua_imin_i64(", .{});
            try self.emit_expr(args[0]);
            self.p(", ", .{});
            try self.emit_expr(args[1]);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_max") and args.len == 2) {
            self.p("lua_imax_i64(", .{});
            try self.emit_expr(args[0]);
            self.p(", ", .{});
            try self.emit_expr(args[1]);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_abs") and args.len == 1) {
            self.p("lua_iabs_i64(", .{});
            try self.emit_expr(args[0]);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_gcd") and args.len == 2) {
            self.p("duo_gcd_i64(", .{});
            try self.emit_expr(args[0]);
            self.p(", ", .{});
            try self.emit_expr(args[1]);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_is_pow2") and args.len == 1 and result_rt == .bool) {
            self.p("((", .{});
            try self.emit_expr(args[0]);
            self.p(") > 0 && ((", .{});
            try self.emit_expr(args[0]);
            self.p(") & (", .{});
            try self.emit_expr(args[0]);
            self.p(" - 1)) == 0)", .{});
            return true;
        }
        return false;
    }

    fn maybe_emit_stdlib_module_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        if (func.* != .field) return false;
        const f = &func.field;

        // 1. Handle nested string.buffer.new() and std.math.fast.*
        if (f.obj.* == .field) {
            const inner = &f.obj.field;
            if (inner.obj.* == .field) {
                const mid = &inner.obj.field;
                if (mid.obj.* == .name and std.mem.eql(u8, mid.obj.name.ident, "std") and
                    std.mem.eql(u8, mid.field, "math") and std.mem.eql(u8, inner.field, "fast"))
                {
                    if (try self.try_emit_math_fast_call(f.field, args, result_rt)) return true;
                }
            }
            if (inner.obj.* == .name and std.mem.eql(u8, inner.obj.name.ident, "string") and std.mem.eql(u8, inner.field, "buffer")) {
                if (std.mem.eql(u8, f.field, "new")) {
                    if (args.len > 0) {
                        self.p("lua_str_buf_new_init(", .{});
                        try self.emit_as_lua_value(args[0]);
                        self.p(")", .{});
                    } else {
                        self.p("lua_str_buf_new()", .{});
                    }
                    return true;
                }
            }
            // 2. Handle std.xxx.yyy() — Duo standard library submodules
            if (inner.obj.* == .name and std.mem.eql(u8, inner.obj.name.ident, "std")) {
                const submod = inner.field;
                const fnname = f.field;
                // std.mem functions
                if (std.mem.eql(u8, submod, "mem")) {
                    if (std.mem.eql(u8, fnname, "page_size")) {
                        self.p("4096", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "arena_new") or std.mem.eql(u8, fnname, "arena")) {
                        // Real arena allocator: bump-pointer, zero malloc overhead
                        if (args.len >= 1) {
                            self.p("duo_arena_new(", .{});
                            try self.emit_expr(args[0]);
                            self.p(")", .{});
                        } else {
                            self.p("duo_arena_new(1048576)", .{}); // 1MB default
                        }
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "arena_alloc")) {
                        // Bump-allocate from arena: O(1), no free needed
                        self.p("duo_arena_alloc(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p(", ", .{});
                        if (args.len >= 2) try self.emit_expr(args[1]);
                        self.p(")", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "arena_reset")) {
                        // Reset arena to beginning: O(1), free all at once
                        self.p("duo_arena_reset(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p(")", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "arena_free")) {
                        self.p("duo_arena_free(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p(")", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "pool_new")) {
                        self.p("duo_pool_new(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]) else self.p("64", .{});
                        self.p(", ", .{});
                        if (args.len >= 2) try self.emit_expr(args[1]) else self.p("4096", .{});
                        self.p(")", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "pool_get")) {
                        self.p("duo_pool_get(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p(")", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "pool_put")) {
                        self.p("duo_pool_put(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p(", ", .{});
                        if (args.len >= 2) try self.emit_expr(args[1]);
                        self.p(")", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "prefetch")) {
                        // CPU cache prefetch hint
                        self.p("__builtin_prefetch((void*)(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p("), 0, 3)", .{}); // read, highest locality
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "prefetch_write")) {
                        self.p("__builtin_prefetch((void*)(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p("), 1, 3)", .{}); // write, highest locality
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "likely")) {
                        self.p("__builtin_expect(!!(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p("), 1)", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "unlikely")) {
                        self.p("__builtin_expect(!!(", .{});
                        if (args.len >= 1) try self.emit_expr(args[0]);
                        self.p("), 0)", .{});
                        return true;
                    }
                    if (std.mem.eql(u8, fnname, "stack_new")) {
                        self.p("duo_arena_new(65536)", .{}); // stack = small arena
                        return true;
                    }
                }
                // std.meta functions — fall through to lua_invoke for now
                // std.wasm.wasi functions — fall through to lua_invoke for now
            }
