    fn binop_str(op: ast.BinOp) []const u8 {
        return switch (op) {
            .add => "+",
            .sub => "-",
            .mul => "*",
            .div => "/",
            .idiv => "/", // integer division — both operands should be integer
            .mod => "%",
            .pow => "/* ^ */", // handled via pow()
            .band => "&",
            .bor => "|",
            .bxor => "^",
            .lshift => "<<",
            .rshift => ">>",
            .concat => "/* .. */",
            .eq => "==",
            .neq => "!=",
            .lt => "<",
            .gt => ">",
            .leq => "<=",
            .geq => ">=",
            .@"and" => "&&",
            .@"or" => "||",
            .contains => "/* in */",
            .matmul => "/* @ */",
            .pipeline => "/* |> */",
        };
    }

    // ── Closures & require ────────────────────────────────────────────────────

    fn collect_closures_expr(self: *CodeGen, expr: *const ast.Expr, list: *std.ArrayList(*ast.FuncBody)) std.mem.Allocator.Error!void {
        switch (expr.*) {
            .func_expr => |fb| {
                if (fb.closure_id) |id| {
                    if (self.emitted_closures.contains(id)) return;
                    try self.emitted_closures.put(self.alloc, id, {});
                    try list.append(self.alloc, fb);
                }
                try self.collect_closures_block(&fb.body, list);
            },
            .binop => |b| {
                try self.collect_closures_expr(b.lhs, list);
                try self.collect_closures_expr(b.rhs, list);
            },
            .unop => |u| try self.collect_closures_expr(u.operand, list),
            .call => |c| {
                try self.collect_closures_expr(c.func, list);
                for (c.args) |a| try self.collect_closures_expr(a, list);
            },
            .method_call => |mc| {
                try self.collect_closures_expr(mc.obj, list);
                for (mc.args) |a| try self.collect_closures_expr(a, list);
            },
            .field => |f| try self.collect_closures_expr(f.obj, list),
            .index => |idx| {
                try self.collect_closures_expr(idx.obj, list);
                try self.collect_closures_expr(idx.key, list);
            },
            .table => |t| {
                for (t.fields) |fld| {
                    switch (fld) {
                        .indexed => |idx| {
                            try self.collect_closures_expr(idx.key, list);
                            try self.collect_closures_expr(idx.val, list);
                        },
                        .named => |nmd| try self.collect_closures_expr(nmd.val, list),
                        .positional => |pos| try self.collect_closures_expr(pos, list),
                        .spread => |sp| try self.collect_closures_expr(sp, list),
                        // Pass 36 G1/G8 recorded, not implemented (Phase 0): walk the implementation only.
                        .semantic => |sm| try self.collect_closures_expr(sm.val, list),
                    }
                }
            },
            .sequence => |seq| {
                for (seq.exprs) |e| try self.collect_closures_expr(e, list);
            },
            else => {},
        }
    }

    fn collect_closures_block(self: *CodeGen, block: *const ast.Block, list: *std.ArrayList(*ast.FuncBody)) std.mem.Allocator.Error!void {
        for (block.stmts) |*stmt| try self.collect_closures_stmt(stmt, list);
        // Closures in the implicit return (tail expression) of a block are
        // missed by the stmt loop above. Ward's test suite hits this: the last
        // test.it(...) call in a test.group(...) closure is the tail expression.
        if (block.tail_expr) |expr| try self.collect_closures_expr(expr, list);
    }

    fn collect_closures_stmt(self: *CodeGen, stmt: *const ast.Stmt, list: *std.ArrayList(*ast.FuncBody)) std.mem.Allocator.Error!void {
        switch (stmt.*) {
            .local_decl => |*ld| for (ld.inits) |e| try self.collect_closures_expr(e, list),
            .const_decl => |*cd| try self.collect_closures_expr(cd.val, list),
            .assign => |*as| for (as.values) |v| try self.collect_closures_expr(v, list),
            .ret => |*r| for (r.vals) |v| try self.collect_closures_expr(v, list),
            .if_stmt => |*is| {
                try self.collect_closures_expr(is.cond, list);
                try self.collect_closures_block(&is.then, list);
                for (is.elseifs) |*ei| {
                    try self.collect_closures_expr(ei.cond, list);
                    try self.collect_closures_block(&ei.body, list);
                }
                if (is.else_body) |*eb| try self.collect_closures_block(eb, list);
            },
            .while_loop => |*wl| {
                try self.collect_closures_expr(wl.cond, list);
                try self.collect_closures_block(&wl.body, list);
            },
            .repeat_loop => |*rl| {
                try self.collect_closures_block(&rl.body, list);
                try self.collect_closures_expr(rl.cond, list);
            },
            .num_for => |*nf| try self.collect_closures_block(&nf.body, list),
            .gen_for => |*gf| {
                for (gf.iters) |e| try self.collect_closures_expr(e, list);
                try self.collect_closures_block(&gf.body, list);
            },
            .call_stmt => |*cs| try self.collect_closures_expr(cs.expr, list),
            .expr_stmt => |*es| try self.collect_closures_expr(es.expr, list),
            .do_block => |*db| try self.collect_closures_block(&db.body, list),
            .func_decl => |*fd| try self.collect_closures_block(&fd.func.body, list),
            else => {},
        }
    }

    fn collect_closures_module(self: *CodeGen, mod: *const ast.Module, list: *std.ArrayList(*ast.FuncBody)) !void {
        try self.collect_closures_block(&mod.body, list);
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                try self.collect_closures_block(&stmt.func_decl.func.body, list);
            }
        }
    }

    fn collect_local_funcs_block(self: *CodeGen, block: *const ast.Block, list: *std.ArrayList(*ast.FuncDecl)) std.mem.Allocator.Error!void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .func_decl => |*fd| {
                    // In duo_mode, single-name bare functions are effectively local
                    const effectively_local = fd.is_local or (self.duo_mode and fd.path.len == 1 and !fd.method);
                    if (effectively_local) try list.append(self.alloc, fd);
                    // Do NOT recurse into function bodies — nested local functions
                    // will be emitted when their parent's body is processed.
                },
                .if_stmt => |*is| {
                    try self.collect_local_funcs_block(&is.then, list);
                    for (is.elseifs) |*ei| try self.collect_local_funcs_block(&ei.body, list);
                    if (is.else_body) |*eb| try self.collect_local_funcs_block(eb, list);
                },
                .while_loop => |*wl| try self.collect_local_funcs_block(&wl.body, list),
                .repeat_loop => |*rl| try self.collect_local_funcs_block(&rl.body, list),
                .num_for => |*nf| try self.collect_local_funcs_block(&nf.body, list),
                .gen_for => |*gf| try self.collect_local_funcs_block(&gf.body, list),
                .do_block => |*db| try self.collect_local_funcs_block(&db.body, list),
                else => {},
            }
        }
    }

    fn collect_local_funcs_module(self: *CodeGen, mod: *const ast.Module, list: *std.ArrayList(*ast.FuncDecl)) std.mem.Allocator.Error!void {
        try self.collect_local_funcs_block(&mod.body, list);
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                try self.collect_local_funcs_block(&stmt.func_decl.func.body, list);
            }
        }
    }

    fn emit_closure_structs(self: *CodeGen, list: []const *ast.FuncBody) E!void {
        for (list) |fb| {
            const id = fb.closure_id orelse continue;
            if (self.emitted_closure_structs.contains(id)) continue;
            try self.emitted_closure_structs.put(self.alloc, id, {});
            self.p("typedef struct {{\n", .{});
            self.p("    duo_ObjHeader header;\n", .{});
            self.p("    int id;\n", .{});
            self.p("    int nup;\n", .{});
            var buf: [256]u8 = undefined;
            for (fb.upvalues, 0..) |up, i| {
                if (upvalue_uses_pointer(up)) {
                    // Mutable upvalue: store pointer to shared cell
                    self.p("    lua_Value* up{d};\n", .{i});
                } else if (up.typ) |t| {
                    if (t == .func) {
                        self.p("    lua_Value up{d};\n", .{i});
                    } else {
                        self.p("    {s} up{d};\n", .{ t.c_type(&buf), i });
                    }
                } else {
                    self.p("    lua_Value up{d};\n", .{i});
                }
            }
            self.p("}} duo_closure_{d};\n\n", .{id});

            self.p("static inline duo_closure_{d}* duo_make_closure_{d}(", .{ id, id });
            for (fb.upvalues, 0..) |up, i| {
                if (i > 0) self.p(", ", .{});
                if (upvalue_uses_pointer(up)) {
                    self.p("lua_Value* up{d}", .{i});
                } else if (up.typ) |t| {
                    if (t == .func) {
                        self.p("lua_Value up{d}", .{i});
                    } else {
                        self.p("{s} up{d}", .{ t.c_type(&buf), i });
                    }
                } else {
                    self.p("lua_Value up{d}", .{i});
                }
            }
            self.p(") {{\n", .{});
            if (self.current_func_noalloc) try self.guardNoAlloc("closure.malloc");
            self.p("    duo_closure_{d}* cl = (duo_closure_{d}*)malloc(sizeof(duo_closure_{d}));\n", .{ id, id, id });
            self.p("    cl->header.refcount = 1;\n", .{});
            self.p("    cl->header.type_tag = VAL_CLOSURE;\n", .{});
            self.p("    cl->id = {d};\n", .{id});
            self.p("    cl->nup = {d};\n", .{fb.upvalues.len});
            for (fb.upvalues, 0..) |up, i| {
                self.p("    cl->up{d} = up{d};\n", .{ i, i });
                if (up.typ) |t| {
                    if (t != .func and self.codegen_needs_arc(t)) {
                        self.p("    duo_retain((void*)cl->up{d});\n", .{i});
                    }
                }
            }
            self.p("    return cl;\n", .{});
            self.p("}}\n\n", .{});

            self.p("static void duo_free_closure_{d}(duo_closure_{d}* cl) {{\n", .{ id, id });
            for (fb.upvalues, 0..) |up, i| {
                if (up.typ) |t| {
                    if (t != .func and self.codegen_needs_arc(t)) {
                        self.p("    duo_release((void*)cl->up{d});\n", .{i});
                    }
                }
            }
            self.p("    free(cl);\n", .{});
            self.p("}}\n\n", .{});

            self.p("static lua_Value duo_cl_{d}(lua_Closure* cl, int argc, lua_Value* argv);\n", .{id});
        }
    }

    fn emit_closure_runtime(self: *CodeGen, list: []const *ast.FuncBody) E!void {
        if (list.len == 0) {
            try jit.emitInvokeWrapperPrologue(self);
            self.p("    (void)id; (void)cl; (void)argc; (void)argv;\n", .{});
            self.p("    return lua_val_nil();\n", .{});
            try jit.emitInvokeWrapperEpilogue(self);
            self.p("void duo_free_closure(lua_Closure* cl) {{\n", .{});
            self.p("    (void)cl;\n", .{});
            self.p("}}\n\n", .{});
            return;
        }

        try jit.emitInvokeWrapperPrologue(self);
        for (list) |fb| {
            if (fb.closure_id) |id| {
                self.p("        case {d}: return duo_cl_{d}(cl, argc, argv);\n", .{ id, id });
            }
        }
        try jit.emitInvokeWrapperEpilogue(self);

        self.p("void duo_free_closure(lua_Closure* cl) {{\n", .{});
        self.p("    switch (cl->id) {{\n", .{});
        for (list) |fb| {
            if (fb.closure_id) |id| {
                self.p("        case {d}: duo_free_closure_{d}((duo_closure_{d}*)cl); return;\n", .{ id, id, id });
            }
        }
        self.p("        default: free(cl); return;\n", .{});
        self.p("    }}\n", .{});
        self.p("}}\n\n", .{});

        for (list) |fb| {
            const id = fb.closure_id orelse continue;
            self.p("static lua_Value duo_cl_{d}(lua_Closure* cl_raw, int argc, lua_Value* argv) {{\n", .{id});
            self.indent = 1;
            self.pl("duo_closure_{d}* cl = (duo_closure_{d}*)cl_raw;", .{ id, id });
            const prev_ret = self.current_ret;
            const prev_ctx = self.closure_ctx;
            const prev_dense = self.dense_table;
            const prev_dense_cap = self.dense_table_cap;
            self.current_ret = .any;
            self.closure_ctx = fb;
            self.dense_table = null;
            self.dense_table_cap = null;
            for (fb.params, 0..) |par, i| {
                const pt = types.resolve(par.typ, null, self.alloc) catch .any;
                if (pt == .any) {
                    self.pl("lua_Value {s} = argc > {d} ? argv[{d}] : lua_val_nil();", .{ par.name, i, i });
                } else if (pt.is_integer()) {
                    var pbuf: [64]u8 = undefined;
                    const pct = pt.c_type(&pbuf);
                    self.pl("{s} {s} = ({s})lua_to_num(argc > {d} ? argv[{d}] : lua_val_nil());", .{ pct, par.name, pct, i, i });
                } else if (pt.is_float()) {
                    var pbuf: [64]u8 = undefined;
                    const pct = pt.c_type(&pbuf);
                    self.pl("{s} {s} = ({s})lua_to_num(argc > {d} ? argv[{d}] : lua_val_nil());", .{ pct, par.name, pct, i, i });
                } else if (pt == .bool) {
                    self.pl("bool {s} = lua_to_bool(argc > {d} ? argv[{d}] : lua_val_nil());", .{ par.name, i, i });
                } else if (pt == .str) {
                    self.pl("const char* {s} = lua_to_str(argc > {d} ? argv[{d}] : lua_val_nil());", .{ par.name, i, i });
                } else {
                    self.pl("lua_Value {s} = argc > {d} ? argv[{d}] : lua_val_nil();", .{ par.name, i, i });
                }
            }
            if (fb.vararg) {
                const vn = fb.vararg_name orelse "__varargs";
                self.pl("lua_Value {s} = lua_tbl_pack_argv(argc - {d}, argv + {d});", .{ vn, fb.params.len, fb.params.len });
            }
            try self.emit_returning_block(&fb.body);
            if (!self.block_fallthrough_returns(&fb.body)) {
                self.pl("return lua_val_nil();", .{});
            }
            self.indent = 0;
            self.current_ret = prev_ret;
            self.closure_ctx = prev_ctx;
            self.dense_table = prev_dense;
            self.dense_table_cap = prev_dense_cap;
            self.p("}}\n\n", .{});
        }
    }

    fn block_fallthrough_returns(self: *CodeGen, blk: *const ast.Block) bool {
        if (blk.tail_expr != null) return true;
        var i = blk.stmts.len;
        while (i > 0) {
            i -= 1;
            if (self.stmt_fallthrough_returns(&blk.stmts[i])) return true;
            switch (blk.stmts[i]) {
                .while_loop, .repeat_loop, .num_for, .gen_for => return false,
                else => {},
            }
        }
        return false;
    }

    fn stmt_fallthrough_returns(self: *CodeGen, stmt: *const ast.Stmt) bool {
        return switch (stmt.*) {
            .ret => true,
            // Pass 23 §4 — final assignment returns its value (including compound assign).
            .assign => |as| as.targets.len == 1 and as.values.len == 1,
            .if_stmt => |*is| blk: {
                if (is.else_body == null) break :blk false;
                if (!self.block_fallthrough_returns(&is.then)) break :blk false;
                for (is.elseifs) |*ei| {
                    if (!self.block_fallthrough_returns(&ei.body)) break :blk false;
                }
                if (is.else_body) |*eb| break :blk self.block_fallthrough_returns(eb);
                break :blk false;
            },
            else => false,
        };
    }

    fn collect_require_names(self: *CodeGen, expr: *const ast.Expr, names: *std.ArrayList([]const u8)) std.mem.Allocator.Error!void {
        switch (expr.*) {
            .call => |c| {
                if (c.func.* == .name and
                    (std.mem.eql(u8, c.func.name.ident, "require") or std.mem.eql(u8, c.func.name.ident, "req")) and
                    c.args.len == 1 and c.args[0].* == .string_lit)
                {
                    try names.append(self.alloc, c.args[0].string_lit.val);
                }
                if (self.ml_intrinsic_name(c.func) != null) {
                    return;
                }
                if (self.mem_intrinsic_name(c.func) != null) {
                    for (c.args) |a| try self.collect_require_names(a, names);
                    return;
                }
                if (self.atomic_intrinsic_name(c.func) != null) {
                    for (c.args) |a| try self.collect_require_names(a, names);
                    return;
                }
                try self.collect_require_names(c.func, names);
                for (c.args) |a| try self.collect_require_names(a, names);
            },
            .binop => |b| {
                try self.collect_require_names(b.lhs, names);
                try self.collect_require_names(b.rhs, names);
            },
            .unop => |u| try self.collect_require_names(u.operand, names),
            .method_call => |mc| {
                try self.collect_require_names(mc.obj, names);
                for (mc.args) |a| try self.collect_require_names(a, names);
            },
            .field => |f| {
                if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "std")) {
                    var buf: [256]u8 = undefined;
                    const mod_name = std.fmt.bufPrint(&buf, "std.{s}", .{f.field}) catch unreachable;
                    try names.append(self.alloc, try self.alloc.dupe(u8, mod_name));
                    try names.append(self.alloc, try self.alloc.dupe(u8, "std"));
                } else if (f.obj.* == .field) {
                    // A nested ambient path names a module at a depth the
                    // two-level case above cannot see: `std.net.url` lives one
                    // hop below `std.net`. Offer the whole dotted path at every
                    // hop and let module resolution keep the one that names a
                    // real file — an unresolvable name is skipped downstream.
                    var dbuf: [512]u8 = undefined;
                    if (ambient_dotted_path(expr, &dbuf)) |dotted| {
                        if (std.mem.startsWith(u8, dotted, "std.")) {
                            try names.append(self.alloc, try self.alloc.dupe(u8, dotted));
                        }
                    }
                }
                try self.collect_require_names(f.obj, names);
            },
            .index => |idx| {
                try self.collect_require_names(idx.obj, names);
                try self.collect_require_names(idx.key, names);
            },
            .table => |t| {
                for (t.fields) |fld| {
                    switch (fld) {
                        .indexed => |idx| {
                            try self.collect_require_names(idx.key, names);
                            try self.collect_require_names(idx.val, names);
                        },
                        .named => |nmd| try self.collect_require_names(nmd.val, names),
                        .positional => |pos| try self.collect_require_names(pos, names),
                        .spread => |sp| try self.collect_require_names(sp, names),
                        // Pass 36 G1/G8 recorded, not implemented (Phase 0): walk the implementation only.
                        .semantic => |sm| try self.collect_require_names(sm.val, names),
                    }
                }
            },
            .func_expr => |fb| try self.collect_require_names_block(&fb.body, names),
            .sequence => |seq| {
                for (seq.exprs) |e| try self.collect_require_names(e, names);
            },
            else => {},
        }
    }

    fn collect_require_names_block(self: *CodeGen, block: *const ast.Block, names: *std.ArrayList([]const u8)) std.mem.Allocator.Error!void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| for (ld.inits) |e| try self.collect_require_names(e, names),
                .global_decl => |*gd| for (gd.inits) |e| try self.collect_require_names(e, names),
                .assign => |*as| for (as.values) |v| try self.collect_require_names(v, names),
                .ret => |*r| for (r.vals) |v| try self.collect_require_names(v, names),
                .if_stmt => |*is| {
                    try self.collect_require_names(is.cond, names);
                    try self.collect_require_names_block(&is.then, names);
                    for (is.elseifs) |*ei| {
                        try self.collect_require_names(ei.cond, names);
                        try self.collect_require_names_block(&ei.body, names);
                    }
                    if (is.else_body) |*eb| try self.collect_require_names_block(eb, names);
                },
                .while_loop => |*wl| {
                    try self.collect_require_names(wl.cond, names);
                    try self.collect_require_names_block(&wl.body, names);
                },
                .repeat_loop => |*rl| {
                    try self.collect_require_names_block(&rl.body, names);
                    try self.collect_require_names(rl.cond, names);
                },
                .num_for => |*nf| try self.collect_require_names_block(&nf.body, names),
                .gen_for => |*gf| {
                    for (gf.iters) |e| try self.collect_require_names(e, names);
                    try self.collect_require_names_block(&gf.body, names);
                },
                .call_stmt => |*cs| try self.collect_require_names(cs.expr, names),
                .expr_stmt => |*es| try self.collect_require_names(es.expr, names),
                .do_block => |*db| try self.collect_require_names_block(&db.body, names),
                .func_decl => |*fd| try self.collect_require_names_block(&fd.func.body, names),
                else => {},
            }
        }
        // A block's trailing expression is NOT in `stmts`, so a program whose
        // only statement is a bare call (`print(std.json.encode(x))`) collected
        // nothing and the module was never registered. Every other walker in
        // this file already descends into `tail_expr`; this one did not.
        if (block.tail_expr) |tail| try self.collect_require_names(tail, names);
    }

    fn find_module_path(self: *CodeGen, base_dir: []const u8, mod_name: []const u8) ?[]const u8 {
        const templates = .{
            "{s}/{s}.duo",
            "{s}/{s}.lua",
            "{s}/{s}/init.duo",
            "{s}/{s}/init.lua",
        };
        const cwd = Io.Dir.cwd();
        inline for (templates) |tmpl| {
            const path = std.fmt.allocPrint(self.alloc, tmpl, .{ base_dir, mod_name }) catch return null;
            if (Io.Dir.access(cwd, self.io, path, .{})) |_| {
                return path;
            } else |_| {
                self.alloc.free(path);
            }
        }
        return null;
    }

    fn emit_required_modules(self: *CodeGen, mod: *const ast.Module) E!void {
        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.alloc);
        if (self.src_path.len > 0) {
            try self.collect_require_names_block(&mod.body, &names);
            for (mod.body.stmts) |*stmt| {
                if (stmt.* == .func_decl) {
                    try self.collect_require_names_block(&stmt.func_decl.func.body, &names);
                }
            }
        } else {
            self.p("static void duo_register_modules(void) {{\n", .{});
            self.p("}}\n\n", .{});
            return;
        }

        var seen: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen.deinit(self.alloc);
        const dir = if (self.src_path.len > 0) std.fs.path.dirname(self.src_path) orelse "." else ".";

        // Find the project root: the parent of the `src` directory that contains the source file.
        // This makes `req "src.foo"` resolve to `<project_root>/src/foo.duo` regardless of whether
        // the current source is `src/main.duo` or `src/wasm/init.duo`.
        const project_root = blk: {
            var d = dir;
            while (d.len > 0) {
                var pbuf: [1024]u8 = undefined;
                const path_to_check = std.fmt.bufPrint(&pbuf, "{s}/src", .{d}) catch break;
                const cwd = Io.Dir.cwd();
                var fd = Io.Dir.openDir(cwd, self.io, path_to_check, .{}) catch {
                    if (std.mem.eql(u8, d, ".")) break;
                    d = std.fs.path.dirname(d) orelse ".";
                    continue;
                };
                fd.close(self.io);
                break :blk d;
            }
            break :blk dir;
        };

        var embedded: std.ArrayList(struct { name: []const u8, cname: []const u8 }) = .empty;
        defer {
            for (embedded.items) |e| self.alloc.free(e.cname);
            embedded.deinit(self.alloc);
        }

        // If the source references the root `std` namespace (via `require "std"`
        // or a bare `std` value), build a lightweight runtime table that re-exports
        // only the std submodules that were actually requested.  This keeps std
        // inclusion lazy: unused std submodules are not parsed, typed, or emitted.
        const needs_std_root = blk: {
            for (names.items) |n| {
                if (std.mem.eql(u8, n, "std")) break :blk true;
            }
            break :blk false;
        };

        var i: usize = 0;
        while (i < names.items.len) : (i += 1) {
            const name = names.items[i];
            if (seen.contains(name)) continue;
            try seen.put(self.alloc, name, {});
            if (self.src_path.len == 0) continue;
            if (std.mem.eql(u8, name, "std")) continue;

            // Handle collection-style namespaces: vendor.xxx → vendor/xxx, std.core.xxx → lib/core/xxx
            const vendor_prefix = "vendor.";
            const core_prefix = "std.core.";
            const has_vendor = std.mem.startsWith(u8, name, vendor_prefix);
            const has_core = std.mem.startsWith(u8, name, core_prefix);
            const strip_len: usize = if (has_vendor) vendor_prefix.len else if (has_core) core_prefix.len else 0;
            const mod_path_name = if (strip_len > 0) blk: {
                const s = try self.alloc.dupe(u8, name[strip_len..]);
                for (s) |*c| {
                    if (c.* == '.') c.* = '/';
                }
                break :blk s;
            } else blk: {
                const s = try self.alloc.dupe(u8, name);
                for (s) |*c| {
                    if (c.* == '.') c.* = '/';
                }
                break :blk s;
            };
            defer self.alloc.free(mod_path_name);

            var mod_path: ?[]const u8 = null;
            if (self.find_module_path(project_root, mod_path_name)) |path| {
                mod_path = path;
            } else if (self.stdlib_root) |root| {
                mod_path = self.find_module_path(root, mod_path_name);
            }
            if (mod_path == null) {
                mod_path = self.find_module_path("lib", mod_path_name);
            }
            if (mod_path == null and has_vendor) {
                mod_path = self.find_module_path("vendor", mod_path_name);
            }
            if (mod_path == null and has_core) {
                mod_path = self.find_module_path("lib/core", mod_path_name);
            }

            if (mod_path == null) continue;
            defer self.alloc.free(mod_path.?);
            const prior_cname = self.embedded_module_paths.get(mod_path.?);
            const already_embedded = prior_cname != null;
            // Reuse the cname the file was emitted under, otherwise we register
            // a `duo_mod_*` symbol that was never defined.
            const cname = if (prior_cname) |pc| try self.alloc.dupe(u8, pc) else try self.module_c_name(name);
            if (!already_embedded) {
                if (!self.emit_embedded_module(cname, mod_path.?)) {
                    term.warn("failed to embed module '{s}' from {s}", .{ name, mod_path.? });
                    self.alloc.free(cname);
                    continue;
                }
            }
            try embedded.append(self.alloc, .{ .name = name, .cname = cname });
            // Recursively collect nested require names from the embedded module.
            // This must run even when the module was ALREADY embedded (pulled in
            // as some other module's dependency): emit_embedded_module records
            // the file but does not add its requires to this discovery worklist,
            // so skipping it here silently drops every module 3+ hops from the
            // entry point — they compile in but are never registered, and the
            // failure only surfaces at runtime as "module not found".
            {
                const sub_src = Io.Dir.readFileAlloc(Io.Dir.cwd(), self.io, mod_path.?, self.alloc, .unlimited) catch |e| {
                    term.err("emit_required_modules: re-read failed for {s}: {}", .{ mod_path.?, e });
                    continue;
                };
                defer self.alloc.free(sub_src);
                var sub_lex = @import("lexer.zig").Lexer.init(sub_src, mod_path.?);
                var sub_parser = @import("parser.zig").Parser.init(&sub_lex, self.alloc);
                sub_parser.duo_mode = std.mem.endsWith(u8, mod_path.?, ".duo");
                // The embed path must parse a `.duo` module in the same dialect the
                // standalone path uses. Without this, duo-mode-only syntax (bare
                // function declarations) parses fine when the file is compiled
                // directly but fails with "expected '<eof>', got 'end'" the moment it
                // is embedded — which is what stopped `std/script.duo` and
                // `std/mcp.duo` from embedding, and so kept the Duo MCP servers dead.
                sub_parser.duo_mode = std.mem.endsWith(u8, mod_path.?, ".duo");
                var sub_mod = sub_parser.parse_module() catch |e| {
                    term.err("emit_required_modules: re-parse failed for {s}: {}", .{ mod_path.?, e });
                    continue;
                };
                try self.collect_require_names_block(&sub_mod.body, &names);
                for (sub_mod.body.stmts) |*sub_stmt| {
                    if (sub_stmt.* == .func_decl) {
                        try self.collect_require_names_block(&sub_stmt.func_decl.func.body, &names);
                    }
                }
            }
        }

        var std_root_count: usize = 0;
        for (embedded.items) |e| {
            if (std.mem.startsWith(u8, e.name, "std.")) std_root_count += 1;
        }

        if (!self.moduleNeedsLuaRuntime()) return;

        // Forward-declare duo_build_std_root if needed (defined after duo_register_modules)
        if (needs_std_root) {
            self.p("static lua_Value duo_build_std_root(lua_Value _unused);\n", .{});
        }
        self.p("static void duo_register_modules(void) {{\n", .{});
        for (embedded.items) |e| {
            self.p("    lua_table_set_raw_lit(duo_modules, \"", .{});
            try self.emit_string_escaped(e.name);
            self.p("\", {d}, {d}, lua_val_from_func((lua_Value (*)(lua_Value))duo_mod_{s}));\n", .{ calc_lua_hash(e.name), e.name.len, e.cname });
        }
        if (needs_std_root) {
            self.p("    lua_table_set_raw_lit(duo_modules, \"std\", {d}, 3, lua_val_from_func((lua_Value (*)(lua_Value))duo_build_std_root));\n", .{calc_lua_hash("std")});
        }
        self.p("}}\n\n", .{});

        if (needs_std_root) {
            self.p("static lua_Value duo_build_std_root(lua_Value _unused) {{\n", .{});
            self.p("    (void)_unused;\n", .{});
            self.p("    lua_Value root = lua_table_new_with_capacity(0, {d});\n", .{std_root_count});
            for (embedded.items) |e| {
                if (std.mem.startsWith(u8, e.name, "std.")) {
                    const sub = e.name[4..];
                    self.p("    lua_table_set_raw_lit(root, \"", .{});
                    try self.emit_string_escaped(sub);
                    self.p("\", {d}, {d}, lua_require(lua_val_lit(\"", .{ calc_lua_hash(sub), sub.len });
                    try self.emit_string_escaped(e.name);
                    self.p("\")));\n", .{});
                }
            }
            self.p("    return root;\n", .{});
            self.p("}}\n\n", .{});
        }
    }

    fn module_c_name(self: *CodeGen, name: []const u8) std.mem.Allocator.Error![]u8 {
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(self.alloc);
        for (name) |c| {
            if (std.ascii.isAlphanumeric(c) or c == '_')
                try out.append(self.alloc, c)
            else
                try out.append(self.alloc, '_');
        }
        return out.toOwnedSlice(self.alloc);
    }

    fn req_path_from_expr(expr: *const ast.Expr) ?[]const u8 {
        if (expr.* != .call) return null;
        const c = &expr.call;
        if (c.func.* != .name) return null;
        const fn_name = c.func.name.ident;
        if (!std.mem.eql(u8, fn_name, "req") and !std.mem.eql(u8, fn_name, "require")) return null;
        if (c.args.len != 1 or c.args[0].* != .string_lit) return null;
        return c.args[0].string_lit.val;
    }

    /// True when `req("path")` / `require("path")` resolves to an embeddable native module.
    fn req_call_expr_is_native_direct(self: *CodeGen, expr: *const ast.Expr) bool {
        const path = req_path_from_expr(expr) orelse return false;
        return self.req_module_is_native_direct(path);
    }

    fn for_each_req_path_in_module(mod: *const ast.Module, ctx: *anyopaque, cb: *const fn (ctx: *anyopaque, path: []const u8) void) void {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| {
                    for (ld.inits) |init_expr| {
                        if (req_path_from_expr(init_expr)) |path| cb(ctx, path);
                    }
                },
                .assign => |*as| {
                    if (as.values.len == 1) {
                        if (req_path_from_expr(as.values[0])) |path| cb(ctx, path);
                    }
                },
                .global_decl => |*gd| {
                    for (gd.inits) |init_expr| {
                        if (req_path_from_expr(init_expr)) |path| cb(ctx, path);
                    }
                },
                else => {},
            }
        }
    }

    fn project_root_dir(self: *const CodeGen) []const u8 {
        if (self.src_path.len == 0) return ".";
        const dir = std.fs.path.dirname(self.src_path) orelse ".";
        var d = dir;
        while (d.len > 0) {
            var pbuf: [1024]u8 = undefined;
            const path_to_check = std.fmt.bufPrint(&pbuf, "{s}/src", .{d}) catch break;
            const cwd = Io.Dir.cwd();
            var fd = Io.Dir.openDir(cwd, self.io, path_to_check, .{}) catch {
                if (std.mem.eql(u8, d, ".")) break;
                d = std.fs.path.dirname(d) orelse ".";
                continue;
            };
            fd.close(self.io);
            return d;
        }
        return dir;
    }

    fn find_module_file_for_req(self: *CodeGen, req_name: []const u8) ?[]const u8 {
        const project_root = self.project_root_dir();
        const vendor_prefix = "vendor.";
        const core_prefix = "std.core.";
        const has_vendor = std.mem.startsWith(u8, req_name, vendor_prefix);
        const has_core = std.mem.startsWith(u8, req_name, core_prefix);
        const strip_len: usize = if (has_vendor) vendor_prefix.len else if (has_core) core_prefix.len else 0;
        const mod_path_name = blk: {
            const s = req_name[strip_len..];
            var buf: [512]u8 = undefined;
            if (s.len > buf.len) return null;
            for (s, 0..) |c, i| {
                buf[i] = if (c == '.') '/' else c;
            }
            break :blk buf[0..s.len];
        };

        if (self.find_module_path(project_root, mod_path_name)) |path| return path;
        if (self.stdlib_root) |root| {
            if (self.find_module_path(root, mod_path_name)) |path| return path;
        }
        if (self.find_module_path("lib", mod_path_name)) |path| return path;
        if (has_vendor) {
            if (self.find_module_path("vendor", mod_path_name)) |path| return path;
        }
        if (has_core) {
            if (self.find_module_path("lib/core", mod_path_name)) |path| return path;
        }
        return null;
    }

    /// True when `req "path"` resolves to a module already embedded for native-direct dispatch.
    fn embedded_req_is_native(self: *CodeGen, req_path: []const u8) bool {
        const mod_path = self.find_module_file_for_req(req_path) orelse return false;
        return self.embedded_module_paths.contains(mod_path);
    }

    /// True when a req target is a stdlib/user module that will embed to native C (compile-time).
    fn req_module_is_native_direct(self: *CodeGen, req_path: []const u8) bool {
        if (!self.duo_mode) return false;
        // If the module has already been embedded, trust how it was ACTUALLY
        // emitted rather than re-deciding. A table-exporting module is not
        // native-direct: its members live in a runtime lua table.
        if (self.find_module_file_for_req(req_path)) |mod_path| {
            if (self.embedded_module_native.get(mod_path)) |emitted_native| {
                return emitted_native;
            }
        }
        if (self.embedded_req_is_native(req_path)) return true;
        return self.find_module_file_for_req(req_path) != null;
    }

    /// True when a `req` binding may omit `lua_require` (embedded native module).
    fn req_module_skips_lua_binding(self: *CodeGen, path: []const u8) bool {
        return self.req_module_is_native_direct(path);
    }

    const ReqDepCtx = struct {
        cg: *CodeGen,
        ok: bool = true,
    };

    fn collect_req_dep_cb(ctx: *anyopaque, path: []const u8) void {
        const rctx: *ReqDepCtx = @ptrCast(@alignCast(ctx));
        if (!rctx.ok) return;
        const mod_path = rctx.cg.find_module_file_for_req(path) orelse return;
        if (rctx.cg.embedded_module_paths.contains(mod_path)) return;
        const cname = rctx.cg.module_c_name(path) catch {
            rctx.ok = false;
            return;
        };
        defer rctx.cg.alloc.free(cname);
        if (!rctx.cg.emit_embedded_module(cname, mod_path)) rctx.ok = false;
    }

    fn ensure_req_deps_embedded(self: *CodeGen, mod: *const ast.Module) bool {
        var ctx: ReqDepCtx = .{ .cg = self };
        for_each_req_path_in_module(mod, &ctx, collect_req_dep_cb);
        return ctx.ok;
    }

    fn type_expr_is_explicit_any(type_expr: ast.TypeExpr) bool {
        return type_expr == .named and std.mem.eql(u8, type_expr.named, "any");
    }

    fn func_decl_blocks_full_native_ast(fd: *const ast.FuncDecl) bool {
        if (type_expr_is_explicit_any(fd.func.ret_type)) return true;
        for (fd.func.params) |param| {
            if (type_expr_is_explicit_any(param.typ)) return true;
        }
        return false;
    }

    fn module_ast_blocks_full_native_ast(mod: *const ast.Module) bool {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            if (func_decl_blocks_full_native_ast(&stmt.func_decl)) return true;
        }
        return false;
    }

    fn module_path_allows_full_native_embed(self: *CodeGen, path: []const u8) bool {
        const cwd = Io.Dir.cwd();
        const src = Io.Dir.readFileAlloc(cwd, self.io, path, self.alloc, .unlimited) catch return false;
        defer self.alloc.free(src);
        var lex = @import("lexer.zig").Lexer.init(src, path);
        var parser = @import("parser.zig").Parser.init(&lex, self.alloc);
        // Embedded .duo files must be parsed with the Duo grammar. Without this
        // they are parsed in Lua-compat mode, where forms like one-line function
        // bodies and typed bindings are rejected — the file then fails to embed
        // and its duo_mod_* thunk is never emitted, while the caller registers
        // it anyway ("use of undeclared identifier duo_mod_*").
        parser.duo_mode = std.mem.endsWith(u8, path, ".duo");
        const submod = parser.parse_module() catch return false;
        return !module_ast_blocks_full_native_ast(&submod);
    }

    fn req_deps_allow_full_native(self: *CodeGen, mod: *const ast.Module) bool {
        if (self.src_path.len == 0) return true;
        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.alloc);
        self.collect_require_names_block(&mod.body, &names) catch return false;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                self.collect_require_names_block(&stmt.func_decl.func.body, &names) catch return false;
            }
        }

        var seen_paths: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen_paths.deinit(self.alloc);
        var seen_names: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen_names.deinit(self.alloc);

        var i: usize = 0;
        while (i < names.items.len) : (i += 1) {
            const name = names.items[i];
            if (seen_names.contains(name)) continue;
            seen_names.put(self.alloc, name, {}) catch return false;
            const mod_path = self.find_module_file_for_req(name) orelse continue;
            if (seen_paths.contains(mod_path)) continue;
            seen_paths.put(self.alloc, mod_path, {}) catch return false;
            if (!self.module_path_allows_full_native_embed(mod_path)) return false;

            const sub_src = Io.Dir.readFileAlloc(Io.Dir.cwd(), self.io, mod_path, self.alloc, .unlimited) catch return false;
            defer self.alloc.free(sub_src);
            var sub_lex = @import("lexer.zig").Lexer.init(sub_src, mod_path);
            var sub_parser = @import("parser.zig").Parser.init(&sub_lex, self.alloc);
            // The embed path must parse a `.duo` module in the same dialect the
            // standalone path uses. Without this, duo-mode-only syntax (bare
            // function declarations) parses fine when the file is compiled
            // directly but fails with "expected '<eof>', got 'end'" the moment it
            // is embedded — which is what stopped `std/script.duo` and
            // `std/mcp.duo` from embedding, and so kept the Duo MCP servers dead.
            sub_parser.duo_mode = std.mem.endsWith(u8, mod_path, ".duo");
            var sub_mod = sub_parser.parse_module() catch return false;
            self.collect_require_names_block(&sub_mod.body, &names) catch return false;
            for (sub_mod.body.stmts) |*sub_stmt| {
                if (sub_stmt.* == .func_decl) {
                    self.collect_require_names_block(&sub_stmt.func_decl.func.body, &names) catch return false;
                }
            }
        }
        return true;
    }

    fn req_binding_path_for_name(mod: *const ast.Module, name: []const u8) ?[]const u8 {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| {
                    for (ld.names, 0..) |*ln, i| {
                        if (!std.mem.eql(u8, ln.ident, name)) continue;
                        if (i < ld.inits.len) {
                            if (req_path_from_expr(ld.inits[i])) |path| return path;
                        }
                    }
                },
                .assign => |*as| {
                    if (as.targets.len != 1 or as.values.len != 1 or as.targets[0].* != .name) continue;
                    if (!std.mem.eql(u8, as.targets[0].name.ident, name)) continue;
                    if (req_path_from_expr(as.values[0])) |path| return path;
                },
                .global_decl => |*gd| {
                    for (gd.names, 0..) |*ln, i| {
                        if (!std.mem.eql(u8, ln.ident, name)) continue;
                        if (i < gd.inits.len) {
                            if (req_path_from_expr(gd.inits[i])) |path| return path;
                        }
                    }
                },
                else => {},
            }
        }
        return null;
    }

    fn emit_embedded_module_req_binding_inits(self: *CodeGen, mod: *const ast.Module) !void {
        var it = self.req_module_bindings.iterator();
        while (it.next()) |entry| {
            const name = entry.key_ptr.*;
            if (self.req_native_direct.contains(name) and !module_top_level_assigns(mod, name)) continue;
            // `module_top_level_assigns` counts a binding's OWN `X = req "..."`
            // as an assignment, so the skip above is unreachable for every req
            // binding and a spurious `lua_require` is emitted beside storage the
            // declaration loop already skipped ("module not found: std.str").
            // Narrow, initializer-only test: if the binding's sole top-level
            // assignment IS its req declaration, there is nothing to initialize.
            // Deliberately does NOT change `module_top_level_assigns` — that
            // predicate is shared, and two attempts to alter it broke the tree.
            if (self.req_native_direct.contains(name) and req_decl_is_sole_assignment(mod, name)) continue;
            const path = req_binding_path_for_name(mod, name) orelse continue;
            // A module that was embedded has its definitions inlined and its
            // functions called directly, so no runtime require is needed. Emitting
            // one anyway assigns to a `duo_g_*` global that is never declared —
            // invalid C. The declaration and the assignment disagree because
            // `mangled_name` prefixes with `current_module_cname` while the
            // declaration was emitted in the outer module's (empty) context, so a
            // *nested* embedded module requiring another embedded module (e.g.
            // std.compiler.token -> std.token.classify) writes to a symbol that
            // does not exist and that nothing reads.
            // ...unless real `duo_g_` storage was declared for this binding, in
            // which case the body *does* read it as a table (e.g. std.script's
            // `_os.read_file(p)` lowers to `lua_table_get_str_lit(duo_g_std_script__os,
            // "read_file", …)`). Skipping the require then leaves the global
            // permanently VAL_NIL and the first call through it segfaults —
            // which is what took out std.script, and with it every repo tooling
            // script and both duo-mcp servers. The declaration loop above has
            // already populated `emitted_global_storage`, so this is exact:
            // emit the require iff something will read the global.
            if (self.current_module_cname.len > 0) {
                if (self.find_module_file_for_req(path)) |mod_file| {
                    if (self.embedded_module_paths.contains(mod_file)) {
                        var kb: [512]u8 = undefined;
                        const declared = if (std.fmt.bufPrint(&kb, "{s}|{s}", .{ self.current_module_cname, name })) |k|
                            self.emitted_global_storage.contains(k)
                        else |_|
                            false;
                        if (!declared) continue;
                    }
                }
            }
            const hash = calc_lua_hash(path);
            self.ind();
            self.p("duo_g_{s}_{s} = lua_require(lua_val_from_literal(\"", .{ self.current_module_cname, name });
            try self.emit_string_escaped(path);
            self.p("\", {d}u, {d}));\n", .{ hash, path.len });
        }
    }

    fn collect_req_module_bindings(self: *CodeGen, mod: *const ast.Module) !void {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| {
                    for (ld.names, 0..) |*ln, i| {
                        if (i >= ld.inits.len) continue;
                        const path = req_path_from_expr(ld.inits[i]) orelse continue;
                        try self.try_register_req_binding(ln.ident, path);
                        if (self.req_module_skips_lua_binding(path)) try self.mark_req_native_direct(ln.ident);
                        if (self.duo_mode) try self.mark_module_sealed(ln.ident);
                    }
                },
                .assign => |*as| {
                    if (as.targets.len != 1 or as.values.len != 1 or as.targets[0].* != .name) continue;
                    const path = req_path_from_expr(as.values[0]) orelse continue;
                    try self.try_register_req_binding(as.targets[0].name.ident, path);
                    if (self.req_module_skips_lua_binding(path)) try self.mark_req_native_direct(as.targets[0].name.ident);
                    if (self.duo_mode) try self.mark_module_sealed(as.targets[0].name.ident);
                },
                .global_decl => |*gd| {
                    for (gd.names, 0..) |*ln, i| {
                        if (i >= gd.inits.len) continue;
                        const path = req_path_from_expr(gd.inits[i]) orelse continue;
                        try self.try_register_req_binding(ln.ident, path);
                        if (self.req_module_skips_lua_binding(path)) try self.mark_req_native_direct(ln.ident);
                        if (self.duo_mode) try self.mark_module_sealed(ln.ident);
                    }
                },
                else => {},
            }
        }
        try self.collect_module_seal_invalidations(mod);
    }

    fn mark_module_sealed(self: *CodeGen, name: []const u8) !void {
        if (self.module_sealed_bindings.contains(name)) return;
        const owned = try self.alloc.dupe(u8, name);
        try self.module_sealed_bindings.put(self.alloc, owned, {});
    }

    /// Pass 34 L2 — assign a stable interned field ID to a fallback `.field` access.
    /// IDs are assigned in first-use order per compilation (0-based).
    fn interned_fallback_field_id(self: *CodeGen, field: []const u8) u32 {
        if (self.fallback_interned_fields.get(field)) |id| return id;
        const owned = self.alloc.dupe(u8, field) catch return 0;
        const next_id: u32 = @intCast(self.fallback_interned_fields.count());
        self.fallback_interned_fields.put(self.alloc, owned, next_id) catch return 0;
        return next_id;
    }

    fn invalidate_module_sealed(self: *CodeGen, name: []const u8) void {
        if (self.module_sealed_bindings.fetchRemove(name)) |kv| {
            self.alloc.free(kv.key);
        }
    }

    fn collect_module_seal_invalidations_in_block(self: *CodeGen, block: *const ast.Block) void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .assign => |*as| {
                    for (as.targets, 0..) |tgt, i| {
                        const val: ?*const ast.Expr = if (i < as.values.len) as.values[i] else null;
                        self.note_module_seal_invalidation(tgt, val);
                    }
                },
                .if_stmt => |*is| {
                    self.collect_module_seal_invalidations_in_block(&is.then);
                    for (is.elseifs) |*ei| self.collect_module_seal_invalidations_in_block(&ei.body);
                    if (is.else_body) |*eb| self.collect_module_seal_invalidations_in_block(eb);
                },
                .while_loop => |*wl| self.collect_module_seal_invalidations_in_block(&wl.body),
                .repeat_loop => |*rl| self.collect_module_seal_invalidations_in_block(&rl.body),
                .do_block => |*db| self.collect_module_seal_invalidations_in_block(&db.body),
                else => {},
            }
        }
    }

    fn collect_module_seal_invalidations(self: *CodeGen, mod: *const ast.Module) !void {
        if (!self.duo_mode) return;
        self.collect_module_seal_invalidations_in_block(&mod.body);
    }

    fn note_module_seal_invalidation(self: *CodeGen, tgt: *const ast.Expr, value: ?*const ast.Expr) void {
        switch (tgt.*) {
            .name => |n| {
                if (self.module_sealed_bindings.contains(n.ident)) {
                    if (value) |v| {
                        if (req_path_from_expr(v) == null) self.invalidate_module_sealed(n.ident);
                    } else {
                        self.invalidate_module_sealed(n.ident);
                    }
                } else if (value) |v| {
                    if (req_path_from_expr(v)) |_| self.mark_module_sealed(n.ident) catch {};
                }
            },
            .field => |f| {
                if (f.obj.* == .name and self.module_sealed_bindings.contains(f.obj.name.ident)) {
                    self.invalidate_module_sealed(f.obj.name.ident);
                }
            },
            else => {},
        }
    }

    fn mark_req_native_direct(self: *CodeGen, name: []const u8) !void {
        const owned = try self.alloc.dupe(u8, name);
        try self.req_native_direct.put(self.alloc, owned, {});
    }

    fn try_register_req_binding(self: *CodeGen, name: []const u8, path: []const u8) !void {
        const cname = try self.module_c_name(path);
        if (self.req_module_bindings.get(name)) |existing| {
            if (std.mem.eql(u8, existing, cname)) return;
        }
        const owned = try self.alloc.dupe(u8, name);
        try self.req_module_bindings.put(self.alloc, owned, cname);
    }

    fn precollect_req_bindings_in_block(self: *CodeGen, block: *const ast.Block) !void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| {
                    for (ld.names, 0..) |*ln, i| {
                        if (i >= ld.inits.len) continue;
                        if (req_path_from_expr(ld.inits[i])) |path| {
                            try self.try_register_req_binding(ln.ident, path);
                            if (self.req_module_skips_lua_binding(path)) try self.mark_req_native_direct(ln.ident);
                        }
                    }
                },
                .assign => |*as| {
                    if (as.targets.len != 1 or as.values.len != 1 or as.targets[0].* != .name) continue;
                    if (req_path_from_expr(as.values[0])) |path| {
                        try self.try_register_req_binding(as.targets[0].name.ident, path);
                        if (self.req_module_skips_lua_binding(path)) try self.mark_req_native_direct(as.targets[0].name.ident);
                    }
                },
                .if_stmt => |*is| {
                    try self.precollect_req_bindings_in_block(&is.then);
                    for (is.elseifs) |*ei| try self.precollect_req_bindings_in_block(&ei.body);
                    if (is.else_body) |*eb| try self.precollect_req_bindings_in_block(eb);
                },
                .while_loop => |*wl| try self.precollect_req_bindings_in_block(&wl.body),
                .repeat_loop => |*rl| try self.precollect_req_bindings_in_block(&rl.body),
                .do_block => |*db| try self.precollect_req_bindings_in_block(&db.body),
                else => {},
            }
        }
    }

    /// Module-level numeric assigns (e.g. `KIND_FUN = 14`) as file-scope natives.
    fn embedded_module_scalar_const_assign(mod: *const ast.Module, name: []const u8) ?*const ast.Expr {
        for (mod.body.stmts) |*stmt| {
            const as = switch (stmt.*) {
                .assign => |*a| a,
                else => continue,
            };
            if (as.targets.len != 1 or as.values.len != 1 or as.targets[0].* != .name) continue;
            if (!std.mem.eql(u8, as.targets[0].name.ident, name)) continue;
            const val = as.values[0];
            switch (val.*) {
                .int_lit, .float_lit, .true_lit, .false_lit => return val,
                else => return null,
            }
        }
        return null;
    }

    fn emit_embedded_module_file_scope_constants(self: *CodeGen, mod: *const ast.Module) E!void {
        if (self.current_module_cname.len == 0) return;
        if (!self.native_scalar_mode and !self.mixed_scalar_mode) return;
        for (mod.body.stmts) |*stmt| {
            const as = switch (stmt.*) {
                .assign => |*a| a,
                else => continue,
            };
            if (as.targets.len != 1 or as.values.len != 1 or as.targets[0].* != .name) continue;
            const val = as.values[0];
            const rt: RT = switch (val.*) {
                .int_lit => .i64,
                .float_lit => .f64,
                .true_lit, .false_lit => .bool,
                else => continue,
            };
            var name_buf: [256]u8 = undefined;
            const ident = as.targets[0].name.ident;
            const mname = self.mangled_name(ident, &name_buf);
            self.p("static const ", .{});
            self.typ(rt);
            self.p(" {s} = ", .{mname});
            try self.emit_expr(val);
            self.p(";\n", .{});
            try self.note_comptime_binding(ident, val);
        }
    }

    fn lookup_req_module_dense_table(self: *CodeGen, mod_cname: []const u8, field: []const u8) ?NativeDenseModuleTable {
        var it = self.native_dense_module_tables.iterator();
        while (it.next()) |entry| {
            if (!std.mem.eql(u8, entry.key_ptr.*, field)) continue;
            if (!std.mem.eql(u8, entry.value_ptr.module_cname, mod_cname)) continue;
            return entry.value_ptr.*;
        }
        return null;
    }

    fn req_module_dense_index_info(self: *CodeGen, obj: *const ast.Expr) ?NativeDenseModuleTable {
        if (obj.* != .field) return null;
        const f = obj.field;
        if (f.obj.* != .name) return null;
        const mod_cname = self.req_module_bindings.get(f.obj.name.ident) orelse return null;
        return self.lookup_req_module_dense_table(mod_cname, f.field);
    }

    /// Flatten a `name.a.b` spine into "name.a.b". Returns null for anything
    /// that is not a pure name/field chain, or that overflows `buf`.
    fn ambient_dotted_path(expr: *const ast.Expr, buf: []u8) ?[]const u8 {
        var parts: [12][]const u8 = undefined;
        var n: usize = 0;
        var cur = expr;
        while (cur.* == .field) {
            if (n >= parts.len) return null;
            parts[n] = cur.field.field;
            n += 1;
            cur = cur.field.obj;
        }
        if (cur.* != .name or n == 0) return null;
        var w: usize = 0;
        const root = cur.name.ident;
        if (root.len > buf.len) return null;
        @memcpy(buf[0..root.len], root);
        w = root.len;
        var i: usize = n;
        while (i > 0) {
            i -= 1;
            if (w + 1 + parts[i].len > buf.len) return null;
            buf[w] = '.';
            w += 1;
            @memcpy(buf[w..][0..parts[i].len], parts[i]);
            w += parts[i].len;
        }
        return buf[0..w];
    }

    /// Spec §2.7: an ambient namespace path is a STATIC path and must fold to a
    /// direct reference, not a runtime `lua_table_get_str_lit` walk through
    /// `duo_g_std`. `std.a.b.C` folds to the same `<cname>__C` symbol the `req`
    /// binding path already produces — so the canonical spelling stops being
    /// slower than the graveyard one.
    fn try_emit_ambient_module_const_field(self: *CodeGen, f_obj: *const ast.Expr, field: []const u8, result_rt: RT) E!bool {
        if (!self.duo_mode) return false;
        var pbuf: [512]u8 = undefined;
        const mod_path = ambient_dotted_path(f_obj, &pbuf) orelse return false;
        if (!std.mem.startsWith(u8, mod_path, "std.")) return false;
        const mod_file = self.find_module_file_for_req(mod_path) orelse return false;
        // Only fold when the module is already embedded — the folded symbol has
        // to exist. Collection of ambient paths is a separate concern.
        if (!self.embedded_module_paths.contains(mod_file)) return false;
        const cname = self.module_c_name(mod_path) catch return false;
        defer self.alloc.free(cname);
        return try self.try_emit_req_module_const_field(cname, field, result_rt);
    }

    fn try_emit_req_module_const_field(
        self: *CodeGen,
        mod_cname: []const u8,
        field: []const u8,
        result_rt: RT,
    ) E!bool {
        // Only a module emitted in native-scalar mode folds its constants into
        // `<mod>__<field>` symbols. A module whose export is a real table has no
        // such symbols — fall through to the table read instead of emitting a
        // reference to something that was never defined.
        if (self.embedded_module_native.get(mod_cname)) |emitted_native| {
            if (!emitted_native) return false;
        }
        var sym_buf: [384]u8 = undefined;
        // A cross-module const field read assumes the target is a folded
        // `static const <mod>__<field>`. When that module instead emitted real
        // `duo_g_` storage (because one of its own functions reads the name),
        // the const symbol does not exist and this produced "use of undeclared
        // identifier 'std_vector__WORD_W'" in the export table. Follow whatever
        // storage was actually declared.
        var key_buf: [512]u8 = undefined;
        const storage_key = std.fmt.bufPrint(&key_buf, "{s}|{s}", .{ mod_cname, field }) catch "";
        const sym = if (storage_key.len > 0 and self.emitted_global_storage.contains(storage_key))
            std.fmt.bufPrint(&sym_buf, "duo_g_{s}_{s}", .{ mod_cname, field }) catch return false
        else
            std.fmt.bufPrint(&sym_buf, "{s}__{s}", .{ mod_cname, field }) catch return false;
        const cast_rt = result_rt;
        if (cast_rt.is_integer() or cast_rt.is_float() or cast_rt == .bool) {
            if (cast_rt.is_integer()) {
                self.p("((", .{});
                self.typ(cast_rt);
                self.p("){s})", .{sym});
            } else if (cast_rt.is_float()) {
                self.p("((", .{});
                self.typ(cast_rt);
                self.p("){s})", .{sym});
            } else {
                self.p("{s}", .{sym});
            }
            return true;
        }
        if (cast_rt == .str) {
            self.p("{s}", .{sym});
            return true;
        }
        return false;
    }

    fn expr_is_req_module_const_field(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .field) return false;
        if (e.field.obj.* != .name) return false;
        return self.req_module_bindings.contains(e.field.obj.name.ident);
    }

    fn expr_is_native_record_field(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .field) return false;
        const obj_rt = self.expr_type(e.field.obj);
        return self.type_lowers_native(obj_rt);
    }

    fn lookup_req_module_func_type(self: *CodeGen, mod_cname: []const u8, field: []const u8) ?RT {
        var name_buf: [256]u8 = undefined;
        const saved_cname = self.current_module_cname;
        self.current_module_cname = mod_cname;
        const mname = self.mangled_name(field, &name_buf);
        const body = self.func_bodies.get(mname);
        const ft: RT = if (body) |b| self.func_expr_type(b) else blk: {
            if (self.func_decls.get(mname)) |fd| {
                const ret = self.resolve_type(fd.func.ret_type);
                const params = self.alloc.alloc(RT, fd.func.params.len) catch break :blk .any;
                for (fd.func.params, 0..) |par, i| {
                    params[i] = self.resolve_type(par.typ);
                }
                const ret_ptr = self.alloc.create(RT) catch break :blk .any;
                ret_ptr.* = ret;
                break :blk .{ .func = .{ .params = params, .ret = ret_ptr, .is_native = fd.func.is_typed, .has_vararg = fd.func.vararg or fd.func.vararg_name != null } };
            }
            break :blk .any;
        };
        self.current_module_cname = saved_cname;
        if (ft != .func) return null;
        return ft;
    }

    fn infer_req_module_call_return_type(self: *CodeGen, expr: *const ast.Expr) ?RT {
        if (expr.* != .call) return null;
        const c = expr.call;
        if (c.func.* != .field) return null;
        const f = &c.func.field;
        if (f.obj.* != .name) return null;
        const mod_cname = self.req_module_bindings.get(f.obj.name.ident) orelse return null;
        const ft = self.lookup_req_module_func_type(mod_cname, f.field) orelse return null;
        var ret = ft.func.ret.*;
        if (ret == .@"struct") {
            if (self.record_aliases.get(ret.@"struct".name)) |alias_rt| ret = alias_rt;
        }
        return ret;
    }

    fn try_emit_req_module_field_call(
        self: *CodeGen,
        func: *const ast.Expr,
        args: []*ast.Expr,
        result_rt: RT,
    ) E!bool {
        if (func.* != .field) return false;
        const f = &func.field;
        if (f.obj.* != .name) return false;
        const mod_cname = self.req_module_bindings.get(f.obj.name.ident) orelse return false;

        var name_buf: [256]u8 = undefined;
        const saved_cname = self.current_module_cname;
        const saved_body = self.current_func_body;
        self.current_module_cname = mod_cname;
        const mname = self.mangled_name(f.field, &name_buf);
        const body = self.func_bodies.get(mname);
        const ft: RT = if (body) |b| self.func_expr_type(b) else .any;
        if (body == null or ft != .func) {
            self.current_module_cname = saved_cname;
            return false;
        }
        self.current_func_body = body;

        const ret_native = self.type_lowers_native(ft.func.ret.*);
        const effective_result: RT = if (result_rt == .any and ret_native) ft.func.ret.* else result_rt;
        const caller_native = self.type_lowers_native(effective_result);
        const needs_lua_box = blk: {
            if (!(ret_native and caller_native)) break :blk true;
            // Native str→str: emit const char* directly (no lua_val_from_str wrapper).
            if (ret_native and caller_native and ft.func.ret.* == .str) break :blk false;
            if (self.current_func_name) |fname| {
                if (self.funcUsesNativeLowering(fname)) break :blk false;
            }
            if (self.moduleNeedsLuaRuntime() and ft.func.ret.* == .str) break :blk true;
            break :blk false;
        };
        if (needs_lua_box) {
            switch (ft.func.ret.*) {
                .str => self.p("lua_val_from_str(", .{}),
                .i64, .u64, .i32, .u32, .i16, .u16, .i8, .u8 => self.p("lua_val_from_int((int64_t)(", .{}),
                .f64, .f32 => self.p("lua_val_from_num((double)(", .{}),
                .bool => self.p("lua_val_from_bool(", .{}),
                else => self.p("(", .{}),
            }
        }
        self.p("{s}(", .{mname});
        // Arguments belong to the caller's scope (names/constants must not pick up
        // the callee module prefix), but record params still use the callee's
        // pointer ABI — restore caller context only for name resolution, not &.
        self.current_module_cname = saved_cname;
        // Arguments are the *caller's* expressions, so the caller's body must be
        // in scope while emitting them. Leaving the callee's body installed made
        // `expr_is_native_record_ptr_param` search the callee's parameter list,
        // so a record the caller holds by pointer emitted `self.src` while the
        // rest of the same function used `self->pos` — clang then rejected the
        // module. The callee is still consulted for param *types* below, which
        // come from `ft` and do not depend on the installed body.
        self.current_func_body = saved_body;
        for (args, 0..) |arg, i| {
            if (i > 0) self.p(", ", .{});
            const pt: RT = if (i < ft.func.params.len) ft.func.params[i] else .any;
            const pass_by_ptr = blk: {
                self.current_module_cname = mod_cname;
                const by_ptr = self.native_record_param_by_ptr(pt);
                self.current_module_cname = saved_cname;
                break :blk by_ptr;
            };
            if (pass_by_ptr) {
                if (arg.* == .name and self.expr_is_native_record_ptr_param(arg)) {
                    try self.emit_expr(arg);
                } else {
                    self.p("&", .{});
                    try self.emit_expr(arg);
                }
            } else {
                try self.emit_arg_for_param(arg, pt, true);
            }
        }
        self.p(")", .{});
        self.current_func_body = saved_body;
        if (needs_lua_box) {
            switch (ft.func.ret.*) {
                .str => self.p(")", .{}),
                .i64, .u64, .i32, .u32, .i16, .u16, .i8, .u8, .f64, .f32 => self.p("))", .{}),
                .bool => self.p(")", .{}),
                else => self.p(")", .{}),
            }
        }
        return true;
    }

    fn add_module_export(
        self: *CodeGen,
        seen: *std.StringArrayHashMapUnmanaged(void),
        names: *std.ArrayList([]const u8),
        name: []const u8,
        force_export: bool,
    ) E!void {
        if (name.len == 0) return;
        if (!force_export and name[0] == '_') return;
        if (seen.contains(name)) return;
        try seen.put(self.alloc, name, {});
        try names.append(self.alloc, name);
    }

    fn binding_has_export_attr(attrs: []const ast.Attribute) bool {
        for (attrs) |attr| {
            if (std.mem.eql(u8, attr.name, "export")) return true;
        }
        return false;
    }

    fn collect_duo_module_exports(self: *CodeGen, mod: *const ast.Module, names: *std.ArrayList([]const u8)) E!void {
        var seen: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen.deinit(self.alloc);

        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| {
                    for (ld.names) |*lname| {
                        try self.add_module_export(
                            &seen,
                            names,
                            lname.ident,
                            binding_has_export_attr(lname.attributes),
                        );
                    }
                },
                .global_decl => |*gd| {
                    if (!gd.star) for (gd.names) |*lname| {
                        try self.add_module_export(&seen, names, lname.ident, binding_has_export_attr(lname.attributes));
                    };
                },
                .const_decl => |*cd| try self.add_module_export(&seen, names, cd.ident, false),
                .assign => |*as| {
                    for (as.targets) |target| {
                        if (target.* == .name) try self.add_module_export(&seen, names, target.name.ident, false);
                    }
                },
                .func_decl => |*fd| {
                    if (fd.path.len == 1 and !fd.method) {
                        const force = func_has_attr(fd.attributes, "export");
                        try self.add_module_export(&seen, names, fd.path[0], force);
                    }
                },
                else => {},
            }
        }
    }

    fn find_duo_module_func(mod: *const ast.Module, name: []const u8) ?*const ast.FuncDecl {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.method or fd.path.len != 1) continue;
            if (std.mem.eql(u8, fd.path[0], name)) return fd;
        }
        return null;
    }

    fn find_duo_module_const(mod: *const ast.Module, name: []const u8) ?*const ast.Expr {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .const_decl) continue;
            const cd = &stmt.const_decl;
            if (std.mem.eql(u8, cd.ident, name)) return cd.val;
        }
        return null;
    }

    fn stmt_declares_name(stmt: *const ast.Stmt, name: []const u8) bool {
        switch (stmt.*) {
            .local_decl => |*ld| for (ld.names) |*lname| {
                if (std.mem.eql(u8, lname.ident, name)) return true;
            },
            .const_decl => |*cd| if (std.mem.eql(u8, cd.ident, name)) return true,
            .global_decl => |*gd| for (gd.names) |*gname| {
                if (std.mem.eql(u8, gname.ident, name)) return true;
            },
            .num_for => |*nf| if (std.mem.eql(u8, nf.var_name, name)) return true,
            .gen_for => |*gf| for (gf.vars) |v| {
                if (std.mem.eql(u8, v, name)) return true;
            },
            .func_decl => |*fd| if (fd.path.len == 1 and std.mem.eql(u8, fd.path[0], name)) return true,
            else => {},
        }
        return false;
    }

    fn expr_references_name(expr: *const ast.Expr, name: []const u8) bool {
        return switch (expr.*) {
            .name => |n| std.mem.eql(u8, n.ident, name),
            .index => |idx| expr_references_name(idx.obj, name) or expr_references_name(idx.key, name),
            .field => |f| expr_references_name(f.obj, name),
            .call => |c| blk: {
                if (expr_references_name(c.func, name)) break :blk true;
                for (c.args) |arg| if (expr_references_name(arg, name)) break :blk true;
                break :blk false;
            },
            .method_call => |mc| blk: {
                if (expr_references_name(mc.obj, name)) break :blk true;
                for (mc.args) |arg| if (expr_references_name(arg, name)) break :blk true;
                break :blk false;
            },
            .binop => |b| expr_references_name(b.lhs, name) or expr_references_name(b.rhs, name),
            .unop => |u| expr_references_name(u.operand, name),
            .func_expr => |fb| func_body_references_name(fb, name),
            .table => |t| blk: {
                for (t.fields) |field| switch (field) {
                    .indexed => |idx| if (expr_references_name(idx.key, name) or expr_references_name(idx.val, name)) break :blk true,
                    .named => |named| if (expr_references_name(named.val, name)) break :blk true,
                    .positional => |pos| if (expr_references_name(pos, name)) break :blk true,
                    .spread => |sp| if (expr_references_name(sp, name)) break :blk true,
                    // Pass 36 G1/G8 recorded, not implemented (Phase 0): only the implementation can reference a name.
                    .semantic => |sm| if (expr_references_name(sm.val, name)) break :blk true,
                };
                break :blk false;
            },
            .list_comp => |lc| blk: {
                if (expr_references_name(lc.iter, name)) break :blk true;
                if (std.mem.eql(u8, lc.value_name, name)) break :blk false;
                if (lc.key_name) |key_name| if (std.mem.eql(u8, key_name, name)) break :blk false;
                if (lc.filter) |filter| if (expr_references_name(filter, name)) break :blk true;
                break :blk expr_references_name(lc.value, name);
            },
            .try_expr => |t| expr_references_name(t.operand, name),
            .unwrap_expr => |u| expr_references_name(u.operand, name),
            .match_expr => |m| expr_references_name(m.scrutinee, name),
            .await_expr => |a| expr_references_name(a.operand, name),
            .contains_expr => |c| expr_references_name(c.lhs, name) or expr_references_name(c.rhs, name),
            .quote => false,
            .unquote => |u| expr_references_name(u.expr, name),
            .macro_call => |mc| blk: {
                for (mc.args) |arg| if (expr_references_name(arg, name)) break :blk true;
                break :blk false;
            },
            .sequence => |seq| blk: {
                for (seq.exprs) |e| if (expr_references_name(e, name)) break :blk true;
                break :blk false;
            },
            .range => |r| expr_references_name(r.start, name) or expr_references_name(r.end, name) or (if (r.step) |step| expr_references_name(step, name) else false),
            else => false,
        };
    }

    fn block_references_name(block: *const ast.Block, name: []const u8) bool {
        for (block.stmts) |*stmt| {
            if (stmt_declares_name(stmt, name)) return false;
            if (stmt_references_name(stmt, name)) return true;
        }
        return if (block.tail_expr) |tail| expr_references_name(tail, name) else false;
    }

    fn stmt_references_name(stmt: *const ast.Stmt, name: []const u8) bool {
        return switch (stmt.*) {
            .local_decl => |*ld| blk: {
                for (ld.inits) |init_expr| if (expr_references_name(init_expr, name)) break :blk true;
                break :blk false;
            },
            .global_decl => |*gd| blk: {
                for (gd.inits) |init_expr| if (expr_references_name(init_expr, name)) break :blk true;
                break :blk false;
            },
            .assign => |*as| blk: {
                for (as.targets) |target| if (expr_references_name(target, name)) break :blk true;
                for (as.values) |value| if (expr_references_name(value, name)) break :blk true;
                break :blk false;
            },
            .call_stmt => |*cs| expr_references_name(cs.expr, name),
            .expr_stmt => |*es| expr_references_name(es.expr, name),
            .do_block => |*db| block_references_name(&db.body, name),
            .while_loop => |*wl| expr_references_name(wl.cond, name) or block_references_name(&wl.body, name),
            .repeat_loop => |*rl| block_references_name(&rl.body, name) or expr_references_name(rl.cond, name),
            .if_stmt => |*is| blk: {
                if (expr_references_name(is.cond, name) or block_references_name(&is.then, name)) break :blk true;
                for (is.elseifs) |*ei| if (expr_references_name(ei.cond, name) or block_references_name(&ei.body, name)) break :blk true;
                if (is.else_body) |*eb| if (block_references_name(eb, name)) break :blk true;
                break :blk false;
            },
            .num_for => |*nf| expr_references_name(nf.start, name) or expr_references_name(nf.stop, name) or (if (nf.step) |step| expr_references_name(step, name) else false) or block_references_name(&nf.body, name),
            .gen_for => |*gf| blk: {
                for (gf.iters) |iter| if (expr_references_name(iter, name)) break :blk true;
                break :blk block_references_name(&gf.body, name);
            },
            .func_decl => false,
            .ret => |*r| blk: {
                for (r.vals) |val| if (expr_references_name(val, name)) break :blk true;
                break :blk false;
            },
            .match_stmt => |*m| expr_references_name(m.scrutinee, name),
            .try_stmt => |*ts| blk: {
                if (block_references_name(&ts.body, name)) break :blk true;
                for (ts.catches) |*catch_clause| if (block_references_name(&catch_clause.body, name)) break :blk true;
                for (ts.defers) |*defer_stmt| if (block_references_name(&defer_stmt.body, name)) break :blk true;
                break :blk false;
            },
            .defer_stmt => |*ds| block_references_name(&ds.body, name),
            else => false,
        };
    }

    fn func_body_references_name(fb: *const ast.FuncBody, name: []const u8) bool {
        for (fb.params) |param| if (std.mem.eql(u8, param.name, name)) return false;
        return block_references_name(&fb.body, name);
    }

    /// True when any top-level function assigns `name` (so it cannot be folded to
    /// a compile-time constant — it needs storage). Uses the existing
    /// `block_assigns_name` method, which already walks nested blocks.
    fn module_functions_assign_name(self: *CodeGen, mod: *const ast.Module, name: []const u8) bool {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl and self.block_assigns_name(&stmt.func_decl.func.body, name)) return true;
        }
        return false;
    }

    fn module_functions_reference_name(mod: *const ast.Module, name: []const u8) bool {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl and func_body_references_name(&stmt.func_decl.func, name)) return true;
        }
        return false;
    }

    fn promote_module_captured_locals(
        self: *CodeGen,
        mod: *const ast.Module,
        globals: *std.StringHashMapUnmanaged(RT),
        type_map: *sema.TypeMap,
    ) E!void {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| {
                    for (ld.names, 0..) |lname, i| {
                        if (!module_functions_reference_name(mod, lname.ident)) continue;
                        const t = if (i < ld.inits.len)
                            type_map.get(ld.inits[i]) orelse .any
                        else
                            .any;
                        const entry = try globals.getOrPut(self.alloc, lname.ident);
                        if (!entry.found_existing or (entry.value_ptr.* == .any and t != .any)) {
                            entry.value_ptr.* = t;
                        }
                    }
                },
                .assign => |*as| {
                    for (as.targets, 0..) |target, i| {
                        if (target.* != .name) continue;
                        const name = target.name.ident;
                        if (!module_functions_reference_name(mod, name)) continue;
                        const t = if (i < as.values.len)
                            type_map.get(as.values[i]) orelse .any
                        else
                            .any;
                        const entry = try globals.getOrPut(self.alloc, name);
                        if (!entry.found_existing or (entry.value_ptr.* == .any and t != .any)) {
                            entry.value_ptr.* = t;
                        }
                    }
                },
                else => {},
            }
        }
    }

    fn promote_embedded_module_captured_locals(self: *CodeGen, mod: *const ast.Module, sem: *sema.Sema) E!void {
        try self.promote_module_captured_locals(mod, &sem.module_globals, &sem.type_map);
    }

    fn emit_native_dense_module_table_as_lua_value(self: *CodeGen, name: []const u8) E!void {
        const nd = self.native_dense_module_tables.get(name).?;
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value tmp = lua_table_new_with_capacity({d}, 0);\n", .{nd.len});
        var i: usize = 0;
        while (i < nd.len) : (i += 1) {
            self.ind();
            const slot: i64 = @intCast(i + 1);
            switch (nd.elem) {
                .i64 => {
                    self.p("lua_table_set_raw_i64(tmp, {d}, lua_val_from_int((int64_t)", .{slot});
                    self.p("{s}[{d}]));\n", .{ nd.c_symbol, slot });
                },
                .f64 => {
                    self.p("lua_table_set_raw_i64(tmp, {d}, lua_val_from_num((double)", .{slot});
                    self.p("{s}[{d}]));\n", .{ nd.c_symbol, slot });
                },
                .str => {
                    self.p("lua_table_set_raw_i64(tmp, {d}, lua_val_from_str({s}[{d}]));\n", .{ slot, nd.c_symbol, slot });
                },
            }
        }
        self.ind();
        self.p("tmp;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn emit_duo_module_return_table(self: *CodeGen, mod: *const ast.Module) E!void {
        // Native-direct embedded modules: exports are C symbols; no lua thunk table.
        if (self.skip_lua_thunk_emit()) {
            self.ind();
            self.pl("(void)0; /* native-direct module — use req field calls, not lua_require */", .{});
            self.ind();
            self.p("return lua_val_nil();\n", .{});
            return;
        }
        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.alloc);
        try self.collect_duo_module_exports(mod, &names);

        self.ind();
        self.p("lua_Value __duo_module = lua_table_new_with_capacity(0, {d});\n", .{names.items.len});
        for (names.items) |name| {
            const hash = calc_lua_hash(name);
            var name_expr = ast.Expr{ .name = .{ .loc = mod.body.loc, .ident = name } };
            self.ind();
            self.p("lua_table_set_raw_lit(__duo_module, \"", .{});
            try self.emit_string_escaped(name);
            self.p("\", {d}, {d}, ", .{ hash, name.len });
            if (find_duo_module_func(mod, name)) |fd| {
                const ft = self.func_expr_type(&fd.func);
                if (ft == .func) {
                    try self.emit_native_func_name_as_lua_value(name, ft.func.params, ft.func.is_compile_only);
                } else {
                    try self.emit_as_lua_value(&name_expr);
                }
            } else if (find_duo_module_const(mod, name)) |cval| {
                try self.emit_as_lua_value(cval);
            } else if (embedded_module_scalar_const_assign(mod, name)) |_| {
                self.p("lua_val_from_int((int64_t)(", .{});
                self.emit_comptime_const_var_name(name);
                self.p("))", .{});
            } else if (self.is_native_dense_module_table(name)) {
                try self.emit_native_dense_module_table_as_lua_value(name);
            } else if (self.module_globals) |globals| {
                if (globals.get(name) != null) {
                    // `find_duo_module_func` above already handled declared
                    // functions; reaching here with a `.func`-typed global means
                    // it is a VARIABLE holding a function value (e.g. `build =
                    // sequential`). No `__lua` thunk exists — emit the binding
                    // directly, which is already a boxed lua_Value.
                    try self.emit_as_lua_value(&name_expr);
                } else {
                    try self.emit_as_lua_value(&name_expr);
                }
            } else {
                try self.emit_as_lua_value(&name_expr);
            }
            self.p(");\n", .{});
        }
        self.ind();
        self.p("return __duo_module;\n", .{});
    }

    /// True when two paths name the same file on disk. Falls back to a byte
    /// comparison when either path cannot be resolved (in-memory tests).
    fn same_source_file(alloc: Allocator, io: Io, a: []const u8, b: []const u8) bool {
        if (std.mem.eql(u8, a, b)) return true;
        const cwd = Io.Dir.cwd();
        const ra = Io.Dir.realPathFileAlloc(cwd, io, a, alloc) catch return false;
        defer alloc.free(ra);
        const rb = Io.Dir.realPathFileAlloc(cwd, io, b, alloc) catch return false;
        defer alloc.free(rb);
        return std.mem.eql(u8, ra, rb);
    }

    fn emit_embedded_module(self: *CodeGen, cname: []const u8, path: []const u8) bool {
        if (self.embedded_module_paths.contains(path)) {
            if (self.trace_embed)
                term.warn("EMBED skip(already) cname={s} path={s}", .{ cname, path });
            return true;
        }
        // A module that transitively requires the entry module must not
        // re-embed it: the entry module's file-scope @c.emit blocks and
        // typedefs are already in the output, so embedding it again emits
        // them twice and the C compiler rejects the redefinitions. Circular
        // requires (a requires b, b requires a) make this reachable.
        if (self.src_path.len > 0 and same_source_file(self.alloc, self.io, path, self.src_path)) {
            if (self.trace_embed)
                term.warn("EMBED skip(selfpath) cname={s} path={s}", .{ cname, path });
            return true;
        }
        const owned_path = self.alloc.dupe(u8, path) catch {
            term.err("emit_embedded_module: oom tracking {s}", .{path});
            return false;
        };
        // The caller owns `cname` and frees it once the `embedded` list is torn
        // down, so the map must hold its own copy — otherwise later lookups
        // return freed memory and the module name is emitted as poison bytes.
        const owned_cname = self.alloc.dupe(u8, cname) catch {
            self.alloc.free(owned_path);
            term.err("emit_embedded_module: oom tracking {s}", .{path});
            return false;
        };
        self.embedded_module_paths.put(self.alloc, owned_path, owned_cname) catch {
            self.alloc.free(owned_path);
            self.alloc.free(owned_cname);
            term.err("emit_embedded_module: oom tracking {s}", .{path});
            return false;
        };

        const cwd = Io.Dir.cwd();
        const src = Io.Dir.readFileAlloc(cwd, self.io, path, self.alloc, .unlimited) catch |e| {
            term.err("emit_embedded_module: readFileAlloc failed for {s}: {}", .{ path, e });
            return false;
        };
        // The parser stores identifier/string slices into this buffer. Embedded
        // closure bodies are emitted after this function returns, so the source
        // must live for the duration of code generation.

        var lex = @import("lexer.zig").Lexer.init(src, path);
        var parser = @import("parser.zig").Parser.init(&lex, self.alloc);
        // Embedded .duo files must be parsed with the Duo grammar. Without this
        // they are parsed in Lua-compat mode, where forms like one-line function
        // bodies and typed bindings are rejected — the file then fails to embed
        // and its duo_mod_* thunk is never emitted, while the caller registers
        // it anyway ("use of undeclared identifier duo_mod_*").
        parser.duo_mode = std.mem.endsWith(u8, path, ".duo");
        var submod = parser.parse_module() catch |e| {
            term.err("emit_embedded_module: parse failed for {s}: {}", .{ path, e });
            return false;
        };
        var subsem = sema.Sema.init(self.alloc);
        defer subsem.deinit();
        subsem.lua55_mode = std.mem.endsWith(u8, path, ".lua");
        subsem.duo_mode = std.mem.endsWith(u8, path, ".duo");
        subsem.next_closure_id = self.next_closure_id;
        subsem.check_module(&submod) catch |e| {
            term.err("emit_embedded_module: sema failed for {s}: {}", .{ path, e });
            return false;
        };
        self.promote_embedded_module_captured_locals(&submod, &subsem) catch |e| {
            term.err("emit_embedded_module: promote captured locals failed for {s}: {}", .{ path, e });
            return false;
        };
        self.next_closure_id = subsem.next_closure_id;
        const old_duo_mode = self.duo_mode;
        const old_module_globals = self.module_globals;
        const old_module_cname = self.current_module_cname;
        const old_native_scalar = self.native_scalar_mode;
        const old_mixed_scalar = self.mixed_scalar_mode;
        const old_native_funcs = self.native_scalar_funcs;
        const old_substrate_native = self.substrate_native_mode;
        const old_module_knowledge = self.module_knowledge;
        const parent_full_native = self.moduleUsesFullNativeLowering();
        self.embed_parent_full_native = parent_full_native;
        self.duo_mode = subsem.duo_mode;
        self.module_globals = &subsem.module_globals;
        self.current_module_cname = cname;
        const old_req_bindings = self.req_module_bindings;
        self.req_module_bindings = .{};
        const old_alias_defs = self.alias_defs.clone(self.alloc) catch self.alias_defs;
        defer {
            var req_it = self.req_module_bindings.iterator();
            while (req_it.next()) |entry| {
                self.alloc.free(entry.key_ptr.*);
            }
            self.req_module_bindings.deinit(self.alloc);
            self.alias_defs.deinit(self.alloc);
            self.alias_defs = old_alias_defs;
            // record_aliases: submodule aliases remain merged in the parent map.
            self.req_module_bindings = old_req_bindings;
            self.duo_mode = old_duo_mode;
            self.module_globals = old_module_globals;
            self.current_module_cname = old_module_cname;
            self.native_scalar_mode = old_native_scalar;
            self.mixed_scalar_mode = old_mixed_scalar;
            self.native_scalar_funcs.deinit(self.alloc);
            self.native_scalar_funcs = old_native_funcs;
            self.substrate_native_mode = old_substrate_native;
            self.module_knowledge = old_module_knowledge;
            self.embed_parent_full_native = false;
        }
        self.collect_req_module_bindings(&submod) catch |e| {
            term.err("emit_embedded_module: req module bindings failed for {s}: {}", .{ path, e });
            return false;
        };
        self.promote_module_captured_locals(&submod, @constCast(self.module_globals.?), self.type_map) catch |e| {
            term.err("emit_embedded_module: promote globals failed for {s}: {}", .{ path, e });
            return false;
        };
        if (!self.ensure_req_deps_embedded(&submod)) {
            term.err("emit_embedded_module: req dependency embed failed for {s}", .{path});
            return false;
        }
        // Copy submodule type map into main type map so codegen can resolve types
        // for submodule expressions.
        var type_it = subsem.type_map.iterator();
        while (type_it.next()) |entry| {
            self.type_map.put(entry.key_ptr.*, entry.value_ptr.*) catch |e| {
                term.err("emit_embedded_module: type map merge failed: {}", .{e});
                return false;
            };
        }

        self.populate_alias_defs(&submod) catch {};
        self.populate_record_aliases(&submod) catch {};

        // Promote module-level mutable globals to static file-scope storage.
        // Functions are emitted at file scope, so they cannot see locals that were
        // declared inside the module-init function.  Static storage makes the
        // shared module state visible to every function in the module.
        self.current_module = &submod;
        self.native_scalar_mode = self.can_emit_native_scalar_module(&submod);
        // Record what we actually chose, so consumers resolve `m.x` the same way
        // this module emits it (see `req_module_is_native_direct`).
        // The keys MUST be duped: callers free `cname` (`defer alloc.free(cname)`
        // in `collect_req_dep_cb`), and storing the caller's slice left a
        // dangling key that panicked the compiler on the next lookup.
        if (self.alloc.dupe(u8, path)) |k| {
            self.embedded_module_native.put(self.alloc, k, self.native_scalar_mode) catch {};
        } else |_| {}
        // Also key by C name: the const-field folding path only has the cname.
        if (self.alloc.dupe(u8, cname)) |k| {
            self.embedded_module_native.put(self.alloc, k, self.native_scalar_mode) catch {};
        } else |_| {}
        self.mixed_scalar_mode = false;
        self.native_scalar_funcs = .empty;
        if (!self.native_scalar_mode and self.compute_native_scalar_funcs(&submod)) {
            self.mixed_scalar_mode = true;
        }
        if (self.mixed_scalar_mode) self.expand_native_scalar_func_transitive(&submod);
        self.emit_embedded_module_file_scope_constants(&submod) catch |e| {
            term.err("emit_embedded_module: file-scope constants failed for {s}: {}", .{ path, e });
            return false;
        };
        self.collect_native_dense_module_tables(&submod) catch |e| {
            term.err("emit_embedded_module: native dense table collect failed for {s}: {}", .{ path, e });
            return false;
        };
        if (self.module_globals) |globals| {
            var globals_it = globals.iterator();
            var any_global = false;
            while (globals_it.next()) |entry| {
                if (self.is_native_dense_module_table(entry.key_ptr.*)) continue;
                // Third instance of the read-vs-write skip defect: a module-top-level
                // scalar assignment (`WORD_W = 3.0` in std/vector.duo) folds at its
                // use sites *only* when those sites resolve it directly. A function
                // body reads it as `duo_g_<mod>_WORD_W`, so dropping the declaration
                // produced "use of undeclared identifier". Keep storage whenever a
                // function in the module references the name; the top-level assign
                // still emits the initializer, so the value is not lost.
                const scalar_const_init = embedded_module_scalar_const_assign(&submod, entry.key_ptr.*);
                if (scalar_const_init != null and
                    !module_functions_reference_name(&submod, entry.key_ptr.*)) continue;
                // A native-direct req binding normally needs no variable (uses
                // resolve to C symbols), but a `global x = req "..."` that the
                // body reads through an `.any`-typed field access still emits
                // duo_g_<mod>_<x>. Keep the declaration in that case.
                if (self.req_native_direct.contains(entry.key_ptr.*) and
                    !module_top_level_assigns(&submod, entry.key_ptr.*)) continue;
                const rt = entry.value_ptr.*;
                // Native-direct modules turn most `.any` globals into plain C
                // symbols, so their declarations are dropped. A global the
                // module body actually assigns at top level (the `M = {}`
                // export-table idiom) is still live: its field writes and the
                // `return M` are emitted, so dropping the declaration produces
                // "use of undeclared identifier". Keep those.
                if (self.skip_lua_thunk_emit() and rt == .any and
                    !module_top_level_assigns(&submod, entry.key_ptr.*)) continue;
                if (!self.moduleNeedsLuaRuntime() and rt == .any) continue;
                any_global = true;
                {
                    var kb: [512]u8 = undefined;
                    if (std.fmt.bufPrint(&kb, "{s}|{s}", .{ self.current_module_cname, entry.key_ptr.* })) |k| {
                        if (self.alloc.dupe(u8, k)) |owned| {
                            self.emitted_global_storage.put(self.alloc, owned, {}) catch {};
                        } else |_| {}
                    } else |_| {}
                }
                if (rt == .any) {
                    self.p("static lua_Value duo_g_{s}_{s};\n", .{ self.current_module_cname, entry.key_ptr.* });
                } else {
                    var buf: [128]u8 = undefined;
                    self.p("static {s} duo_g_{s}_{s}", .{ rt.c_type(&buf), self.current_module_cname, entry.key_ptr.* });
                    // The top-level assignment that gave this global its value is
                    // folded away, not emitted, so declaring the storage alone left
                    // `WORD_W` reading 0.0 instead of 3.0 — a silent wrong answer
                    // rather than a link error. Carry the literal into the
                    // declaration. `embedded_module_scalar_const_assign` only ever
                    // returns int/float/true/false literals, so this cannot reorder
                    // or duplicate a side effect.
                    if (scalar_const_init) |ce| {
                        self.p(" = ", .{});
                        self.emit_expr(ce) catch |e| {
                            term.err("emit_embedded_module: const init emit failed for {s}: {}", .{ entry.key_ptr.*, e });
                            return false;
                        };
                    }
                    self.p(";\n", .{});
                }
            }
            self.emit_native_dense_module_table_decls() catch |e| {
                term.err("emit_embedded_module: native dense table decl failed for {s}: {}", .{ path, e });
                return false;
            };
            if (any_global) self.p("\n", .{});
        }

        // Emit submodule closure structs
        const start_idx = self.all_closures.items.len;
        self.collect_closures_module(&submod, &self.all_closures) catch {};
        self.emit_closure_structs(self.all_closures.items[start_idx..]) catch {};

        // Emit submodule constants at file scope. Table-valued constants are
        // declared here; their init functions are emitted after submodule
        // function definitions so the init functions can call module functions.
        var table_consts: std.ArrayList(*const ast.Stmt) = .empty;
        defer table_consts.deinit(self.alloc);
        for (submod.body.stmts) |*stmt| {
            if (stmt.* == .const_decl) {
                const cd = &stmt.const_decl;
                var name_buf: [256]u8 = undefined;
                const mname = self.mangled_name(cd.ident, &name_buf);
                const rt = if (cd.typ != .inferred)
                    types.resolve(cd.typ, null, self.alloc) catch .any
                else
                    self.expr_type(cd.val);
                if (cd.val.* == .table) {
                    // Table literal: forward-declare static storage; _init emitted later
                    self.p("static lua_Value {s};\n", .{mname});
                    table_consts.append(self.alloc, stmt) catch |e| {
                        term.err("emit_embedded_module: oom collecting table const {s}: {}", .{ cd.ident, e });
                        return false;
                    };
                } else {
                    if (!self.module_functions_assign_name(&submod, cd.ident))
                        self.const_read_only.put(self.alloc, cd.ident, {}) catch {};
                    self.p("static const ", .{});
                    self.typ(rt);
                    self.p(" {s} = ", .{mname});
                    self.emit_expr(cd.val) catch |e| {
                        term.err("emit_embedded_module: expr emit failed for const {s}: {}", .{ cd.ident, e });
                        return false;
                    };
                    self.p(";\n", .{});
                }
                self.note_comptime_binding(cd.ident, cd.val) catch |e| {
                    term.err("emit_embedded_module: comptime binding failed for const {s}: {}", .{ cd.ident, e });
                    return false;
                };
            }
        }

        // Emit module-level @c.emit directives at file scope so raw C
        // declarations (e.g., struct/typedef definitions) are visible to
        // file-scope functions in the submodule.
        for (submod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .directive => |d| {
                    if (!CodeGen.isCEmitDirectiveName(d.attr.name)) continue;
                    const code = @import("directives.zig").extractAndUnescapeCRawCode(self.alloc, d.attr.args orelse "") catch "";
                    self.emit_file_scope_c_payload(code);
                },
                .expr_stmt => |es| {
                    if (self.fold_c_emit_payload(es.expr)) |code| {
                        self.emit_file_scope_c_payload(code);
                    }
                },
                else => {},
            }
        }
        self.nl();

        // Collect all top-level and nested local functions from submodule
        var sub_funcs: std.ArrayList(*ast.FuncDecl) = .empty;
        defer sub_funcs.deinit(self.alloc);
        for (submod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                sub_funcs.append(self.alloc, &stmt.func_decl) catch |e| {
                    term.err("emit_embedded_module: oom collecting funcs: {}", .{e});
                    return false;
                };
            }
        }
        var nested: std.ArrayList(*ast.FuncDecl) = .empty;
        defer nested.deinit(self.alloc);
        for (sub_funcs.items) |fd| {
            self.collect_local_funcs_block(&fd.func.body, &nested) catch |e| {
                term.err("emit_embedded_module: oom collecting nested funcs: {}", .{e});
                return false;
            };
        }
        sub_funcs.appendSlice(self.alloc, nested.items) catch |e| {
            term.err("emit_embedded_module: oom appending nested funcs: {}", .{e});
            return false;
        };

        // Submodule-native lowering: preserve per-submodule scalar eligibility
        // (computed above) for direct C calls during function emission.
        const saved_native_scalar = self.native_scalar_mode;
        const saved_mixed_scalar = self.mixed_scalar_mode;
        defer {
            self.native_scalar_mode = saved_native_scalar;
            self.mixed_scalar_mode = saved_mixed_scalar;
            self.current_module = null;
        }

        self.collect_and_emit_record_decls(&submod) catch |e| {
            term.err("emit_embedded_module: collect_and_emit_record_decls failed for {s}: {}", .{ path, e });
            return false;
        };

        // Functions named by the module's export table (`M.foo = foo`) must be
        // emitted even when they are not native-scalar eligible. The table holds
        // lua_Values, so the `__lua` thunk has to exist; skipping them left the
        // table entry referencing a bare, undefined identifier and the C compiler
        // rejected the module (this is what broke `req "std.jit"` — every helper
        // returning `any` was dropped, and only `arch`, which returns `str`,
        // survived because it was devirtualized to a direct call).
        var exported_fn_names: std.StringHashMapUnmanaged(void) = .{};
        defer exported_fn_names.deinit(self.alloc);
        for (submod.body.stmts) |*stmt| {
            if (stmt.* != .assign) continue;
            for (stmt.assign.values) |v| {
                if (v.* == .name) {
                    exported_fn_names.put(self.alloc, v.name.ident, {}) catch {};
                }
            }
        }

        const saved_exports_funcs = self.embedded_module_exports_funcs;
        self.embedded_module_exports_funcs = true;
        defer self.embedded_module_exports_funcs = saved_exports_funcs;

        // Forward-declare submodule functions
        for (sub_funcs.items) |fd| {
            if (fd.path.len == 1 and !fd.method) {
                // Embedded-module functions are always emitted: they are the module's API,
                // reachable through its export table. Filtering them by native-scalar
                // eligibility dropped every helper with `any` in its signature while the
                // table still referenced it, so `req "std.jit"`/`"std.mem"` could not
                // compile at all (BUG C).
                self.note_func_body(fd.path[0], &fd.func) catch |e| {
                    term.err("emit_embedded_module: func body registration failed for {s}: {}", .{ fd.path[0], e });
                    return false;
                };
                self.note_func_decl(fd.path[0], fd) catch |e| {
                    term.err("emit_embedded_module: func decl registration failed for {s}: {}", .{ fd.path[0], e });
                    return false;
                };
                self.emit_func_decl_forward(fd) catch |e| {
                    term.err("emit_embedded_module: forward decl failed for {s}: {}", .{ fd.path[0], e });
                    return false;
                };
            }
        }
        // Emit submodule function definitions at file scope
        for (sub_funcs.items) |fd| {
            if (self.current_module_cname.len > 0 and !self.embedded_module_exports_funcs and !self.funcUsesNativeLowering(fd.path[0])) continue;
            self.emit_func_def(fd) catch |e| {
                term.err("emit_embedded_module: func def failed for {s}: {}", .{ fd.path[0], e });
                return false;
            };
        }

        // Emit table-valued submodule const init functions after function definitions
        // so they can call module functions that are already declared.
        for (table_consts.items) |stmt| {
            const cd = &stmt.const_decl;
            var name_buf: [256]u8 = undefined;
            const mname = self.mangled_name(cd.ident, &name_buf);
            self.p("static void _init_{s}(void) {{\n", .{mname});
            self.indent += 1;
            self.ind();
            self.p("{s} = ", .{mname});
            self.emit_expr(cd.val) catch |e| {
                term.err("emit_embedded_module: _init expr emit failed for const {s}: {}", .{ cd.ident, e });
                return false;
            };
            self.p(";\n", .{});
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }
        if (table_consts.items.len > 0) self.p("\n", .{});

        // Emit the module thunk whenever a lua runtime exists. The caller
        // registers every embedded module in duo_register_modules(), and ward
        // requires several of them at runtime — skipping the thunk while that
        // registration is emitted leaves it naming an undefined symbol.
        //
        // Under full native lowering there is no lua runtime: the registration
        // returns early on `moduleNeedsLuaRuntime()`, so nothing references the
        // thunk, and emitting it anyway spells `lua_Value` — which that profile
        // never declares. The two guards must stay symmetric, and the registration
        // is emitted in the *parent's* context: `native_scalar_mode`,
        // `substrate_native_mode` and `module_knowledge` are all swapped to the
        // submodule's values by the time we get here, so consulting
        // `moduleNeedsLuaRuntime()` now answers for the wrong module, and
        // `embed_parent_full_native` answers for the immediate parent (which
        // nesting clobbers: proof -> lexer -> token/classify). Use the
        // translation-unit decision captured at preamble time.
        if (!self.tu_needs_lua_runtime) return true;

        self.p("static lua_Value duo_mod_{s}(lua_Value _unused) {{\n", .{cname});
        self.p("    (void)_unused;\n", .{});
        self.indent = 1;
        const prev_ret = self.current_ret;
        const prev_ctx = self.closure_ctx;
        self.current_ret = .any;
        self.closure_ctx = null;
        self.push_local_scope() catch |e| {
            term.err("emit_embedded_module: scope setup failed: {}", .{e});
            return false;
        };
        self.emit_embedded_module_req_binding_inits(&submod) catch |e| {
            term.err("emit_embedded_module: req binding init failed: {}", .{e});
            return false;
        };
        // A module body is emitted statement-by-statement below, NOT through
        // `emit_block_stmts`, so the str-list disqualification scan that runs
        // for function blocks never fired here. Without it, `M = {}` followed by
        // `M.field = v` was speculatively lowered to `M_items[]` + `M_len` and
        // the field writes then targeted a table that was never declared —
        // emitting `lua_table_set_str_lit((void*)0, ...)`. That made every
        // constants-style module (including duo's own
        // lib/std/wasm/ward_mvp_opcodes.duo) impossible to `req`.
        self.note_str_list_disqualifications(&submod.body) catch |e| {
            term.err("emit_embedded_module: disqualification scan failed: {}", .{e});
            return false;
        };
        // Initialize table-valued submodule constants
        for (submod.body.stmts) |*stmt| {
            if (stmt.* == .const_decl and stmt.const_decl.val.* == .table) {
                self.ind();
                var name_buf: [256]u8 = undefined;
                const mname = self.mangled_name(stmt.const_decl.ident, &name_buf);
                self.p("_init_{s}();\n", .{mname});
            }
        }
        for (submod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .func_decl, .const_decl => {},
                .directive => |dir| {
                    if (std.mem.eql(u8, dir.attr.name, "c.emit")) continue;
                    self.emit_stmt(stmt) catch |e| {
                        term.err("emit_embedded_module: stmt emit failed: {}", .{e});
                        return false;
                    };
                },
                else => blk: {
                    if (stmt.* == .assign) {
                        const as = &stmt.assign;
                        if (as.targets.len == 1 and as.targets[0].* == .name and
                            embedded_module_scalar_const_assign(&submod, as.targets[0].name.ident) != null)
                        {
                            break :blk;
                        }
                    }
                    self.emit_stmt(stmt) catch |e| {
                        term.err("emit_embedded_module: stmt emit failed: {}", .{e});
                        return false;
                    };
                },
            }
        }
        if (submod.body.tail_expr) |expr| {
            self.ind();
            self.p("return ", .{});
            self.emit_as_lua_value(expr) catch |e| {
                term.err("emit_embedded_module: tail expr emit failed: {}", .{e});
                return false;
            };
            self.p(";\n", .{});
        } else if (subsem.duo_mode) {
            self.emit_duo_module_return_table(&submod) catch |e| {
                term.err("emit_embedded_module: auto module table emit failed: {}", .{e});
                return false;
            };
        } else {
            self.pl("return lua_val_nil();", .{});
        }
        self.pop_local_scope();
        self.indent = 0;
        self.current_ret = prev_ret;
        self.closure_ctx = prev_ctx;
        self.p("}}\n\n", .{});
        return true;
    }

    // ── Duo Language Extensions ────────────────────────────────────────────────

    /// Emit a match expression or statement as nested if/switch in C.
    fn emit_match_expr(self: *CodeGen, match_expr: anytype) E!void {
        // Generate a temporary variable to hold the scrutinee value
        const scrutinee_var = try self.alloc.dupe(u8, "__match_s");
        defer self.alloc.free(scrutinee_var);

        // Emit scrutinee evaluation. Use the scrutinee's concrete C type
        // rather than the GNU `auto` extension so the code is portable.
        const scrutinee_type = self.expr_type(match_expr.scrutinee);
        self.p("({{", .{});
        self.indent += 1;
        self.ind();
        self.typ(scrutinee_type);
        self.p(" __match_s = ", .{});
        try self.emit_expr(match_expr.scrutinee);
        self.p(";", .{});

        // Generate arms
        for (match_expr.arms, 0..) |arm, i| {
            self.nl();
            self.ind();

            if (i == 0) {
                self.p("if (", .{});
            } else {
                self.p("else if (", .{});
            }

            try self.emit_pattern_condition(arm.pattern, scrutinee_var, scrutinee_type);
            self.p(") {{", .{});

            self.indent += 1;
            self.nl();

            try self.emit_pattern_bindings(arm.pattern, scrutinee_var, scrutinee_type);

            // Emit guard if present
            if (arm.guard) |guard| {
                self.ind();
                self.p("if (!(", .{});
                try self.emit_expr(guard);
                self.p(")) goto __match_arm_{d}_fail;", .{i});
                self.nl();
            }

            // Emit arm body (Block contains stmts)
            for (arm.body.stmts) |*stmt| {
                try self.emit_stmt(stmt);
            }

            if (arm.guard != null) {
                self.nl();
                self.indent -= 1;
                self.ind();
                self.p("__match_arm_{d}_fail:;", .{i});
                self.indent += 1;
            }

            self.indent -= 1;
            self.nl();
            self.ind();
            self.p("}}", .{});
        }

        // Default case if no wildcard
        self.nl();
        self.ind();
        self.p("else {{", .{});
        self.indent += 1;
        self.nl();
        self.ind();
        self.p("lua_error(lua_val_from_str(\"match non-exhaustive\"));", .{});
        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}}", .{});

        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}})", .{});
    }

    /// Emit pattern matching condition for an arm. `scrutinee_type` is the
    /// resolved type of the value being matched, used to pick the enum
    /// representation for variant patterns.
    fn emit_pattern_condition(self: *CodeGen, pattern: ast.Pattern, scrutinee_var: []const u8, scrutinee_type: RT) E!void {
        switch (pattern) {
            .wildcard => self.p("1", .{}), // Always match
            .literal => |lit| {
                self.p("(", .{});
                if (scrutinee_type == .any) {
                    const lit_t = self.expr_type(lit);
                    if (lit_t.is_numeric()) {
                        self.p("lua_to_num({s}) == ", .{scrutinee_var});
                        try self.emit_expr(lit);
                    } else if (lit_t == .bool) {
                        self.p("lua_to_bool({s}) == ", .{scrutinee_var});
                        try self.emit_expr(lit);
                    } else if (lit_t == .str) {
                        self.p("strcmp(lua_to_str({s}), ", .{scrutinee_var});
                        try self.emit_expr(lit);
                        self.p(") == 0", .{});
                    } else {
                        self.p("{s} == ", .{scrutinee_var});
                        try self.emit_expr(lit);
                    }
                } else {
                    self.p("{s} == ", .{scrutinee_var});
                    try self.emit_expr(lit);
                }
                self.p(")", .{});
            },
            .binding => |b| {
                _ = b;
                self.p("1", .{});
            },
            .variant => |v| {
                // The pattern tag may be qualified ("Color.Red") or bare
                // ("Red"). Resolve the enum name from the scrutinee type and
                // the variant name from the tail of the tag.
                const variant_name = if (std.mem.lastIndexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[dot + 1 ..]
                else
                    v.tag;
                const enum_name = if (scrutinee_type == .enum_type)
                    scrutinee_type.enum_type.name
                else if (std.mem.indexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[0..dot]
                else
                    v.tag;
                const has_payload = self.enum_has_payload.get(enum_name) orelse false;
                self.p("(", .{});
                if (has_payload) {
                    self.p("{s}.tag == duo_{s}_tag_{s}", .{ scrutinee_var, enum_name, variant_name });
                } else {
                    self.p("{s} == duo_{s}_{s}", .{ scrutinee_var, enum_name, variant_name });
                }
                // Recursively check non-trivial sub-pattern conditions for payload fields.
                if (has_payload) {
                    if (v.payload) |payload_pats| {
                        if (self.find_enum_variant_def(enum_name, variant_name)) |vdef| {
                            const fields = vdef.payload orelse &.{};
                            for (payload_pats, 0..) |sub_pat, fi| {
                                switch (sub_pat) {
                                    .wildcard, .binding => continue,
                                    else => {},
                                }
                                const field_name = if (fi < fields.len)
                                    fields[fi].name orelse (try std.fmt.allocPrint(self.alloc, "_{d}", .{fi}))
                                else
                                    try std.fmt.allocPrint(self.alloc, "_{d}", .{fi});
                                const owns_field = fi >= fields.len or fields[fi].name == null;
                                defer if (owns_field) self.alloc.free(field_name);
                                const payload_expr = try std.fmt.allocPrint(self.alloc, "{s}.as.{s}.{s}", .{
                                    scrutinee_var, variant_name, field_name,
                                });
                                defer self.alloc.free(payload_expr);
                                const ft = if (fi < fields.len)
                                    types.resolve(fields[fi].typ, null, self.alloc) catch RT.any
                                else
                                    RT.any;
                                self.p(" && ", .{});
                                try self.emit_pattern_condition(sub_pat, payload_expr, ft);
                            }
                        }
                    }
                }
                self.p(")", .{});
            },
            else => self.p("1", .{}), // Conservative: match everything
        }
    }

    fn emit_pattern_bindings(self: *CodeGen, pattern: ast.Pattern, scrutinee_var: []const u8, scrutinee_type: RT) E!void {
        try self.emit_pattern_binding_from(pattern, scrutinee_var, scrutinee_type);
    }

    fn emit_pattern_binding_from(self: *CodeGen, pattern: ast.Pattern, value_expr: []const u8, value_type: RT) E!void {
        switch (pattern) {
            .binding => |b| {
                const bind_type = if (b.typ) |type_expr|
                    types.resolve(type_expr, null, self.alloc) catch value_type
                else
                    value_type;
                self.ind();
                self.typ(bind_type);
                self.p(" {s} = {s};\n", .{ b.name, value_expr });
                try self.note_local_type(b.name, bind_type);
            },
            .variant => |v| {
                const variant_name = if (std.mem.lastIndexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[dot + 1 ..]
                else
                    v.tag;
                const enum_name = if (value_type == .enum_type)
                    value_type.enum_type.name
                else if (std.mem.indexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[0..dot]
                else
                    v.tag;
                const variant = self.find_enum_variant_def(enum_name, variant_name) orelse return;
                const fields = variant.payload orelse return;
                const payload_pats = v.payload orelse return;
                for (payload_pats, 0..) |sub_pat, i| {
                    if (i >= fields.len) break;
                    const field_type = types.resolve(fields[i].typ, null, self.alloc) catch RT.any;
                    const field_name = fields[i].name orelse try std.fmt.allocPrint(self.alloc, "_{d}", .{i});
                    defer if (fields[i].name == null) self.alloc.free(field_name);
                    const payload_expr = try std.fmt.allocPrint(self.alloc, "{s}.as.{s}.{s}", .{ value_expr, variant_name, field_name });
                    defer self.alloc.free(payload_expr);
                    try self.emit_pattern_binding_from(sub_pat, payload_expr, field_type);
                }
            },
            .table_destr => |entries| {
                for (entries) |entry| {
                    const key_hash = calc_lua_hash(entry.key);
                    const field_expr = try std.fmt.allocPrint(self.alloc, "lua_table_get_str_lit({s}, \"{s}\", {d}u, {d})", .{ value_expr, entry.key, key_hash, entry.key.len });
                    defer self.alloc.free(field_expr);
                    try self.emit_pattern_binding_from(entry.pat, field_expr, .any);
                }
            },
            .array_destr => |pats| {
                for (pats, 0..) |sub_pat, ai| {
                    const elem_expr = try std.fmt.allocPrint(self.alloc, "lua_table_get_num({s}, {d})", .{ value_expr, ai + 1 });
                    defer self.alloc.free(elem_expr);
                    try self.emit_pattern_binding_from(sub_pat, elem_expr, .any);
                }
            },
            .rest => |name| {
                self.ind();
                self.p("lua_Value {s} = {s};\n", .{ name, value_expr });
                try self.note_local_type(name, .any);
            },
            else => {},
        }
    }

    /// Emit a try/catch statement.
    fn emit_try_stmt(self: *CodeGen, try_stmt: ast.TryStmt) E!void {
        // Use setjmp/longjmp for error handling
        self.p("({{", .{});
        self.indent += 1;
        self.nl();
        self.ind();
        self.p("jmp_buf __try_env;", .{});
        self.nl();
        self.ind();
        self.p("if (setjmp(__try_env) == 0) {{", .{});

        // Try block
        self.indent += 1;
        self.nl();
        for (try_stmt.body.stmts) |*stmt| {
            try self.emit_stmt(stmt);
        }
        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}}", .{});

        // Catch clauses
        for (try_stmt.catches) |catch_clause| {
            self.p(" else {{", .{});
            self.indent += 1;
            self.nl();

            if (catch_clause.binding) |var_name| {
                self.ind();
                self.p("lua_Value {s} = __catch_val;", .{var_name});
                self.nl();
            }

            for (catch_clause.body.stmts) |*stmt| {
                try self.emit_stmt(stmt);
            }

            self.indent -= 1;
            self.nl();
            self.ind();
            self.p("}}", .{});
        }

        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}})", .{});
    }
};

/// Pass 23 — emit `lua_binop_metamethod` dispatch line from protocol registry.
fn runtimeBinopMetamethodLine(comptime op: pass23_protocol_registry.KernelOp) []const u8 {
    const mm = pass23_protocol_registry.luaMetamethodForKernel(op) orelse
        @compileError("pass23 registry: missing lua metamethod for runtime binop");
    return std.fmt.comptimePrint(
        \\    lua_Value mm = lua_binop_metamethod("{s}", a, b);
    , .{mm});
}

/// Pass 23 — emit `lua_get_metafield_lit(obj, mm, hash, len)` from registry metamethod name.
fn runtimeMetafieldLitLine(
    comptime lua_mm: []const u8,
    comptime obj_expr: []const u8,
    comptime var_name: []const u8,
) []const u8 {
    if (pass23_protocol_registry.findLuaAlias(lua_mm) == null)
        @compileError("pass23 registry: unregistered runtime metamethod");
    const hash = pass23_protocol_registry.luaHash(lua_mm);
    return std.fmt.comptimePrint(
        \\    lua_Value {s} = lua_get_metafield_lit({s}, "{s}", {d}u, {d});
    , .{ var_name, obj_expr, lua_mm, hash, lua_mm.len });
}

/// Reassign form: `mm = lua_get_metafield_lit(b, "__eq", …)`.
fn runtimeMetafieldLitReassignLine(
    comptime lua_mm: []const u8,
    comptime obj_expr: []const u8,
    comptime var_name: []const u8,
) []const u8 {
    if (pass23_protocol_registry.findLuaAlias(lua_mm) == null)
        @compileError("pass23 registry: unregistered runtime metamethod");
    const hash = pass23_protocol_registry.luaHash(lua_mm);
    return std.fmt.comptimePrint(
        \\    {s} = lua_get_metafield_lit({s}, "{s}", {d}u, {d});
    , .{ var_name, obj_expr, lua_mm, hash, lua_mm.len });
}

const duo_runtime =
    \\/* --- Duo Runtime Support --- */
    \\#include <stdbool.h>
    \\#include <stdio.h>
    \\#include <stdlib.h>
    \\#include <string.h>
    \\#include <stdarg.h>
    \\#include <stdint.h>
    \\#if defined(__APPLE__)
    \\#include <mach-o/dyld.h>
    \\#endif
    \\
    \\#define LUA_LIKELY(x)   __builtin_expect(!!(x), 1)
    \\#define LUA_UNLIKELY(x) __builtin_expect(!!(x), 0)
    \\
    \\typedef enum {
    \\    VAL_NIL,
    \\    VAL_BOOL,
    \\    VAL_NUMBER,
    \\    VAL_STRING,
    \\    VAL_TABLE,
    \\    VAL_BUFFER,
    \\    VAL_THREAD,
    \\    VAL_FUNC,
    \\    VAL_FILE,
    \\    VAL_CLOSURE,
    \\} lua_ValType;
    \\
    \\typedef struct {
    \\    lua_ValType type;
    \\    uint8_t number_kind; /* 1=integer, 2=float; only when type==VAL_NUMBER */
    \\    union {
    \\        bool bval;
    \\        double nval;
    \\        int64_t ival;   /* exact integer when number_kind == 1 */
    \\        const char* sval;
    \\        void* tval;
    \\        void* fval; // Cast to function pointer when needed
    \\    } as;
    \\} lua_Value;
    \\
    \\typedef struct {
    \\    FILE* f;
    \\    bool is_pipe;
    \\    bool is_stdio;
    \\} lua_File;
    \\
    \\typedef struct {
    \\    uint32_t hash;
    \\    size_t len;
    \\    char data[];
    \\} lua_String;
    \\
    \\#define LUA_TABLE_INLINE_CAP 4
    \\
    \\typedef struct {
    \\    lua_Value* array;
    \\    int array_size;
    \\    int array_capacity;
    \\    lua_Value inline_array[LUA_TABLE_INLINE_CAP];
    \\    bool array_inline;
    \\    /* Robin-Hood hash part: struct-of-arrays for cache-efficient probing */
    \\    lua_Value* hash_keys;
    \\    lua_Value* hash_vals;
    \\    int capacity;
    \\    int count;
    \\    /* Small-table optimization: embed inline storage for up to LUA_TABLE_INLINE_CAP entries */
    \\    lua_Value inline_keys[LUA_TABLE_INLINE_CAP];
