// ── WASM target string detection ──────────────────────────────────────────

test "wasm: target string 'wasm32-wasi' is correctly identified" {
    const target = "wasm32-wasi";
    try testing.expect(std.mem.eql(u8, target, "wasm32-wasi"));
    try testing.expect(!std.mem.eql(u8, "native", "wasm32-wasi"));
    try testing.expect(!std.mem.eql(u8, "x86_64-linux", "wasm32-wasi"));
    try testing.expect(!std.mem.eql(u8, "aarch64-macos", "wasm32-wasi"));
}

test "wasm: output extension is .wasm for wasm32-wasi target" {
    // Mirrors the logic in main.zig lines 87-90.
    const stem = "hello";
    const target_wasm = "wasm32-wasi";
    const target_native = "native";
    const ext_wasm = if (std.mem.eql(u8, target_wasm, "wasm32-wasi")) ".wasm" else ".out";
    const ext_native = if (std.mem.eql(u8, target_native, "wasm32-wasi")) ".wasm" else ".out";
    try testing.expectEqualStrings(".wasm", ext_wasm);
    try testing.expectEqualStrings(".out", ext_native);
    _ = stem;
}

// ── Library init skip logic ───────────────────────────────────────────────

test "wasm: library init skip condition is based on wasm32-wasi string" {
    // Mirrors codegen.zig line 631: `if (!std.mem.eql(u8, self.target, "wasm32-wasi"))`
    // coroutine/io/os are NOT initialized on WASM.
    const target_wasm = "wasm32-wasi";
    const should_init = !std.mem.eql(u8, target_wasm, "wasm32-wasi");
    try testing.expect(!should_init); // should NOT init for WASM
}

test "native: all libraries are initialized on non-wasm targets" {
    const targets = [_][]const u8{ "native", "x86_64-linux", "aarch64-macos" };
    for (targets) |t| {
        const should_init = !std.mem.eql(u8, t, "wasm32-wasi");
        try testing.expect(should_init);
    }
}

// ── XOPEN_SOURCE suppression logic ────────────────────────────────────────

test "wasm: _XOPEN_SOURCE is suppressed for wasm32-wasi" {
    const target_wasm = "wasm32-wasi";
    const emit_xopen = !std.mem.eql(u8, target_wasm, "wasm32-wasi");
    try testing.expect(!emit_xopen);
}

test "native: _XOPEN_SOURCE is emitted for non-wasm targets" {
    const targets = [_][]const u8{ "native", "x86_64-linux-gnu", "aarch64-macos" };
    for (targets) |t| {
        const emit_xopen = !std.mem.eql(u8, t, "wasm32-wasi");
        try testing.expect(emit_xopen);
    }
}

// ── PGO skip logic ────────────────────────────────────────────────────────

test "wasm: PGO is skipped for wasm32-wasi (mirrors main.zig condition)" {
    // main.zig: `if (pgo and !is_wasm and !load_chunk)`
    const pgo = true;
    const load_chunk = false;
    const is_wasm_true = true;
    const is_wasm_false = false;
    const run_pgo_wasm = pgo and !is_wasm_true and !load_chunk;
    const run_pgo_native = pgo and !is_wasm_false and !load_chunk;
    try testing.expect(!run_pgo_wasm);
    try testing.expect(run_pgo_native);
}

// ── run_after skip logic ──────────────────────────────────────────────────

test "wasm: program is not executed after compile on wasm target" {
    // main.zig: `if (run_after and !is_wasm)`
    const run_after = true;
    const is_wasm_true = true;
    const is_wasm_false = false;
    const exec_after_wasm = run_after and !is_wasm_true;
    const exec_after_native = run_after and !is_wasm_false;
    try testing.expect(!exec_after_wasm);
    try testing.expect(exec_after_native);
}

// ── Compile-time constant folding ─────────────────────────────────────────

test "const fold: i64 int literal addition" {
    // Mirrors the binop fold path: both int_lit → fold to sum.
    const lv: i64 = 1;
    const rv: i64 = 2;
    try testing.expectEqual(@as(i64, 3), lv +% rv);
}

test "const fold: i64 int literal subtraction" {
    const lv: i64 = 10;
    const rv: i64 = 7;
    try testing.expectEqual(@as(i64, 3), lv -% rv);
}

test "const fold: i64 int literal multiplication" {
    const lv: i64 = 6;
    const rv: i64 = 7;
    try testing.expectEqual(@as(i64, 42), lv *% rv);
}

test "const fold: i64 idiv" {
    const lv: i64 = 17;
    const rv: i64 = 5;
    try testing.expectEqual(@as(i64, 3), @divFloor(lv, rv));
}

test "const fold: i64 mod" {
    const lv: i64 = 17;
    const rv: i64 = 5;
    try testing.expectEqual(@as(i64, 2), @mod(lv, rv));
}

test "const fold: i64 bitwise and" {
    const lv: i64 = 0b1100;
    const rv: i64 = 0b1010;
    try testing.expectEqual(@as(i64, 0b1000), lv & rv);
}

test "const fold: i64 bitwise or" {
    const lv: i64 = 0b1100;
    const rv: i64 = 0b1010;
    try testing.expectEqual(@as(i64, 0b1110), lv | rv);
}

test "const fold: i64 bitwise xor" {
    const lv: i64 = 0b1100;
    const rv: i64 = 0b1010;
    try testing.expectEqual(@as(i64, 0b0110), lv ^ rv);
}

test "const fold: i64 left shift" {
    const lv: i64 = 1;
    const rv: i64 = 10;
    try testing.expectEqual(@as(i64, 1024), lv << @intCast(rv));
}

test "const fold: i64 right shift (logical)" {
    const lv: i64 = 1024;
    const rv: i64 = 2;
    const result = @as(i64, @bitCast(@as(u64, @bitCast(lv)) >> @intCast(rv)));
    try testing.expectEqual(@as(i64, 256), result);
}

test "const fold: i64 comparison eq" {
    try testing.expectEqual(true, @as(i64, 3) == @as(i64, 3));
    try testing.expectEqual(false, @as(i64, 3) == @as(i64, 4));
}

test "const fold: i64 comparison lt" {
    try testing.expectEqual(true, @as(i64, 2) < @as(i64, 5));
    try testing.expectEqual(false, @as(i64, 5) < @as(i64, 2));
}

test "const fold: float literal addition" {
    const lv: f64 = 1.5;
    const rv: f64 = 2.5;
    try testing.expectApproxEqAbs(@as(f64, 4.0), lv + rv, 1e-12);
}

test "const fold: float literal multiplication" {
    const lv: f64 = 3.0;
    const rv: f64 = 2.5;
    try testing.expectApproxEqAbs(@as(f64, 7.5), lv * rv, 1e-12);
}

test "const fold: mixed int+float promoted to float" {
    const lv: f64 = @as(f64, @floatFromInt(@as(i64, 3)));
    const rv: f64 = 1.5;
    try testing.expectApproxEqAbs(@as(f64, 4.5), lv + rv, 1e-12);
}

test "const fold: division by zero is not folded (skipped)" {
    // We verify the guard condition: rv != 0 prevents div-by-zero fold.
    const rv: i64 = 0;
    try testing.expect(rv == 0); // fold is skipped when rv == 0
}

test "const fold: float div by zero not folded" {
    const rv: f64 = 0.0;
    try testing.expect(rv == 0.0); // fold is skipped
}

test "const fold: out-of-range shift not folded" {
    // Shifts ≥ 64 are not folded to avoid undefined behavior.
    const rv: i64 = 64;
    try testing.expect(rv >= 64); // guard: fold skipped
}

test "const fold: wrapping overflow semantics" {
    // i64 overflow wraps (Lua semantics): maxInt + 1 wraps to minInt.
    const max: i64 = std.math.maxInt(i64);
    try testing.expectEqual(std.math.minInt(i64), max +% 1);
}

