// ── Type-narrowing improvements ────────────────────────────────────────────

test "num_for: loop variable is typed as i64 by default" {
    // num_for now calls note_local_type(name, vt2) instead of note_local(name).
    // vt2 defaults to i64 when the start expression is untyped.
    const vt: RT = .any; // start expression has unknown type
    const vt2: RT = if (vt == .any) RT.i64 else vt;
    try testing.expect(vt2 == .i64);
}

test "num_for: loop variable uses declared type annotation" {
    // When the loop declares `for i: f64 = 0.0, 1.0, 0.1 do`, vt resolves to f64.
    const vt: RT = .f64;
    const vt2: RT = if (vt == .any) RT.i64 else vt;
    try testing.expect(vt2 == .f64);
}

test "num_for: loop variable inherits start expression type" {
    // `for i = some_f64_expr, limit do` should use f64.
    const vt: RT = .f64; // expr_type(start) = f64
    const vt2: RT = if (vt == .any) RT.i64 else vt;
    try testing.expect(vt2 == .f64);
}

test "expr_type: unwrap_expr propagates operand type" {
    // x! where x is i64 should produce i64, not .any.
    // Simulates the added `if (e.* == .unwrap_expr) return self.expr_type(e.unwrap_expr.operand);`
    const operand_type: RT = .i64;
    const result_type: RT = operand_type; // propagation
    try testing.expect(result_type == .i64);
}

test "expr_type: try_expr propagates operand type" {
    const operand_type: RT = .f64;
    const result_type: RT = operand_type;
    try testing.expect(result_type == .f64);
}

test "expr_type: await_expr propagates operand type" {
    const operand_type: RT = .i64;
    const result_type: RT = operand_type;
    try testing.expect(result_type == .i64);
}

test "expr_type: contains_expr always produces bool" {
    // `x in y` is a membership test, always boolean.
    const result_type: RT = .bool;
    try testing.expect(result_type == .bool);
    try testing.expect(result_type != .any);
}

test "expr_type: indexed native containers recover their element type" {
    var elem_i32: RT = .i32;
    var elem_f64: RT = .f64;
    var type_map = sema.TypeMap.init(testing.allocator);
    defer type_map.deinit();
    var cg = CodeGen.init(testing.allocator, undefined, &type_map, null, undefined, 0, null, null);
    defer {
        cg.local_scopes.deinit(testing.allocator);
        cg.comptime_scopes.deinit(testing.allocator);
        cg.close_scopes.deinit(testing.allocator);
        cg.arc_scopes.deinit(testing.allocator);
        cg.defer_scopes.deinit(testing.allocator);
        for (cg.numeric_lua_scopes.items) |*m| m.deinit(testing.allocator);
        cg.numeric_lua_scopes.deinit(testing.allocator);
    }
    try cg.push_local_scope();
    defer cg.pop_local_scope();

    try testing.expectEqual(RT.i32, cg.indexed_element_type(.{ .array = .{ .elem = &elem_i32, .size = 8 } }).?);
    try testing.expectEqual(RT.f64, cg.indexed_element_type(.{ .pointer = &elem_f64 }).?);
    try testing.expectEqual(RT.f64, cg.indexed_element_type(.v4f64).?);
    try testing.expectEqual(RT.i32, cg.indexed_element_type(.v8i32).?);
    try testing.expect(cg.indexed_element_type(.any) == null);

    try cg.note_local_type("xs", .{ .array = .{ .elem = &elem_i32, .size = 8 } });
    const loc = ast.Loc{ .file = "test", .line = 1, .col = 1 };
    var xs = ast.Expr{ .name = .{ .loc = loc, .ident = "xs" } };
    var key = ast.Expr{ .int_lit = .{ .loc = loc, .val = 0 } };
    var index = ast.Expr{ .index = .{ .loc = loc, .obj = &xs, .key = &key } };
    try testing.expectEqual(RT.i32, cg.expr_type(&index));
}

test "expr_type: named record alias field fallback recovers declared field type" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var type_map = sema.TypeMap.init(testing.allocator);
    defer type_map.deinit();
    var cg = CodeGen.init(testing.allocator, undefined, &type_map, null, undefined, 0, null, null);
    defer {
        cg.record_aliases.deinit(testing.allocator);
        cg.local_scopes.deinit(testing.allocator);
        cg.comptime_scopes.deinit(testing.allocator);
        cg.close_scopes.deinit(testing.allocator);
        cg.arc_scopes.deinit(testing.allocator);
        cg.defer_scopes.deinit(testing.allocator);
        for (cg.numeric_lua_scopes.items) |*m| m.deinit(testing.allocator);
        cg.numeric_lua_scopes.deinit(testing.allocator);
    }
    try cg.push_local_scope();
    defer cg.pop_local_scope();

    const fields = try alloc.alloc(types.FieldType, 2);
    fields[0] = .{ .name = "x", .typ = .i64 };
    fields[1] = .{ .name = "label", .typ = .str };
    try cg.record_aliases.put(testing.allocator, "Point", .{ .table_type = .{ .fields = fields } });
    try cg.note_local_type("p", .{ .@"struct" = .{ .name = "Point" } });

    const loc = ast.Loc{ .file = "test", .line = 1, .col = 1 };
    var p_name = ast.Expr{ .name = .{ .loc = loc, .ident = "p" } };
    var x_field = ast.Expr{ .field = .{ .loc = loc, .obj = &p_name, .field = "x" } };
    var label_field = ast.Expr{ .field = .{ .loc = loc, .obj = &p_name, .field = "label" } };

    try testing.expectEqual(RT.i64, cg.expr_type(&x_field));
    try testing.expectEqual(RT.str, cg.expr_type(&label_field));
}

test "codegen: generic type alias resolves through normal type syntax" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var type_map = sema.TypeMap.init(testing.allocator);
    defer type_map.deinit();
    var cg = CodeGen.init(alloc, undefined, &type_map, null, undefined, 0, null, null);
    defer {
        cg.alias_defs.deinit(alloc);
        cg.local_scopes.deinit(alloc);
        cg.comptime_scopes.deinit(alloc);
        cg.close_scopes.deinit(alloc);
        cg.arc_scopes.deinit(alloc);
        cg.defer_scopes.deinit(alloc);
        for (cg.numeric_lua_scopes.items) |*m| m.deinit(alloc);
        cg.numeric_lua_scopes.deinit(alloc);
    }

    const tparams = try alloc.alloc(ast.TypeExpr, 1);
    tparams[0] = .{ .named = "T" };
    const list_base = try alloc.create(ast.TypeExpr);
    list_base.* = .{ .named = "List" };
    const list_args = try alloc.alloc(ast.TypeExpr, 1);
    list_args[0] = .{ .named = "T" };
    const alias = try alloc.create(ast.AliasDef);
    alias.* = .{
        .loc = .{ .file = "test", .line = 1, .col = 1 },
        .name = "Vec",
        .type_params = tparams,
        .target = .{ .generic = .{ .base = list_base, .params = list_args } },
        .fields = &.{},
        .methods = &.{},
    };
    try cg.alias_defs.put(alloc, "Vec", alias);

    const vec_base = try alloc.create(ast.TypeExpr);
    vec_base.* = .{ .named = "Vec" };
    const vec_args = try alloc.alloc(ast.TypeExpr, 1);
    vec_args[0] = .{ .named = "i64" };
    const resolved = cg.resolve_type(.{ .generic = .{ .base = vec_base, .params = vec_args } });

    try testing.expect(resolved == .array);
    try testing.expect(resolved.array.elem.* == .i64);
}

test "expr_type: statically typed callee recovers its return type" {
    var ret_type: RT = .i32;
    var type_map = sema.TypeMap.init(testing.allocator);
    defer type_map.deinit();
    var cg = CodeGen.init(testing.allocator, undefined, &type_map, null, undefined, 0, null, null);
    defer {
        cg.local_scopes.deinit(testing.allocator);
        cg.comptime_scopes.deinit(testing.allocator);
        cg.close_scopes.deinit(testing.allocator);
