}

test "expr_type: string returning builtins recover native str" {
    const loc = ast.Loc{ .file = "test", .line = 1, .col = 1 };
    var string_name = ast.Expr{ .name = .{ .loc = loc, .ident = "string" } };
    var sub_func = ast.Expr{ .field = .{ .loc = loc, .obj = &string_name, .field = "sub" } };
    var len_func = ast.Expr{ .field = .{ .loc = loc, .obj = &string_name, .field = "len" } };
    var cg: CodeGen = undefined;

    try testing.expectEqual(RT.str, cg.string_call_result_type(&sub_func, &.{}).?);
    try testing.expectEqual(RT.i64, cg.string_call_result_type(&len_func, &.{}).?);
}

test "expr_type: structural fallback recovers literal and function expression types" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var type_map = sema.TypeMap.init(alloc);
    defer type_map.deinit();
    var cg = CodeGen.init(alloc, undefined, &type_map, null, undefined, 0, null, null);
    defer {
        cg.local_scopes.deinit(alloc);
        cg.comptime_scopes.deinit(alloc);
        cg.close_scopes.deinit(alloc);
        cg.arc_scopes.deinit(alloc);
        cg.defer_scopes.deinit(alloc);
        for (cg.numeric_lua_scopes.items) |*m| m.deinit(alloc);
        cg.numeric_lua_scopes.deinit(alloc);
    }

    const loc = ast.Loc{ .file = "test", .line = 1, .col = 1 };
    var nil_expr = ast.Expr{ .nil = loc };
    var bool_expr = ast.Expr{ .true_lit = loc };
    var int_expr = ast.Expr{ .int_lit = .{ .loc = loc, .val = 42 } };
    var float_expr = ast.Expr{ .float_lit = .{ .loc = loc, .val = 3.14 } };
    var str_expr = ast.Expr{ .string_lit = .{ .loc = loc, .val = "duo" } };
    try testing.expectEqual(RT.nil, cg.expr_type(&nil_expr));
    try testing.expectEqual(RT.bool, cg.expr_type(&bool_expr));
    try testing.expectEqual(RT.i64, cg.expr_type(&int_expr));
    try testing.expectEqual(RT.f64, cg.expr_type(&float_expr));
    try testing.expectEqual(RT.str, cg.expr_type(&str_expr));

    const params = try alloc.alloc(ast.FuncParam, 1);
    params[0] = .{ .name = "x", .typ = .{ .named = "i64" }, .loc = loc };
    var body = ast.FuncBody{
        .loc = loc,
        .params = params,
        .vararg = false,
        .ret_type = .{ .named = "str" },
        .body = .{ .loc = loc, .stmts = &.{} },
    };
    var func_expr = ast.Expr{ .func_expr = &body };
    const func_type = cg.expr_type(&func_expr);
    try testing.expect(func_type == .func);
    try testing.expectEqual(@as(usize, 1), func_type.func.params.len);
    try testing.expectEqual(RT.i64, func_type.func.params[0]);
    try testing.expectEqual(RT.str, func_type.func.ret.*);
    try testing.expect(!func_type.func.has_vararg);
}

test "codegen: closure programs emit runtime JIT tables" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\local n = 10
        \\local f = function(x) return x + n end
        \\print(f(1))
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();
    try testing.expect(std.mem.indexOf(u8, output, "duo_jit_sources") != null);
    try testing.expect(std.mem.indexOf(u8, output, "duo_jit_dispatch") != null);
    try testing.expect(std.mem.indexOf(u8, output, "duo_jit_pack_") != null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_jit_init") != null);
}

test "arc: record and enum value types do not emit retain release hooks" {
    const alloc = testing.allocator;
    var type_map = sema.TypeMap.init(alloc);
    defer type_map.deinit();
    var cg = CodeGen.init(alloc, undefined, &type_map, null, undefined, 0, null, null);
    defer {
        cg.local_scopes.deinit(alloc);
        cg.comptime_scopes.deinit(alloc);
        cg.close_scopes.deinit(alloc);
        cg.arc_scopes.deinit(alloc);
        cg.defer_scopes.deinit(alloc);
        for (cg.numeric_lua_scopes.items) |*m| m.deinit(alloc);
        cg.numeric_lua_scopes.deinit(alloc);
    }

    var fields = [_]types.FieldType{.{ .name = "value", .typ = .i64 }};
    const record = RT{ .table_type = .{ .fields = fields[0..] } };
    var variants = [_]types.EnumVariantType{
        .{ .name = "Red", .payload = null },
        .{ .name = "Green", .payload = null },
    };
    const enum_rt = RT{ .enum_type = .{ .name = "Color", .variants = variants[0..] } };

    try testing.expect(!cg.codegen_needs_arc(record));
    try testing.expect(!cg.codegen_needs_arc(enum_rt));
}

